UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 혼합만 하면 해내지 못할 것이 없지.', `MaleText_loc4`='恰当的合剂是无所不能的！', `MaleText_loc5`='正確的混合步驟能解決一切問題。', `MaleText_loc7`='No hay nada que no se pueda solucionar con la mezcla adecuada.' WHERE `ID`=75128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 죽음에... 마개를 끼우는 법만큼은... 알아내지 못했다...', `MaleText_loc4`='我一直没能发现……阻止死亡的……药物……', `MaleText_loc5`='我從未發現...能阻止死亡...的藥...', `MaleText_loc7`='Nunca descubrí... con qué detener... la muerte…' WHERE `ID`=75129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보게, 형제들이여. 깨우는 자가 왔네!', `MaleText_loc4`='看呐，兄弟们，唤醒者来了！', `MaleText_loc5`='看啊，兄弟們!喚醒者來了!', `MaleText_loc7`='Miren, hermanos, ¡el heraldo está aquí!' WHERE `ID`=75130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 마지막으로 너희를 파멸로 데려가 주마!', `MaleText_loc4`='让我最后送你一程，唤醒者，飞向你的末日。', `MaleText_loc5`='喚醒者，讓我在最後這次把你送上西天。', `MaleText_loc7`='Te llevaré una última vez heraldo... A tu condena.' WHERE `ID`=75131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 바람을 탄 나뭇잎이다!', `MaleText_loc4`='我是风中落叶！', `MaleText_loc5`='我是風中的落葉!', `MaleText_loc7`='¡Soy una hoja en el viento!' WHERE `ID`=75132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 치솟는 걸 보아라!', `MaleText_loc4`='看我如何飞翔！', `MaleText_loc5`='看我如何翱翔!', `MaleText_loc7`='¡Mírenme volar alto!' WHERE `ID`=75133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 분명히 경고했다.', `MaleText_loc4`='我可是警告过你的，唤醒者。', `MaleText_loc5`='我警告過你了，喚醒者。', `MaleText_loc7`='Yo te lo advertí, heraldo.' WHERE `ID`=75134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠다, 깨우는 자여. 우리는 다시 만날 것이다...', `MaleText_loc4`='打得好，唤醒者，后会有期……', `MaleText_loc5`='打得好，喚醒者。我們會再見的...', `MaleText_loc7`='Buena pelea, heraldo. Volveremos a vernos…' WHERE `ID`=75135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 왔다고? 그러게 내가 놈들한테 미세음파 유전자 조작을 쓰자고 했지.', `MaleText_loc4`='他们竟能走到这里？我早说了，其他人需要一些微波基因改造。', `MaleText_loc5`='他們居然能來到這裡?我跟你說過其他人需要微音波基因改造。', `MaleText_loc7`='¿Lograron llegar hasta aquí? Te dije que los otros necesitaban algunas alteraciones genéticas microsónicas.' WHERE `ID`=75136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아... 새로운 실험 대상이군!', `MaleText_loc4`='很好……全新的试验品！', `MaleText_loc5`='太好了，新的實驗體!', `MaleText_loc7`='¡Sí! ¡Mis nuevos sujetos de pruebas!' WHERE `ID`=75137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공이다! 아직 살아 있어!', `MaleText_loc4`='成功了！他们还活着！', `MaleText_loc5`='成功了，他們還活著!', `MaleText_loc7`='¡Éxito! ¡Están vivos!' WHERE `ID`=75138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연 진화에는 시간이 너무 오래 걸린다. 자, 내가 도와주지...', `MaleText_loc4`='自然进化所需的时间太长了。让我来帮你一把……', `MaleText_loc5`='自然的進化需要太久的時間。來，讓我幫你們一把...', `MaleText_loc7`='La evolución natural lleva mucho tiempo. Mira, déjenme ayudarles…' WHERE `ID`=75139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 이렇게 빨리 죽어 버리면 자료 축적이 안 되잖아.', `MaleText_loc4`='该死！早夭导致数据丢失了。', `MaleText_loc5`='該死!過早的死亡使資料損失了不少。', `MaleText_loc7`='¡Con un demonio!  Más datos perdidos en una muerte prematura.' WHERE `ID`=75140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 벌써 죽었나? 미세음파 유전자 검출로 되살릴 수 있을까나...', `MaleText_loc4`='唔，已经死了？我在想，微波深度基因探测能不能让他们复苏……', `MaleText_loc5`='嗯，已經死了嗎?不知道微聲波深度基因探測能不能讓他們甦醒...', `MaleText_loc7`='¿Mmm? ¿Muertos, ya?  Me pregunto si una sesión de sondeo infragenético microsónico podrá reanimarlos…' WHERE `ID`=75141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을... 진화시켜야... 했던 건가...', `MaleText_loc4`='或许我应该……强化一下……我自己……', `MaleText_loc5`='也許我該把自己...強化一下...', `MaleText_loc7`='Tal vez debí... usar algunas mejoras... de las mías…' WHERE `ID`=75142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 좀 보십시오! 알려진 어떤 시간의 길에도 속하지 않는, 완전히 분리된 생태계입니다!$b$b저 같은 블러드 엘프가 이렇게 놀라는 건 정말 드문 일입니다. 여기서 보내는 일 분 일 초가 제게 큰 기쁨이 될 것 같군요.', `MaleText_loc4`='看看这儿！一个与世隔绝的、完整的生态圈，与已知的所有时间流都毫无牵连！$b$b很少有东西能让我这样的人感到吃惊。我一定要好好珍惜在这里度过的每一秒钟。', `MaleText_loc5`='看看這個地方!整個生態都與所有已知的時空隔離!$b$b我很難對任何事情像這樣感到驚訝。我會用在這裡的每一刻來好好感受這一切。', `MaleText_loc7`='¡Observa este lugar! Todo un ecosistema, aislado de todas las líneas temporales conocidas.$b$bLa verdad es que no suelo sorprenderme ante prácticamente nada, pero voy a disfrutar del tiempo que pase aquí.' WHERE `ID`=75143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 많은 업적을 이루고 당당히 이 자리에 섰지만, 이제 너희 몰락이 시작될 것이다.', `MaleText_loc4`='你们高高在上，居功自傲，它会让你们走向灭亡。', `MaleText_loc5`='你們趾高氣昂地站在自己的成就上面，這會是你們的敗因。', `MaleText_loc7`='Desde la cima de sus logros miran hacia abajo con orgullo y esto será su perdición.' WHERE `ID`=75159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락을 이겨내고 싶다면, 먼저 너희 자신 속의 타락을 정화해야 한다.', `MaleText_loc4`='要想击败腐蚀，首先要净化自己内心的腐蚀。', `MaleText_loc5`='想要擊敗腐化，你們必須先淨化你們內心的腐化。', `MaleText_loc7`='Si desean vencer a la corrupción, primero tienen que purificar la corrupción dentro de ustedes.' WHERE `ID`=75160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림이 우릴 실망시켰다. 코르크론! 침입자들을 처치해라!', `MaleText_loc4`='纳兹戈林辜负了我们。库卡隆，消灭入侵者！', `MaleText_loc5`='納茲格寧姆失敗了。柯爾克隆，殺光這些入侵者!', `MaleText_loc7`='Nazgrim nos ha fallado. ¡Kor''kron, destruye a estos intrusos!' WHERE `ID`=75161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 대족장님을 실망시키지 않아!', `MaleText_loc4`='我是不会辜负酋长的！', `MaleText_loc5`='我不會讓大酋長失望!', `MaleText_loc7`='¡Nunca le fallaré al jefe de guerra!' WHERE `ID`=75162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님의 힘이다!', `MaleText_loc4`='加尔鲁什赐予我力量！', `MaleText_loc5`='卡爾洛斯給我力量!', `MaleText_loc7`='¡Garrosh me da fuerzas!' WHERE `ID`=75163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해 빠진 것!', `MaleText_loc4`='懦夫……', `MaleText_loc5`='弱者!', `MaleText_loc7`='Debiluchos...' WHERE `ID`=75164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 대족장님께 도전해?', `MaleText_loc4`='你竟敢挑战酋长？', `MaleText_loc5`='你們敢挑戰大酋長?', `MaleText_loc7`='¿Se atreven a desafiar al jefe de guerra?' WHERE `ID`=75165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드의 힘을 봐라!', `MaleText_loc4`='看看正统部落的力量吧！', `MaleText_loc5`='見證正統部落的力量吧!', `MaleText_loc7`='¡Contemplen la fuerza de la verdadera Horda!' WHERE `ID`=75166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 힘은 너희를 압도한다!', `MaleText_loc4`='让酋长的力量湮没你们吧！', `MaleText_loc5`='大酋長的力量會擊垮你們!', `MaleText_loc7`='¡El poder del jefe de guerra los abrumará!' WHERE `ID`=75167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드를... 막을 순... 없다!', `MaleText_loc4`='正统部落是……不可阻挡的！', `MaleText_loc5`='你們無法阻止正統的部落!', `MaleText_loc7`='¡La Verdadera Horda... no puede... ser... DETENIDA!' WHERE `ID`=75168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라... 어서... 내게 덤벼!', `MaleText_loc4`='站起来……面对我吧！', `MaleText_loc5`='站起來...面對我!', `MaleText_loc7`='¡Vengan... y... ENFRÉNTENME!' WHERE `ID`=75169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님을 위해 죽는 건... 영광이다...', `MaleText_loc4`='为酋长而死……是我的……荣幸……', `MaleText_loc5`='為大酋長而死...十分光榮...', `MaleText_loc7`='Morir por el Jefe de Guerra... es... un... honor...' WHERE `ID`=75170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 넘친다!', `MaleText_loc4`='所向披靡！', `MaleText_loc5`='如此強大的力量啊!', `MaleText_loc7`='¡Poder aplastante!' WHERE `ID`=75171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 뜻이다!', `MaleText_loc4`='这是酋长的命令！', `MaleText_loc5`='這是大酋長之命!', `MaleText_loc7`='¡El Jefe de Guerra lo demanda!' WHERE `ID`=75172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철의 거대괴수가 당신에게 |cFFFF0404|Hspell:144918|h[절단 레이저]|h|r를 집중시킵니다!', `MaleText_loc4`='钢铁战蝎向你发射了一束|cFFFF0404|Hspell:144918|h[切割激光]|h|r！', `MaleText_loc5`='鋼鐵破滅邪神瞄準你並使用|cFFFF0404|Hspell:144918|h[雷射切割]|h|r!', `MaleText_loc7`='¡El gigante férreo fija un |cFFFF0404|Hspell:144918|h[Láser cortante]|h|r en ti!' WHERE `ID`=75173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카이로즈! 내 요원 중에서도 가장 뛰어난 자를 소개시켜 주마.', `MaleText_loc4`='凯诺兹！来认识一下，这位是我最出色的帮手。', `MaleText_loc5`='凱洛斯!我要你來見見我最得力的探員。', `MaleText_loc7`='¡Kairoz! Quiero presentarte a uno de mis mejores agentes.' WHERE `ID`=75174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 말해 다오. 이 섬이 왜 이렇게... 특별한지.', `MaleText_loc4`='说说看，这里为何如此奇特？', `MaleText_loc5`='告訴我們這座島有什麼特別之處?', `MaleText_loc7`='Explícanos otra vez por favor, ¿por qué es tan especial esta isla?' WHERE `ID`=75175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 특별한 물건은 꼭 한번 연구해 보고 싶은데.', `MaleText_loc4`='我就是喜欢研究这些特别的东西。', `MaleText_loc5`='我很希望能研究一下如此特殊的物品。', `MaleText_loc7`='Me encantaría estudiar esos objetos tan únicos.' WHERE `ID`=75176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음?', `MaleText_loc4`='哦？', `MaleText_loc5`='哦?', `MaleText_loc7`='¿Sí?' WHERE `ID`=75177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 네 사고 방식이 마음에 드는구나!', `MaleText_loc4`='……我喜欢你这个想法！', `MaleText_loc5`='...我喜歡你的思考方式!', `MaleText_loc7`='¡Me gusta cómo piensas!' WHERE `ID`=75178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광입니다.', `MaleText_loc4`='你好。', `MaleText_loc5`='我的榮幸。', `MaleText_loc7`='Encantado.' WHERE `ID`=75179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 수 없습니다! 그래서 제가 여기 와 있는 거죠.', `MaleText_loc4`='我们不知道！所以我才会到这里来。', `MaleText_loc5`='我們也不知道!這正是我來的原因。', `MaleText_loc7`='¡No lo sabemos! Es por eso que estamos aquí.' WHERE `ID`=75180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 시간이 얼어붙어 있습니다. 섬에 생명이 가득한데, 그 무엇도 변하진 않죠.', `MaleText_loc4`='这里的时间是凝固的。岛上充满生机，却又亘古不变。', `MaleText_loc5`='時間在這裡凍結了。整座島生機盎然，卻從不改變。', `MaleText_loc7`='El tiempo no transcurre en este lugar. La isla está llena de vida, sin embargo, nunca cambia.' WHERE `ID`=75181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근까지도 이 섬은 안개에 가려져 있었습니다. 어쩌다 여기에 좌초하게 된 이들은, 시간의 흐름에 영향을 받지 않는 자기들만의 화폐를 만들어야만 했지요. 그래야 거래가 가능하니까요.', `MaleText_loc4`='不久前，这里还为迷雾所笼罩。那些被迫滞留于此的居民只能自行铸造能够抵抗时间扭曲的货币。只有这样，才能进行交易。', `MaleText_loc5`='這座島之前被迷霧遮蔽。困在這裡的居民不得不製造他們自己不受時間扭曲影響的貨幣。這是唯一能讓交易可行的方法。', `MaleText_loc7`='Hasta hace poco, este lugar estuvo perdido en las nieblas. Los pocos habitantes que quedaron varados en este lugar tuvieron que acuñar su propia moneda, inmune a la distorsión en el tiempo. Es la única forma en que pueden comerciar.' WHERE `ID`=75182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 그렇습니다! 영원의 섬은 시간의 흐름을 일직선으로 보는 사고 방식을 넘어선 일들이 가능하다는 증거죠.', `MaleText_loc4`='我也是！永恒岛的存在证明许多原本被视为疯狂的设想是完全有可能实现的。', `MaleText_loc5`='我也是!永恆之島的存在證明了許多東西有可能跳脫單線性思考的束縛。', `MaleText_loc7`='¡A mí también! La existencia de la Isla Intemporal es la prueba de que muchas cosas más allá de los límites del pensamiento lineal son posibles.' WHERE `ID`=75183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니다. 대격변은 시간의 길과 저희 용군단의 연결을 영원히 바꾸었죠.', `MaleText_loc4`='确实。在大灾变之后，青铜龙军团与时间流的联系彻底改变了。', `MaleText_loc5`='是的。在大災變之後，我們軍團對時間之道的連結永遠地改變了。', `MaleText_loc7`='Claro. Luego del Cataclismo, mi conexión de vuelo con los portales del tiempo cambió para siempre.' WHERE `ID`=75184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 찰흙을 주무르듯 시간을 원하는 모습으로 만들 수 있다면? 무엇이 가능할까요? 우리가 어떤 세상을 만들 수 있을까요?', `MaleText_loc4`='如果能像捏泥巴一样塑造时间，那会怎么样？历史会变成什么样？我们能创造出怎样的新世界？', `MaleText_loc5`='如果時間能像黏土一樣塑造會如何呢?有多少的可能性?我們能創造怎樣的新世界?', `MaleText_loc7`='¿Qué pasaría si se pudiera moldear el tiempo como si fuera una bola de arcilla? ¿Qué posibilidades nos depararían? ¿Qué mundos nuevos podríamos crear?' WHERE `ID`=75185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s|1이;가; |cFFF00000|Hspell:142879|h[피의 분노]|h|r에 돌입합니다!', `MaleText_loc4`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s进入了|cFFF00000|Hspell:142879|h[血之怒]|h|r状态！', `MaleText_loc5`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s進入|cFFF00000|Hspell:142879|h[血性之怒]|h|r狀態!', `MaleText_loc7`='|TInterfaceIcons
acial_orc_berserkerstrength.blp:20|t¡%s entra en una |cFFF00000|Hspell:142879|h[Ira sangrienta]|h|r!' WHERE `ID`=75186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s의 |cFFF00000|Hspell:142879|h[피의 분노]|h|r가 멈춥니다!', `MaleText_loc4`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s的|cFFF00000|Hspell:142879|h[血之怒]|h|r消退了！', `MaleText_loc5`='|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s的|cFFF00000|Hspell:142879|h[血性之怒]|h|r效果消失!', `MaleText_loc7`='|TInterfaceIcons
acial_orc_berserkerstrength.blp:20|t¡La |cFFF00000|Hspell:142879|h[Ira sangrienta]|h|r de %s amaina!' WHERE `ID`=75189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 놈들! 이 항구는 이미 용아귀 부족의 것이다! 배와 함께 불탈 준비나 해라!', `FemaleText_loc4`='蠢货！这里已经被龙喉氏族控制了！你们将和这些船只一起葬身火海！', `FemaleText_loc5`='蠢貨!這個碼頭在龍喉的掌控之下!你們的船艦會隨你們一起燃燒!', `FemaleText_loc7`='¡Tontos!  ¡Estos muelles están bajo el control de los Faucedracos!  ¡Sus naves arderán y ustedes arderán con ellas!' WHERE `ID`=75190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항구에 지원군을 더 보내! 록타르 오가르!', `FemaleText_loc4`='增援部队快去码头！Lok''tar Ogar！', `FemaleText_loc5`='增援碼頭!Lok''tar Ogar!', `FemaleText_loc7`='¡Refuercen los muelles!  ¡Lok''tar Ogar!' WHERE `ID`=75191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이겼다고 생각하나? 우린 오크다! 가장 위대한 대족장이 지휘하는 순수 혈통이지! 너희들의 피가 이 바다를 적시리라!', `FemaleText_loc4`='你们自以为能赢？我们是兽人！是史上最伟大的酋长领导下的纯血兽人！你们的鲜血将染红这片海湾！', `FemaleText_loc5`='你以為你們贏了嗎?我們是獸人!純正的血統，由史上最強的大酋長率領我們!你們的血會染紅這個港灣!', `FemaleText_loc7`='¿Creen que ganaron? ¡Somos orcos! ¡Puros de sangre, comandados por el Jefe de Guerra más grande de la historia! ¡Su sangre manchará esta bahía!' WHERE `ID`=75192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용아귀 부족 용사들이여! 항구를 탈환하고 적을 바다로 몰아내라! 헬스크림 님과 진정한 호드를 위하여!', `FemaleText_loc4`='龙喉氏族，夺回码头，把他们赶到海里去！以地狱咆哮和正统部落的名义！', `FemaleText_loc5`='龍喉氏族，奪回碼頭，把他們推進海裡!以地獄吼及正統部落之名!', `FemaleText_loc7`='¡Clan Faucedraco, recuperen los muelles y empújenlos hacia el mar! ¡En el nombre de Grito Infernal y la verdadera Horda!' WHERE `ID`=75193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 분대, 진격!', `FemaleText_loc4`='下一队，前进！', `FemaleText_loc5`='下一隊，前進!', `FemaleText_loc7`='Siguiente escuadrón: ¡empujen la línea, avancen!' WHERE `ID`=75194;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용아귀 용사들아, 진격하라!', `FemaleText_loc4`='龙喉氏族，前进！', `FemaleText_loc5`='龍喉氏族，前進!', `FemaleText_loc7`='Faucedracos: ¡avancen!' WHERE `ID`=75195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림 님을 위하여!', `FemaleText_loc4`='为了地狱咆哮！', `FemaleText_loc5`='為了地獄吼!', `FemaleText_loc7`='¡Por Grito Infernal!' WHERE `ID`=75196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정한 호드를 위해!', `FemaleText_loc4`='为了正统部落！', `FemaleText_loc5`='為了正統的部落!', `FemaleText_loc7`='¡Por la verdadera Horda!' WHERE `ID`=75197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 탑에 침투했다. 쓰러뜨려라!', `FemaleText_loc4`='他们攻破了塔楼，摧毁它！', `FemaleText_loc5`='他們奪下哨塔了，把它打下來!', `FemaleText_loc7`='Penetraron la torre, ¡derrúmbenla!' WHERE `ID`=75198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 영예로운 죽음을 맞이할 것이다!', `FemaleText_loc4`='那就让他们光荣地战死吧！', `FemaleText_loc5`='他們會在戰鬥中光榮地死去!', `FemaleText_loc7`='¡Entonces morirán con honor en combate!' WHERE `ID`=75199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공성 무기로 탑을 공격해서 놈들을 산 채로 매장시켜라!', `FemaleText_loc4`='让攻城武器攻击那座塔，把他们都活埋了！', `FemaleText_loc5`='把攻城武器轉向，把塔打下來，活埋他們!', `FemaleText_loc7`='¡Apunten las armas de asedio hacia esa torre y entiérrenlos vivos!' WHERE `ID`=75200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갈라크라스, 불 비를 내려라!', `FemaleText_loc4`='迦拉卡斯，喷火烧死他们！', `FemaleText_loc5`='葛拉卡斯，燒死他們!', `FemaleText_loc7`='¡Galakras, báñalos con fuego!' WHERE `ID`=75201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아!', `FemaleText_loc4`='啊啊啊！！', `FemaleText_loc5`='啊啊!!!', `FemaleText_loc7`='¡Aaaaaaaah!' WHERE `ID`=75202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='국왕 폐하! 지원군을 데려왔습니다.', `FemaleText_loc4`='国王陛下！我带来了援军。', `FemaleText_loc5`='大君主!我帶援軍來了。', `FemaleText_loc7`='¡Su Majestad! Traje refuerzos.' WHERE `ID`=75203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항구로 차원문을 열게요. 공격대가 다 들어갈 만큼 크게요.', `FemaleText_loc4`='我可以打开通向码头的传送门——足以让突击队通过。', `FemaleText_loc5`='我可以開一道傳送門去碼頭，足以讓一個突擊小隊通過。', `FemaleText_loc7`='Puedo abrir un portal a los muelles para que pase un equipo de asalto.' WHERE `ID`=75204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용아귀 부족이 대족장을 지원하네요.', `FemaleText_loc4`='龙喉氏族在支持着酋长。', `FemaleText_loc5`='龍喉氏族支持這位大酋長。', `FemaleText_loc7`='Los Faucedraco apoyan al Jefe de Guerra.' WHERE `ID`=75205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄청난 화력이 필요할 거예요.', `FemaleText_loc4`='我们现在急需火力支援。', `FemaleText_loc5`='我們需要很強的火力才行。', `FemaleText_loc7`='Vamos a necesitar artillería pesada.' WHERE `ID`=75206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 와요!', `FemaleText_loc4`='他们来了！', `FemaleText_loc5`='他們來了!', `FemaleText_loc7`='¡Aquí vienen!' WHERE `ID`=75207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주세요!', `FemaleText_loc4`='帮帮我！', `FemaleText_loc5`='幫我!', `FemaleText_loc7`='¡Ayúdenme!' WHERE `ID`=75208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오... 감사해요!', `FemaleText_loc4`='噢——谢谢！', `FemaleText_loc5`='噢...謝謝你!', `FemaleText_loc7`='Ah... ¡Gracias!' WHERE `ID`=75209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋지군요!', `FemaleText_loc4`='打得好！', `FemaleText_loc5`='打得漂亮!', `FemaleText_loc7`='¡Buen tiro!' WHERE `ID`=75210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잴라가 공성무기로 탑을 부수려 해요!', `FemaleText_loc4`='她将攻城武器对准了自己的塔楼！', `FemaleText_loc5`='她要用攻城武器打自己的塔!', `FemaleText_loc7`='¡Está apuntando sus armas de asedio hacia sus propias torres!' WHERE `ID`=75211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하나는 처치했어요!', `FemaleText_loc4`='干掉一个，还剩一个！', `FemaleText_loc5`='解決一個，還有一個!', `FemaleText_loc7`='¡Cayó una y queda otra!' WHERE `ID`=75212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어요! 원시비룡이 추락하네요!', `FemaleText_loc4`='成功了！始祖龙掉下来了！', `FemaleText_loc5`='成功了!元龍正在墜落!', `FemaleText_loc7`='¡Funcionó!  ¡El Protodraco está cayendo!' WHERE `ID`=75213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈어요!', `FemaleText_loc4`='我们成功了！', `FemaleText_loc5`='我們成功了!', `FemaleText_loc7`='¡Lo hemos logrado!' WHERE `ID`=75214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나머지 병력이 상륙할 수 있게 항구를 사수하겠어요. 오그리마 정문으로 가는 길을 따라가서 볼진의 혁명군과 합류하세요.', `FemaleText_loc4`='我们会守住码头，等待后续登陆部队。沿着这条路到奥格瑞玛的城门那里去，找到沃金和他的起义军。', `FemaleText_loc5`='我們會替其他的登陸部隊守住碼頭。去奧格瑪的正門，和沃金及他的反抗軍取得聯繫。', `FemaleText_loc7`='Nosotros protegeremos los muelles hasta que lleguen los grupos que quedan. Sigan el sendero a las puertas de Orgrimmar y busca a Vol''jin y a sus revolucionarios.' WHERE `ID`=75215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈보라를 내릴게요. 적을 유인하세요!', `FemaleText_loc4`='我召唤了暴风雪，把他们引进去！', `FemaleText_loc5`='我召喚了暴風雪，把他們引進去!', `FemaleText_loc7`='¡He conjurado una Ventisca, llévalos hasta ella!' WHERE `ID`=75216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서... 끝이라니...', `FemaleText_loc4`='我……坚持……不住了……', `FemaleText_loc5`='我...不行...了...', `FemaleText_loc7`='No... puedo... seguir...' WHERE `ID`=75217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안! 안 돼! 바리안!', `FemaleText_loc4`='瓦里安！不！瓦里安！', `FemaleText_loc5`='瓦里安!不!瓦里安!', `FemaleText_loc7`='¡Varian! ¡No! ¡Varian!' WHERE `ID`=75218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아있군요! 다행이에요. 도시는 말 그대로 처참해요.', `FemaleText_loc4`='你还活着！很好。城里的街道已经乱作一团了。', `FemaleText_loc5`='你們還活著!很好。街道上十分混亂。', `FemaleText_loc7`='¡Siguen vivos! Bien. Hay caos en las calles de la ciudad.' WHERE `ID`=75219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 우리 거점으로 오고 있어요. 끈질긴 놈들이군요!', `FemaleText_loc4`='库卡隆正在煽动这群乌合之众。他们还不肯投降！', `FemaleText_loc5`='柯爾克隆正在猛攻這個區域。他們還不死心!', `FemaleText_loc7`='Los Kor''kron avanzan hacia este complejo. ¡No se rinden!' WHERE `ID`=75220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 좋은 시간에 와줬군. 볼진의 반란군이 제 역할을 못했다. 우리 군이 공격받고 있지.', `MaleText_loc4`='我们都等得望眼欲穿了。沃金的起义军没有能守住海湾。我们遭到了重创。', `MaleText_loc5`='我們等得望眼欲穿啊。沃金的軍隊無法攻下海灣。我們受到了重創。', `MaleText_loc7`='Es un alivio ver a tus héroes. La rebelión de Vol''jin no pudo asegurar la bahía. Nos están masacrando.' WHERE `ID`=75221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리하시오. 만을 확보하면 우리가 상륙하지. 용사들이여, 그대들을 믿는다.', `MaleText_loc4`='去吧！等我们肃清这里，就能顺利登陆了。勇士们，我就指望你们了。', `MaleText_loc5`='就這麼辦!等肅清那裡我們就登陸。勇士們，就靠你們了。', `MaleText_loc7`='¡Hazlo! Cuando el área esté despejada, haremos el desembarque. Cuento con ustedes.' WHERE `ID`=75222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 상륙 부대, 정렬! 보병대, 앞으로!', `MaleText_loc4`='干得好！登陆小队，集合！步兵打头阵！', `MaleText_loc5`='做得好!登陸小隊，集合!步兵打前鋒!', `MaleText_loc7`='¡Bien hecho! Grupos de desembarque: ¡formen filas! ¡Los soldados al frente!' WHERE `ID`=75223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 정찰병들이 보고하더군. "전쟁군주 잴라." 그녀의 원시비룡만 끌어내리면 나머지 용아귀 부족은 흩어질 것이오.', `MaleText_loc4`='是的。斥候们已经发现了。“督军扎伊拉”。只要把她的始祖龙打下来，龙喉氏族就会崩溃。', `MaleText_loc5`='是的。我的斥候已經探查清楚了。「督軍札伊拉」。把她的元龍打下來，龍喉氏族就會潰散。', `MaleText_loc7`='Sí. Mis exploradores aprendieron todo sobre esta. La “Señora de la guerra Zaela”. Derriben a su Protodraco y el resto de los Faucedraco se derrumbarán.' WHERE `ID`=75224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑을 점령하라! 대공포를 돌려 원시비룡에게 화력을 집중하라!', `MaleText_loc4`='占领那些塔楼！调转炮口，把她给我从天上打下来！', `MaleText_loc5`='佔領那些塔!把對空砲台轉過去，把她從天上打下來!', `MaleText_loc7`='¡Comanden esas torres! ¡Den vuelta a la artillería antiaérea y derríbenla del cielo!' WHERE `ID`=75225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들 중 몇몇은 상륙지를 지키도록.', `MaleText_loc4`='你们得留下一部分人，守住登陆区域。', `MaleText_loc5`='你們得留下一部分的人守住登陸的區域。', `MaleText_loc7`='Algunos deberían quedarse y proteger la zona de desembarque.' WHERE `ID`=75226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='견딜 수가 없다!', `MaleText_loc4`='我不能再受伤了！', `MaleText_loc5`='我快撐不下去了!', `MaleText_loc7`='¡No puedo soportar mucho más!' WHERE `ID`=75227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!' WHERE `ID`=75228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 강력한 한방이군!', `MaleText_loc4`='沉重的一击！', `MaleText_loc5`='好強的一擊!', `MaleText_loc7`='¡Qué golpe tan poderoso!' WHERE `ID`=75229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잴라가 공성무기를 더 배치했다!', `MaleText_loc4`='她正在调集更多的攻城武器！', `MaleText_loc5`='她在調動更多的攻城武器!', `MaleText_loc7`='¡Acaba de ordenar más armas de asedio!' WHERE `ID`=75230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지도 처치했다! 대포를 발사하라!', `MaleText_loc4`='两个都完蛋了！开炮！', `MaleText_loc5`='兩個都解決了!立刻開砲!', `MaleText_loc7`='¡Acabamos con ambas! ¡Disparen los cañones!' WHERE `ID`=75231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 바로 덤빌 것이다. 조심하라!', `MaleText_loc4`='它向我们冲过来了。小心！', `MaleText_loc5`='牠正往我們的方向墜落。小心牠的嘴!', `MaleText_loc7`='Sí, pero si vienen hacia nosotros. ¡Cuidado con las fauces!' WHERE `ID`=75232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 덩치만 큰 녀석이군...', `MaleText_loc4`='哈！他们要是再大一点……', `MaleText_loc5`='哈哈哈!這麼大隻又怎麼樣...', `MaleText_loc7`='¡Ja ja ja! Cuanto más grandes son…' WHERE `ID`=75233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 아직 약속을 기억하는지 지켜봐야겠군.', `MaleText_loc4`='让我们看看，他到底能不能完成自己的承诺。', `MaleText_loc5`='讓我們看看他有沒有做到他承諾的那些事情。', `MaleText_loc7`='Veremos si ha podido respetar su parte del trato.' WHERE `ID`=75234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게로 놈들을 끌어들여라!', `MaleText_loc4`='把他们引到我的剑下来！', `MaleText_loc5`='把他們引到我的刀鋒之下!', `MaleText_loc7`='¡Acérquenlos al filo de mi espada!' WHERE `ID`=75235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나! 이 쓰레기 같은 오크놈이!', `MaleText_loc4`='吉安娜！你这个兽人杂种！', `MaleText_loc5`='珍娜!你們這些獸人雜種!', `MaleText_loc7`='¡Jaina!  ¡BASURA ORCA!' WHERE `ID`=75236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인...', `MaleText_loc4`='安度因……', `MaleText_loc5`='不...安杜因...', `MaleText_loc7`='No…Anduin…' WHERE `ID`=75237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진의 반란군이 지금 한창 전투중인가보군.', `MaleText_loc4`='沃金的起义军被压制了，但我们守住了阵线。', `MaleText_loc5`='我們守住了戰線，但沃金的軍隊正受到猛攻。', `MaleText_loc7`='Los rebeldes de Vol''jin están recibiendo una paliza, pero nuestra formación se mantiene. ' WHERE `ID`=75238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이곳을 사수하겠다. 전방을 정찰하고 가로쉬의 위치를 노출시킬 방법을 모색해봐라.', `MaleText_loc4`='我们得留下一些部队。斥候去侦察一下，看能不能把加尔鲁什揪出来。', `MaleText_loc5`='我們在這裡留些部隊。探查前方看你能不能把卡爾洛斯從暗處引出來。', `MaleText_loc7`='Armaremos un puesto aquí con algunas tropas. Avancen y exploren a ver si podemos hacer que Garrosh salga de su escondite.' WHERE `ID`=75239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 탑에는 아군도 있습니다!', `MaleText_loc4`='那塔里面还有我们的部队！', `MaleText_loc5`='還有我們的人在塔裡!', `MaleText_loc7`='¡Todavía hay fuerzas nuestras en esa torre!', `FemaleText_loc1`='하지만, 탑에는 아군도 있습니다!', `FemaleText_loc4`='那塔里面还有我们的部队！', `FemaleText_loc5`='還有我們的人在塔裡!', `FemaleText_loc7`='¡Todavía hay fuerzas nuestras en esa torre!' WHERE `ID`=75240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만의 방비가 견고하군! 우리가 밀리고 있소!', `MaleText_loc4`='刃拳海湾的防御增强了——这简直是屠杀！', `MaleText_loc5`='刃拳海灣的防禦增強了...太陽之井啊，這是屠殺!', `MaleText_loc7`='La Bahía de Garrafilada está fortificada... ¡por La Fuente del Sol, nos están masacrando!' WHERE `ID`=75241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 항구로 가서 수비군을 처치하시오. 이 학살을 끝내야 하오!', `MaleText_loc4`='英雄们。快传送到码头，摧毁他们的海防工事，阻止这场杀戮。', `MaleText_loc5`='英雄們。傳到碼頭並摧毀他們的防禦工事。阻止這場殺戮。', `MaleText_loc7`='Diríjanse a los muelles y derroten a sus defensas costeras. Detengan esta matanza.' WHERE `ID`=75242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스! 우리 동족의 시체를 건드리면 내 그대와 먼저 담판을 짓겠소.', `MaleText_loc4`='希尔瓦娜斯！不准碰我们的尸体，否则我现在就干掉你。', `MaleText_loc5`='希瓦娜斯!你敢碰我們的死者，我現在就對你不客氣。', `MaleText_loc7`='¡Sylvanas! Deja nuestros cadáveres en paz o yo mismo me encargaré de ti aquí y ahora.' WHERE `ID`=75243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...뭐, 그건 당신과 얼라이언스 사이의 문제지 않겠소?', `MaleText_loc4`='……呃，那是你和联盟之间的事，不是吗？', `MaleText_loc5`='...呃，我想那是你跟聯盟之間的事了，對吧?', `MaleText_loc7`='Bueno, supongo que eso queda entre tú y la Alianza, ¿no?' WHERE `ID`=75244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 했소. 선봉대가 성공적으로 상륙했군.', `MaleText_loc4`='干得好。第一纵队已经成功登陆了。', `MaleText_loc5`='很好，第一梯隊已經登陸。', `MaleText_loc7`='Bien hecho. La primera brigada ha tocado tierra.' WHERE `ID`=75245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전략을 쓰면 되오, 여군주여. 해안의 수비 시설을 이용하는 거지.', `MaleText_loc4`='要用战术，黑暗女王。我们得重新布置海防工事。', `MaleText_loc5`='用戰術啊，黑暗女王。我們得重新布置海岸的防禦。', `MaleText_loc7`='Estrategia, Dama Oscura. Tenemos que reforzar las defensas costeras.' WHERE `ID`=75246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 탑으로 가시오. 원시비룡에 화력을 집중해서 놈을 끌어내리시오!', `MaleText_loc4`='英雄们，占领那些塔楼，把枪口对准那条始祖龙，把它打下来！', `MaleText_loc5`='英雄們，把塔拿下來，把砲台對準元龍，把牠從天上打下來!', `MaleText_loc7`='Héroes: ¡tomen las torres, apunten las armas hacia el Protodraco y derríbenlo!' WHERE `ID`=75247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 명은 이곳에서 해안을 지켜야 할 거요.', `MaleText_loc4`='你们得留一部分人守住滩头阵地。', `MaleText_loc5`='你們得留一些人守住灘頭堡。', `MaleText_loc7`='Algunos tendrán que quedarse a defender la playa.' WHERE `ID`=75248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요하오!', `MaleText_loc4`='我需要帮助！', `MaleText_loc5`='我需要幫助!', `MaleText_loc7`='¡Requiero asistencia!' WHERE `ID`=75249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 좀 낫군.', `MaleText_loc4`='啊，这下好多了。', `MaleText_loc5`='啊，好多了。', `MaleText_loc7`='Ah, mucho mejor.' WHERE `ID`=75250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제법이군!', `MaleText_loc4`='漂亮的一击！', `MaleText_loc5`='令人讚嘆!', `MaleText_loc7`='¡Impresionante!' WHERE `ID`=75251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잴라가 탑을 공격하고 있소!', `MaleText_loc4`='看来她要攻击自己的塔楼了！', `MaleText_loc5`='看來她正在攻擊自己的塔!', `MaleText_loc7`='¡Parece que ataca a sus propias torres!' WHERE `ID`=75252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈은 잡았군!', `MaleText_loc4`='我们已经成功一半了！', `MaleText_loc5`='我們搞定一半了!', `MaleText_loc7`='¡Estamos a la mitad del camino!' WHERE `ID`=75253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났군! 이 먼지를 언제 다 털어내지?', `MaleText_loc4`='真不容易！看来我得换身衣服了。', `MaleText_loc5`='終於!這場戰鬥真是讓人終生難忘。', `MaleText_loc7`='¡Al fin!  Nunca terminaré de sacudirme todo este polvo de mi ropa.' WHERE `ID`=75254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칭찬으로 받아들이지. 일단은 우리는 항구에서 병력을 모으겠소. 그대들은 볼진이 있는 오그리마 정문으로 가시오.', `MaleText_loc4`='谢谢你的赞美。我们得守住码头，指挥部队。沃金应该就在奥格瑞玛的城门前等你们。', `MaleText_loc5`='我姑且當這是一種讚美。我們繼續守住碼頭並指揮大局。沃金應該在奧格瑪的城門口等你。', `MaleText_loc7`='Lo tomaré como un cumplido.  Nosotros protegeremos los muelles por ahora y comandaremos a las fuerzas. Vol''jin deberá estar esperándote en las puertas de Orgrimmar.' WHERE `ID`=75255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불기둥을 일으키겠소. 놈들을 유인하시오!', `MaleText_loc4`='我正在召唤烈焰风暴，把他们引进去！', `MaleText_loc5`='我正要召喚烈焰風暴，把他們引進去!', `MaleText_loc7`='¡Invocaré un Fogonazo, llévalos hasta él!' WHERE `ID`=75256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이.. 피는... 뭐지?', `MaleText_loc4`='这……血……是从哪儿来的？', `MaleText_loc5`='這...這些血是哪來的...?', `MaleText_loc7`='¿De... de dónde sale esta sangre?' WHERE `ID`=75257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 참, 여군주님 체면이 말이 아니군.', `MaleText_loc4`='噢，天呐，我们的黑暗女王怎么了？', `MaleText_loc5`='好，咱們的黑暗女王怎麼啦?', `MaleText_loc7`='Oh, no, ¿qué le ocurre a nuestra Dama Oscura?' WHERE `ID`=75258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 네 동족을 되살릴 수 있다. 그들은 다시 싸울 수 있겠지.', `FemaleText_loc4`='我能复活死者，摄政王，让你的游侠重返战场。', `FemaleText_loc5`='我可以讓你的死者復生，攝政王。你的遊俠能再度作戰。', `FemaleText_loc7`='Yo puedo hacer caminar a sus muertos, Señor Regente. Sus soldados pueden volver a pelear.' WHERE `ID`=75259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='결단력이 부족하군. 인간들의 시체는 상관 없겠지?', `FemaleText_loc4`='可惜啊，你真是缺乏奉献精神。那人类的尸体呢？', `FemaleText_loc5`='真遺憾，你沒有奉獻精神。那人類的屍體如何?', `FemaleText_loc7`='Lamento tu falta de compromiso. ¿Y qué hay de los cadáveres humanos? ' WHERE `ID`=75260;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나라, 내 천사들이여! 너희 비명으로 오그리마를 공포에 빠뜨려라!', `FemaleText_loc4`='来吧，我的天使们！用尖叫声让奥格瑞玛的街道颤栗吧！', `FemaleText_loc5`='起身吧，天使們!讓你們恐怖的尖嘯迴盪在奧格瑪的街道上!', `FemaleText_loc7`='¡Levántense, mis ángeles! ¡Que sus gritos llenen de terror las calles de Orgrimmar!' WHERE `ID`=75261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬가 이번에는 정말 단단히 준비했군. 그래도 지붕에 가시가 더 많을 줄 알았는데.', `FemaleText_loc4`='加尔鲁什真是豁出去了，对吧？说实话，我本以为要多费一些手脚的。', `FemaleText_loc5`='卡爾洛斯已經沒招了，對吧?說真的，我原本以為會更麻煩的。', `FemaleText_loc7`='Garrosh dio todo de sí esta vez, ¿no?  Aunque, sinceramente, esperaba más pinchos.' WHERE `ID`=75262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용아귀 부족이 가로쉬를 돕나 보군.', `FemaleText_loc4`='看来龙喉氏族把宝押在加尔鲁什身上了。', `FemaleText_loc5`='看來龍喉已經跟卡爾洛斯同流合污了。', `FemaleText_loc7`='Veo que los Faucedracos unieron sus fuerzas con Garrosh.' WHERE `ID`=75263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 화살만으로는 저 괴수를 쏘아 내릴 수 없다.', `FemaleText_loc4`='光凭我的箭没法把那头怪物打下来。', `FemaleText_loc5`='光靠我的弓箭沒有辦法殺死那個怪物。', `FemaleText_loc7`='No podré derribar a esa monstruosidad solo con mis flechas.' WHERE `ID`=75264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 계집을 당장 끌어내려라. 내가 친히 그녀의 목을 죌 것이다.', `FemaleText_loc4`='快把她打下来，然后我要活活掐死她。', `FemaleText_loc5`='趕快把她弄下來，讓我用手掐死她。', `FemaleText_loc7`='Derríbenla rápidamente para que pueda apretar su cuello con mis manos.' WHERE `ID`=75265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 쓰러지지 않는다. 지금은 안 돼!', `FemaleText_loc4`='此时此地，我是不会倒下的！', `FemaleText_loc5`='我不能倒下，絕不!', `FemaleText_loc7`='¡No caeré! ¡Aquí no! ¡Ahora no!' WHERE `ID`=75266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기분이 한층 나아졌군.', `FemaleText_loc4`='我已经好多了。', `FemaleText_loc5`='我感到好多了。', `FemaleText_loc7`='Ya me siento mejor.' WHERE `ID`=75267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대담하군.', `FemaleText_loc4`='勇敢的一击。', `FemaleText_loc5`='勇敢的一擊。', `FemaleText_loc7`='Un movimiento decisivo.' WHERE `ID`=75268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잴라가 다시 탑을 공격한다.', `FemaleText_loc4`='她又去攻击塔楼了。', `FemaleText_loc5`='她又在攻擊塔了。', `FemaleText_loc7`='Está atacando las torres otra vez.' WHERE `ID`=75269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 위로 떨어지고 있다는 건 알고 있나?', `FemaleText_loc4`='你也发现我们就在它下边，对吧？', `FemaleText_loc5`='你有注意到我們在牠的正下方，對吧?', `FemaleText_loc7`='Te das cuenta de que estamos justo debajo de él, ¿no?' WHERE `ID`=75270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 아직 살아있나? 아쉽군. 넌 정말로 매력적인 언데드가 되었을 텐데 말이야.', `FemaleText_loc4`='噢，你还活着呢？我还真希望你死掉。你的尸体一定很迷人。', `FemaleText_loc5`='噢，你還在啊?我本來有點希望你會死掉。你的屍體一定很帥。', `FemaleText_loc7`='Ah, ¿sigues aquí?  Tenía la esperanza de que hubieras muerto.  Serías un cadáver atractivo.' WHERE `ID`=75271;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 안 죽었다면.', `FemaleText_loc4`='如果他还没死的话。', `FemaleText_loc5`='哼!如果他還活著的話。', `FemaleText_loc7`='Si todavía no ha muerto.' WHERE `ID`=75272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음의 소나기가 몰아친다! 놈들을 유인하라!', `FemaleText_loc4`='死亡已经逼近！让他们偿命吧！', `FemaleText_loc5`='從天而降的死亡來了!把他們引到裡面!', `FemaleText_loc7`='¡Pronto lloverá muerte! ¡Tráiganlos a su destino!' WHERE `ID`=75273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로르테마르가 되살아나면 어떤 표정일지 궁금하군.', `FemaleText_loc4`='我都等不及要看看他被复活后的表情了。', `FemaleText_loc5`='嗯!我等不及要看他的屍首被蹂躪時的表情!我們最好贏這場戰爭!', `FemaleText_loc7`='No puedo esperar a ver la expresión de su rostro cuando dé vida a su cadáver.  ¡Tenemos que ganar esta batalla!' WHERE `ID`=75274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난... 다시... 일어나리라...', `FemaleText_loc4`='我还会……回来的……', `FemaleText_loc5`='我...會...再...起...', `FemaleText_loc7`='Me levantaré... nuevamente…' WHERE `ID`=75275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불을 붙여라! 한 놈도 살려 보내지 마!', `FemaleText_loc4`='点燃导火索！他们休想活着离开这里！', `FemaleText_loc5`='點燃引線!他們休想活著離開這座塔!', `FemaleText_loc7`='¡Enciendan las mechas! ¡Que no salgan de esta torre con vida!' WHERE `ID`=75276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고작 이 정도냐?', `FemaleText_loc4`='你就这点本事吗？', `FemaleText_loc5`='哈哈哈哈哈!你們只有這點本事嗎?', `FemaleText_loc7`='¿Es lo mejor que tienen?' WHERE `ID`=75277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래도 난... 명예롭게... 죽는다...', `FemaleText_loc4`='至少……我是光荣地……战死……', `FemaleText_loc5`='至少...我是光榮...戰死...', `FemaleText_loc7`='Al menos... he de morir... con honor.' WHERE `ID`=75278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 탑을 차지하겠다고? 하하...', `MaleText_loc4`='你们竟敢攻击我的塔楼？哈哈哈……', `MaleText_loc5`='你們竟敢攻擊我的塔?哈哈哈...', `MaleText_loc7`='¿Se atreven a tomar mi torre?  Jajaja…' WHERE `ID`=75279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 용아귀 부족, 용의 피가 흐르는 호드의 주먹이다!', `MaleText_loc4`='我是龙喉兽人，我是巨龙血脉、部落之拳！', `MaleText_loc5`='我屬於龍喉氏族，身懷巨龍之血，手為部落之拳!', `MaleText_loc7`='¡Soy Faucedraco, soy la sangre del Dragón y el puño de la Horda!' WHERE `ID`=75280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는... 이 전쟁을... 이길 수 없다...', `MaleText_loc4`='你们……休想赢得……这场战争……', `MaleText_loc5`='你們...不可能...贏這場戰爭...', `MaleText_loc7`='No pueden... ganar... esta guerra…' WHERE `ID`=75281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아버지가 공책을 어디 두셨을까나? 분명 여기 어딘가 있을 텐데...', `FemaleText_loc4`='我父亲把他的笔记放在哪儿了？肯定就在这附近……', `FemaleText_loc5`='我的父親把筆記放哪去了?應該在這附近才對...', `FemaleText_loc7`='¿Qué hizo mi padre con sus notas? Tienen que estar por alguna parte...' WHERE `ID`=75282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비밀 재료가 없는데 어떻게 비밀 재료 국수를 만들겠어?', `FemaleText_loc4`='没有秘密配方，叫我怎么做秘制面汤啊？', `FemaleText_loc5`='如果沒有神秘食材，我要怎麼煮含有神秘食材的湯?', `FemaleText_loc7`='¿Cómo quieren que haga la sopa del ingrediente secreto sin el ingrediente secreto?' WHERE `ID`=75283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망할. 가문의 비법을 모르는데 어떻게 국수 수레를 운영하란 거야?', `FemaleText_loc4`='真该死，没有了祖传秘方，我要怎么把祖传的面摊经营下去啊？', `FemaleText_loc5`='可惡，我如果不知道我們家族食譜，我要怎麼經營家族的麵攤?', `FemaleText_loc7`='¡Se supone que me tengo que encargar del carrito de fideos familiar y ni siquiera me sé la receta!' WHERE `ID`=75284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국수 먹고 싶은 사람?', `MaleText_loc4`='谁还要汤！', `MaleText_loc5`='誰想喝湯!', `MaleText_loc7`='¿Quién quiere sopa?' WHERE `ID`=75285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 새로 온 손님들이군. 잘 왔네!', `MaleText_loc4`='啊，有新客人来了，欢迎欢迎！', `MaleText_loc5`='啊，新顧客。歡迎!', `MaleText_loc7`='Ah, clientes nuevos. ¡Bienvenidos!' WHERE `ID`=75286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있는 국수의 비결은 튼튼하고 굵은 면발에서 시작되지!', `MaleText_loc4`='做好汤面的诀窍就在于筋道的面条！', `MaleText_loc5`='美味湯麵的秘訣就是有嚼勁的粗麵!', `MaleText_loc7`='¡El primer secreto de una buena sopa de fideos son unos fideos gruesos y hermosos!' WHERE `ID`=75287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국물은 영혼까지 데울 수 있게 모락모락 김이 날 정도로 뜨거워야 한다네!', `MaleText_loc4`='面汤一定要烧得滚烫，才能温暖食客的心！', `MaleText_loc5`='湯一定要滾燙，喝下去才能暖心。', `MaleText_loc7`='¡La sopa tiene que estar tan caliente que la sientas en el alma!' WHERE `ID`=75288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 가는가? 또 오게나!', `MaleText_loc4`='这就要走了吗？下次再来！', `MaleText_loc5`='這麼快就要走了?一定要再來喔!', `MaleText_loc7`='¿Ya te vas? ¡Vuelve cuando quieras!' WHERE `ID`=75289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 가는가? 친구들한테 린 가문의 국수 수레를 찾아서 비밀 재료 국수를 맛보라고 전해 주게.', `MaleText_loc4`='这就要走了吗？请告诉你的朋友，务必要来林家面摊尝尝我们的秘制汤面。', `MaleText_loc5`='這麼快就要走了?記得告訴你的朋友，經過這裡時別忘了來一碗林家秘傳湯麵。', `MaleText_loc7`='¿Ya te vas? Diles a tus amigos que se acerquen al carrito de fideos familiar Lin para probar nuestra sopa de fideos del ingrediente secreto.' WHERE `ID`=75290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 문을 닫을 때가 됐나? 챠오웨이가 기다리니 집에나 가야겠군.', `MaleText_loc4`='已经要关门了？好吧，我得回家去看潮薇了。', `MaleText_loc5`='已經到關店時間了嗎?好吧，我想我應該回家去找巧蔚了。', `MaleText_loc7`='¿Ya es hora de cerrar? Bueno, volveré a casa con Chao Wei.' WHERE `ID`=75291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 건투를 빈다. 함께 전투를 치를 수 있어 영광이다.', `MaleText_loc4`='祝你们好运，英雄们。很荣幸能和你们并肩战斗。', `MaleText_loc5`='英雄，一路順風。跟你並肩作戰真是莫大的榮幸。', `MaleText_loc7`='Buena suerte, héroes. Será un honor luchar con ustedes en esta batalla.' WHERE `ID`=75292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티에 오신 것을 환영합니다, $n 님. 부하들을 데리고 싸울 땐 어떻게 해야 하는지 알고 싶으십니까?', `MaleText_loc4`='欢迎来到比武大会，$n。你想学学怎么指挥宠物战斗吗？', `MaleText_loc5`='歡迎加入我們的行列，$n。你想學習如何和手下們對戰嗎?', `MaleText_loc7`='$gBienvenido:Bienvenida; a la fiesta, $n. ¿Quieres que te dé una lección sobre el combate con esbirros?' WHERE `ID`=75293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 감당할 수만 있다면, 내 제대로 된 전투를 맛보여 주지.', `MaleText_loc4`='我酝酿着一场真正的战斗，就看你能不能应付了。', `MaleText_loc5`='我已經準備好跟你打一場了，只要你覺得你能應付的來。', `MaleText_loc7`='Si crees estar a la altura, he preparado un combate de lo más refrescante.' WHERE `ID`=75294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 대전은 아제로스에서 본 적 없는 정말 엄청난 구경거리지. 하지만 대부분은 아이가 아버지의 활을 가지고 노는 것처럼 실력이 형편없소. 당신은 어떻소?', `MaleText_loc4`='宠物对战是艾泽拉斯有史以来最棒的游戏，可我见过不少人在战斗中表现得就像三岁小孩儿。你又能好到哪里去呢？', `MaleText_loc5`='寵物戰是艾澤拉斯最有看頭的戰鬥，但我也看過有人如同找到爸爸的十字弓的小孩一樣見獵心喜。那你呢?', `MaleText_loc7`='Los duelos de mascotas son la mayor fuerza de Azeroth, pero algunos la esgrimen como el niño que ha encontrado la ballesta de su padre. ¿Y tú?' WHERE `ID`=75295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 시합은 거의 판다리아 대륙 자체만큼이나 오래됐다네. 많은 이가 여기서 자신의 기개를 시험했지. 자네도 시험해 보겠나?', `MaleText_loc4`='天神比武大会的历史几乎和潘达利亚一样古老。许多人都曾来这里检验自己的勇气。我们可以开始了吗？', `MaleText_loc5`='天尊武道會的歷史幾乎就和潘達利亞一樣久遠，很多人來此試試身手。你也想試試嗎?', `MaleText_loc7`='El Torneo Celestial es casi tan antiguo como la propia Pandaria. Viene mucha gente a poner a prueba su habilidad. ¿Probamos la tuya?' WHERE `ID`=75296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 예쁜 얼굴을 감상하러 오신 건가요, 전투를 벌이러 오신 건가요?', `FemaleText_loc4`='你到底是来欣赏美女还是来打架的？', `FemaleText_loc5`='你是來看我漂亮的臉蛋，還是來找碴的?', `FemaleText_loc7`='¿Has venido a admirar mi belleza o quieres pelea?' WHERE `ID`=75297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 친구들이 나타나기 전엔 내가 동물이랑 잘 지낼 수 있을 거라곤 꿈에도 생각 못 했지. 자, 그럼, 한판 하고 싶나?', `MaleText_loc4`='我从没想过自己会有跟动物交流的天分，直到这些小家伙的出现。那么，你想来打一场吗？', `MaleText_loc5`='直到這些小傢伙出現之前，我都不知道自己對動物還蠻有一套的。那你怎麼說呢，想打一場嗎?', `MaleText_loc7`='Creía que no tenía mano para los animales, pero entonces aparecieron estos pequeñajos. ¿Qué dices? ¿Luchamos?' WHERE `ID`=75298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤 의술사들이 내 수도사들을 애완동물 대전 규정에 맞는 크기로 축소시켰네. 어디 한번 수도사들과 붙어 보겠나?', `MaleText_loc4`='我让一个巨魔巫医把我的武僧们给变小了，以迎合比赛的体型要求。你想跟他们打一场吗？', `MaleText_loc5`='我的武僧們被一個食人妖巫醫變小了，所以他們的身材正好適合參加戰鬥。你想跟他們對戰嗎？', `MaleText_loc7`='Un médico brujo trol encogió a mis monjes, así que cumplen los requisitos de altura del torneo. ¿Quieres enfrentarte a ellos en combate?' WHERE `ID`=75299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 물과 맞서서 패배를 피할 수 있으십니까?', `MaleText_loc4`='你能在活水面前赢得胜利吗？', `MaleText_loc5`='你能否面對源頭活水，避免失敗?', `MaleText_loc7`='¿Eres capaz de enfrentarte al agua viviente y alzarte con la victoria?' WHERE `ID`=75300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다. 운이 좋으시군요. 당신의 선물 상자에 죽은 두더지가 가득하길.', `MaleText_loc4`='你赢了，算你走运。但愿你的礼物盒里装满死老鼠。', `MaleText_loc5`='恭喜你，幸運的贏家。願你的禮物袋裡裝滿死鼴鼠。', `MaleText_loc7`='Enhorabuena por tu victoria. Que tus paquetes de regalo se llenen de topos muertos.' WHERE `ID`=75301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $n. 내가 술 마시는 것만큼이나 솜씨가 좋은걸!', `MaleText_loc4`='干得好，$n。你的战斗力就跟我的酒量一样强！', `MaleText_loc5`='做得好，$n。你打架就像我喝酒一樣猛!', `MaleText_loc7`='Bien hecho, $n. ¡Se te da mejor la lucha que a mí la bebida!' WHERE `ID`=75302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게, 에, 모든 걸 다시 생각해 봐야겠소. 모든 걸!', `MaleText_loc4`='好吧，呃，我得再回顾一下战局。从头想起！', `MaleText_loc5`='嗯，呃...我得重新思考每件事。每件事!', `MaleText_loc7`='Vaya, eh, creo que tengo que replanteármelo todo. ¡Todo!' WHERE `ID`=75303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 자네가 나에게는 이겼지만, 천신에게 승리하려면 온갖 미덕을 모두 발휘해야 할 걸세.', `MaleText_loc4`='今天你战胜了我，但你必须具备一切优良品质才有可能面对至尊天神。', `MaleText_loc5`='你今天打敗我了，但是你需要所有的美德才能跟天尊們交手。', `MaleText_loc7`='Hoy me has derrotado, pero te harán falta todas las virtudes para enfrentarte a los celestiales.' WHERE `ID`=75304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='외로운 늑대가 죽어도 무리는 살아남는 법이지요.', `FemaleText_loc4`='独狼难逃，群狼易生。', `FemaleText_loc5`='孤狼死了，但狼群還活著。', `FemaleText_loc7`='El lobo solitario muere, pero la manda sobrevive.' WHERE `ID`=75305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 언데드 너구리를 어떻게 치유하는 거지?', `MaleText_loc4`='你是怎么给亡灵浣熊治疗的？', `MaleText_loc5`='你到底要怎麼治療一隻亡靈浣熊啊？', `MaleText_loc7`='¿Cómo se supone que hay que sanar a un mapache no-muerto?' WHERE `ID`=75306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 훈련이 더 필요한 것 같군.', `MaleText_loc4`='看来我们还得多练习练习。', `MaleText_loc5`='看樣子我們還得做更多訓練。', `MaleText_loc7`='Parece que nos falta entrenamiento.' WHERE `ID`=75307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격류처럼 사납게 싸우시는군요. 그 물이 영원히 마르지 않길.', `MaleText_loc4`='你战斗起来就像暴怒的河水一样凶猛。但愿你的勇气永不干涸。', `MaleText_loc5`='你的戰鬥就像憤怒的河水一般。希望這條河流不會乾涸。', `MaleText_loc7`='Luchas con la ferocidad de un río bravo. Esperemos que no te alcance la sequía.' WHERE `ID`=75308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 이제부터 특별한 시험을 치를 걸세! 따르는 이들의 기량을 보면 지도자의 지혜를 가늠할 수 있지. 자네의 가르침이 그들에게 진정 감화를 주었는지 보세...', `MaleText_loc4`='欢迎你来参加这一特殊的试炼！领袖的智慧要靠他的追随者来反映。让我们来看看你能否真正激励你的追随者……', `MaleText_loc5`='歡迎來到一個很特別的試煉!領袖的智慧會體現在追隨者的身上。讓我們看看你的訓練是否真的能鼓舞你的追隨者...', `MaleText_loc7`='¡Te doy la bienvenida a una prueba muy especial!  La sabiduría de un líder se refleja en la grandeza de sus seguidores. Veamos si tu entrenamiento realmente inspiró a los que lideras…' WHERE `ID`=75309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 시험에서는 자네의 부하들을 치유할 수 없다네. 훌륭한 지도자라면, 다양한 배경을 지닌 부하 여럿이 하나의 기치 아래 단결하도록 이끌 수 있는 능력이 있어야 하지.', `MaleText_loc4`='在这场试炼当中，你不能治疗自己的宠物。伟大领袖的特质之一就是能够将不同背景的属下团结在同一面旗帜之下。', `MaleText_loc5`='在這場試煉中，你不能治療自己的寵物。偉大領袖的特徵之一，便是將許多不同背景的屬下結合在一面旗幟之下。', `MaleText_loc7`='En esta prueba no podrás sanar a tus mascotas.  Una de las características de un gran líder es la habilidad de liderar a muchos súbditos de muchos distintos orígenes, unidos bajo un mismo estandarte.' WHERE `ID`=75310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 자네는 실력을 갈고닦아 스스로를 증명한 조련사를 여럿 상대하게 될 걸세. 자네도 그만한 실력을 보여 줄 수 있을까? 두고 보겠네! 행운을 빌지!', `MaleText_loc4`='今天，你将面对许多成名已久的驯宠高手。你的宠物是否也能证明你的优秀呢？让我们拭目以待！祝你好运！', `MaleText_loc5`='今天你會碰到許多實力已經受到肯定的訓練師。你的寵物是否也能讓你受到肯定呢?我們來看看吧!祝你好運!', `MaleText_loc7`='Hoy, te enfrentarás a muchos entrenadores que han afinado sus habilidades y se han comprobado dignos. ¿Tus mascotas dirán lo mismo de ti? ¡Pronto lo veremos! ¡Buena suerte!' WHERE `ID`=75311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 부하들을 잘 이끌었군. 판다리아에서 가장 노련하고 권위 있는 조련사들을 꺾었어. 하지만 시험은 아직 끝나지 않았네. 아직 멀었지!', `MaleText_loc4`='啊，你把宠物养得很好，还击败了潘达利亚最老道、最杰出的驯宠师。但试炼，还远未结束！', `MaleText_loc5`='啊，你的寵物培養得很不錯，還擊敗了幾位在潘達利亞最有經驗、最有魅力的訓練師。但是試煉還沒結束，吼吼...還早呢!', `MaleText_loc7`='Ah, has criado bien a tus mascotas y derrotado a algunos de los entrenadores más preparados y carismáticos de Pandaria. Pero la prueba no ha terminado, ¡no, no!' WHERE `ID`=75312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 지혜, 힘, 인내, 그리고 희망의 진정한 현신을 상대하게 될 걸세. 네 천신의 아이들이지! 조심해야 할 거야. 수 세기 동안 볼 수 없었던 힘과 능력을 모두 지니고 있으니.', `MaleText_loc4`='你将要面对智慧、力量、坚毅与希望的真正化身——至尊天神的后裔！请多加小心，他们拥有着失传已久的强大力量和神秘技巧。', `MaleText_loc5`='你即將面對智慧、力量、堅忍、希望的真正象徵 - 四大聖獸的後代!要小心，他們的力量和能力都是前所未見的強悍。', `MaleText_loc7`='Te enfrentarás a los verdaderos pilares de la sabiduría, la fuerza, la fortaleza y la esperanza... ¡los mismísimos hijos de los Celestiales!  Ten cuidado: tienen poderes y habilidades que no se han visto en generaciones.' WHERE `ID`=75313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 용사에게 환호를! 자네는 내면의 힘을 증명했네. 자네가 이끄는 부하들에게서도 그 힘이 보인다네. 이토록 강한 지도자와 함께하다니 운이 좋은 이들이로군. 천신의 가르침이 가장 힘든 시기에 그대의 길을 비추기를.', `MaleText_loc4`='为我们的新冠军欢呼吧！你展现了自己的内在力量，并由你的宠物表现了出来。他们很幸运，能拥有如此强大的领袖。愿至尊天神之道在危急关头指引你。', `MaleText_loc5`='讚美我們新的冠軍!你顯出了自己內心的力量，並投射在你所飼養的寵物身上。他們很幸運能有這麼強的領袖。希望天尊們的教導能在最困苦的時候照亮你的道路。', `MaleText_loc7`='¡Vivan nuestros nuevos valientes!  Has demostrado tu fuerza interna y se refleja en los que preparaste.  Tienen suerte de tener a un líder tan fuerte.  Que las lecciones de los Celestiales iluminen tu camino en los momentos más difíciles.' WHERE `ID`=75314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 지금 전쟁의 시발점에 서있다. 부대 정비를 마치고 내게 신호를 보내면 공격 명령을 내리겠다.', `MaleText_loc4`='我们已经站在了战争的悬崖边上。当你的部队准备好之后，就给我发信号吧，然后我就会下达进攻的指令。', `MaleText_loc5`='我們到了，戰爭一觸即發。等你的部隊準備就緒，就發信號通知我，我會下令攻擊。', `MaleText_loc7`='Nos encontramos al borde de la guerra. Avísame cuando estén preparados y daré la orden de atacar.' WHERE `ID`=75315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 피의 욕망을 채울 때까지 얼마나 더 많은 이가 죽어야 하는지 모르겠소.내가 오그리마의 성벽에 공격을 퍼붓는 건 부끄러우면서도 영광스러운 일이지만,어쨌든 자네 영웅들이 곁에 있어 다행이오.', `MaleText_loc4`='加尔鲁什还要杀害多少人才会满意？能在这里攻击奥格瑞玛的城墙既是我的耻辱，也是我的荣幸，但我很高兴能有你们这样的英雄在我身边。', `MaleText_loc5`='在卡爾洛斯滿足殺戮慾望之前，還要死多少人?我對奧格瑪的突襲可謂榮辱交加，但我很高興有你們這些英雄與我並肩。', `MaleText_loc7`='¿Cuántas muertes hacen falta para saciar la sed de sangre de Garrosh? Siento vergüenza y honor al asaltar las murallas de Orgrimmar. Me alegro de contar con ustedes.' WHERE `ID`=75316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 가장 중요한 곳이오. 공격을 가할 준비가 되면 내게 신호를 보내시오. 아, 그리고 실바나스 여군주님을 엄호해 드리겠소?', `MaleText_loc4`='就是这里了，英雄。当你们做好进攻准备后，就给我发信号吧。噢，还有，别让希尔瓦娜斯女王乱来，好吗？', `MaleText_loc5`='這就是最關鍵的地方，英雄。你必須在準備好進行攻擊時給我一個信號。噢，還有，盡量讓希瓦娜斯女士守規矩，好嗎?', `MaleText_loc7`='Ha llegado el momento. Hazme una señal cuando estén listos para iniciar el asalto. Ah, y trata de controlar a Lady Sylvanas, por favor.' WHERE `ID`=75317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다하겠습니다, 섭정님. 저희 부대는 준비를 마쳤습니다.', `MaleText_loc4`='我会尽力的，摄政王阁下。我的部队已经准备好了。', `MaleText_loc5`='我會全力以赴的，攝政王。我的部隊已經就緒。', `MaleText_loc7`='Haré lo posible, Señor Regente. Estamos listos.', `FemaleText_loc1`='최선을 다하겠습니다, 섭정님. 저희 부대는 준비를 마쳤습니다.', `FemaleText_loc4`='我会尽力的，摄政王阁下。我的部队已经准备好了。', `FemaleText_loc5`='我會全力以赴的，攝政王。我的部隊已經就緒。', `FemaleText_loc7`='Haré lo posible, Señor Regente. Estamos listos.' WHERE `ID`=75318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하, 저희 부대는 폐하의 명령을 따를 것입니다.', `MaleText_loc4`='我的部队听候您的吩咐，国王陛下。', `MaleText_loc5`='我的部隊全聽您號令，吾王。', `MaleText_loc7`='Estamos a tu servicio, majestad.', `FemaleText_loc1`='국왕 폐하, 저희 부대는 폐하의 명령을 따를 것입니다.', `FemaleText_loc4`='我的部队听候你的吩咐，国王陛下。', `FemaleText_loc5`='我的部隊全聽您號令，吾王。', `FemaleText_loc7`='Estamos a tu servicio, majestad.' WHERE `ID`=75319;
