UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 가문의 비밀 재료 국수의 비밀 재료를 알아낼 준비가 됐습니다!', `MaleText_loc4`='我准备好发掘林家秘制汤面的秘方了！', `MaleText_loc5`='我準備好要去探查林家秘傳湯麵的神秘食材了!', `MaleText_loc7`='¡Estoy listo para descubrir el ingrediente secreto de la sopa de fideos del ingrediente secreto de la familia Lin!', `FemaleText_loc1`='린 가문의 비밀 재료 국수의 비밀 재료를 알아낼 준비가 됐습니다!', `FemaleText_loc4`='我准备好发掘林家秘制汤面的秘方了！', `FemaleText_loc5`='我準備好要去探查林家秘傳湯麵的神秘食材了!', `FemaleText_loc7`='¡Estoy lista para descubrir el ingrediente secreto de la sopa de fideos del ingrediente secreto de la familia Lin!' WHERE `ID`=75322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1인 시나리오가 시작됩니다. 진행하시겠습니까?', `MaleText_loc4`='这将是一个单人场景战役。你确定要继续吗？', `MaleText_loc5`='這將會開始進行單人事件。你確定要繼續嗎?', `MaleText_loc7`='Esto dará comienzo a una gesta en solitario. ¿Seguro que quieres continuar?', `FemaleText_loc1`='1인 시나리오가 시작됩니다. 진행하시겠습니까?', `FemaleText_loc4`='这将是一个单人场景战役。你确定要继续吗？', `FemaleText_loc5`='這將會開始進行單人事件。你確定要繼續嗎?', `FemaleText_loc7`='Esto dará comienzo a una gesta en solitario. ¿Seguro que quieres continuar?' WHERE `ID`=75323;
