UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 박살내고 피로 흠뻑 적셔라!', `MaleText_loc4`='用钢铁碾碎他们！用血海湮没他们！', `MaleText_loc5`='用鋼鐵擊垮他們!讓他們倒在血泊之中!', `MaleText_loc7`='¡Aplástenlos con hierro! ¡Ahóguenlos en sangre!' WHERE `ID`=75332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰러진 동료들의 명예를 위해 놈들을 모두 처치하라!', `MaleText_loc4`='为了阵亡的将士们，杀光他们！', `MaleText_loc5`='為了我們的犧牲者，殺光他們! ', `MaleText_loc7`='¡Mátenlos a todos en honor de los caídos!' WHERE `ID`=75333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈라크라스가 비틀거리지만 폭발로부터 회복합니다!', `MaleText_loc4`='迦拉卡斯摇晃了一下，又从冲击中恢复了过来！', `MaleText_loc5`='葛拉卡斯會腳步踉蹌，但也會在衝擊中復原。', `MaleText_loc7`='Galakras retrocede, ¡pero se recupera del disparo!', `FemaleText_loc1`='갈라크라스가 비틀거리지만 폭발로부터 회복합니다!', `FemaleText_loc4`='迦拉卡斯摇晃了一下，又从冲击中恢复了过来！', `FemaleText_loc5`='葛拉卡斯會腳步踉蹌，但也會在衝擊中復原。', `FemaleText_loc7`='Galakras retrocede, ¡pero se recupera del disparo!' WHERE `ID`=75342;
