UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요마들이 화가 난 것 같습니다! 최대한 빨리 처치하세요!', `MaleText_loc4`='这些幽灵看起来很愤怒！快杀了它们！', `MaleText_loc5`='這群妖精看起來很生氣!趕快把他們殺光!', `MaleText_loc7`='¡Los duendes se han enfadado! ¡Mátalos mientras puedas!' WHERE `ID`=75352;
