UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 국수가 맛있다고 하던걸.', `MaleText_loc4`='我听说这地方有很棒的汤面。', `MaleText_loc5`='我聽說這裡有美味的湯麵。', `MaleText_loc7`='He oído que aquí sirven una sopa de fideos deliciosa.', `FemaleText_loc1`='여기 국수가 맛있다고 하던걸요.', `FemaleText_loc4`='我听说这地方有很棒的汤面。', `FemaleText_loc5`='我聽說這裡有美味的湯麵。', `FemaleText_loc7`='He oído que aquí sirven una sopa de fideos deliciosa.' WHERE `ID`=75354;
