UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 린 가문 비밀 재료 국수의 비밀을 발견했다고 하더군.', `MaleText_loc4`='我听说他们发现了失传的林家秘制汤面秘方。', `MaleText_loc5`='我聽說他們發現了林家秘傳湯麵失傳的秘方。', `MaleText_loc7`='He oído que ya han descubierto el mítico ingrediente de la sopa de fideos del ingrediente secreto de la familia Lin.', `FemaleText_loc1`='저들이 린 가문 비밀 재료 국수의 비밀을 발견했다고 하더군요.', `FemaleText_loc4`='我听说他们发现了失传的林家秘制汤面秘方。', `FemaleText_loc5`='我聽說他們發現了林家秘傳湯麵失傳的秘方。', `FemaleText_loc7`='He oído que ya han descubierto el mítico ingrediente de la sopa de fideos del ingrediente secreto de la familia Lin.' WHERE `ID`=75356;
