UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 국수는 늘 내 몸과 마음을 새롭게 해주지.', `MaleText_loc4`='啊……美味的汤面总能让我身心舒畅。', `MaleText_loc5`='啊...吃完湯麵總是讓我覺得身心舒暢。', `MaleText_loc7`='Ah... La sopa de fideos siempre me reconforta en cuerpo y alma.', `FemaleText_loc1`='아... 국수는 늘 내 몸과 마음을 새롭게 해줘요.', `FemaleText_loc4`='啊……美味的汤面总能让我身心舒畅。', `FemaleText_loc5`='啊...吃完湯麵總是讓我覺得身心舒暢。', `FemaleText_loc7`='Ah... La sopa de fideos siempre me reconforta en cuerpo y alma.' WHERE `ID`=75361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 맛있는 국수는 처음 먹어 보는군요. 비결이 뭡니까?', `MaleText_loc4`='我从没吃过这么好吃的汤面。你们有什么秘诀吗？', `MaleText_loc5`='我從來沒吃過這麼好吃的湯麵，訣竅是什麼?', `MaleText_loc7`='Nunca había probado una sopa de fideos tan maravillosa. ¿Cuál es el secreto?', `FemaleText_loc1`='이렇게 맛있는 국수는 처음 먹어 보네요. 비결이 뭐죠?', `FemaleText_loc4`='我从没吃过这么好吃的汤面。你们有什么秘诀吗？', `FemaleText_loc5`='我從來沒吃過這麼好吃的湯麵，訣竅是什麼?', `FemaleText_loc7`='Nunca había probado una sopa de fideos tan maravillosa. ¿Cuál es el secreto?' WHERE `ID`=75362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오래 기다렸어.', `MaleText_loc4`='这里上菜真慢。', `MaleText_loc5`='這裡的上菜速度實在太慢了。', `MaleText_loc7`='Tardan mucho en servir.', `FemaleText_loc1`='너무 오래 기다렸네요.', `FemaleText_loc4`='这里上菜真慢。', `FemaleText_loc5`='這裡的上菜速度實在太慢了。', `FemaleText_loc7`='Tardan mucho en servir.' WHERE `ID`=75363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 못 기다리겠어. 돌밭에나 가야지. 키메로크 찹스테이크를 판다고 하더라고.', `MaleText_loc4`='等不下去了，我还是去石犁村吧。听说那边有奇美拉肉片卖。', `MaleText_loc5`='我實在等不及了，我要去石犁村。我聽說那邊有人要煮奇美拉肉片。', `MaleText_loc7`='No puedo esperar más. Me voy a Villarroca. Dicen que allí cocinan chuletillas de quimerok.', `FemaleText_loc1`='더 못 기다리겠네요. 돌밭에나 가야겠어요. 키메로크 찹스테이크를 판다고 하더라고요.', `FemaleText_loc4`='等不下去了，我还是去石犁村吧。听说那边有奇美拉肉片卖。', `FemaleText_loc5`='我實在等不及了，我要去石犁村。我聽說那邊有人要煮奇美拉肉片。', `FemaleText_loc7`='No puedo esperar más. Me voy a Villarroca. Dicen que allí cocinan chuletillas de quimerok.' WHERE `ID`=75364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 하면 장사 오래 못할 텐데.', `MaleText_loc4`='要是他们继续这么下去，那这儿经营不了多久。', `MaleText_loc5`='這地方要是不改進的話，很快就會倒店了。', `MaleText_loc7`='Este sitio acabará por quebrar si siguen así.', `FemaleText_loc1`='이런 식으로 하면 장사 오래 못할 텐데.', `FemaleText_loc4`='要是他们继续这么下去，那这儿经营不了多久。', `FemaleText_loc5`='這地方要是不改進的話，很快就會倒店了。', `FemaleText_loc7`='Este sitio acabará por quebrar si siguen así.' WHERE `ID`=75365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘진 않지만 내가 기대한 게 아니군요. 주방장이라면 내가 뭘 기대하는지 알아야 하는 거 아닙니까?', `MaleText_loc4`='这面是不错，可我点的不是这个，厨师都不知道我点的是什么面吗？', `MaleText_loc5`='這味道還可以，但不是我真的想要的。廚師不是應該知道我要什麼嗎?', `MaleText_loc7`='Esto me gusta, pero no es el plato que pedí. ¿Tan difícil es recordar el pedido?', `FemaleText_loc1`='나쁘진 않지만 내가 기대한 게 아니네요. 주방장이라면 내가 뭘 기대하는지 알아야 하는 거 아니에요?', `FemaleText_loc4`='这面是不错，可我点的不是这个，厨师都不知道我点的是什么面吗？', `FemaleText_loc5`='這味道還可以，但不是我真的想要的。廚師不是應該知道我要什麼嗎?', `FemaleText_loc7`='Esto me gusta, pero no es el plato que pedí. ¿Tan difícil es recordar el pedido?' WHERE `ID`=75366;
