UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 저한테 감정이란 게 있더라도 이 상황이 슬플 것 같지는 않습니다.', `MaleText_loc4`='如果我有感情——那我也不会为你感到难过的。', `MaleText_loc5`='就算我有感覺，我也不會為此傷心。', `MaleText_loc7`='No me darías pena ni aunque tuviera sentimientos.' WHERE `ID`=75379;
