UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장치를 발로 찹니다.', `MaleText_loc4`='用力踢这台机器。', `MaleText_loc5`='踢那機器一腳。', `MaleText_loc7`='Dale una patada a la máquina.', `FemaleText_loc1`='장치를 발로 찹니다.', `FemaleText_loc4`='用力踢这台机器。', `FemaleText_loc5`='踢那機器一腳。', `FemaleText_loc7`='Dale una patada a la máquina.' WHERE `ID`=75381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님은 절대 패배하지 않을 겁니다. 전투에서 그분의 기량은 매우 출중합니다.', `MaleText_loc4`='雪怒是不会被打败的。他在战斗中是如此优雅。', `MaleText_loc5`='雪怒不可能被擊敗。他在戰鬥中根本就是藝術的化身。', `MaleText_loc7`='Nadie puede derrotar a Xuen. En combate, es la gracia personificada.' WHERE `ID`=75382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 쉬엔 님을 막을 수는 없습니다.', `MaleText_loc4`='在雪怒面前，他们毫无取胜的希望。', `MaleText_loc5`='他們對上雪怒一點機會都沒有。', `MaleText_loc7`='No tienen ninguna posibilidad contra Xuen.' WHERE `ID`=75383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아래에 있는 게 제가 아니라 다행이군요.', `MaleText_loc4`='幸好我没下场。', `MaleText_loc5`='我很高興我不是倒在那邊的人。', `MaleText_loc7`='Me alegro de tener compañía.' WHERE `ID`=75384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님. 언덕골 최초의 국수 수레를 열기 위해 시장에 공터를 마련해 뒀어요. 바로 당신의 수레죠!', `FemaleText_loc4`='欢迎，$n。我已经在市集上为半山的第一家面摊腾出一块空地了，由你来经营！', `FemaleText_loc5`='歡迎，$n。我把市集的區域整理了一下，替半丘前所未有，由你經營的拉麵攤騰出空間來了!', `FemaleText_loc7`='Hola, $n. He pedido que despejen la zona del mercado para hacer sitio al primer carrito de fideos de El Alcor... ¡el tuyo!' WHERE `ID`=75385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들에게 얘기해줄 만한 좋은 전투로구나, 향아.', `MaleText_loc4`='这将是一场值得你去向朋友们炫耀的战斗，伊莱。', `MaleText_loc5`='這場戰鬥會是個值得你跟朋友分享的故事，伊利。', `MaleText_loc7`='Esta batalla será digna de contar a nuestros amigos, Eli.' WHERE `ID`=75386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님들은 줄을 서서 당신이 자리로 안내해주기를 기다릴 거예요. 조금만 오래 기다린다 싶으면 가 버리니까, 그 전에 자리를 마련해 주세요.', `FemaleText_loc4`='客人们会排队等待你的招呼。但他们只愿意等一小会儿，所以你必须在他们离开之前招呼他们入座。', `FemaleText_loc5`='顧客會排隊並等待你告訴他們坐下。他們等一會兒就會離開，所以要確保在他們離開之前幫他們挪出位子。', `FemaleText_loc7`='Los clientes harán cola y esperarán a que les digas dónde sentarse. Si les haces esperar, se irán, así que asígnales asientos antes de que se marchen.' WHERE `ID`=75387;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자리에 앉은 손님은 국수가 올 때까지 기다릴 거예요. 줄을 서서 기다릴 때와 마찬가지로, 손님이 가 버리기 전에 국수를 내세요.', `FemaleText_loc4`='坐下之后，客人会等着你给他们上面。和排队一样，你要在他们离开前送上他们要的食物。', `FemaleText_loc5`='在坐下後，顧客會稍等片刻直到你把他們的湯麵送上。就跟排隊一樣，要在他們決定離開之前上菜。', `FemaleText_loc7`='Cuando se sienten, los clientes esperarán un rato a que les entregues su sopa de fideos. Igual que antes, asegúrate de darles la comida antes de que se vayan.' WHERE `ID`=75388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님이 입은 옷을 보면 뭘 먹고 싶어할지 알 수 있죠.', `FemaleText_loc4`='提示：你可以从客人的穿着打扮上看出他们的需求。', `FemaleText_loc5`='小提示:你可以透過顧客的衣著來看出他們想要什麼。', `FemaleText_loc7`='Un consejo: el atuendo de un cliente te dirá lo que quiere.' WHERE `ID`=75389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배고픈 손님은 첫 번째 그릇을 다 먹기 전에 한 그릇을 더 원할 거예요.', `FemaleText_loc4`='有些客人特别饿，会在吃完之后再要一碗。', `FemaleText_loc5`='有些顧客很餓，他們會在吃完第一碗之後加點一碗。', `FemaleText_loc7`='Algunos clientes tienen tanta hambre que quieren un segundo plato después del primero.' WHERE `ID`=75390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오. 투기장 안으로 떨어지면 안됩니다.', `MaleText_loc4`='小心。我可不想让你摔到赛场里去。', `MaleText_loc5`='小心點。我可不想讓你掉進競技場裡。', `MaleText_loc7`='Ten cuidado. No quiero que te caigas en la arena.' WHERE `ID`=75391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성질이 급한 손님은 오래 못 기다려요. 하지만 빨리 안내를 하거나 국수를 내주면 정말 좋아하죠.', `FemaleText_loc4`='有些客人比较性急，不愿等太久。但如果你能迅速招呼好他们，他们就会很开心。', `FemaleText_loc5`='有些顧客比較急性子，他們不會等很久，但是如果很快就上菜，他們會很高興。', `FemaleText_loc7`='Otros clientes son impacientes y no esperan mucho tiempo; se alegrarán mucho si los atiendes con rapidez.' WHERE `ID`=75392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가서 국수 좀 말아 보세요!', `FemaleText_loc4`='现在，快去煮汤面吧！', `FemaleText_loc5`='現在，去做湯麵吧!', `FemaleText_loc7`='¡Ahora ponte manos a la obra y prepara sopa de fideos!' WHERE `ID`=75393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘따라 입맛이 마구 당기는걸!', `MaleText_loc4`='哇，我今天真是胃口大开啊！', `MaleText_loc5`='哇，我今天胃口可真好!', `MaleText_loc7`='¡Hoy me muero de hambre!', `FemaleText_loc1`='오늘따라 입맛이 마구 당기네요!', `FemaleText_loc4`='哇，我今天真是胃口大开啊！', `FemaleText_loc5`='哇，我今天胃口可真好!', `FemaleText_loc7`='¡Hoy me muero de hambre!' WHERE `ID`=75394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 부하의 생명 활동이 정지되었습니다.', `MaleText_loc4`='你的宠物已经完蛋了。', `MaleText_loc5`='你的手下已經玩完了。', `MaleText_loc7`='Tu esbirro ha sido aniquilado.' WHERE `ID`=75395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 후각 센서에 뭔가 불타는 냄새가 감지됩니다.', `MaleText_loc4`='我的嗅觉感应器检测到一股烧焦的味道。', `MaleText_loc5`='我嗅覺靈敏的小夥伴聞到燒焦的味道了。', `MaleText_loc7`='Mis sensores olfativos detectan el aroma de la derrota.' WHERE `ID`=75396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런. 이제부터가 진짜입니다.', `MaleText_loc4`='真糟糕。现在，来见识下真正的宠物吧。', `MaleText_loc5`='真可惜，現在讓你瞧瞧真正的寵物。', `MaleText_loc7`='Una pena. Ahora toca una mascota de verdad.' WHERE `ID`=75397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 치르게 해드리죠.', `MaleText_loc4`='你会为此付出代价的。', `MaleText_loc5`='你會為此付出代價的。', `MaleText_loc7`='Me las pagarás.' WHERE `ID`=75398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t %s|1이;가; |cFFF00000|Hspell:144563|h[감금]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t%s开始施放|cFFF00000|Hspell:144563|h[囚禁]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t%s開始施展|cFFF00000|Hspell:144563|h[禁錮]|h|r!', `MaleText_loc7`='|TInterfaceIconssha_ability_rogue_sturdyrecuperate.blp:20|t ¡%s empieza a lanzar |cFFF00000|Hspell:144563|h[Encarcelar]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t %s|1이;가; |cFFF00000|Hspell:144563|h[감금]|h|r을 시전합니다!', `FemaleText_loc4`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t%s开始施放|cFFF00000|Hspell:144563|h[囚禁]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t%s開始施展|cFFF00000|Hspell:144563|h[禁錮]|h|r!', `FemaleText_loc7`='|TInterfaceIconssha_ability_rogue_sturdyrecuperate.blp:20|t ¡%s empieza a lanzar |cFFF00000|Hspell:144563|h[Encarcelar]|h|r!' WHERE `ID`=75400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 놀라운 곳이에요. 그렇죠?', `MaleText_loc4`='你不觉得吗？这地方很神奇！', `MaleText_loc5`='這地方真是太棒了，你不覺得嗎?', `MaleText_loc7`='Es un lugar fascinante, ¿no te parece?' WHERE `ID`=75401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 따끈한 국수 한 그릇 안 드시겠습니까?', `MaleText_loc4`='嘿，$n。要来尝尝我的热汤面吗？', `MaleText_loc5`='嗨，$n。想不想來一碗我煮的熱湯麵?', `MaleText_loc7`='Hola, $n. ¿Quieres probar mi sopa de fideos picante?', `FemaleText_loc1`='안녕하세요, $n 님. 따끈한 국수 한 그릇 안 드실래요?', `FemaleText_loc4`='嘿，$n。要来尝尝我的热汤面吗？', `FemaleText_loc5`='嗨，$n。想不想來一碗我煮的熱湯麵?', `FemaleText_loc7`='Hola, $n. ¿Quieres probar mi sopa de fideos picante?' WHERE `ID`=75402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑의 수비 병력을 탑에서 끌어낼 수 없습니다!', `MaleText_loc4`='塔楼里的援军拒绝撤离岗位！', `MaleText_loc5`='哨塔的援軍不會放棄他們的崗哨!', `MaleText_loc7`='¡Los refuerzos de la torre no abandonan su puesto!', `FemaleText_loc1`='탑의 수비 병력을 탑에서 끌어낼 수 없습니다!', `FemaleText_loc4`='塔楼里的援军拒绝撤离岗位！', `FemaleText_loc5`='哨塔的援軍不會放棄他們的崗哨!', `FemaleText_loc7`='¡Los refuerzos de la torre no abandonan su puesto!' WHERE `ID`=75403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화끈하게! 불타올라!', `FemaleText_loc4`='烧吧，宝贝，烧吧！', `FemaleText_loc5`='燒吧，寶貝，燒吧!', `FemaleText_loc7`='¡Arde!' WHERE `ID`=75404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열기가 후끈 달아오르네요!', `FemaleText_loc4`='这里真是热火朝天啊！', `FemaleText_loc5`='這個地方開始熱起來了!', `FemaleText_loc7`='¡Aquí empieza a hacer calor!' WHERE `ID`=75405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 불이 아름답지 않다고 했나요?', `FemaleText_loc4`='谁说火焰不美丽？', `FemaleText_loc5`='誰說火焰不美麗的?', `FemaleText_loc7`='¿Quién dice que el fuego no sea hermoso?' WHERE `ID`=75406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경계를 늦추지 않겠어요. 하지만 가끔은 이런 휴식도 나쁘진 않군요.', `FemaleText_loc4`='我的守望永不停歇，但我很珍惜这个短暂的假期。', `FemaleText_loc5`='我的警戒永不止息，但我很珍惜在工作中能有這樣的短暫休憩。', `FemaleText_loc7`='La vigilia no termina nunca, pero aprecio este breve descanso en el ejercicio del deber.' WHERE `ID`=75410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치열한 전투는 언제나 제 피를 끓어오르게 만듭니다.', `FemaleText_loc4`='一场精彩的战斗总能令我肾上腺素飙升。', `FemaleText_loc5`='一場精采的戰鬥總是能讓我精神百倍。', `FemaleText_loc7`='Una buena batalla da un subidón de adrenalina.' WHERE `ID`=75411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에는 세상 곳곳에서 각각의 삶을 살고 온 많은 이들이 있어요. 하지만 오늘만큼은 우리 모두가 이 장엄한 전투의 목격자가 될 거예요.', `FemaleText_loc4`='这里聚集了来自各行各业的人们。今天，我们都是观众，来此观看这些史诗般的战斗。', `FemaleText_loc5`='有許多不同人生經歷的人們在這裡集結。今天，我們都是這些史詩戰鬥的平等旁觀者。', `FemaleText_loc7`='Muchos individuos muy distintos se han reunido hoy aquí. Hoy todos somos iguales al observar estas batallas épicas.' WHERE `ID`=75412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 그리 놀란 얼굴인가, $n?$b$b내 항상 자네에게 얘기하지 않았나. 판다리아는 비밀과 수수께끼가 가득한 경이로운 곳이라고.', `MaleText_loc4`='干嘛这么吃惊，$n？$b$b我早就跟你说了。潘达利亚是一片充满未解之谜的神奇土地。', `MaleText_loc5`='為什麼這麼驚訝，$n?$b$b我一直這麼跟你說的，潘達利亞是充滿神秘事物的奇幻大陸。', `MaleText_loc7`='¿Por qué te sorprendes, $n?$b$bTe lo dije desde el principio: Pandaria es una tierra maravillosa, llena de secretos y misterios.' WHERE `ID`=75413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천신을 상대하는 것은 곧 당신의 의지와 실력, 그리고 비범함을 보이는 겁니다.$B$B준비되셨나요?', `FemaleText_loc4`='挑战至尊天神将考验你的决心、技巧并唤醒你的崇高精神。$B$B你准备好了吗？', `FemaleText_loc5`='面對天尊會測試你的決心，驗收你的能力，並喚起你的英勇。$B$B你準備好了嗎?', `FemaleText_loc7`='Enfrentarte a los celestiales pondrá a prueba tu determinación, desafiará tu habilidad y revelará tu grandeza.$b$b¿Estarás a la altura?' WHERE `ID`=75414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 큰 행사가 양조 대회가 아닌 것이 안타깝군요. 이렇게나 많은 양조사들이 한 자리에 모이는 건 처음 봤어요!', `FemaleText_loc4`='可惜没有酿酒比赛。我从没见过这么多酒仙聚在一起！', `FemaleText_loc5`='真遺憾，這不是釀酒的比賽。我從沒見過這麼多釀酒大師聚集在一起!', `FemaleText_loc7`='Es una pena que no se trate de un torneo de elaboración de cerveza. ¡Nunca había visto tantos maestros cerveceros juntos!' WHERE `ID`=75415;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 오늘, 천신을 상대로 승리할 자와 패배할 자가 가려질 겁니다.', `FemaleText_loc4`='今天，就让我们看看谁能打败至尊天神，谁又会被打得一败涂地吧。', `FemaleText_loc5`='今天，讓我們看看是誰能擊敗天尊，還有誰被天尊擊敗。', `FemaleText_loc7`='Veamos hoy quién derrota a un celestial y quién cae a sus pies.' WHERE `ID`=75416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스가 저지른 만행을 보고도 판다렌들은 아직도 놈들을 이곳에 들이는군요!', `FemaleText_loc4`='在联盟对熊猫人做出了那些事之后，他们居然还被允许来到这里！', `FemaleText_loc5`='在聯盟對熊貓人做了那些事之後，熊貓人還讓他們來這裡!', `FemaleText_loc7`='Después de todo lo que ha hecho la Alianza a los pandaren... ¿todavía les dejan entrar?' WHERE `ID`=75417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운이 좋으면 얼라이언스 놈의 사지가 찢기는 광경을 볼 수도 있겠군요.', `FemaleText_loc4`='如果走运的话，我们或许能看到哪个联盟狗被撕成碎片。', `FemaleText_loc5`='也許我們能很幸運地看到聯盟狗被五馬分屍。', `FemaleText_loc7`='Con un poco de suerte igual conseguimos ver cómo descuartizan a un perro de la Alianza.' WHERE `ID`=75418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장님의 뜻이 당신을 승리로 이끌길.', `FemaleText_loc4`='愿酋长指引你走向胜利。', `FemaleText_loc5`='願大酋長指引你獲得勝利。', `FemaleText_loc7`='Que el Jefe de Guerra te guíe a la victoria.' WHERE `ID`=75419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신들과 싸우고 싶나, 우낏?$B$B카 카는 흔쾌히 구경하겠지만 도와주진 않을 거야.', `MaleText_loc4`='嗯？你想跟至尊天神打架吗，蠢蛋？$B$B卡哈卡哈很乐意看热闹，但不会出手帮你。', `MaleText_loc5`='你想跟聖獸天尊戰鬥是嗎，怪怪人?$B$B卡卡很樂意在旁邊看，但不會幫忙。', `MaleText_loc7`='¿Makaku kiere luchar kon los celestiales?$b$bKah Kah mira, pero no ayuda.' WHERE `ID`=75420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼한 진위가 여기 왜 있는 거지!$B$B$n $n, 너 카 카와 함께 진위 몇 마리 때찌할래?', `MaleText_loc4`='该死的锦鱼人居然也来了！$B$B$n愿意帮卡哈卡哈干掉几个锦鱼人吗？', `MaleText_loc5`='壞壞錦魚人不應該來這裡!$B$B$n $n想幫卡卡宰幾個錦魚人嗎?', `MaleText_loc7`='¡Akí no tenía ke haber jinyu dingue!$b$b¿$n $n kiere ayudar a Kah Kah a hacer kraku en los mikos a algunos jinyu?' WHERE `ID`=75421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카 카에게 그 반짝이는 거 좀 줄래?$B$B그런 무기가 있으면 카 카도 재밌게 놀 수 있을 거야!', `MaleText_loc4`='愿意给卡哈卡哈一把亮闪闪的武器吗？$B$B想想看，要是卡哈卡哈有了这么一把武器，能干出多少大事啊！', `MaleText_loc5`='想給卡卡一些你的亮晶晶嗎?$B$B想想卡卡可以用那樣的武器幹掉好多人!', `MaleText_loc7`='¿Tú kiere dar kosas brillantes a Kah Kah?$b$b¡Kah Kah puede hacer mucho kraku kon un arma komo esa!' WHERE `ID`=75422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 철권호에서 판다리아를 내려다봤을 때 이런 곳이 있을 거라고 누가 알았겠어?', `MaleText_loc4`='当我们在地狱咆哮之拳上第一次见到潘达利亚时，谁能想到这里还会有这种地方的存在？', `MaleText_loc5`='當我們從地獄吼之拳初次見到潘達利亞時，誰會想到這世上竟然有這樣的地方？', `MaleText_loc7`='Nunca pensamos que existiera este lugar, cuando vimos Pandaria por primera vez a bordo del Puño de Grito Infernal...' WHERE `ID`=75423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 필요한 건 딱 두 마디야. 우르르 꽝꽝!$B$B화약이랑 폭탄만 좀 더 있으면 이 잔치가 얼마나 더 흥겨울지 생각해 보라고!', `MaleText_loc4`='两个字：轰隆！$B$B我想说的是，像这样的盛会，如果能再来一两桶炸药就更好了。', `MaleText_loc5`='兩個字:卡蹦!$B$B我只是想說這整個社交聚會如果能點幾個火藥桶就好了。', `MaleText_loc7`='Dos palabras: ¡ka-bum!$b$bSolo digo que a este sarao le vendría bien un barril de pólvora o dos.' WHERE `ID`=75424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 새로운 발명품을 만들고 있어. 성능을 한 번 보면 엄청난 충격을 받을걸?$B$B아, 물론 전치 4주는 안 넘어갈테니 걱정 마.', `MaleText_loc4`='我正在研究一项能把你的理智炸飞的新发明！$B$B或许还能让你的其他肢体一起瘫痪。', `MaleText_loc5`='我還在做這個能爆掉你的頭的裝置!$B$B搞不好也會爆掉其他身體部位...', `MaleText_loc7`='¡Estoy trabajando en un nuevo invento que va a ser la bomba!$b$bPorque va a explotar.' WHERE `ID`=75425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='박진감 넘치는 싸움을 지켜보자고요!', `FemaleText_loc4`='让我们看一场精彩的战斗吧！', `FemaleText_loc5`='讓我們看到精采的一戰吧!', `FemaleText_loc7`='¡Ofrécenos un buen combate!' WHERE `ID`=75426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참으로 흥미진진하네요. 안 그래요?', `FemaleText_loc4`='这真的很刺激，不是吗？', `FemaleText_loc5`='這真是令人興奮，對吧?', `FemaleText_loc7`='Es emocionante, ¿a que sí?' WHERE `ID`=75427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤와의 싸움에서 잠시 쉬는 것도 괜찮네요.', `FemaleText_loc4`='能在与煞魔斗争之余稍稍休息一下，这种感觉可真不错。', `FemaleText_loc5`='能在跟煞的對抗中小憩片刻還真不賴。', `FemaleText_loc7`='Me alegro de tomarme un respiro de luchar contra los sha.' WHERE `ID`=75428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페이 리가 아주 신이 났군요.', `FemaleText_loc4`='非离最好小心摆弄她那些焰火。', `FemaleText_loc5`='菲里不應該再繼續玩弄那些煙火了。', `FemaleText_loc7`='Fei Li debería calmarse con los fuegos artificiales.' WHERE `ID`=75429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 아주 평온하군요. 대륙을 집어삼킨 혼돈은 찾아볼 수가 없네요.', `FemaleText_loc4`='这地方可真是安宁祥和。它完全没有被肆虐大陆的战火所波及。', `FemaleText_loc5`='這裡有種寧靜感，沒有被在大陸上肆虐的戰爭波及。', `FemaleText_loc7`='Este lugar es muy sereno. No ha sido víctima de las guerras que asolan nuestro hogar.' WHERE `ID`=75431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나 자신을 진실되게 대하세요. 그러면 장엄한 빙하만큼 당신의 의지는 굳건해질 것입니다.', `FemaleText_loc4`='忠于自我，你的决心就会变成强大的冰川。', `FemaleText_loc5`='保持真正的自我，你的決心就會跟強大的冰川一樣。', `FemaleText_loc7`='Sigue siempre tu instinto; tu determinación será comparable a un gran glaciar.' WHERE `ID`=75432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플레이어들이 북쪽 탑 대공포를 점령하였습니다!', `MaleText_loc4`='玩家控制了北部塔楼的防空炮台！', `MaleText_loc5`='玩家控制了北邊的防空砲塔!', `MaleText_loc7`='¡Los jugadores se han apoderado de la torreta antiaérea del norte!', `FemaleText_loc1`='플레이어들이 북쪽 탑 대공포를 점령하였습니다!', `FemaleText_loc4`='玩家控制了北部塔楼的防空炮台！', `FemaleText_loc5`='玩家控制了北邊的防空砲塔!', `FemaleText_loc7`='¡Los jugadores se han apoderado de la torreta antiaérea del norte!' WHERE `ID`=75433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 하나가 저를 추격하더군요.$B$B쓴맛을 좀 보여줬습니다.', `MaleText_loc4`='一只螳螂妖试图跟踪我到这里。$B$B他的下场可不太好。', `MaleText_loc5`='有個螳螂人想跟蹤我到這裡。$B$B他的下場不太妙。', `MaleText_loc7`='Un mántide intentó seguirme hasta aquí.$b$bUn error que no volverá a cometer.' WHERE `ID`=75434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬은 모험을 떠나기 딱 좋군요!', `MaleText_loc4`='这座岛上一定会有很多奇遇的！', `MaleText_loc5`='在這座島嶼上還有更多冒險等你去完成。', `MaleText_loc7`='¡En esta isla nos esperan muchas aventuras!' WHERE `ID`=75435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 즐기러 오셨나 보군요.', `MaleText_loc4`='我看出来了，这里会有很多乐趣的！', `MaleText_loc5`='來這裡找點樂子，我懂!', `MaleText_loc7`='¡Veo que has venido a unirte a la fiesta!' WHERE `ID`=75436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴장을 푸십시오. 그대는 우리의 친구입니다.', `MaleText_loc4`='放松点。你还有朋友呢。', `MaleText_loc5`='放輕鬆，你還有朋友在呢。', `MaleText_loc7`='Relájate. Estamos entre amigos.' WHERE `ID`=75437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마십시오. 그렇다고 인생의 긍정적인 면을 놓치지는 말고요. 좋은 음식, 좋은 친구들, 그리고 좋은 술이 있잖습니까!', `MaleText_loc4`='保持警惕，但也别忘了享受生活中的小乐趣。美食，好友，还有美酒！', `MaleText_loc5`='全神貫注、提高警覺，但也別忘了享受人生。佳餚，好友，美酒!', `MaleText_loc7`='Mantente alerta, pero no olvides disfrutar de los placeres de la vida. La buena comida, los buenos amigos, ¡y la buena bebida!' WHERE `ID`=75438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이들이 싸우는 것을 보며 많은 것을 배울 수 있습니다.', `MaleText_loc4`='我们可以通过观摩他人的战斗学到很多东西。', `MaleText_loc5`='我們可以經由觀戰學到很多寶貴教訓。', `MaleText_loc7`='Ver luchar a otros puede ser muy instructivo.' WHERE `ID`=75439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉬엔 님과 다른 천신들을 뵙는 건 엄청난 영광이죠.', `FemaleText_loc4`='能见到雪怒和其他至尊天神真是我的荣幸。', `FemaleText_loc5`='很榮幸能出現在雪怒及其他天尊的面前。', `FemaleText_loc7`='Es un honor estar en presencia de Xuen y de los demás celestiales.' WHERE `ID`=75440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 아마 평생토록 천신들께 도전하지 못 할 거예요.', `FemaleText_loc4`='我觉得自己根本不可能去挑战任何一位至尊天神。', `FemaleText_loc5`='我從不認為我能挑戰任何一位天尊。', `FemaleText_loc7`='Creo que nunca podría desafiar a un celestial.' WHERE `ID`=75441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들은 이곳을 시간의 굴레에서 벗어난 곳이라 하더군요. 온갖 진귀한 볼거리가 가득할 거예요!', `FemaleText_loc4`='听说这座岛屿不受时光的侵蚀。在这里肯定能发现许多神奇的东西！', `FemaleText_loc5`='他們說時間不會影響這座島。這裡一定有很多令人驚奇的東西可以探索!', `FemaleText_loc7`='Dicen que el tiempo no transcurre en esta isla. ¡Debe albergar misterios impresionantes!' WHERE `ID`=75442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 물은 참으로 불가사의합니다. 분명 제게 말을 걸고는 있지만 무슨 뜻인지 모르겠군요.', `MaleText_loc4`='我从没见过这样的水。它会说话，可我听不懂它说的是什么。', `MaleText_loc5`='我從來沒在別的地方看過這樣的水。它會說話，但我聽不懂它在說什麼。', `MaleText_loc7`='Nunca había visto agua como la de esta isla. Habla, pero no entiendo lo que dice.' WHERE `ID`=75443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감하게 싸워 당신의 종족의 명예를 드높이십시오!', `MaleText_loc4`='好好打，为你的同胞争光吧！', `MaleText_loc5`='努力奮戰，把榮耀帶給你的人!', `MaleText_loc7`='Lucha bien, y honra a tu gente.' WHERE `ID`=75444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 뛰어난 실력과 의지를 겸비하고 있군요. 저도 언젠가 당신의 길을 따르고 싶습니다.', `MaleText_loc4`='你有出色的战斗技巧，也有坚定的战斗意志。但愿有一天我也能像你一样。', `MaleText_loc5`='你的戰鬥有著高超的技巧及效果。我希望有天能追隨你的道路。', `MaleText_loc7`='Luchas con habilidad y con determinación. Espero seguir tus pasos algún día.' WHERE `ID`=75445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t |cFFF00000|Hspell:144359|h[티탄의 선물]|h|r로 축복받습니다!', `MaleText_loc4`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t你受到了|cFFF00000|Hspell:144359|h[泰坦之赐]|h|r的祝福！', `MaleText_loc5`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t你已經受到|cFFF00000|Hspell:144359|h[泰坦之賜]|h|r的祝福!', `MaleText_loc7`='|TInterfaceIconsachievement_dungeon_ulduarraid_titan_01.blp:20|t ¡Has recibido la bendición de la |cFFF00000|Hspell:144359|h[Ofrenda de los titanes]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t |cFFF00000|Hspell:144359|h[티탄의 선물]|h|r로 축복받습니다!', `FemaleText_loc4`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t你受到了|cFFF00000|Hspell:144359|h[泰坦之赐]|h|r的祝福！', `FemaleText_loc5`='|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t你已經受到|cFFF00000|Hspell:144359|h[泰坦之賜]|h|r的祝福!', `FemaleText_loc7`='|TInterfaceIconsachievement_dungeon_ulduarraid_titan_01.blp:20|t ¡Has recibido la bendición de la |cFFF00000|Hspell:144359|h[Ofrenda de los titanes]|h|r!' WHERE `ID`=75446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님이 식사를 마치고 나면 빈 자리를 치워야 해요. 자리를 클릭하면 제가 치우러 가죠.', `FemaleText_loc4`='客人吃完之后，他们坐过的位子还需要清洁。你只需要点击它们，我就会去清洁了。', `FemaleText_loc5`='當顧客吃完之後，他們坐過的位子將需要清理。點擊這些位子，我就會去清理它們。', `FemaleText_loc7`='Cuando un cliente termine de comer, habrá que limpiar su asiento. Señálamelo y me encargaré de adecentarlo.' WHERE `ID`=75447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은 경기장에 뛰어들고 싶은 생각도 들더군요. 아, 물론 지금은 아니고요.', `MaleText_loc4`='我都想自己下场试试了……但现在还不行。', `MaleText_loc5`='我在考慮自己跳進競技場...不過不是現在。', `MaleText_loc7`='Estoy pensando en entrar en el ring... Quizás más tarde.' WHERE `ID`=75448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구와 싸워본 적이 있어요. 다른 적들은 더 강할까요?', `MaleText_loc4`='在与魔古族战斗过之后，其他敌人又能比他们强大多少呢？', `MaleText_loc5`='跟魔古交手過後，還有什麼敵人能稱得上強大?', `MaleText_loc7`='Estos oponentes no pueden ser peores que los mogu que hemos combatido, ¿no?' WHERE `ID`=75449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 시합은 애완동물 대전에서 다른 참가자들에 맞서 자신의 지도력을 시험하는 행사입니다. 충분히 실력을 증명하면 천신의 자손과 싸워볼 수도 있지요.', `MaleText_loc4`='至尊天神的子民们，天神比武大会将考验你们在宠物战斗中的领导能力，以及你们能否做个成功的领袖。', `MaleText_loc5`='天尊武道會考驗你在寵物戰中與其他參賽者對壘時的領導調度能力是否爐火純青，聖獸天尊之子。', `MaleText_loc7`='El Torneo Celestial pone a prueba tus dotes de liderazgo mediante los duelos de mascotas con otros participantes. Si tienes éxito, te enfrentarás a los hijos de los celestiales.' WHERE `ID`=75451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 시합에 참가하고 싶습니다.', `MaleText_loc4`='我要参加天神比武大会。', `MaleText_loc5`='我想參加天尊武道會。', `MaleText_loc7`='Me gustaría participar en el Torneo Celestial.', `FemaleText_loc1`='천신의 시합에 참가하고 싶습니다.', `FemaleText_loc4`='我要参加天神比武大会。', `FemaleText_loc5`='我想參加天尊武道會。', `FemaleText_loc7`='Me gustaría participar en el Torneo Celestial.' WHERE `ID`=75453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 주화로 무엇을 살 수 있나요?', `MaleText_loc4`='我能用天神铸币买到些什么？', `MaleText_loc5`='天尊硬幣能買什麼?', `MaleText_loc7`='¿Qué se puede comprar con las monedas celestiales?', `FemaleText_loc1`='천신의 주화로 무엇을 살 수 있나요?', `FemaleText_loc4`='我能用天神铸币买到些什么？', `FemaleText_loc5`='天尊硬幣能買什麼?', `FemaleText_loc7`='¿Qué se puede comprar con las monedas celestiales?' WHERE `ID`=75454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 츠지 님께 끌려요. 어쩌면 주학께서 제게 가르침을 내려주실 지도 모르죠.', `MaleText_loc4`='我很仰慕赤精。伟大的朱鹤或许能传授一些智慧给我。', `MaleText_loc5`='我感受到赤吉的召喚。或許紅鶴會傳授其智慧給我。', `MaleText_loc7`='Chi-Ji me parece muy interesante. A lo mejor la Grulla Roja comparte su sabiduría conmigo.' WHERE `ID`=75455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 좋은 마음가짐으로 싸운다. 모두 마신다. 모두 행복하다!', `MaleText_loc4`='大家都在努力战斗。大家都在开怀畅饮。大家都很开心！', `MaleText_loc5`='大家都好好地打，痛快地喝，大家都高興!', `MaleText_loc7`='Todo el mundo lucha bien. Todo el mundo bebe. ¡Todo el mundo kontento!' WHERE `ID`=75456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 마실 거 필요하다! 마셔라! 행복해진다!', `MaleText_loc4`='你也该喝一杯！干！祝你开心！', `MaleText_loc5`='你需要喝一杯!喝吧!開心一點!', `MaleText_loc7`='¡Makaku también tiene ke beber! ¡Bebe! ¡Sé feliz!' WHERE `ID`=75457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 시간이 안 흘러서 좋다. 컨컨은 여기 계속 있고 싶다!', `MaleText_loc4`='这里的时间是停滞的，这样真好。肯肯希望比试永远不要结束！', `MaleText_loc5`='這個地方是永恆的，真好!肯·肯希望一直這樣下去!', `MaleText_loc7`='Menos mal ke este sitio es intemporal. ¡Ken-Ken no kiere que la diversión se akabe nunka!' WHERE `ID`=75458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니우짜오 님이 건강하셔서 다행입니다.', `MaleText_loc4`='我很高兴看到砮皂依然健壮。', `MaleText_loc5`='看到怒兆健康又強壯真是令人高興。', `MaleText_loc7`='Me alegro de que Niuzao siga fuerte y saludable.' WHERE `ID`=75459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 역경이 우리를 찾아오기 전에 이 시간을 마음껏 즐깁시다.', `MaleText_loc4`='在更多冲突降临之前，我们一定要好好享受这段团聚的时光。', `MaleText_loc5`='在更多衝突來臨前，我們應該一起好好享受平靜的時光。', `MaleText_loc7`='Debemos disfrutar del tiempo que tenemos antes de que se produzcan más conflictos.' WHERE `ID`=75460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 긴장을 풀 수 있는 게 얼마만인지 모르겠군요!', `MaleText_loc4`='我好久没这么放松过了！', `MaleText_loc5`='我已經好久沒有這麼輕鬆了!', `MaleText_loc7`='¡Hacía tiempo que no me sentía tan tranquilo!' WHERE `ID`=75461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 전사가 아닐세. 대신 야채를 재배하고 야크를 돌보지.$B$B자네가 싸우게. 난 구경을 할테니.', `MaleText_loc4`='我不是战士。我只是个种菜养牦牛的。$B$B你去打，我就看看。', `MaleText_loc5`='我不是戰士，我是種菜、養犛牛的。$B$B你打吧，我看就好。', `MaleText_loc7`='Yo no lucho. Yo cultivo verduras y crío yaks.$b$bLucha tú, prefiero observar.' WHERE `ID`=75462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여! 해냈구나!', `MaleText_loc4`='勇士……你成功了……', `MaleText_loc5`='勇士...你成功了...', `MaleText_loc7`='Lo has logrado…' WHERE `ID`=75463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 자네! 내 맥주잔 좀 채워주겠나?', `MaleText_loc4`='你何不表现一番，让我开开眼界呢？', `MaleText_loc5`='幫個忙，去幫我倒杯酒如何?', `MaleText_loc7`='¿Por qué no haces algo útil y me rellenas el vaso?' WHERE `ID`=75464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 정신력과 힘을 지닌 필멸자는 드물다. 정말이다... 여러 명을 시험했지!', `MaleText_loc4`='凡人很难拥有这种精神和力量。真的——我试过很多人！', `MaleText_loc5`='極少凡人能擁有如此的精神和力量。相信我，我試過許多人!', `MaleText_loc7`='Pocos mortales poseen tanto espíritu, tanto poder. Créeme... ¡He puesto muchos a prueba!' WHERE `ID`=75465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 작물을 재배하는 걸 생각해보고 있다네.$B$B불가사의한 씨앗을 심으면 무슨 일이 일어날지 기대가 되는군!', `MaleText_loc4`='我正考虑在这里种点庄稼。$B$B你能想象，如果我在这里种下一颗谜之种，会发生什么事吗？', `MaleText_loc5`='我考慮在這裡試著種點穀物。$B$B你能想像如果我種神秘種子的話會發生什麼事嗎?', `MaleText_loc7`='Estoy pensando en cultivar algo aquí.$b$b¿Te imaginas lo que podría pasar si plantara semillas enigma?' WHERE `ID`=75466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위대한 작업을 마무리하려면 신성한 장소가 필요하다.', `MaleText_loc4`='要完成我们的伟大目标，还需要一片圣地。', `MaleText_loc5`='要完成我們的偉大工作，我們需要一個神聖之地。', `MaleText_loc7`='Para completar nuestra gran obra necesitaremos un lugar sagrado.' WHERE `ID`=75467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기로 오너라. 지식의 연단에서 다시 만나자.', `MaleText_loc4`='快去锦绣谷吧，到闻道之座来找我。', `MaleText_loc5`='前往恆春谷，在知識之座跟我碰面。', `MaleText_loc7`='Viaja al Valle de la Flor Eterna y búscame en el Trono del Saber.' WHERE `ID`=75468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설이 탄생했다!', `MaleText_loc4`='一个传奇诞生了！', `MaleText_loc5`='傳說誕生了!', `MaleText_loc7`='¡Ha nacido una leyenda!' WHERE `ID`=75469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 시합에 참가하려면 어떤 조건을 만족시켜야 하나요?', `MaleText_loc4`='参加天神比武大会有什么要求？', `MaleText_loc5`='參加天尊武道會的條件是什麼?', `MaleText_loc7`='¿Cuáles son los requisitos para entrar en el Torneo Celestial?', `FemaleText_loc1`='천신의 시합에 참가하려면 어떤 조건을 만족시켜야 하나요?', `FemaleText_loc4`='参加天神比武大会有什么要求？', `FemaleText_loc5`='參加天尊武道會的條件是什麼?', `FemaleText_loc7`='¿Cuáles son los requisitos para entrar en el Torneo Celestial?' WHERE `ID`=75470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭넓은 훈련을 거친 이들만이 시합에 참가할 수 있습니다.

적어도 15마리 이상의 애완동물이 최고 레벨에 도달해야 자격이 있다고 간주되죠.', `MaleText_loc4`='只有经过充分训练的人才能参加比武大会。

当你拥有15只满级宠物时，你才能获得参赛资格。', `MaleText_loc5`='只有受過充分訓練的人才能參加聯賽。

當你把15隻寵物訓練到牠們的最高等級，就會被認為具備資格了。', `MaleText_loc7`='En el torneo solo pueden entrar los entrenadores más experimentados.

Cuando hayas alcanzado el nivel máximo con al menos 15 mascotas, habrás demostrado estar a la altura.' WHERE `ID`=75471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시합에 대해 이야기해 주십시오.', `MaleText_loc4`='再跟我说说比武大会的事吧。', `MaleText_loc5`='再跟我說一次聯賽的事。', `MaleText_loc7`='Explícame el torneo una vez más.', `FemaleText_loc1`='시합에 대해 이야기해 주십시오.', `FemaleText_loc4`='再跟我说说比武大会的事吧。', `FemaleText_loc5`='再跟我說一次聯賽的事。', `FemaleText_loc7`='Explícame el torneo una vez más.' WHERE `ID`=75472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 병아리들은 지금은 작지만, 매우 빨리 자란다네!', `MaleText_loc4`='这些小鸡现在或许还很小，但它们很快就会长大的！', `MaleText_loc5`='這些小雞現在個頭還小，但牠們長得很快!', `MaleText_loc7`='Estos polluelos son pequeños ahora, ¡pero crecen rapidísimo!' WHERE `ID`=75478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움은 적고, 작물은 많게. 그게 내가 원하는 세상이라네.$B$B물론, 자네가 싸운다면 구경은 하겠네만.', `MaleText_loc4`='少打架，多种田。我跟你说，这才是生活。$B$B当然，如果你想打架，我也不妨来看看。', `MaleText_loc5`='少打點架，多種點田。我告訴你，這才是人生的正途。$B$B當然，你要打的話，我是不介意在旁邊看啦。', `MaleText_loc7`='Menos luchar y más cultivar. ¡Eso sí que es vida!$b$bEso sí, si $gel:la; que lucha eres tú, no me importa quedarme a mirar.' WHERE `ID`=75479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 옛날에는 말일세, 눈보라가 휘몰아치는 가파른 언덕을 겨우겨우 올라가야 천신을 만날 수 있었다네.', `MaleText_loc4`='哼。想当年，我们可得翻过一座雪山才能觐见至尊天神的。', `MaleText_loc5`='嗯哼，在我那個時候，我們得冒雪上山才能見到天尊。', `MaleText_loc7`='Mmm. En mis tiempos, teníamos que andar kilómetros para ver a un celestial.' WHERE `ID`=75480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 기꺼이 당신 곁에서 싸울 테지만, 제 도움 없이도 괜찮을 것 같네요.', `FemaleText_loc4`='我很乐意与你并肩战斗，但你并没有向我求助。', `FemaleText_loc5`='我很樂意與你並肩作戰，但你不需要我的協助。', `FemaleText_loc7`='Lucharía a tu lado encantada, pero no te hace falta mi ayuda.' WHERE `ID`=75481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정한 $c의 실력을 볼 수 있겠군요.', `FemaleText_loc4`='我很期待能看到一位真正的$c全部的潜力。', `FemaleText_loc5`='我很期待能看到真正的$c的完整實力。', `FemaleText_loc7`='No veo el momento de ver a $gun auténtico:una auténtica; $c en acción.' WHERE `ID`=75482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투기장은 제 취향이라 하기엔 좀 시끌벅적해요. 하지만 이런 엄청난 구경거리를 놓칠 수는 없죠.', `FemaleText_loc4`='对我而言，竞技场有点太吵了，但能看到这么精彩的比赛还是值得的。', `FemaleText_loc5`='這個競技場對我來說有點太吵，但能見證這一切就是值得的。', `FemaleText_loc7`='La arena es un poco ruidosa para mi gusto, pero el espectáculo merece la pena.' WHERE `ID`=75483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 제 옷차림 마음에 드세요?', `FemaleText_loc4`='你喜欢我今天这身打扮吗？', `FemaleText_loc5`='你喜歡我今天的服裝嗎?', `FemaleText_loc7`='¿Te gusta mi vestido?' WHERE `ID`=75484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 탐험하는 당신에게 행운이 깃들길 빌게요!', `FemaleText_loc4`='祝你能在这里交上好运！', `FemaleText_loc5`='我希望你在這裡的冒險中充滿了好運!', `FemaleText_loc7`='¡Te deseo mucha suerte en tus aventuras!' WHERE `ID`=75485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='농부 윤과 농부 펑도 이곳에 있다니!$B$B여자 혼자서 뭘 어쩌란 말이죠?', `FemaleText_loc4`='真不敢相信，农夫老愚和农夫老方都来了！$B$B这叫我一个姑娘家该怎么办啊？', `FemaleText_loc5`='我真不敢相信農夫尹跟農夫老豐都在這裡!$B$B我這個好女孩該怎麼做呢?', `FemaleText_loc7`='¡No me puedo creer que el granjero Yoon y el granjero Fung estén aquí!$b$b¿Qué hago?' WHERE `ID`=75486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 앉아서 시원한 맥주 한 잔 마시며 이야기나 나누지 않겠나?', `MaleText_loc4`='让我们坐下来喝杯冰镇啤酒，好好聊聊吧？', `MaleText_loc5`='坐下來喝杯冰啤酒聊聊怎麼樣？', `MaleText_loc7`='¿Por qué no nos sentamos y nos tomamos algo fresquito?' WHERE `ID`=75487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼 연합의 여러 회원들이 싸움을 구경하기 위해 왔군. 화끈한 싸움과 시원한 맥주만큼 어울리는 것도 없다네!', `MaleText_loc4`='许多阡陌客都赶来看比赛了。再没有比精彩的战斗和冰镇啤酒更棒的消遣了！', `MaleText_loc5`='耕者工會的多數人都來到這裡觀戰。沒有比精彩的打鬥和冰啤酒更過癮的了!', `MaleText_loc7`='Han venido muchos Labradores para ver los combates. ¡No hay nada como un buen combate y una cerveza fría!' WHERE `ID`=75488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한바탕 잘 싸우고 오게. 그 후에 농장을 돌보는 것도 잊지 말게나!', `MaleText_loc4`='好好打，但可别忘了去照料你的农场！', `MaleText_loc5`='好好打一場，但別忘了打完以後去看看農田。', `MaleText_loc7`='¡Buena pelea! Pero no olvides que luego tienes que cuidar de la granja...' WHERE `ID`=75489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장에서 열심히 단련하면 훗날의 어려움도 이겨낼 수 있을 걸세.', `MaleText_loc4`='赛场上的激烈战斗可以帮助你保持状态，迎接未来的挑战。', `MaleText_loc5`='在競技場內一回好的表現能讓你在未來的試煉中保持強大。', `MaleText_loc7`='Una buena liza en la arena te fortalecerá para el futuro.' WHERE `ID`=75490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에는 온갖 숨겨진 보물들이 많다고 하네. 한 번 찾아보게나.', `MaleText_loc4`='这座岛上隐藏着许多秘密。你得把它们找出来。', `MaleText_loc5`='這個島上藏著很多秘密。你應該去找一找。', `MaleText_loc7`='Esta isla oculta muchas cosas. Deberías buscarlas.' WHERE `ID`=75491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네같이 강한 $r|1을;를; 지켜보는 건 언제나 즐거운 일이지.', `MaleText_loc4`='见到像你这么强大的$r总是一件令人高兴的事。', `MaleText_loc5`='能見到像你這樣強大的$r總是令人高興。', `MaleText_loc7`='Siempre es un placer ver a $gun:una; $r fuerte como tú.' WHERE `ID`=75492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 역사적인 순간이에요...', `MaleText_loc4`='历史正在被创造……', `MaleText_loc5`='這是新的歷史篇章...', `MaleText_loc7`='Esto será histórico...' WHERE `ID`=75493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에서 정말 멀리도 왔군요!', `MaleText_loc4`='我显然已经离家万里了！', `MaleText_loc5`='我真的是離鄉背井!', `MaleText_loc7`='¡Estamos muy lejos de casa!' WHERE `ID`=75494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 흥미롭군요.', `MaleText_loc4`='……有意思。', `MaleText_loc5`='...有意思。', `MaleText_loc7`='... Interesante.' WHERE `ID`=75495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 싸워본 적은 별로 없지만, 꽤 흥미진진하네요!', `MaleText_loc4`='我很少打架，但这真的很刺激！', `MaleText_loc5`='我沒什麼戰鬥經驗，不過這真的很刺激!', `MaleText_loc7`='Apenas he luchado en la vida, ¡pero estoy emocionado!' WHERE `ID`=75496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 엄청난 싸움이군요!', `MaleText_loc4`='哇，打得好！', `MaleText_loc5`='哇!打得真精彩!', `MaleText_loc7`='¡Guau! ¡Qué combate!' WHERE `ID`=75497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 너에게 감명받았다!', `MaleText_loc4`='英雄，你是一个榜样！', `MaleText_loc5`='英雄，你真是鼓舞人心啊!', `MaleText_loc7`='¡Eres una inspiración!' WHERE `ID`=75498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 좋은 이야깃거리가 되겠군요. 안 그래요?', `FemaleText_loc4`='这会是一个很精彩的故事的，你不觉得吗？', `FemaleText_loc5`='這會是個好故事，你不覺得嗎?', `FemaleText_loc7`='Será una buena historia que contar, ¿verdad?' WHERE `ID`=75499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 위대한 운명을 타고났음을 알고 있었다.', `MaleText_loc4`='我早知道，你会成为伟大的人。', `MaleText_loc5`='我就知道你一定會成就偉業。', `MaleText_loc7`='Sabía que la grandeza era tu destino.' WHERE `ID`=75500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아침 내내 천신님들이랑 투닥거렸어요!', `FemaleText_loc4`='我一早上都在跟至尊天神们搏斗！', `FemaleText_loc5`='我整個早上都在跟天尊角力!', `FemaleText_loc7`='¡Llevo toda la mañana luchando con celestiales!' WHERE `ID`=75501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 저절로 우리를 찾아왔군! 네 망토의 잠재력을 최고로 끌어올리는 데 영원의 섬이 가장 중요한 역할을 할 것이다.', `MaleText_loc4`='大好的机会送上门来了！我敢肯定，激发你斗篷潜力的关键就在永恒岛。', `MaleText_loc5`='機會出現了!我相信永恆之島掌握了解放你披風完整潛力的關鍵。', `MaleText_loc7`='¡Se ha presentado una oportunidad! Creo que la Isla Intemporal tiene la clave para desatar todo el potencial de tu capa.' WHERE `ID`=75502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 속에 잊힌, 해가 지지 않는 섬. 어떤 의미일까요?', `MaleText_loc4`='一座失落在时间长河中，永不日落的海岛。这意味着什么呢？', `MaleText_loc5`='一座失落在時間中的永晝島嶼。這代表什麼?', `MaleText_loc7`='Una isla, perdida en el tiempo, donde jamás se pone el sol. ¿Qué significa?' WHERE `ID`=75503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘! 영광! 전리품!', `MaleText_loc4`='力量！荣耀！宝藏！', `MaleText_loc5`='力量!榮耀!寶藏!', `MaleText_loc7`='¡Poder! ¡Gloria! ¡Botín!' WHERE `ID`=75504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손만 뻗으면 우리 것이다! 영웅이여, 영원의 섬에서 만나자.', `MaleText_loc4`='全是我们的！英雄，来永恒岛找我吧。', `MaleText_loc5`='我們垂手可得!英雄，在永恆之島碰面吧。', `MaleText_loc7`='¡Y es todo nuestro! Búscame en la Isla Intemporal.' WHERE `ID`=75505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 많은 일들이 벌어지고 있네요! 가슴이 두근대지 않나요?', `FemaleText_loc4`='发生了那么多的事！这难道不刺激吗？', `FemaleText_loc5`='有好多精采的東西喔!你不覺得興奮嗎?', `FemaleText_loc7`='¡Cuánta actividad! ¿A que es emocionante?' WHERE `ID`=75506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬을 직접 보고 싶은 마음이 크군요. 거기서 뵐까요?', `MaleText_loc4`='我很想亲眼看看这座岛。或许我们还会在那里相见？', `MaleText_loc5`='我也很想親自見識這座島。我們在那裡見吧?', `MaleText_loc7`='Me gustaría mucho ver esa isla con mis propios ojos. ¿Nos vemos allí?' WHERE `ID`=75507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우후! 너 완전 우낏하게 두들겼구나!', `MaleText_loc4`='哇！你真是狠狠教训了他们一顿啊！', `MaleText_loc5`='哇!打得好!', `MaleText_loc7`='¡Guau! ¡Makaku ha hecho kraku!' WHERE `ID`=75508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕해, 대장? 뭉뭉이 한 잔 줄테니 마셔!', `MaleText_loc4`='最近怎么样啊，老板？跟蒙蒙来喝一杯吧！', `MaleText_loc5`='怎麼樣了，老闆?為芒芒喝一杯吧!', `MaleText_loc7`='¿Ké pasa, $gjefe:jefa;? ¡Bebe a la salud de Mung-Mung!' WHERE `ID`=75509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉뭉이 피지우 마을에서 맥주 마셨어. 맛 없더라!', `MaleText_loc4`='蒙蒙尝过老酒湾的啤酒。太难喝了！', `MaleText_loc5`='芒芒喝過老埤周村的啤酒。好難喝!', `MaleText_loc7`='Mung-Mung ha probado la cerveza de Pi''jiu. ¡Es horrible!' WHERE `ID`=75510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 농사를 안 지어도 되니, 이렇게 시간을 보내는 것도 괜찮은데!', `MaleText_loc4`='反正我现在不用种田，这真是个消遣的好去处！', `MaleText_loc5`='既然我現在不耕作了，這是個打發時間的好方法!', `MaleText_loc7`='Esta es una buena forma de pasar el rato cuando no estoy en la granja.' WHERE `ID`=75512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 끝나면 좀 쉬는 것도 잊지 말게. 노련한 $c|1이라면;라면; 숨 돌릴 때도 알아야지.', `MaleText_loc4`='在战斗之余，别忘了好好休息。一个好$c应该懂得劳逸结合。', `MaleText_loc5`='別忘了在戰鬥之間稍事休息，一個好$c知道什麼時候該戰鬥。', `MaleText_loc7`='Acuérdate de tomarte un descanso entre un combate y otro. $gEl:La; $c $gsabio:sabia; es $gaquel:aquella; que sabe cuándo no le conviene luchar.' WHERE `ID`=75513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 나쁘지 않군.', `MaleText_loc4`='还不错。', `MaleText_loc5`='還不錯。', `MaleText_loc7`='No está mal.' WHERE `ID`=75514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉뭉은 농사를 짓기엔 너무 성급하다네.$B$B그래서 내가 그에게 인내를 가르치고 있지.', `MaleText_loc4`='蒙蒙不够耐心，没法独立工作。$B$B我正试图帮他放慢节奏。', `MaleText_loc5`='芒芒實在沒有耐心去耕種自己的農地。$B$B我在試著幫他把做事的節奏慢下來。', `MaleText_loc7`='Mung-Mung es demasiado impaciente para cultivar su propio terreno.$b$bIntento ayudarle a que se tome las cosas con calma.' WHERE `ID`=75518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 안녕하세요! 음... 이곳에서 뵐 줄은 몰랐네요!$B$B<갑자기 고개를 돌리고 투기장을 바라보는 엘라>', `FemaleText_loc4`='噢！你好啊！我……呃……没想到能在这儿遇见你！$B$B<艾拉突然回头向竞技场看去。>', `FemaleText_loc5`='噢!哈囉!我...呃...沒想到你會在這裡!$B$B<艾拉突然把視線轉回競技場上。>', `FemaleText_loc7`='¡Ah! ¡Hola! Eh... ¡No esperaba verte aquí!$b$b<Ella aparta la mirada bruscamente.>' WHERE `ID`=75523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 앞으로 오랫동안 널 칭송할 것이다.', `MaleText_loc4`='熊猫人将世代传颂你的事迹。', `MaleText_loc5`='熊貓人們會世世代代傳頌你的事蹟。', `MaleText_loc7`='Los Pandaren cantarán tus alabanzas por eras.' WHERE `ID`=75524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분홍색 학들은 정말 아름다워요!$B$B음... 그냥 그렇다고요...', `FemaleText_loc4`='那些粉色的仙鹤真漂亮！$B$B我是说……如果你想知道的话……', `FemaleText_loc5`='粉紅色的鶴真是漂亮!$B$B我的意思是...如果你願意聽這些...', `FemaleText_loc7`='¡Las grullas rosas son preciosas!$b$bDigo... Por si te interesa...' WHERE `ID`=75525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고양이들을 돌보러 가야 되는데... 애들이 괜찮았으면 좋겠어요.', `FemaleText_loc4`='噢，我得去看看我的猫咪们了。但愿它们一切都好！', `FemaleText_loc5`='噢，我應該去看看我的貓。希望牠們沒事!', `FemaleText_loc7`='Debería volver con mis gatos. ¡Espero que estén bien!' WHERE `ID`=75526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 참으로 신기하군요. 온 사방에서 강한 마력이 느껴집니다.', `MaleText_loc4`='这地方真古怪，到处都充斥着强大的魔力。', `MaleText_loc5`='這地方很不尋常。在我們周遭到處都有強大的魔法。', `MaleText_loc7`='Es un lugar muy extraño. Una magia poderosa nos rodea por todas partes.' WHERE `ID`=75527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에서 차원문을 열다간... 흥미로운 결과를 불러올 수 있겠군요.', `MaleText_loc4`='我不敢在这里开传送门。这么做的后果会……很有趣的。', `MaleText_loc5`='我不敢在這裡放置傳送門，後果可能會...很有意思。', `MaleText_loc7`='No me atrevo a crear portales aquí. Los resultados serían... interesantes.' WHERE `ID`=75528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에 숨겨진 보물들이 많다고 들었습니다.', `MaleText_loc4`='我听说岛上藏着许多宝藏。', `MaleText_loc5`='我聽說這座島上有很多不為人知的寶藏。', `MaleText_loc7`='He oído que hay muchos tesoros escondidos por la isla.' WHERE `ID`=75529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 제 아버지의 희생을 잊지 않을 겁니다.', `FemaleText_loc4`='我永远不会忘记我父亲的牺牲。', `FemaleText_loc5`='我永不會忘記我父親的犧牲。', `FemaleText_loc7`='Nunca olvidaré el sacrificio de mi padre.' WHERE `ID`=75533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='편히 쉴 수 있는 이 기회가 싫지는 않군요.', `FemaleText_loc4`='要说我不珍惜这个放松的机会，那是假的。', `FemaleText_loc5`='如果我說我不感謝這個放輕鬆的機會，我就是在說謊。', `FemaleText_loc7`='Para serte sincera, me alegro de poder relajarme un poco.' WHERE `ID`=75538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 대결들을 보니 제가 신병이었던 시절에 겪은 훈련이 생각나는군요.', `FemaleText_loc4`='这些比赛让我想起了自己接受新兵训练时的日子。', `FemaleText_loc5`='這些對戰讓我想起了當初年輕時身為新兵的訓練。', `FemaleText_loc7`='Estos combates me recuerdan a los entrenamientos que nos asignaban cuando era una joven recluta.' WHERE `ID`=75539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서까지 전쟁을 벌일 필요는 없겠군요.', `MaleText_loc4`='这里没有战争的空间。', `MaleText_loc5`='這裡可沒有開戰的餘地。', `MaleText_loc7`='Aquí la guerra no tiene cabida.' WHERE `ID`=75540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 긍지를 가지고 싸우십시오.', `MaleText_loc4`='为荣耀而战。', `MaleText_loc5`='永遠為榮譽而戰。', `MaleText_loc7`='Lucha siempre con honor.' WHERE `ID`=75541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군인은 언제나 직무에 충실해야 하죠.', `MaleText_loc4`='战士的责任是永无止尽的。', `MaleText_loc5`='一日士兵，終身士兵。', `MaleText_loc7`='La guardia de un soldado no acaba nunca.' WHERE `ID`=75542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 배치하라! 방어선을 구축해!', `MaleText_loc4`='部署设备！建立防御带！', `MaleText_loc5`='準備儀器!建立陣地!', `MaleText_loc7`='¡Activen el equipamiento!  ¡Establezcan un perímetro!' WHERE `ID`=75544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 반갑네! 방금 지상을 거의 확보하고 왔는데, 진짜 싸움은 이 밑에서 벌어지고 있었군!', `MaleText_loc4`='噢，你们好，朋友们！我们已经差不多肃清了地面，看来真正的战斗还在下面！', `MaleText_loc5`='噢，哈囉朋友!我們已經差不多鞏固地面了，看來真正的戰鬥會在地底!', `MaleText_loc7`='Ah, ¡hola, amigos!  ¡Estamos a punto de asegurar la superficie, parece que la verdadera batalla será aquí abajo!' WHERE `ID`=75545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정마. 우리가 지켜줄 테니! 영웅들이여! 전진!', `MaleText_loc4`='别担心，我们会支援你们的！前进吧，英雄们！', `MaleText_loc5`='不用擔心，我們會掩護你們!前進吧，勇敢的英雄們!', `MaleText_loc7`='No se preocupen, nosotros los cubrimos. ¡Avancen héroes valientes!' WHERE `ID`=75546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 저 여자 봐. 정말 완벽한걸. 10점 만점에 10점이야!', `MaleText_loc4`='噢，快看那个姑娘。真漂亮，10分！', `MaleText_loc5`='噢，看看那邊的美女。她可真漂亮，貨真價實的10分!', `MaleText_loc7`='Ah, mira a esa de ahí. Es una belleza. ¡Un 10 perfecto!' WHERE `ID`=75547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10점이라고? 하! 칼바위 언덕에서나 그렇겠지. 오그리마였으면 6점밖에 안 될걸.', `MaleText_loc4`='10分？哈！这也就是在剃刀岭了。在奥格瑞玛，她最多也就6分。', `MaleText_loc5`='10分?哈!在剃刀嶺大概能拿到10分吧，不過在奧格瑪頂多只有6分。', `MaleText_loc7`='¿Un 10? ¡Ja! Quizás en Cerrotajo. En Orgrimmar sería un 6 raspado.' WHERE `ID`=75548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티나도 여기 왔더군요.$B$B농부 윤이나 농부 펑도 알고 있을까요?', `FemaleText_loc4`='你听说了吗？迪娜·泥爪也来了。$B$B不知道农夫老愚和农夫老方发现没有……', `FemaleText_loc5`='你有聽說蒂娜·泥爪來這裡了嗎?$B$B不知道農夫尹或農夫老豐會不會注意到...', `FemaleText_loc7`='¿Has oído que Tina Zarpa Fangosa anda por aquí?$b$b¿Lo sabrán el granjero Yoon o el granjero Fung?' WHERE `ID`=75549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠시 동안 상점을 닫고 쉬는 것도 정말 편하군요.', `FemaleText_loc4`='总算不用打理市集了，真是太轻松了。', `FemaleText_loc5`='偶爾可以不用在市場做生意，還真是輕鬆啊。', `FemaleText_loc7`='Qué tranquilidad, no tener que llevar el mercado por un día...' WHERE `ID`=75550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='팔 물건을 좀 챙겨올걸 그랬어요. 장사가 꽤 잘 됐을 텐데 말이죠!', `FemaleText_loc4`='我真该带一辆餐车来的。在这里绝对能赚大钱！', `FemaleText_loc5`='我應該把我的攤位搬過來的。看來這裡也有錢可以賺!', `FemaleText_loc7`='Debería haberme traído el carrito. ¡Aquí se puede hacer dinero!' WHERE `ID`=75551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 힘이 이 땅을 오랜 어둠으로부터 자유롭게 했네. 영웅이여, 그대의 위업을 내 두 눈으로 확인할 수 있어 영광이었네.', `MaleText_loc4`='你的力量将这片土地从恒古的黑暗中解救了出来。我很荣幸能亲眼见证你的事迹，勇士。', `MaleText_loc5`='你用自己的力量讓這片土地擺脫了黑暗長久以來的控制。能目睹你做的這些努力，真是我的榮幸，勇士。', `MaleText_loc7`='Tu fuerza ha ayudado a esta tierra a liberarse de una oscuridad muy antigua. Es un honor presenciar tus hazañas, $gcampeón:campeona;.' WHERE `ID`=75553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나무는 희망의 상징이다. 너희들의 공으로 언젠간 이 땅이 치유되고 강해질 수 있다는 희망의 상징.', `MaleText_loc4`='这棵树就是希望的象征。但愿你所做的一切能让这片土地痊愈，并更加繁荣昌盛。', `MaleText_loc5`='這棵樹聳立在此，就如希望的象徵。希望這片土地能及時復原，而且能在你們的努力之下更加豐沃、強健。', `MaleText_loc7`='Este árbol es un símbolo de esperanza. Espero que, con el tiempo, la tierra se sane y se fortalezca gracias a tus hazañas.' WHERE `ID`=75557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 절 놀라게 만드시는군요, $n 님.', `MaleText_loc4`='你总能打动我，$n。', `MaleText_loc5`='你再度讓我讚嘆不已，$n。', `MaleText_loc7`='Nunca dejas de impresionarme, $n.' WHERE `ID`=75558;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅을 치유하고 우리의 상처를 아물게 하려면 아직 갈 길이 멀다. 하지만 너의 공으로 이제 이샤라즈의 일곱 숨결의 그림자는 걱정하지 않아도 되겠구나.$b$b시간이 지나면 샤는 사라질 것이고, 네 이름은 최후의 황제와 함께 칭송받고, 또 기억될 것이다.', `FemaleText_loc4`='要想治愈这片土地和我们自己的伤口，还有许多事情要做。多亏了你的帮助，我们再也不用担心亚煞极的七大吐息了。$b$b同时，煞魔也不再活动了，你的美名将与末代皇帝一样流芳百世。', `FemaleText_loc5`='如果我們想要治療這片大地，使我們的傷口癒合，我們還有許多工作要做。不過，感謝你的行動，讓我們無需繼續在亞煞拉懼七股氣息的陰影之下進行。$b$b隨時間過去，煞會徹底消失，你的名字會在回憶中受到像末代皇帝一樣的尊敬。', `FemaleText_loc7`='Nos queda mucho trabajo por delante para sanar la tierra y curar nuestras heridas. Pero gracias a tus hazañas, ya no nos acecha la sombra de las siete cabezas de Y''Shaarj.$b$bCon el tiempo, los sha dejarán de existir y tu nombre se recordará con tanta veneración como el del último emperador.' WHERE `ID`=75562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 잔 하시겠습니까, $c님?', `MaleText_loc4`='来喝一杯吧，$c？', `MaleText_loc5`='來一杯吧，$c?', `MaleText_loc7`='¿Te apetece una copa, $c?' WHERE `ID`=75563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적을 가지고 싸우십시오, 친구여.', `MaleText_loc4`='带着决心去战斗吧，朋友。', `MaleText_loc5`='為你的目標而戰，朋友。', `MaleText_loc7`='Lucha con decisión.' WHERE `ID`=75564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천신과 겨룰 수 있다니, 정말 뜻깊은 기회군요.', `FemaleText_loc4`='能和至尊天神战斗真是叫人羡慕。', `FemaleText_loc5`='能與天尊作戰真是令人佩服。', `FemaleText_loc7`='Luchar con un celestial es algo realmente admirable.' WHERE `ID`=75565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옛 친구들과 서로 어울리는 건 언제나 즐거운 일이죠.', `FemaleText_loc4`='和老朋友一起渡过的时光总是宝贵的。', `FemaleText_loc5`='能與老朋友一同打發時間真是愉快。', `FemaleText_loc7`='Siempre es un placer ponerse al día con los viejos amigos.' WHERE `ID`=75566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 섬은 아직 숨겨진 비밀들이 많다고 하더군요.', `FemaleText_loc4`='这座岛上藏着许多未解之谜。', `FemaleText_loc5`='這座島上有著許多還沒被發現的秘密。', `FemaleText_loc7`='Esta isla alberga muchos secretos que aún están por descubrir.' WHERE `ID`=75567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운이 우리에게 미소짓네요. 물건을 사줄 사람도 많아 보이고요.', `MaleText_loc4`='我们今天可走运了。好多人都来托运东西了。', `MaleText_loc5`='今天，幸運之神在對我們微笑。要給好多人送東西去。', `MaleText_loc7`='Hoy la fortuna nos sonríe. Hay mucha gente a la que entregar cosas.' WHERE `ID`=75568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r님, 당신은 정말 용사가 될 기질이 보여요.', `MaleText_loc4`='你很有冠军像哦，$r。', `MaleText_loc5`='你具有勇士般的步伐，$r。', `MaleText_loc7`='Tienes el andar de $gun campeón:una campeona;, $r.' WHERE `ID`=75569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쁜 그루멀이 좋은 그루멀이죠!', `MaleText_loc4`='忙碌的土地精才是好土地精！', `MaleText_loc5`='一個忙碌的咕嚕摩就是個好咕嚕摩!', `MaleText_loc7`='¡El buen grúmel es el grúmel ocupado!' WHERE `ID`=75570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가슴은 뜨겁게, 맥주는 맛있게! 꼭 기억하게나.', `MaleText_loc4`='愿你的美酒醇香，心志坚定。', `MaleText_loc5`='願你的酒勁強，心更強。', `MaleText_loc7`='Que tus brebajes sean fuertes, y tu corazón lo sea más aún.' WHERE `ID`=75571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 이야기는 아직 끝나지 않았네, 친구여.$B$B아주 멋진 이야기가 될 걸세.', `MaleText_loc4`='你的故事还将继续，朋友。$B$B这个故事很有看头。', `MaleText_loc5`='你的故事仍在繼續，朋友。$B$B這是個值得一讀的故事。', `MaleText_loc7`='Tu historia continúa, camarada.$b$bEs una historia digna de ser leída.' WHERE `ID`=75572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 진정한 $r답게 싸우는군.', `MaleText_loc4`='你战斗起来就像个真正的$r。', `MaleText_loc5`='你像是真正的$r一樣地戰鬥。', `MaleText_loc7`='Luchas como $gun auténtico:una auténtica; $r.' WHERE `ID`=75573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 떠돌아다니며 자신의 이야기를 쓰는 것보다 큰 기쁨은 없다네.$B$B그것이야말로 방랑자의 길 아니겠는가.', `MaleText_loc4`='再也没有比环游世界，谱写你的故事更有趣的工作了。$B$B这就是云游者之道。', `MaleText_loc5`='沒有什麼是比在這個世界上恣意漫遊、寫下自己的故事更愜意的。$B$B這就是浪人之道。', `MaleText_loc7`='No hay mayor alegría que recorrer el mundo y escribir tu propia historia.$b$bEs la filosofía del viajero.' WHERE `ID`=75574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에 술이 빠질 수야 없지!', `MaleText_loc4`='这种场合怎么能少了美酒呢！', `MaleText_loc5`='這種時候就該喝一杯!', `MaleText_loc7`='¡Una ocasión como esta se merece un trago!' WHERE `ID`=75575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='같이 이 섬을 탐험할래요?', `FemaleText_loc4`='想跟我一起去岛上探险吗？', `FemaleText_loc5`='想要一起去探索這座島嗎?', `FemaleText_loc7`='¿Quieres explorar la isla conmigo?' WHERE `ID`=75576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불꽃놀이 봤어요? 정말 예쁘다고요!', `FemaleText_loc4`='你看到那些烟火了吗？真漂亮！', `FemaleText_loc5`='你看到煙火了嗎?真是美麗!', `FemaleText_loc7`='¿Has visto los fuegos artificiales? ¡Son estupendos!' WHERE `ID`=75577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천신들은 정말 큼지막해요!', `FemaleText_loc4`='至尊天神都好高大啊！', `FemaleText_loc5`='天尊們好巨大啊!', `FemaleText_loc7`='¡Los celestiales son enormes!' WHERE `ID`=75578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야, 당신은 $c죠?$B$B$C는 정말 최고에요!', `FemaleText_loc4`='哇，你肯定是个$c吧？$B$B$C最厉害了！', `FemaleText_loc5`='哇，你一定是位$c，嗯?$B$B$C是最棒的!', `FemaleText_loc7`='¡Guau! ¡Así que eres $gun:una; $c!$b$bNo sabía que ser $gun:una; $c fuera algo tan genial...' WHERE `ID`=75579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투와 맥주. 이보다 더 좋을 수는 없군요.', `MaleText_loc4`='战斗和啤酒。再也没有比这里更棒的地方了。', `MaleText_loc5`='有酒喝，有架打，沒有比這裡更好的地方了。', `MaleText_loc7`='Peleas y cerveza. Este es el mejor lugar del mundo.' WHERE `ID`=75581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 술은 제가 사겠습니다!', `MaleText_loc4`='下次我请！', `MaleText_loc5`='下一輪算我的!', `MaleText_loc7`='¡Invito a la siguiente ronda!' WHERE `ID`=75582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 좋은 날이군요.', `MaleText_loc4`='今天是个好日子。', `MaleText_loc5`='今天是個好日子。', `MaleText_loc7`='Hoy es un buen día.' WHERE `ID`=75583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상 모든 대륙에 내 정보원들이 있는데, 그중 누구도 오그리마에서 벌어진 일을 내게 제대로 설명하지 못했다!', `MaleText_loc4`='我的密探遍布各个大陆，可没有一个人能明白地告诉我，奥格瑞玛到底出了什么事！', `MaleText_loc5`='我在每個大陸上都佈有密探，但沒有人能清楚地告訴我奧格瑪的現狀!', `MaleText_loc7`='¡Tengo agentes en los cuatro costados del mundo y ninguno es capaz de decirme lo que ha pasado en Orgrimmar!' WHERE `ID`=75584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 왕!', `MaleText_loc4`='该死的国王！', `MaleText_loc5`='白痴國王!', `MaleText_loc7`='¡Rey idiota!' WHERE `ID`=75585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 여길 떠날 수 없다. 집에 가는 길은 없어.', `MaleText_loc4`='你休想离开这里。你回不去了。', `MaleText_loc5`='你不能離開這裡。你無路可退。', `MaleText_loc7`='Nunca se irán de este lugar. No hay forma de regresar.' WHERE `ID`=75586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이 여길 벗어나는 유일한 길. 이제 네 세상엔 아무것도 없다.', `MaleText_loc4`='要想离开这里，唯有一死。你的世界已经化为乌有了。', `MaleText_loc5`='想要離開這裡，你就會死。你的世界已經完全毀滅。', `MaleText_loc7`='Morirás cuando se vayan de este lugar. No queda nada de tu mundo.' WHERE `ID`=75587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이미 졌다.', `MaleText_loc4`='你已经失败了。', `MaleText_loc5`='你已經輸了。', `MaleText_loc7`='Ya han perdido.' WHERE `ID`=75588;
