UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 내려오세요. 피시 님이 떨어지면 제가 농사꾼 연합에 뭐라고 얘기해야겠어요?', `MaleText_loc4`='拜托，快下来吧。你让我怎么去跟其他阡陌客交代啊？', `MaleText_loc5`='拜託你，下來吧。我要怎麼跟耕者工會的其他人解釋?', `MaleText_loc7`='Baja de una vez. ¿Cómo voy a explicarles esto a los Labradores?' WHERE `ID`=75608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요, 그냥 떨어져요. 신경 안 쓸테니까요.', `MaleText_loc4`='很好，摔下来吧。我不在乎。', `MaleText_loc5`='隨便，摔就摔吧，我不在乎。', `MaleText_loc7`='Vale, cáete si quieres. Me da igual.' WHERE `ID`=75609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조에 관해서 정말 많은 걸 배웠다네. 아직 완벽한 맥주에는 다다르지 못했지만, 확실히 나아지고 있어!', `MaleText_loc4`='我学到了很多酿酒知识。我还没能酿出自己的酒，但快了！', `MaleText_loc5`='我學到了很多釀酒知識，我還沒有釀出過恰到好處的酒，不過我快成功了!', `MaleText_loc7`='He aprendido mucho sobre la elaboración de la cerveza. Todavía no me sale perfecta, ¡pero voy progresando!' WHERE `ID`=75618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 술을 팔고 계십니까?', `MaleText_loc4`='你现在有些什么？', `MaleText_loc5`='你現在有哪些存貨?', `MaleText_loc7`='¿Qué tienes en venta?', `FemaleText_loc1`='어떤 술을 팔고 계신가요?', `FemaleText_loc4`='你现在有些什么？', `FemaleText_loc5`='你現在有哪些存貨?', `FemaleText_loc7`='¿Qué tienes en venta?' WHERE `ID`=75619;
