UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸움에는 역시 맛 좋은 술이 있어야죠!', `FemaleText_loc4`='没有好酒的战斗不是好战斗！', `FemaleText_loc5`='戰鬥沒有配上好酒的話就不是戰鬥了!', `FemaleText_loc7`='¡El combate no es lo mismo sin un buen brebaje!' WHERE `ID`=75626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 술처럼 좋은 것도 없지!', `MaleText_loc4`='再没有比美酒更好的东西了！', `MaleText_loc5`='什麼都比不上一杯好喝的啤酒!', `MaleText_loc7`='¡No hay nada mejor que un buen brebaje!' WHERE `ID`=75627;
