UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 마시느냐가 그 사람을 결정한다네, $n. 그간 강한 걸 마셨길 비네.', `MaleText_loc4`='你就像你喝的酒，$n——呃，但愿你喝的是烈酒吧。', `MaleText_loc5`='什麼人喝什麼酒，$n。我希望你向來都是喝烈酒。', `MaleText_loc7`='Somos lo que bebemos, $n. Así que espero que te gusten las bebidas fuertes.' WHERE `ID`=75629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠네만, 전략이 영 틀렸어. 한잔 하면서 곰곰이 생각해 보게나.', `MaleText_loc4`='你打得很好，但你的战术完全错了。来喝一杯，好好想想吧。', `MaleText_loc5`='你打得很好，但戰術全錯了。好好喝一杯，再重新想過。 ', `MaleText_loc7`='Has luchado bien, pero tu táctica es imperfecta. Tómate una copa y reflexiona.' WHERE `ID`=75630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 보게, 내가 졌잖아! 다음엔 뭔가 새로운 작전을 짜내야겠군.', `MaleText_loc4`='你看看，我可被打惨了！下次我得好好想几个计划。', `MaleText_loc5`='你看看我，被打得慘兮兮!我要去為下次戰鬥好好想些計策了。', `MaleText_loc7`='¡Vaya! ¡Me han derrotado! Voy a tener que inventarme algo para la próxima vez.' WHERE `ID`=75631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 녀석은 왜 싸웠을까? 내 보기엔 죽기 위해서였던 것 같군.', `MaleText_loc4`='他为什么要打比赛？很显然，就是为了找死。', `MaleText_loc5`='他為什麼要上場?很明顯，是來找死的。', `MaleText_loc7`='¿Por qué luchaba? Para morir, por lo visto.' WHERE `ID`=75632;
