UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면, 에, 당신은 혼돈에서 교훈을 얻을 준비가 됐는지도 모르겠소만?', `MaleText_loc4`='你，呃，做好学习混沌之道的准备了吗？', `MaleText_loc5`='或許，呃，或許你已經準備好上一堂關於混沌的課程了?', `MaleText_loc7`='¡Prepárate para una lección sobre el caos!' WHERE `ID`=75638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 자신이 이길지 질지에만 너무 정신이 팔려 있었소. 정녕 이겨야만 하는지에 대해서는 생각해보지 않았지.', `MaleText_loc4`='你太过执着于输赢，却没有停下来想想是否应该这么做。', `MaleText_loc5`='你太煩惱自己能不能贏，卻沒有停下來思考你該不該這麼做。', `MaleText_loc7`='Te preocupaba tanto si podías o no ganar, que no te paraste a pensar si debías.' WHERE `ID`=75639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 자연 앞에서 이렇게 겸허하지 않은 태도를 보이다니, 에... 충격적이군.', `MaleText_loc4`='喔唷，你还真是不懂得敬畏自然啊，呃……我真是太吃惊了。', `MaleText_loc5`='啊，對大自然不敬的後果就是這樣，呃...嚇死我了。', `MaleText_loc7`='La falta de humildad ante la naturaleza que se demuestra aquí... me deja atónito.' WHERE `ID`=75640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 어째서 위대하오? 손 닿는 모든 것에 상처를 남기는 폭력적인 행위일 뿐인데. 당신이 승리라 부르는 것은... 아, 그만둡시다.', `MaleText_loc4`='胜利好在什么地方？那是一种让人刻骨铭心的暴力行为。你所说的胜利……呃，还是算了。', `MaleText_loc5`='勝利到底有什麼得意的?這是種暴力、充滿破壞力的行為，凡有勝利，就有滿目瘡痍。你所謂的勝利不過就是...算了，當我沒說。', `MaleText_loc7`='¿Y qué hay de bueno en la victoria? Es un acto violento de invasión que hiere lo que explora. Lo que tú llamas victoria... Bah, da igual.' WHERE `ID`=75641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음? 소멸이 맞는 말 아니오?', `MaleText_loc4`='死了？你是指灭绝吗？', `MaleText_loc5`='死了?你是說絕種了吧?', `MaleText_loc7`='¿Muerto? ¿Quieres decir extinto?' WHERE `ID`=75642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 애완동물에게는 기회가 주어졌고, 자연은 녀석의 소멸을 택했소.', `MaleText_loc4`='你的宠物完全是活该，自然已经决定了它的灭绝。', `MaleText_loc5`='你的寵物有其缺點，這正是物競天擇、適者生存的體現。', `MaleText_loc7`='Tu mascota tuvo su oportunidad, y la naturaleza la seleccionó para su extinción.' WHERE `ID`=75643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내, 내가 보기에 그 생명체는, 에... 방법을 찾지 못한 것 같소.', `MaleText_loc4`='我，我只是说生命，呃……是找不到出路的。', `MaleText_loc5`='我，我只是說...生命沒有找到出路.', `MaleText_loc7`='Yo solo digo que la vida... no se abrió camino. ' WHERE `ID`=75644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거... 이거야말로 혼돈 이론이지.', `MaleText_loc4`='这，这就是混沌理论。', `MaleText_loc5`='這，這是混沌理論。', `MaleText_loc7`='Esa, esa es la teoría del caos.' WHERE `ID`=75645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 팀에 대체 어떤 대단한 애완동물이 있는 거요? 밀림의 왕 무클라?', `MaleText_loc4`='你队伍里那是什么啊，穆克拉？', `MaleText_loc5`='你隊伍裡都是什麼烏合之眾啊，穆克拉大王?', `MaleText_loc7`='¿Qué tienes en ese equipo? ¿Al rey Mukla?' WHERE `ID`=75646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공룡... 배설물?', `MaleText_loc4`='恐龙……粪便？粪便？', `MaleText_loc5`='恐龍...倒下了?真的倒下了?', `MaleText_loc7`='Dinosaurios... ¿muertos? ¿Muertos?' WHERE `ID`=75647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 이제 뭘 상대해야 하는지 아나? 인내! 지혜! 지식일세! 자네는 어떤 미덕을 지녔나, $n?', `MaleText_loc4`='你将要面对耐心！智慧！还有知识！你又有哪些优点呢，$n？', `MaleText_loc5`='$n，你要面對的是耐心、知識和智慧的挑戰，而你又擁有哪些美德呢?', `MaleText_loc7`='¡Te enfrentas a la paciencia! ¡A la sabiduría! ¡Al conocimiento! ¿Qué virtudes posees, $n?' WHERE `ID`=75648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 오늘 졌네... 하지만 덕분에 무엇을 배웠을까?', `MaleText_loc4`='今天你失败了——可你从中学到了什么呢？', `MaleText_loc5`='今天你雖有所失，但也有所得吧?', `MaleText_loc7`='Hoy has perdido... ¿pero qué has aprendido?' WHERE `ID`=75649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 많은 가르침을 얻었네, $r. 스승이 다시 제자가 된 것 같군.', `MaleText_loc4`='你教会了我很多，$r。看来老师又变成学生了。', `MaleText_loc5`='你教了我很多事，$r。感覺就像大師重新做回了學生。', `MaleText_loc7`='Me has enseñado muchas cosas, $r. Parece que el maestro vuelve a ser el discípulo.' WHERE `ID`=75650;
