UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙엽이 떨어져야 새순이 돋는 법이지.', `MaleText_loc4`='秋叶必须为春花让路。', `MaleText_loc5`='落紅不是無情物，化作春泥更護花。', `MaleText_loc7`='Las hojas del otoño deben caer para dejar paso a las flores de la primavera.' WHERE `ID`=75652;
