UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물줄기가 벼랑을 만났을 때처럼, 추락에도 모종의 아름다움이 있다네. 무엇을 봐야 하는지 안다면 말일세.', `MaleText_loc4`='如同溪流遭遇悬崖就会变成美丽的瀑布，只要你懂得该从何处着眼。', `MaleText_loc5`='正如泉石相激之時，其墜落之美，只有慧眼獨具的人懂得欣賞。', `MaleText_loc7`='Como el arroyo que se encuentra con un acantilado, la caída puede ser hermosa, si sabes dónde mirar.' WHERE `ID`=75654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이란 놀랍도록 위대한 모험이지.', `MaleText_loc4`='死亡将是一场神奇的大冒险。', `MaleText_loc5`='慷慨赴死將是最偉大、最壯烈的冒險。', `MaleText_loc7`='Morir será una gran aventura. ' WHERE `ID`=75655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미덕을 하나 잃으면, 남은 미덕을 잘 지켜야 하네.', `MaleText_loc4`='如果你失去了一项美德，就必须牢牢把握剩余的那些。', `MaleText_loc5`='若失去了一個美德，就該更加堅守剩下的美德。', `MaleText_loc7`='Cuando una virtud se pierde, aférrate a las que quedan.' WHERE `ID`=75656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가치 있는 희생인가?', `MaleText_loc4`='这样的牺牲值得吗？', `MaleText_loc5`='這犧牲有價值嗎?', `MaleText_loc7`='¿Un sacrificio digno?' WHERE `ID`=75657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 깜짝 놀라는 걸 좋아하셨으면 좋겠군요.', `FemaleText_loc4`='噢，但愿你会喜欢惊喜。', `FemaleText_loc5`='噢，希望你喜歡驚喜啊。', `FemaleText_loc7`='Espero que te gusten las sorpresas.' WHERE `ID`=75658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저렇게 된 게 당신의 애완동물일 뿐이라는 걸 감사하셔야 할 거예요... 이번에는 말이죠.', `FemaleText_loc4`='算你走运，这次还只是你的宠物……', `FemaleText_loc5`='算你好運，這次只是你的寵物...', `FemaleText_loc7`='Tienes suerte de que solo haya acabado con tus mascotas... Esta vez.' WHERE `ID`=75659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천신의 시합에서는 이기거나 죽는 길뿐이죠.', `FemaleText_loc4`='在天神比武大会上，向来都是你死我活的。', `FemaleText_loc5`='天尊武道會中，你只有勝利跟死亡兩條路。', `FemaleText_loc7`='En el Torneo Celestial, o ganas o mueres.' WHERE `ID`=75660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 강한 놈을 처치하고 나면 그때부턴 일사천리죠.', `FemaleText_loc4`='把握机会，趁胜追击。', `FemaleText_loc5`='先解決掉正確的對手，接下來就輕鬆了。', `FemaleText_loc7`='Si matas al oponente adecuado, todo lo demás va rodado.' WHERE `ID`=75661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 아끼는 녀석이었나요? 죄송해라.', `FemaleText_loc4`='噢，那是你最喜欢的宠物？我很抱歉。', `FemaleText_loc5`='噢，那是你最喜歡的之一?抱歉抱歉。', `FemaleText_loc7`='Ah, ¿era tu mascota favorita? Lo siento.' WHERE `ID`=75662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 쉬워서 지루할 뻔했어요... 사실은 재미있었다는 게 함정이지만.', `FemaleText_loc4`='要不是本身很有意思的话，这么轻松的战斗就会很无聊。', `FemaleText_loc5`='這太簡單了，會很無聊...幸好還算有趣。', `FemaleText_loc7`='Esto es tan fácil que sería aburrido... si no fuera tan divertido.' WHERE `ID`=75663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 짓을! 내 애완동물이 다시는 못 걷게 됐잖아요!', `FemaleText_loc4`='你这混蛋，我的宠物恐怕再也不能走路了！', `FemaleText_loc5`='你這混蛋，我的寵物可能會從此殘廢!', `FemaleText_loc7`='¡Maldita sea! ¡Puede que mi mascota no vuelva a andar!' WHERE `ID`=75664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 사랑하는 것들은 언제나 우리를 파멸시킨답니다, $c님. 기억하세요.', `FemaleText_loc4`='我们所珍爱的东西总会毁掉我们自己，$c，记住这句话。', `FemaleText_loc5`='我們所愛的事物每次都會摧毀我們，$c。要記得這一點。', `FemaleText_loc7`='Aquello que amamos nos destruye, $c. No lo olvides.' WHERE `ID`=75665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속 제 애완동물을 쓰러뜨리시면, 오늘밤 당신이 마시는 음료 안에 독이 약간 들어 있을지도 몰라요.', `FemaleText_loc4`='你要再敢伤害我的宠物，你今晚的酒杯里就会多出一滴毒药了。', `FemaleText_loc5`='再殺死我的寵物，你晚上喝的飲料可能就會被下毒。', `FemaleText_loc7`='Si sigues matando a mis mascotas, encontrarás veneno en tu bebida esta noche.' WHERE `ID`=75666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공포가 칼보다 깊은 상처를 내죠.', `FemaleText_loc4`='恐惧比利剑伤得更深。', `FemaleText_loc5`='恐懼比劍的傷害還深。', `FemaleText_loc7`='El miedo hiere más que las espadas.' WHERE `ID`=75667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운의 기즈모가 없어도 난 자네를 납작하게 만들 수 있다네, $c.', `MaleText_loc4`='算你走运，吉兹莫来不了了，可我照样能把你打得落花流水，$c。', `MaleText_loc5`='你這走運的吉事摩可不能待在這裡，不過我還是會跟你一起擦地板的，$c。', `MaleText_loc7`='Tienes suerte de que Gizmo no esté aquí... ¡pero pienso barrer el suelo contigo de todas formas, $c!' WHERE `ID`=75668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 승리를 네게 바치마, 기즈모!', `MaleText_loc4`='这场胜利是送给你的，吉兹莫！', `MaleText_loc5`='那個是給你的，吉事摩!', `MaleText_loc7`='¡Esa va por ti, Gizmo!' WHERE `ID`=75669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽, 동물이랑 잘 지내는 게 참 만만찮은 일이란 말이지. 자, 붕대를 어떻게 쓰는 거더라?', `MaleText_loc4`='哎，我指挥动物的本事也就这样了。这些绷带该怎么用？', `MaleText_loc5`='啊，對動物仁慈的下場就是這樣。這些繃帶效果如何?', `MaleText_loc7`='Ay, y yo que pensaba que se me daban bien los animales. ¿Cómo funcionan las vendas?' WHERE `ID`=75670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 생각보다 더 잘 먹혔는데!', `MaleText_loc4`='哈！这比我想象中还要管用！', `MaleText_loc5`='哈!比我想的還管用!', `MaleText_loc7`='¡Ja! ¡Ha ido mejor de lo que esperaba!' WHERE `ID`=75671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 미안하네. 나중에 그 녀석 잘 보듬어줘야 할 게야.', `MaleText_loc4`='噢，抱歉，你待会儿恐怕要好好安慰安慰那家伙了。', `MaleText_loc5`='噢，抱歉，那傢伙待會需要愛的抱抱了。', `MaleText_loc7`='¡Lo siento! ¡Vas a tener que curar a tu amiguito!' WHERE `ID`=75672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 잠깐은 이거 큰일났다고 생각했다네.', `MaleText_loc4`='有那么一瞬间，我还以为我们要有大麻烦了。', `MaleText_loc5`='曾有那麼一瞬間，我以為我們完蛋了。', `MaleText_loc7`='Por un momento pensé que estábamos en apuros.' WHERE `ID`=75673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 다시 이런 일이 생기다니!', `MaleText_loc4`='不！又输了！', `MaleText_loc5`='不!別再來了!', `MaleText_loc7`='¡No! ¡Otra vez no!' WHERE `ID`=75674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프의 행운 따위 개나 주라지!', `MaleText_loc4`='我这该死的运气！', `MaleText_loc5`='該死，走什麼矮人霉運!', `MaleText_loc7`='¡Maldita suerte enana!' WHERE `ID`=75675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악, 자네 후회하게 될 걸세. 가만두지 않겠어!', `MaleText_loc4`='喂，你会为此付出代价的！', `MaleText_loc5`='噢，你會付出代價的，肯定會!', `MaleText_loc7`='¡Oh! ¡Me las pagarás por eso!' WHERE `ID`=75676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 크기에 속지 말게, $n. 그들은 잘 단련된, 재빠른 수도사들일세.', `MaleText_loc4`='别被他们娇小的体型给骗了，$n，他们可都是训练有素，行动敏捷的家伙。', `MaleText_loc5`='別被他們嬌小的身軀給騙了，$n，他們可是有紀律又迅速。', `MaleText_loc7`='Que no te engañe su tamaño, $n. Son rápidos y disciplinados.' WHERE `ID`=75677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성급함은 패배의 지름길이지. 절호의 기회를 포착하는 법을 익혀야 하네.', `MaleText_loc4`='莽撞是失败的根源，你必须学会控制节奏。', `MaleText_loc5`='輕舉妄動只會招致失敗，你必須學著掌握時機。', `MaleText_loc7`='La impaciencia es el camino a la derrota. Aprende a sincronizar tus movimientos.' WHERE `ID`=75678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 수도사들을 쓰러뜨리려면 치밀한 전략이 필요하지. 잘했네, $n.', `MaleText_loc4`='要想击败我的武僧们真的需要高明的战术。干得好，$n。', `MaleText_loc5`='只有最狡猾的戰略家才有本事打敗我的武僧。做得好，$n。', `MaleText_loc7`='Hace falta una estrategia muy astuta para derrotar a mis monjes. Bien hecho, $n.' WHERE `ID`=75679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 계획대로군.', `MaleText_loc4`='跟我预想的完全一样。', `MaleText_loc5`='正如我所計劃的。', `MaleText_loc7`='Justo lo que esperaba.' WHERE `ID`=75680;
