UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 녀석들과 함께 이 전투를 헤쳐나갈 수 있겠나?', `MaleText_loc4`='你还能靠剩下的宠物反败为胜吗？', `MaleText_loc5`='你能在接下來的戰鬥中全身而退嗎?', `MaleText_loc7`='¿Puedes sobrevivir con lo que te queda?' WHERE `ID`=75682;
