UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리엔 종종 희생이 따르는 법.', `MaleText_loc4`='胜利总是需要牺牲的。', `MaleText_loc5`='勝利往往是用犧牲換來的。', `MaleText_loc7`='La victoria suele exigir sacrificios.' WHERE `ID`=75684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 대원 한 명이 쓰러지면, 다른 이가 떨치고 나와 그의 자리를 채우지.', `MaleText_loc4`='当一名影踪派成员倒下时，总会有更多战友站出来顶上他的位置。', `MaleText_loc5`='當一名影潘倒下時，另一個就會上前遞補。', `MaleText_loc7`='Cuando un miembro del Shadopan cae, otro ocupa su puesto.' WHERE `ID`=75685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙숫물이 바위를 뚫듯, 당신은 패배할 것입니다.', `MaleText_loc4`='就像水滴能令石穿，我们也将成为你的终结者。', `MaleText_loc5`='正如水能穿石，我們也會擊潰你。', `MaleText_loc7`='Te derrotaremos igual que el agua parte la roca.' WHERE `ID`=75686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강이 이 승리를 예견했지요.', `MaleText_loc4`='河流早就预言了这场胜利。', `MaleText_loc5`='河流已經預言了這場勝利。', `MaleText_loc7`='Los ríos vaticinaron este triunfo.' WHERE `ID`=75687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강이 이 패배를 예견했지요.', `MaleText_loc4`='河流早就预言了这场失败。', `MaleText_loc5`='河流已經預言了這次失敗。', `MaleText_loc7`='Los ríos vaticinaron esta derrota.' WHERE `ID`=75688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희미한 흔적만 남기고, 존재가 물에 휩쓸려 버렸군요.', `MaleText_loc4`='他们连同那一点可怜的痕迹都被一起冲刷掉了。', `MaleText_loc5`='他們被洗得乾乾淨淨，幾乎不留先前的蛛絲馬跡。', `MaleText_loc7`='La marea se lleva lo poco que queda de este animal...' WHERE `ID`=75689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위는 자기가 꿈쩍도 않으리라 여기지만, 자길 붙들고 있는 흙이 떠내려가면 진실을 알게 되죠.', `MaleText_loc4`='岩石总以为自己不可撼动，直到它身下的大地被一起冲走。', `MaleText_loc5`='直到山崩地裂之前，石頭都以為自己是至堅不移的。', `MaleText_loc7`='La roca se cree inamovible, hasta que el agua se lleva el suelo sobre el que reposa.' WHERE `ID`=75690;
