UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 친구가 흩어졌군요. 때가 되면 다시 제게 흘러올 것입니다.', `MaleText_loc4`='我的同伴被打散了。但她一定会在适当的时候卷土重来的。', `MaleText_loc5`='我的夥伴被驅散了。時機對了，她就會回到我身邊了。', `MaleText_loc7`='Mi mascota se ha dispersado. Fluirá hasta mí cuando sea el momento.' WHERE `ID`=75692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 하나로 강의 흐름을 막을 수는 없습니다.', `MaleText_loc4`='一块孤岩阻挡不了汹涌澎湃的河流。', `MaleText_loc5`='河水不因一枚石子而停止流動。', `MaleText_loc7`='El río no se detiene ante una simple piedra.' WHERE `ID`=75693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썰물과 밀물처럼, 전투에도 변화가 있는 법이지요.', `MaleText_loc4`='战斗中总是免不了会有高潮和低谷。', `MaleText_loc5`='戰鬥中的跌宕起伏都是備受期待的。', `MaleText_loc7`='Es el flujo de toda batalla.' WHERE `ID`=75694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영겁의 시간 끝에 내가 돌아왔다.', `MaleText_loc4`='亘古的呼唤唤醒了我。', `MaleText_loc5`='我已從萬古長夜中甦醒。', `MaleText_loc7`='Los eones me han despertado.' WHERE `ID`=75695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용은 어떤 크기라도 무시무시하지. 곧 직접 느끼게 해주마.', `MaleText_loc4`='龙无论大小都是非常危险的，我一定会让你明白这一点的。', `MaleText_loc5`='龍不管體型多大都很危險，我很確定你會知道的。', `MaleText_loc7`='Los dragones de todos los tamaños son peligrosos. Estás a punto de comprobarlo.' WHERE `ID`=75696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투에서 이긴 걸 보면 천신과의 전투에서도 승산이 있겠군.', `MaleText_loc4`='如果我能赢得这样的战斗，那我或许就有机会战胜至尊天神了。', `MaleText_loc5`='如果我能那樣贏一場，我可能就有機會對抗天尊了。', `MaleText_loc7`='Si soy capaz de ganar un combate como este, puede que consiga vencer a los celestiales.' WHERE `ID`=75697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, $n. 친구를 잘 고르고 명예롭게 그들을 이끌었군.', `MaleText_loc4`='干得好，$n。你明智地选择了自己的战友，并出色地领导了它们。', `MaleText_loc5`='做得好，$n。你明智地挑選你的朋友，並以榮耀帶領他們。', `MaleText_loc7`='Bien hecho, $n. Has elegido bien a tus amigos, y los has dirigido con honor.' WHERE `ID`=75698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 경고했다시피, 용들은 무시무시한 공격으로 유명하지.', `MaleText_loc4`='我早就警告过你，龙是以其致命的攻击而著称的。', `MaleText_loc5`='就像我之前提醒過的，龍的致命攻擊可是出了名的。', `MaleText_loc7`='Como te advertí, los dragones son conocidos por sus ataques mortales.' WHERE `ID`=75699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 강력한 동료도 용의 마법 앞에서 무릎 꿇을 수 있지.', `MaleText_loc4`='哪怕是最强大的盟友也会倒在龙族魔法之下。', `MaleText_loc5`='就是最強大的盟友，都可能敗在龍的法術之下。', `MaleText_loc7`='Hasta el aliado más fuerte puede caer ante la magia dracónica.' WHERE `ID`=75700;
