UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 내가 처음엔 보지 못한 힘을 지니고 있구나.', `MaleText_loc4`='你的力量超出了我的预料。', `MaleText_loc5`='你擁有我一開始沒看出來的力量。', `MaleText_loc7`='Tienes una fuerza que no se ve a simple vista.' WHERE `ID`=75702;
