UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 손실을 만회하기란 어렵겠는데.', `MaleText_loc4`='这真是个难以弥补的损失。', `MaleText_loc5`='要從這麼慘重的損傷中恢復，會是件難事。', `MaleText_loc7`='Será difícil sobreponerse a una pérdida semejante.' WHERE `ID`=75704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슝!!!', `MaleText_loc4`='轰！', `MaleText_loc5`='咻!!', `MaleText_loc7`='¡Zum!' WHERE `ID`=75705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 참상에 절망하지 말게.', `MaleText_loc4`='不要因为这儿的满目疮痍而绝望。', `MaleText_loc5`='別為這裡受到的破壞感到絕望。', `MaleText_loc7`='No desesperes por el daño aquí causado.' WHERE `ID`=75706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 전, 이 땅은 의심, 공포, 증오의 그림자로 가득했네.', `MaleText_loc4`='很久很久以前，这片土地曾为猜忌、恐惧和仇恨的阴影所笼罩。', `MaleText_loc5`='很久以前，這塊土地籠罩在懷疑、恐懼和仇恨的陰影下。', `MaleText_loc7`='Hace mucho tiempo, esta tierra sufrió a la sombra de la duda, el miedo y el odio.' WHERE `ID`=75707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 하나, 난 그들을 극복했고, 대지 깊은 곳에 묻어두었지.', `MaleText_loc4`='我将其逐一制服——并深深埋入地下。', `MaleText_loc5`='我會一個一個擊敗他們，把他們深深埋進地底。', `MaleText_loc7`='Una a una, vencí a esas emociones y las enterré profundamente.' WHERE `ID`=75708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그곳에... 이들은 남았다네.', `MaleText_loc4`='可是……它们依然存在。', `MaleText_loc5`='他們仍然...屹立不搖。', `MaleText_loc7`='Y allí... pervivieron.' WHERE `ID`=75709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만 년 동안... 안개의 장막은 판다리아를 적들의 눈으로부터 숨겨주었네.', `MaleText_loc4`='一万年以来……浓雾保护着潘达利亚不受外敌的觊觎。', `MaleText_loc5`='一萬年來...這片迷霧就如面紗，將潘達利亞隱於窺探之下。', `MaleText_loc7`='Durante diez mil años... mientras el velo de niebla ocultaba Pandaria de ojos curiosos.' WHERE `ID`=75710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이 일어났을 때, 나는 안개의 일부를 걷어내기로 결정했네... 부서진 세계의 치유를 돕기 위해.', `MaleText_loc4`='当大灾变降临时，我意识到散去迷雾的时刻到了……我们要协助治愈这个破碎的世界。', `MaleText_loc5`='當大災變發生，我認為驅散迷霧...治療我們破碎世界的時機到了。', `MaleText_loc7`='Cuando llegó el Cataclismo, decidí que era el momento de despejar la niebla... Y ayudar a sanar nuestro mundo.' WHERE `ID`=75711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 자네들의 전함이 우리 해안에 들이닥쳤을 때, 내 모든 의심과 공포는 다시 차올랐네. 이 땅에 다시 고통을 안기기 위해.', `MaleText_loc4`='可当你们的舰队抵达我们的海岸，我昔日的猜忌和恐惧再次袭来，又一次在这片土地上肆虐。', `MaleText_loc5`='But as your war-fleets crashed upon our shores, all of my old doubts and fears rose up, to torment the land once again.', `MaleText_loc7`='Pero cuando sus flotas de guerra tomaron nuestras costas, todos mis miedos y mis dudas volvieron para atormentar la tierra.' WHERE `ID`=75712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 내가 묻어둔 어둠에 맞서 승리했네.', `MaleText_loc4`='你战胜了那被封印已久的黑暗。', `MaleText_loc5`='你們成功驅散了被我深鎖的黑暗。', `MaleText_loc7`='Triunfaste sobre la oscuridad que yo alguna vez aprisioné.' WHERE `ID`=75713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에 진짜 영웅의 힘을 보여줬지.', `MaleText_loc4`='向潘达利亚展示了一个真英雄的力量。', `MaleText_loc5`='你們向潘達利亞展現了真英雄的力量。', `MaleText_loc7`='Le has mostrado a Pandaria el poder de un verdadero héroe.' WHERE `ID`=75714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 아직 의문이 남았네... 우리가 왜 싸우는가?', `MaleText_loc4`='但你是否仍有困惑：吾辈何以为战？', `MaleText_loc5`='但疑問仍未解答...我族為何而戰?', `MaleText_loc7`='Pero la pregunta sigue sin respuesta... ¿por qué luchamos?' WHERE `ID`=75715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 맞서게. 증오를 거두게.', `MaleText_loc4`='直面恐惧。抛开仇恨。', `MaleText_loc5`='面對恐懼。平息仇恨。', `MaleText_loc7`='Enfrenta tus miedo. Calma tus odios.' WHERE `ID`=75716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신의 내면에서 평화를 찾게. 그리고 그 평화를 세상과 나누게.', `MaleText_loc4`='只有当自己静心忍性，才能做到万物归心，宠辱不惊。', `MaleText_loc5`='尋求自我的寧靜，來與身邊的世人一起分享。', `MaleText_loc7`='Encuentra paz interna, para que puedas compartirla con el mundo que te rodea.' WHERE `ID`=75717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이는 삶에서 가장 위대한 보물이니.', `MaleText_loc4`='这些才是生命宝贵的真谛。', `MaleText_loc5`='這些才是生命中最大的寶藏。', `MaleText_loc7`='Estos son los tesoros más valiosos en la vida.' WHERE `ID`=75718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이야말로... 싸울 가치가 있는 것이라네.', `MaleText_loc4`='告诉了我们何以为战。', `MaleText_loc5`='這些才真的值得一戰。', `MaleText_loc7`='Sin duda... Merece la pena luchar por ellos.' WHERE `ID`=75719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 말코록이 침입자들을 모두 찢어버린 것 같군.', `MaleText_loc4`='嘿，听起来马尔考罗克已经把那些入侵者给撕成碎片了。', `MaleText_loc5`='嘿，聽上去馬可羅克剛把入侵者打個稀巴爛。', `MaleText_loc7`='Ja. Parece que Malkorok acaba de pulverizar a los intrusos.' WHERE `ID`=75720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠어. 느낌이 안 좋아. 너무 조용하단 말이지.', `MaleText_loc4`='不知道，但我的感觉不太好。那边有点太安静了。', `MaleText_loc5`='我不知道，我有不祥的預感。這裡安靜得不尋常。', `MaleText_loc7`='No sé, este silencio me da mala espina...' WHERE `ID`=75721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 우리 밖으로 나오려 한다! 전기 목줄을 작동시켜! 놈을 통제해야 돼!', `MaleText_loc4`='它要从笼子里冲出来了！快用电击项圈控制住它！', `MaleText_loc5`='牠要從籠子裡衝出來了!快用電擊項圈控制牠!', `MaleText_loc7`='¡El demosaurio se escapa de su jaula! ¡Prepara el collar de choques y pon a esa cosa bajo control!' WHERE `ID`=75722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못 움직일 때까지 충격을 줘라! 사태가 더 커지기 전에!', `MaleText_loc4`='电击它，别让它动弹！真是一团糟！', `MaleText_loc5`='直到牠不能動為止!牠把這搞的一團糟!', `MaleText_loc7`='Arggg, ¡está provocando que los otros animales se rebelen! ¡Sacúdelo hasta que no se mueva más!' WHERE `ID`=75723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 데빌사우루스부터 처리하고, 나머지를 가두자!', `MaleText_loc4`='先对付魔暴龙，然后把剩下的关起来！', `MaleText_loc5`='先對付魔暴龍，然後再把剩下的關起來!', `MaleText_loc7`='¡Tu prioridad número uno es que no te coman! ¡Ignora al resto de las criaturas y derriba a ese demosaurio!' WHERE `ID`=75724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천치! 얼간이!', `MaleText_loc4`='蠢货！低能！', `MaleText_loc5`='愚蠢!低能!', `MaleText_loc7`='¡Tontos! ¡Imbéciles!' WHERE `ID`=75725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 이뤄낸 위업들을 전승지기에게 알려주던 참이었다, 용사여. 너의 이야기를 들을 준비가 되었나?', `MaleText_loc4`='我已经向游学者叙述了你的事迹，勇士。想听听你的故事吗？', `MaleText_loc5`='我跟博學行者講了很多你的事，英雄。你準備好要聽故事了嗎?', `MaleText_loc7`='Le he estado contando tus hazañas al eremita. ¿Quieres que te contemos tu historia?' WHERE `ID`=75726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 들려주십시오.', `MaleText_loc4`='说说我的故事吧。', `MaleText_loc5`='傳誦我的故事。', `MaleText_loc7`='Cuenta mi historia.', `FemaleText_loc1`='네, 들려주세요.', `FemaleText_loc4`='说说我的故事吧。', `FemaleText_loc5`='傳誦我的故事。', `FemaleText_loc7`='Cuenta mi historia.' WHERE `ID`=75727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙구나, $n. 이제 이 동굴에서 나갈 수 있어서 얼마나 고마운지 모른단다. 내 성의의 표시를 받아다오.', `FemaleText_loc4`='你好，$n。你把我从这个洞里救了出来，我要谢谢你。请接受这份礼物以及我最衷心的感谢。', `FemaleText_loc5`='你好，$n。你把我從這個洞穴放出來了，我想要感謝你。請接受我的禮物和我的謝意。', `FemaleText_loc7`='Hola, $n. Me has liberado de esta cueva, y deseo agradecértelo. Te ruego que aceptes este regalo y mi humilde gratitud.' WHERE `ID`=75735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 선물을 받아들이겠습니다.', `MaleText_loc4`='我接受这份礼物。', `MaleText_loc5`='我接受這份禮物。', `MaleText_loc7`='Acepto este regalo.', `FemaleText_loc1`='이 선물을 받아들이겠어요.', `FemaleText_loc4`='我接受这份礼物。', `FemaleText_loc5`='我接受這份禮物。', `FemaleText_loc7`='Acepto este regalo.' WHERE `ID`=75736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라. 네 교만에 복종하고 "위대함"을 증명해 봐라!', `MaleText_loc4`='来吧。臣服于你的骄傲吧。让我看看你有多么“伟大”。', `MaleText_loc5`='來吧，面對我。臣服於傲慢。讓我看看你們的「偉大」。', `MaleText_loc7`='Vengan, enfréntenme. Déjense llevar por su orgullo. Muéstrenme su "Grandeza".' WHERE `ID`=75737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석긴...', `MaleText_loc4`='多么愚蠢……', `MaleText_loc5`='如此愚蠢...', `MaleText_loc7`='Tanta ignorancia…' WHERE `ID`=75738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 네 동료들보다 우월하다!', `MaleText_loc4`='你比其他人优秀多了！', `MaleText_loc5`='你比你的同伴更優秀!', `MaleText_loc7`='¡Tú eres mejor que tus compañeros!' WHERE `ID`=75739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오만이 너를 이끈다..', `MaleText_loc4`='你的傲慢驱使着你……', `MaleText_loc5`='你的傲慢驅使著你...', `MaleText_loc7`='Tu arrogancia te comanda...' WHERE `ID`=75740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 교만에 복종하라!', `MaleText_loc4`='屈服于你的骄傲吧！', `MaleText_loc5`='屈服於你的驕傲!', `MaleText_loc7`='¡Sucumbe ante tu orgullo!' WHERE `ID`=75741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 오만이 나를 키운다!', `MaleText_loc4`='你的傲慢让我壮大！', `MaleText_loc5`='你的傲慢強化了我!', `MaleText_loc7`='¡Tu arrogancia me alimenta!' WHERE `ID`=75742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이나 대족장 따위에게 왜 복종하지?', `MaleText_loc4`='不要向任何国王或酋长低头。', `MaleText_loc5`='你不該向國王或酋長低頭。', `MaleText_loc7`='No deberías postrarte ante ningún rey ni jefe de guerra.' WHERE `ID`=75743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교만에 눈먼 티탄의 꼭두각시여! 너는 나를 감당할 수 없다!', `MaleText_loc4`='你被骄傲蒙蔽了双眼，泰坦的傀儡。你休想阻止我！', `MaleText_loc5`='你讓驕傲蒙蔽了雙眼，泰坦的傀儡!休想阻止我!', `MaleText_loc7`='¡Permitiste que el orgullo nublara tu visión, títere de Titán! ¡NUNCA PODRÁS CONTENERME!' WHERE `ID`=75744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해 빠진 놈.', `MaleText_loc4`='一个弱者。', `MaleText_loc5`='真是弱小。', `MaleText_loc7`='Ese es DÉBIL.' WHERE `ID`=75745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께할 가치도 없는 동료다.', `MaleText_loc4`='这家伙只会拖你们后腿。', `MaleText_loc5`='這個人只會拖後腿。', `MaleText_loc7`='Ese no merece estar en su grupo.' WHERE `ID`=75746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 동료를 원망해라!', `MaleText_loc4`='要怪就怪你的同伴吧！', `MaleText_loc5`='去怪你的同伴吧!', `MaleText_loc7`='¡Culpen a sus acompañantes!' WHERE `ID`=75747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기 절반이 파괴되었습니다! 외부인들은 사마귀와 모구를 합친 것보다 더 이 땅을 파괴하고 있습니다!', `MaleText_loc4`='半个锦绣谷都被毁了！这些外来者的破坏性比螳螂妖和魔古族加起来还要大。', `MaleText_loc5`='恆春谷毀了大半!這些外來者造成的破壞比螳螂人加上魔古還要大!', `MaleText_loc7`='¡Medio Valle se encuentra en ruinas! Estos forasteros han sido más destructivos que los mántides y los mogu combinados!' WHERE `ID`=75748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 보태고 싶습니다. 골짜기를 재건하는 걸 돕고 싶어요.', `MaleText_loc4`='我们到这儿是来帮忙的。我们可以帮忙重建锦绣谷。', `MaleText_loc5`='我們是來提供幫助的。讓我們幫忙重建恆春谷。', `MaleText_loc7`='Estamos aquí para ayudar. Podemos ayudar a reconstruir el Valle.' WHERE `ID`=75749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹음되고 있는 건가? 응? 좋아. 고블린 티탄 제어 모듈 시동 중. 물러서라고.', `MaleText_loc4`='录像开了吗？开了？很好。地精泰坦控制模块启动，请退后。', `MaleText_loc5`='我們在錄音嗎?有嗎?好。哥布林-泰坦控制模組開始運作，請後退。', `MaleText_loc7`='¿Estamos grabando?  ¿Sí?  Bien.  Iniciando el módulo de control Goblin-Titán. Retrocedan, por favor.' WHERE `ID`=75750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데이터 확인 중이니까 잠깐 기다려 줄래?', `MaleText_loc4`='正在检查数据，请稍等，好吗？', `MaleText_loc5`='檢查資料中，先等一下好嗎?', `MaleText_loc7`='Estoy revisando los datos, ¡dame un segundo!' WHERE `ID`=75751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 지금 입력한 코드는 완전히, 완전히 틀려 먹었어.', `MaleText_loc4`='噢，那你来试试？那绝对绝对绝对不是正确的代码。', `MaleText_loc5`='噢，你這麼做了，那可真的不是正確的輸入碼。', `MaleText_loc7`='Ahora sí que metiste la pata... Ese código de entrada está mal, mal, mal.' WHERE `ID`=75752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t %s|1이;가; |cFFFF0000|Hspell:144985|h[소용돌이치는 타락]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t%s开始施放|cFFFF0000|Hspell:144985|h[腐蚀漩涡]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t%s開始施展|cFFFF0000|Hspell:144985|h[迴旋腐化]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_garrosh_whirling_corruption.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:144985|h[Torbellino de corrupción]|h|r!' WHERE `ID`=75753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='GB-11010 "대재앙"급 방어 시스템 가동. 혹시 우리 이거 허가받았는지 아는 사람?', `MaleText_loc4`='激活GB-11010“末日决战”级防御系统。嘿，我们到底有没有给它分区？', `MaleText_loc5`='啟動GB-11010世界末日級防禦系統。嘿，我們有劃分好安全區域了嗎?', `MaleText_loc7`='Activando los sistemas defensivos clase "Armagedón" GB-11010. Ey, ¿alguien sabe si estamos a una distancia segura?' WHERE `ID`=75754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린식 입력 행위 감지. 금은보화 잠금 해제 중.', `MaleText_loc4`='发现地精类生命体，正在解锁财宝室。', `MaleText_loc5`='偵測到類哥布林物體，解鎖金銀財寶。', `MaleText_loc7`='Tecleo estilo goblin detectado, desbloqueando el caché de riquezas y tesoros.' WHERE `ID`=75755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 초기화 시작. 제1 모듈 50%%. 이봐, 시스템 초기화에는 모듈이 두 개 필요하다고.', `MaleText_loc4`='正在启动系统重置。1号模组达到50%%。嘿，系统重置需要完成两个模组。', `MaleText_loc5`='啟動系統重置。模組一號達到五成。嘿，系統重置需要兩個模組才能完成。', `MaleText_loc7`='Iniciando el reinicio de sistema. Módulo 1 al 50%%. Ey, el reinicio de sistema requiere dos módulos para completarse.' WHERE `ID`=75756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제1 모듈, 시스템 초기화 준비 완료.', `MaleText_loc4`='1号模组准备完毕，可以系统重置。', `MaleText_loc5`='模組一號已準備好系統重置。', `MaleText_loc7`='El Módulo 1 ya está listo para el reinicio de sistema.' WHERE `ID`=75757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 초기화 시작. 제2 모듈 50%%. 이봐, 시스템 초기화에는 모듈이 두 개 필요하다고.', `MaleText_loc4`='正在启动系统重置。2号模组达到50%%。嘿，系统重置需要完成两个模组。', `MaleText_loc5`='啟動系統重置。模組二號達到五成。嘿，系統重置需要兩個模組才能完成。', `MaleText_loc7`='Iniciando el reinicio de sistema. Módulo 2 al 50%%. Ey, el reinicio de sistema requiere dos módulos para completarse.' WHERE `ID`=75758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제2 모듈, 시스템 초기화 준비 완료.', `MaleText_loc4`='2号模组准备完毕，可以系统重置。', `MaleText_loc5`='模組二號已準備好系統重置。', `MaleText_loc7`='El Módulo 2 ya está listo para el reinicio de sistema.' WHERE `ID`=75759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 초기화 중. 전원을 끄면 폭발할 수 있으니 주의하라고.', `MaleText_loc4`='系统重置中。请勿关闭电源，否则将发生爆炸。', `MaleText_loc5`='系統重置中。請勿關閉電源，否則可能會爆炸。', `MaleText_loc7`='Reiniciando. No apague el sistema o es probable que explote todo.' WHERE `ID`=75760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보안 시스템 비활성화. 공성기술자 블랙퓨즈 님 환영합니다.', `MaleText_loc4`='安全系统关闭。欢迎回来，攻城匠师黑索。', `MaleText_loc5`='安全系統已關閉。歡迎回來，攻城機匠黑引信。', `MaleText_loc7`='Sistema de seguridad desactivado. Bienvenido otra vez, Asediador Mechanegra.' WHERE `ID`=75761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_titankeeper_uncheckedcorruption.blp:20|t %s|1이;가; |cFFFF0000|Hspell:147011|h[명백한 분노]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_titankeeper_uncheckedcorruption.blp:20|t%s开始施放|cFFFF0000|Hspell:147011|h[暴怒具象]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_titankeeper_uncheckedcorruption.blp:20|t%s開始施展|cFFFF0000|Hspell:147011|h[實體化的怒氣之煞]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_titankeeper_uncheckedcorruption.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:147011|h[Ira manifiesta]|h|r!' WHERE `ID`=75762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 하루 보내고, 나가다가 문에 부딪히지 말라고.', `MaleText_loc4`='祝你拥有美好的一天，出去时别让门夹了。', `MaleText_loc5`='祝你擁有美好的一天，出去時別撞到門。', `MaleText_loc7`='Que tengan un buen día y no dejen que la puerta los golpee al salir.' WHERE `ID`=75763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t %s|1이;가; |cFFFF0000|Hspell:144985|h[강화된 소용돌이치는 타락]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t%s开始施放|cFFFF0000|Hspell:144985|h[强化腐蚀漩涡]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t%s開始施展|cFFFF0000|Hspell:144985|h[強化迴旋腐化]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_garrosh_empowered_whirling_corruption.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:144985|h[Torbellino de corrupción potenciado]|h|r!' WHERE `ID`=75764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 종료 중. 이봐, 이거 원래 이러는 거 맞아?', `MaleText_loc4`='系统正在关闭。嘿，有谁知道，这样正常吗？', `MaleText_loc5`='系統關閉中。欸，有人知道這樣是正常的嗎?', `MaleText_loc7`='Sistemas apagándose.  EY, ¿ALGUIEN SABE SI ESO ES NORMAL?' WHERE `ID`=75765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"대재앙"급 방어 시스템 준비 완료. 폭파 시작!', `MaleText_loc4`='“末日决战”级防御系统全面上线。大爆炸来啦！', `MaleText_loc5`='世界末日級防禦系統已完全啟動。大爆炸要開始啦!', `MaleText_loc7`='Sistemas defensivos clase "Armagedón" 100% en línea. ¡Aquí vienen las explosiones!' WHERE `ID`=75766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제시여, 이제 끝났습니다. 한때 폐하께서 맞서 싸웠던 어둠을 판다리아에서 몰아냈습니다. 영원히.', `MaleText_loc4`='亲爱的皇上，我们来了。那些曾让您苦苦挣扎的邪恶和黑暗已经永远地远离了潘达利亚。', `MaleText_loc5`='親愛的皇帝。成功了。您曾努力對抗的黑暗已經從潘達利亞永遠，永遠地驅除了。', `MaleText_loc7`='Querido Emperador, ha terminado. La oscuridad que alguna vez enfrentaste, ha sido desterrada de Pandaria... para siempre.' WHERE `ID`=75772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그 대가는... 너무도 끔찍했습니다...', `MaleText_loc4`='可这代价…这惨痛的代价…', `MaleText_loc5`='但是代價...無比地慘痛。', `MaleText_loc7`='Pero el costo... El costo fue terrible.' WHERE `ID`=75773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이방인들은 우리 땅에 혼돈을 불러왔다. 이들이 잘못을 바로잡으리라 믿어도 될까?', `MaleText_loc4`='这些外来者给这片土地带来了混乱。我们能够相信他们吗？', `MaleText_loc5`='這些外來者給大地帶來混亂。我們能相信他們嗎?', `MaleText_loc7`='Estos forasteros trajeron el caos a esta tierra. ¿Podemos confiar en que corrijan sus acciones?' WHERE `ID`=75776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 내 몸을 찾았어! 얼마만인지 모르겠네.', `MaleText_loc4`='见鬼！你找到了我的身体！看看这些老骨头。', `MaleText_loc5`='太棒了!你找到我的屍體了!看看這些老骨頭。', `MaleText_loc7`='¡Estupendo! ¡Has encontrado mi cuerpo! Mira qué huesos tan salados.' WHERE `ID`=75777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 생각보다 기쁘지가 않아...', `MaleText_loc4`='我还以为自己会更加激动呢……', `MaleText_loc5`='我本來真的以為我會更激動的...', `MaleText_loc7`='Pensaba que me emocionaría más...' WHERE `ID`=75778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 오히려 필요 없을 것 같아. 난 이렇게 둥둥 떠 다니는 게 더 좋거든.', `MaleText_loc4`='知道吗？我根本就不想要身体。我喜欢自由自在地飘浮。', `MaleText_loc5`='你知道嗎?我根本不想擁有，只想自由自在地活著。', `MaleText_loc7`='¿Sabes qué? No los quiero. Me gusta esto de flotar a mi aire.' WHERE `ID`=75779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기를 배불리 먹은 학이 처참하게 죽어있습니다.$B$B전신에 발톱과 이빨에 짓이기고 뜯긴 자국이 가득합니다. 내장은 거의 남아있지 않습니다.$B$B뭔가 포악한 생물이 게걸스럽게 먹은 것이 분명합니다.', `MaleText_loc4`='这头嗜鱼鹤死得很惨。$B$B它的身体上布满了齿痕和爪印，内脏也被吞吃一空。$B$B它显然成了某个家伙的一顿美餐。', `MaleText_loc5`='證據顯示這隻魚嚥紅鶴死狀甚慘。$B$B牠身上滿是咬痕和抓痕，內臟也被吞食一空。$B$B牠一定是某種飢餓生物最喜歡的佳餚。', `MaleText_loc7`='Parece que esta grulla atiborrada de peces sufrió una muerte violenta.$b$bSu cuerpo está cubierto de mordeduras y de arañazos, y la mayor parte de sus vísceras han sido devoradas.$b$bDebe de ser el plato favorito de alguna fiera.', `FemaleText_loc1`='물고기를 배불리 먹은 학이 처참하게 죽어있습니다.$B$B전신에 발톱과 이빨에 짓이기고 뜯긴 자국이 가득합니다. 내장은 거의 남아있지 않습니다.$B$B뭔가 포악한 생물이 게걸스럽게 먹은 것이 분명합니다.', `FemaleText_loc4`='这头嗜鱼鹤死得很惨。$B$B它的身体上布满了齿痕和爪印，内脏也被吞吃一空。$B$B它显然成了某个家伙的一顿美餐。', `FemaleText_loc5`='證據顯示這隻魚嚥紅鶴死狀甚慘。$B$B牠身上滿是咬痕和抓痕，內臟也被吞食一空。$B$B牠一定是某種飢餓生物最喜歡的佳餚。', `FemaleText_loc7`='Parece que esta grulla atiborrada de peces sufrió una muerte violenta.$b$bSu cuerpo está cubierto de mordeduras y de arañazos, y la mayor parte de sus vísceras han sido devoradas.$b$bDebe de ser el plato favorito de alguna fiera.' WHERE `ID`=75780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 진정한 호드 앞에 쓰러질 것이다!', `MaleText_loc4`='臣服于正统部落吧！', `MaleText_loc5`='在正統部落面前，你必敗無疑!', `MaleText_loc7`='¡Caerán ante la verdadera Horda!', `FemaleText_loc1`='너희는 진정한 호드 앞에 쓰러질 것이다!', `FemaleText_loc4`='臣服于正统部落吧！', `FemaleText_loc5`='在正統部落面前，你必敗無疑!', `FemaleText_loc7`='¡Caerán ante la verdadera Horda!' WHERE `ID`=75781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 대족장님을 위해!', `MaleText_loc4`='为了加尔鲁什酋长！', `MaleText_loc5`='為了大酋長卡爾洛斯!', `MaleText_loc7`='¡Por el Jefe de Guerra Garrosh!', `FemaleText_loc1`='가로쉬 대족장님을 위해!', `FemaleText_loc4`='为了加尔鲁什酋长！', `FemaleText_loc5`='為了大酋長卡爾洛斯!', `FemaleText_loc7`='¡Por el Jefe de Guerra Garrosh!' WHERE `ID`=75782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 두개골은 훌륭한 보상이 될 거다!', `MaleText_loc4`='你的脑袋将是一个不错的战利品！', `MaleText_loc5`='你的頭骨會是很好的獎賞!', `MaleText_loc7`='¡Usaremos sus cráneos de trofeo!', `FemaleText_loc1`='네 두개골은 훌륭한 보상이 될 거다!', `FemaleText_loc4`='你的脑袋将是一个不错的战利品！', `FemaleText_loc5`='你的頭骨會是很好的獎賞!', `FemaleText_loc7`='¡Usaremos sus cráneos de trofeo!' WHERE `ID`=75783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 가로쉬 님에게 맞설 수 없다!', `MaleText_loc4`='加尔鲁什是所向无敌的！', `MaleText_loc5`='沒人能阻擋卡爾洛斯!', `MaleText_loc7`='¡Nadie desafiará a Garrosh!', `FemaleText_loc1`='그 누구도 가로쉬 님에게 맞설 수 없다!', `FemaleText_loc4`='加尔鲁什是所向无敌的！', `FemaleText_loc5`='沒人能阻擋卡爾洛斯!', `FemaleText_loc7`='¡Nadie desafiará a Garrosh!' WHERE `ID`=75784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 선택받은 자들이다! 진정한 호드의 힘이다!', `MaleText_loc4`='你们是精英中的精英！是正统部落的中坚力量！', `MaleText_loc5`='你們是被選定的戰士!正統部落之拳!', `MaleText_loc7`='¡Son los elegidos! ¡La fuerza de la verdadera Horda!' WHERE `ID`=75790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 군대가 세계의 기둥을 뒤흔들 것이다!', `MaleText_loc4`='我们的大军将动摇世界的支柱！', `MaleText_loc5`='我們的軍隊將撼動世界支柱!', `MaleText_loc7`='¡Nuestros ejércitos sacudirán los cimientos del mundo!' WHERE `ID`=75792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 맞서는 자들에게 자비란 없다!', `MaleText_loc4`='不要对妨碍我们的敌人心慈手软！', `MaleText_loc5`='那些反抗我們的都不會得到憐憫!', `MaleText_loc7`='¡Nuestros enemigos no conocerán la piedad!' WHERE `ID`=75793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 가로쉬 대족장님을 위해 승리를 쟁취할 것이다!', `MaleText_loc4`='我们将为加尔鲁什酋长夺取胜利！', `MaleText_loc5`='為了大酋長卡爾洛斯，我們要贏得勝利!', `MaleText_loc7`='¡Reclamaremos la victoria en nombre del Jefe de Guerra Garrosh!' WHERE `ID`=75794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t 호드 함대가 |cFFFF0000|Hspell:147088|h[폭격]|h|r을 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t部落舰队开始进行|cFFFF0000|Hspell:147088|h[轰炸]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t部落艦隊開始|cFFFF0000|Hspell:147088|h[轟炸]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_vehicle_demolisherflamecatapult.blp:20|t¡La flota de la Horda comienza el |cFFFF0000|Hspell:147088|h[Bombardeo]|h|r!' WHERE `ID`=75795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개인이 사리사욕을 위해 시간의 길을 건드리는 자들은 대개 매우 위험한 인물들이오.

이때문에 나는 파수꾼 역할을 맡았소. 파수꾼들은 시간여행단의 든든한 수호자들이오. 

우리는 감시자와 세공사들이 직무를 수행하는 걸 지켜준다오.', `MaleText_loc4`='为了私利而去干扰时间流的家伙通常都很危险。

所以我才加入了守望者的队伍，这是时光旅行者中的防卫部队。

我们会在观察者和编织者执行任务时保护他们。', `MaleText_loc5`='那些為了一己之私的理由而干擾時間之道的傢伙通常都很危險。

這就是我加入時光守衛的原因，成為時光行者最牢靠的護衛。

我們會在時光看守者和編織者工作時保護他們。', `MaleText_loc7`='Las personas que manipulan las líneas temporales para su propio beneficio suelen ser muy peligrosas.

Por eso me uní a los celadores, los defensores de los Caminantes del Tiempo.

Protegemos a los tejedores y a los vigías mientras desempeñan sus tareas.' WHERE `ID`=75796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 배웠으리라 믿네. 공포, 분노와 싸우는 것은 영원한 전쟁을 치르는 것과 같아.', `MaleText_loc4`='我相信你已经领悟了：若因恐惧和愤怒而战，则此战永无休止。', `MaleText_loc5`='我相信你們學到了:因恐懼和憤怒而作戰就像是一場永不止息的戰爭。', `MaleText_loc7`='Confío en que hayas aprendido: que luchar a causa del miedo o la ira es luchar una guerra interminable.' WHERE `ID`=75797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기 같으니라고!', `MaleText_loc4`='真是浪费！', `MaleText_loc5`='徹底的浪費了!', `MaleText_loc7`='¡Qué desperdicio!' WHERE `ID`=75798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t 함대장이 집결한 적을 발견해 |cFFFF0000|Hspell:147047|h[불안정한 강철의 별]|h|r을 발사합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t部落舰长发现了一处密集人群！开始发射|cFFFF0000|Hspell:147047|h[不稳定的钢铁之星]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t部落艦長偵測到敵人!發射|cFFFF0000|Hspell:147047|h[不穩定的鋼鐵之星]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_garrosh_siege_engine.blp:20|t ¡El capitán de la flota ha detectado un grupo! ¡Va a disparar una |cFFFF0000|Hspell:147047|h[estrella de hierro inestable]|h|r!' WHERE `ID`=75799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 실패군! 정신을 잃기 전에 쓰러뜨려라!', `MaleText_loc4`='又失败了！趁这头野兽还没失控，快干掉他！', `MaleText_loc5`='又失誤了!在那個野獸掙脫前把牠打倒!', `MaleText_loc7`='¡Otro fracaso! Destruyan a la bestia antes de que se escape.' WHERE `ID`=75800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주입 작업에 성공하기만 하면, 이샤라즈의 힘이 우리를 막을 수 없는 존재로 만들 것이다!', `MaleText_loc4`='等我完善了灌注过程，亚煞极的力量将使我们所向披靡！', `MaleText_loc5`='一旦我讓注入的過程臻於完美，亞煞拉懼的力量將使我們銳不可當!', `MaleText_loc7`='Cuando haya perfeccionado el proceso de infusión, ¡el poder de Y''Shaarj nos volverá imparables!' WHERE `ID`=75801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세공사들은 시간의 학문에 통달하여 시간 자체를 세공하는 신비술사들을 일컫습니다.

시간여행단 중에서 오직 우리만이 손상된 시간의 길을 복원하거나 일시적인 차원문을 여는 등의 일을 할 수 있습니다. 

본래 이런 일은 청동용군단이 손쉽게 할 수 있었습니다. 하지만 아쉽게도 그들은 힘을 잃고 말았죠.', `MaleText_loc4`='编织者都是精通时间法术的魔法师，最擅长编织时间。

在时光旅行者中，只有我们能修复受损的时间流，开启时光传送门，并执行其他类似的任务。

这些事原本对青铜龙军团来说轻而易举，可惜，一切都变了。', `MaleText_loc5`='時光編織者是專精於時光系法術，編織時間的秘法師。

在時光行者當中，只有我們能替時間之道修復傷害，開啟時光傳送門，及類似的工作。

這些事情原本對青銅龍軍團來說是小菜一碟，但可惜，不再如此了。', `MaleText_loc7`='Los tejedores somos arcanistas especializados en cronomancia, el arte de tejer el tiempo.

Dentro de los Caminantes del Tiempo, solo nosotros somos capaces de reparar el daño de las líneas temporales, abrir portales en el tiempo y tareas similares.

Antes era algo natural para el Vuelo Bronce, pero por desgracia ya no es así.' WHERE `ID`=75802;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시자들은 시간여행단의 학자들이자 연구원이고, 정찰이나 염탐 임무도 수행합니다.

우리는 시간의 길을 감시하며 기록하고, 조사하고, 보수가 필요하거나 비정상적인 징후가 보이는 곳을 보고하죠.

이 영원의 섬이라는 불가사의한 장소에 대해 알아낸 것도 감시자들이라고요.', `FemaleText_loc4`='观察者是时光旅行者中的学者、斥候、研究员以及密探。

我们观察时间流并记录、调查和报告时光的扰动和异常现象。

也正是观察者将时光旅行者的目光引向这座时间凝固的小岛的。', `FemaleText_loc5`='時光看守者是時光行者的學者與斥候，研究者與間諜。

我們觀察時間之道並記錄、調查、回報時空的人為改動及不尋常的情況。

當然了，就是時光看守者告訴時光行者關於這個奇特、永恆的島嶼。', `FemaleText_loc7`='Los vigías somos los eruditos de los Caminantes del Tiempo, pero también exploradores, investigadores y espías.

Observamos las líneas temporales y anotamos, investigamos e identificamos manipulaciones temporales o fenómenos inusuales.

Huelga decir que fue un vigía el que llamó la atención de los Caminantes del Tiempo sobre esta extraña Isla Intemporal.' WHERE `ID`=75803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t |cFFF00000|Hspell:146817|h[교만의 오라]|h|r에 휩싸입니다!', `MaleText_loc4`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t你受到了|cFFF00000|Hspell:146817|h[傲气光环]|h|r的影响！', `MaleText_loc5`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t你正受到|cFFF00000|Hspell:146817|h[傲慢光環]|h|r影響!', `MaleText_loc7`='|TInterfaceIconssha_ability_rogue_envelopingshadows.blp:20|t ¡Te afecta una |cFFF00000|Hspell:146817|h[Aura de orgullo]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t |cFFF00000|Hspell:146817|h[교만의 오라]|h|r에 휩싸입니다!', `FemaleText_loc4`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t你受到了|cFFF00000|Hspell:146817|h[傲气光环]|h|r的影响！', `FemaleText_loc5`='|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t你正受到|cFFF00000|Hspell:146817|h[傲慢光環]|h|r影響!', `FemaleText_loc7`='|TInterfaceIconssha_ability_rogue_envelopingshadows.blp:20|t ¡Te afecta una |cFFF00000|Hspell:146817|h[Aura de orgullo]|h|r!' WHERE `ID`=75804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 황제가 가장 아끼는 여러 물건을 가지고 있다네. 샤오하오 님의 호의를 얻으려면 천신의 광장을 장악하고 있는 오르도 야운골들을 물리쳐주게.', `MaleText_loc4`='我这里有着皇帝陛下最珍贵的遗物。如果你想赢得少昊的青睐，就请帮我们赶走那些试图占据天神庭院的斡耳朵野牛人吧。', `MaleText_loc5`='我手裡握有一些皇帝最珍視的寶藏。如果你想給紹昊大帝留下一點好印象，可以幫助我們擊退那些妄圖佔領天尊之廷的歐朵揚古。', `MaleText_loc7`='Tengo en mi poder algunas de las pertenencias más valiosas del Emperador. Si quieres ganarte el favor de Shaohao, puedes ayudarnos echando a los yaungol Ordon que intentan tomar la Corte Celestial.', `FemaleText_loc1`='나는 황제가 가장 아끼는 여러 물건을 가지고 있다네. 샤오하오 님의 호의를 얻으려면 천신의 광장을 장악하고 있는 오르도 야운골들을 물리쳐주게.', `FemaleText_loc4`='我这里有着皇帝陛下最珍贵的遗物。如果你想赢得少昊的青睐，就请帮我们赶走那些试图占据天神庭院的斡耳朵野牛人吧。', `FemaleText_loc5`='我手裡握有一些皇帝最珍視的寶藏。如果你想給紹昊大帝留下一點好印象，可以幫助我們擊退那些妄圖佔領天尊之廷的歐朵揚古。', `FemaleText_loc7`='Tengo en mi poder algunas de las pertenencias más valiosas del Emperador. Si quieres ganarte el favor de Shaohao, puedes ayudarnos echando a los yaungol Ordon que intentan tomar la Corte Celestial.' WHERE `ID`=75805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들을 이리로 오게 해라! 내 손으로 놈들의 두개골을 박살내주고 싶으니.', `MaleText_loc4`='让入侵者来吧！我已经等不及要砸碎他们的脑袋了。', `MaleText_loc5`='讓入侵者往這裡來吧!我等著砍碎他們的頭蓋骨!', `MaleText_loc7`='¡Que vengan los intrusos! Tengo ganas de aplastarles el cráneo.' WHERE `ID`=75806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 저 겁쟁이 놈들은 내 분노에 맞서기 보다 몰래 도망치려 하겠지.', `MaleText_loc4`='当然，这些懦夫很可能会悄悄溜过去而不敢直面我的怒火。', `MaleText_loc5`='當然，比起直接面對我的怒火，那群懦夫更可能偷偷溜走。', `MaleText_loc7`='¡Claro! Los muy cobardes preferirán escabullirse antes que enfrentarse a mi ira.' WHERE `ID`=75807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기도 없는 저런 놈들에게 뭘 기대하겠나?', `MaleText_loc4`='对于那些胆小鬼，你还能指望什么呢？', `MaleText_loc5`='你還能從這些沒有勇氣的傢伙身上期望什麼?', `MaleText_loc7`='¡Es de esperar de gente sin valor!' WHERE `ID`=75808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼에 쓰러지는 게 아마 놈들이 이룰 수 있는 가장 큰 업적이겠지.', `MaleText_loc4`='死在我手里可能就是他们最大的成就了。', `MaleText_loc5`='死在我的手裡是他們所能期望的最高成就。', `MaleText_loc7`='Morir a mis manos sería el mayor logro que podrían desear.' WHERE `ID`=75809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원의 주화로 뭘 살 수 있습니까?', `MaleText_loc4`='我能用永恒铸币买到些什么？', `MaleText_loc5`='永恆硬幣能買什麼?', `MaleText_loc7`='¿Qué puedo comprar con monedas intemporales?', `FemaleText_loc1`='영원의 주화로 뭘 살 수 있죠?', `FemaleText_loc4`='我能用永恒铸币买到些什么？', `FemaleText_loc5`='永恆硬幣能買什麼?', `FemaleText_loc7`='¿Qué puedo comprar con monedas intemporales?' WHERE `ID`=75810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안정한 강철의 별 폭발을 유발했습니다.', `MaleText_loc4`='%s引爆了不稳定的钢铁之星。', `MaleText_loc5`='%s造成了不穩定的鋼鐵之星爆炸。', `MaleText_loc7`='%s ha provocado que estalle la estrella de hierro inestable.' WHERE `ID`=75811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해결해 볼까.', `MaleText_loc4`='让我们来解决它。', `MaleText_loc5`='咱們做個了斷吧。', `MaleText_loc7`='Terminemos con esto.' WHERE `ID`=75812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하하하하하!', `MaleText_loc4`='啊哈哈哈哈！', `MaleText_loc5`='呵哈哈哈哈!', `MaleText_loc7`='¡Jajajajajajaja!' WHERE `ID`=75813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 블랙퓨즈 군단이 어떻게 싸우는지 보여 주자고!', `MaleText_loc4`='好吧，伙计们，让他们看看黑索公司的战斗力！', `MaleText_loc5`='好啦小子們，讓他們看看黑引信有限公司如何戰鬥!', `MaleText_loc7`='Muy bien, muchachos, ¡mostrémosles cómo pelea la compañía Mechanegra!' WHERE `ID`=75814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 블랙퓨즈는 못 꺾어. 아무도.', `MaleText_loc4`='没人能打败黑索。没有人！', `MaleText_loc5`='沒有人能擊敗黑引信。沒有人!', `MaleText_loc7`='Nadie derrota a Mechanegra. Nadie.' WHERE `ID`=75815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예술가를 방해하면 못쓰지.', `MaleText_loc4`='别来打扰艺术家。', `MaleText_loc5`='不要干擾藝術家!', `MaleText_loc7`='Nunca interrumpas a un artista.' WHERE `ID`=75816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 가만 있지 않겠다...', `MaleText_loc4`='噢，你会为此付出代价的……', `MaleText_loc5`='噢，你們會付出代價的!', `MaleText_loc7`='Uy, vas a pagar por eso…' WHERE `ID`=75817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 젠장!', `MaleText_loc4`='你这个……', `MaleText_loc5`='你們這些該死的...', `MaleText_loc7`='Hijo de una gran...' WHERE `ID`=75818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 유산은... 영원할 것이다...', `MaleText_loc4`='我的精神……永垂不朽……', `MaleText_loc5`='我的遺願...會延續下去...', `MaleText_loc7`='Mi legado seguirá vivo... ' WHERE `ID`=75819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 이겼다고 생각하나? 넌 눈이 멀었다! 내가 그 눈을 뜨게해 주마!', `MaleText_loc4`='别以为你们已经赢了，你们这些瞎子。睁大眼睛好好看看！', `MaleText_loc5`='你們以為贏了嗎?你們都瞎了眼。我會讓你們看清楚。', `MaleText_loc7`='¿Crees haber GANADO? Estás CIEGO. TE FORZARÉ A ABRIR LOS OJOS.' WHERE `ID`=75820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐라. 내 영광스러운 운명을! 으하하하하!', `MaleText_loc4`='见证我充满荣耀的命运吧！啊哈哈哈！', `MaleText_loc5`='看啊，我無比榮耀的宿命!', `MaleText_loc7`='¡CONTEMPLA MI GLORIOSO DESTINO!' WHERE `ID`=75821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 세계는 너 따위가 있을 곳이 아니다.', `MaleText_loc4`='在我的世界里，你们无处容身！', `MaleText_loc5`='我的世界裡面沒有你們的位置。', `MaleText_loc7`='NO HAY LUGAR PARA TI EN MI MUNDO.' WHERE `ID`=75822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 사랑했던 모든 것을 박살내 주마!', `MaleText_loc4`='我会摧毁你们所钟爱的一切。', `MaleText_loc5`='我會摧毀你們珍愛的一切事物。', `MaleText_loc7`='ACABARÉ CON TODO LO QUE SIEMPRE HAS AMADO.' WHERE `ID`=75823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼... 이 세계는... 내 운명인데... 내 운명이라고...', `MaleText_loc4`='不，不！这难道就是我的宿命……我的宿命…… ', `MaleText_loc5`='不...不...這個世界...是我的宿命...我的宿命...', `MaleText_loc7`='No… Este mundo… es mi destino… Mi destino…' WHERE `ID`=75824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 그롬의 아들 가로쉬가, 헬스크림이라는 이름이 무슨 뜻인지 보여주겠다!', `MaleText_loc4`='我，格罗姆之子，加尔鲁什，会让你们看看地狱咆哮家族的力量！', `MaleText_loc5`='我，卡爾洛斯，葛羅之子，要讓你們看看什麼叫做地獄吼!', `MaleText_loc7`='¡Yo, Garrosh, hijo de Grom, te mostraré lo que significa el nombre Grito Infernal!' WHERE `ID`=75825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기네, 친구!', `MaleText_loc4`='到这儿来，英雄。', `MaleText_loc5`='在這裡，英雄!', `MaleText_loc7`='¡Aquí, valiente!' WHERE `ID`=75826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 이런... 그리 오랫동안 판다리아를 괴롭혀 온 끔찍한 존재가 이 유해만을 남겼군.', `MaleText_loc4`='天哪。这就是多年以来一直侵扰着潘达利亚的恐怖生物。', `MaleText_loc5`='唉呀唉呀 - 這些年來折磨潘達利亞的恐怖東西就只剩這樣了。', `MaleText_loc7`='Así que... Esto es todo lo que queda del ser terrible que acechó Pandaria todos estos años.' WHERE `ID`=75827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없는 어둠을 내뿜어왔지만, 마침내 조용해졌어.', `MaleText_loc4`='终于，它也归于沉寂，化为乌有。', `MaleText_loc5`='它曾散發出的黑暗終於停止了。', `MaleText_loc7`='La extraña oscuridad que emanaba al fin guarda silencio.' WHERE `ID`=75828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나와 함께 가세. 골짜기로 돌아가세. 아마 이번 일에 각별한 관심이 있는 누군가 기다리고 있을 걸세. 물론, 우리가 그분의 주의를 끌 수 있을지는 모르겠네만.', `MaleText_loc4`='跟我来，英雄。我们回到山谷中去。有个人现在一定非常想知道事情的起承转合，如果他愿意搭理我们的话。', `MaleText_loc5`='跟我來吧，英雄。讓我們回去恆春谷。只要我們能跟某個人說上話，我想他會對這些事態的發展特別感興趣的。', `MaleText_loc7`='Ven conmigo valiente, volvamos al valle. Hay alguien que creo que estará especialmente interesado en este desenlace, si es que podemos llamar su atención.' WHERE `ID`=75829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 왔군! 사실이냐? 오그리마에서 벌어진 일이?', `MaleText_loc4`='你来了！这么说都是真的？奥格瑞玛怎么了？', `MaleText_loc5`='你當時在那裡!是真的嗎?奧格瑪發生什麼事了?', `MaleText_loc7`='¡Tú estabas allí! ¿Es cierto, entonces? ¿Lo que ocurrió en Orgrimmar?' WHERE `ID`=75834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 왕 같으니!', `MaleText_loc4`='那个愚蠢的国王！！', `MaleText_loc5`='那個愚蠢的國王!', `MaleText_loc7`='¡¡Ese Rey idiota!!' WHERE `ID`=75836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 내가 할 수 있는 모든 일을 했다. 온 세상이 그의 것이고, 붙잡기만 하면 됐는데!', `MaleText_loc4`='我准备好了一切，对他而言，整个世界已经唾手可得！', `MaleText_loc5`='我已經盡我全部力量。整個世界都是他的，他垂手可得!', `MaleText_loc7`='Hice todo lo que pude. ¡Tenía al mundo a sus pies, solamente debía apoderarse de él!' WHERE `ID`=75837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 물론 전쟁이 좀 이어졌겠지. 썬더 블러프를 공략하느라 희생자가 많이 나왔을 거야. 하지만 결국 모든 호드가 항복했을 텐데!', `MaleText_loc4`='当然，还是得打一仗。要想攻陷雷霆崖必然会伤亡惨重。但其他部落成员一定会逐渐崩溃。', `MaleText_loc5`='噢，當然，還會打上一兩年，要打下雷霆崖還會死傷許多人。但是部落終究會崩塌的。', `MaleText_loc7`='Bueno, claro, era otro año de lucha. Enormes bajas al intentar tomar la Cima del Trueno. Pero el resto de la Horda habría sucumbido a la larga.' WHERE `ID`=75838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통! 술! 당장!', `MaleText_loc4`='童福！拿酒来！快！', `MaleText_loc5`='老童!拿喝的來!快!', `MaleText_loc7`='¡TONG! ¡Una bebida! ¡YA!' WHERE `ID`=75839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 표정은 뭐지? 그래, 난 얼라이언스를 지지했다.', `MaleText_loc4`='什么？没错，我支持了联盟。', `MaleText_loc5`='什麼?沒錯，我是在支持聯盟。', `MaleText_loc7`='¿Qué? Sí, yo apoyaba a la Alianza.' WHERE `ID`=75840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 헬스크림이 당연히 승리할 줄 알았지. 그런데 호드의 반이 그에게 등을 돌리더군. 그래서 편을 바꿨지.', `MaleText_loc4`='我本以为地狱咆哮赢定了，结果他把部落搞得四分五裂。所以我改变了想法。', `MaleText_loc5`='我本來以為地獄吼必定會獲得勝利，直到他把半個部落推到對立面為止。我因此換了支持的對象。', `MaleText_loc7`='Creí que la victoria de Grito Infernal era segura, hasta que por su propia culpa la mitad de la horda se volviera contra él. Así que cambié mi lealtad.' WHERE `ID`=75841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 패배하여 무릎을 꿇습니다. 부대가 후퇴합니다.', `MaleText_loc4`='%s战败并跪了下来。你的部队撤退了。', `MaleText_loc5`='%s輸得一敗塗地。你的軍隊在撤退。', `MaleText_loc7`='%s cae de rodillas, derrotado. Tu ejército se retira.', `FemaleText_loc1`='%s|1이;가; 패배하여 무릎을 꿇습니다. 부대가 후퇴합니다.', `FemaleText_loc4`='%s战败并跪了下来。你的部队撤退了。', `FemaleText_loc5`='%s輸得一敗塗地。你的軍隊在撤退。', `FemaleText_loc7`='%s cae de rodillas, derrotada. Tu ejército se retira.' WHERE `ID`=75842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_eradication.blp:20|t %s|1이;가; |cFFFF0000$n|r에게 |cFFFF0000|Hspell:147209|h[악의]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_eradication.blp:20|t%s对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:147209|h[恶意]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_eradication.blp:20|t%s施展|cFFFF0000|Hspell:147209|h[惡意]|h|r在|cFFFF0000$n|r!', `MaleText_loc7`='|TInterfaceIconsability_warlock_eradication.blp:20|t¡%s lanza |cFFFF0000|Hspell:147209|h[Malicia]|h|r en |cFFFF0000$n|r!' WHERE `ID`=75843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하겠습니다!', `MaleText_loc4`='我认输！', `MaleText_loc5`='我投降!', `MaleText_loc7`='¡Me rindo!', `FemaleText_loc1`='포기하겠습니다!', `FemaleText_loc4`='我认输！', `FemaleText_loc5`='我投降!', `FemaleText_loc7`='¡Me rindo!' WHERE `ID`=75844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 포기하시겠습니까?', `MaleText_loc4`='确定要认输吗？', `MaleText_loc5`='你投不投降?', `MaleText_loc7`='¿Te rindes?', `FemaleText_loc1`='정말 포기하시겠습니까?', `FemaleText_loc4`='确定要认输吗？', `FemaleText_loc5`='你投不投降?', `FemaleText_loc7`='¿Te rindes?' WHERE `ID`=75845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=75846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련의 장에 오신 걸 환영합니다. 곧 첫 번째 시험이 시작될 겁니다. 제한 시간 내에 환영 무리를 처치하십시오.', `MaleText_loc4`='欢迎来到试炼场。你的首场试炼即将开始。请在时间用尽前击败所有的幻影。', `MaleText_loc5`='歡迎來到試煉場。你的第一場試煉即將開始。在時間結束前擊敗每一波幻影吧。', `MaleText_loc7`='Bienvenidos al Terreno de Pruebas. Tu primera prueba comenzará ahora. Derrota a cada ola de ilusiones antes de que se acabe el tiempo.' WHERE `ID`=75847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞서와 같이 제한 시간 내에 환영 무리를 처치하십시오. 이번에는 좀 더 까다로운 환영과 싸우게 될 겁니다.', `MaleText_loc4`='和以前一样，请在时间用尽前击败所有的幻影。但这次，你所面对的幻影将更强大。', `MaleText_loc5`='像之前一樣，在時間結束前擊敗每一波幻影。這次，你會面對更困難的幻影。', `MaleText_loc7`='Como antes, derrota a cada ola de ilusiones antes de que se acabe el tiempo. Esta vez, te encontrarás con ilusiones más difíciles.' WHERE `ID`=75848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 힘겨운 환영과 싸울 준비를 하십시오. 제한 시간 내에 놈들을 모두 처치하면 성공입니다.', `MaleText_loc4`='准备迎接最强大的幻影吧。在时间用尽前击败他们，你就胜利了。', `MaleText_loc5`='準備面對最困難的幻影。在時間結束前擊敗他們，你就能獲得勝利。', `MaleText_loc7`='Prepárate para más ilusiones difíciles. Derrótalas antes de que se acabe el tiempo y el éxito será tuyo.' WHERE `ID`=75849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시험으로 실력의 한계를 시험해볼 겁니다. 시험은 끝이 없고, 계속 어려워집니다.', `MaleText_loc4`='这个试炼将考验你的技巧极限。它永不结束，只会越来越难。', `MaleText_loc5`='這個試煉會測試你的技巧究竟到達什麼樣的程度。它不會結束，只會越來越難。', `MaleText_loc7`='Esta prueba demostrará hasta dónde te pueden llevar tus habilidades. Nunca termina, solo se vuelve más y más difícil.' WHERE `ID`=75850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공했군요! 훌륭합니다. 다음 시험에서 만나지요.', `MaleText_loc4`='成功了！干得好。来找我开启下一场试炼吧。', `MaleText_loc5`='成功!呵，做得好。準備好進行下一個試煉時跟我說。', `MaleText_loc7`='¡Éxito! Bien hecho. Nos vemos en tu próxima prueba.' WHERE `ID`=75851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 다 됐네요. 다시 해볼까요?', `MaleText_loc4`='时间到。要再试一次吗？', `MaleText_loc5`='你的時間到了。要再試試看嗎?', `MaleText_loc7`='Se te acabó el tiempo. ¿Quieres volver a intentarlo?' WHERE `ID`=75852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 요마들은 무리지어 다니는데, 피해를 주진 않습니다. 광역 공격 주문으로 공격해서 신속히 처치하십시오.', `MaleText_loc4`='幻影恶棍总是成群结队地出现，但完全无害。你可以用范围伤害技能快速击杀它们。', `MaleText_loc5`='幻影兔妖會成群結隊而來，但不會傷害你。使用對一整個區域造成傷害的攻擊，快速殺死它們。', `MaleText_loc7`='Los mures ilusorios vienen en manada y son inofensivos. Usa ataques que alcancen a varios oponentes para matarlos rápidamente.' WHERE `ID`=75853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 호박술사는 호박석 방울을 만들어 당신 쪽으로 띄워 보냅니다. 거기에 닿으면 폭발하죠. 호박석 방울을 다른 환영에게 유인하십시오!', `MaleText_loc4`='幻影织珀者会召唤一些琥珀球向你飘去，并在接触后爆炸。将琥珀球引到其他幻影身边去吧！', `MaleText_loc5`='幻影編珀者會召出飄向你的琥珀珠並在接觸時爆炸。把琥珀珠引到其他的幻影那裡!', `MaleText_loc7`='¡El Tejeámbar ilusorio conjura esferas de ámbar que flotan hacia ti y explotan al hacer contacto. ¡Dirige las esferas de ámbar hacia las otras ilusiones!' WHERE `ID`=75854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 바나나 투척자군요. 당신에게 빠른 속도로 바나나를 던질 겁니다. 움직여서 피하십시오. 가능하면 놈이 도망치지 못하게 하십시오.', `MaleText_loc4`='啊，幻影掷蕉兵。它会向你快速投掷香蕉，你可以通过移动来躲避。你要尽量避免让它拉开距离。', `MaleText_loc5`='欸，幻影擲蕉者。它會一直對你投擲香蕉。移動並躲開它們。盡你可能別讓他們逃開。', `MaleText_loc7`='Ah, el Lanzaplátanos ilusorio. Lanzará plátanos hacia ti rápidamente; muévete para esquivarlos. Si puedes, no permitas que se aleje de ti.' WHERE `ID`=75855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 비술사는 부상이 심한 동료를 치유합니다. 놈들의 치유 주문을 방해하십시오.', `MaleText_loc4`='幻影秘法师会治疗被重创的幻影。注意打断它的治疗法术！', `MaleText_loc5`='幻影秘法師會治療任何受到重傷的幻影。打斷它的治療。', `MaleText_loc7`='El Místico ilusorio sanará cualquier aliado que esté muy herido. Interrumpe sus poderes de sanación.' WHERE `ID`=75856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어의 명수인 환영 수호자는 전방의 모든 공격을 막아냅니다. 그 뒤에 서십시오!', `MaleText_loc4`='作为防御大师，幻影守卫会偏转来自正面的所有攻击。绕到它背后去！', `MaleText_loc5`='幻影守護者是防禦的高手，會彈開前方的所有攻擊。繞到它的後面!', `MaleText_loc7`='¡Un maestro de la defensa! El Guardián ilusorio desvía todos los ataques de frente. ¡Mantente detrás de él!' WHERE `ID`=75857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 환영 샤군요. 놈의 보호막이 사라져서 노출될 때까지 가장 강력한 공격을 아껴두십시오!', `MaleText_loc4`='噢，幻影煞魔。等它的屏障消散，弱点暴露后再使用你最强的攻击！', `MaleText_loc5`='噢，幻影煞。在它的護盾失效，暴露出身體時，才使用你最強的攻擊!', `MaleText_loc7`='Uuuh, el Sha ilusorio. ¡Guarda tus ataques más fuertes para cuando caiga su barrera y quede expuesto!' WHERE `ID`=75858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 환영 학살자는 당신이 적에게 피해를 얼마나 주는지 시험할 겁니다. 공격은 안 하니 안심하십시오.', `MaleText_loc4`='这个幻影杀戮者会测试你的伤害输出能力。别担心，它不会攻击的。', `MaleText_loc5`='這個幻影殺戮者會測試你造成傷害的能力。不用擔心，它不會攻擊你。', `MaleText_loc7`='El destripador ilusorio pondrá a prueba tu habilidad para dañar a tu oponente. No te preocupes, no podrá hacerte daño.' WHERE `ID`=75859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 밴시군요! 폭발하기 전에 어서 처치하십시오!', `MaleText_loc4`='幻影女妖！杀了它，快，别让它爆炸！', `MaleText_loc5`='幻影女妖!快，殺死它，別讓它爆炸!', `MaleText_loc7`='¡Un Alma en pena ilusoria! ¡Mátala rápido antes de que explote!' WHERE `ID`=75860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 이번 시험에서 환영과 맞서는 저희를 지켜주십시오. 저, 오토가 당신을 보호하겠습니다.', `MaleText_loc4`='你好。在试炼中，你必须在我对付幻影时保证我的生命。我是鸥图，我会保护你的。', `MaleText_loc5`='哈囉。在這場戰鬥中，你必須讓我們活著，讓我們能迎戰其他幻影。我是奧托，我會保護你。', `MaleText_loc7`='Hola. Para esta prueba, tienes que mantenernos con vida mientras enfrentamos las ilusiones que nos atacan. Soy Oto y yo te protegeré.' WHERE `ID`=75861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 버티세요! 제가 갑니다!', `MaleText_loc4`='坚持住，我来了！', `MaleText_loc5`='撐住!我來了!', `MaleText_loc7`='¡Aguanta, ahí voy!' WHERE `ID`=75862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철벽같이 방어해 보겠습니다! 하지만 오래는 못 버팁니다.', `MaleText_loc4`='我是钢铁之盾！但是我坚持不了多久了！', `MaleText_loc5`='我是鋼鐵之牆，但我撐不了多久!', `MaleText_loc7`='¡Muro de escudo!' WHERE `ID`=75863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영 둥지가수다! 음파 공격을 조심하십시오!', `MaleText_loc4`='幻影虫巢咏者来了！它们的音波能伤害整个团队。', `MaleText_loc5`='幻影巢歌者!它們的聲波會傷害到所有人。', `MaleText_loc7`='¡Vienen unas cantantes de la colmena ilusorios! Sus ondas sónicas dañarán a todo el grupo.' WHERE `ID`=75864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 도전이군요. 환영 정복자입니다! 놈들이 격노하면 저를 신속히 치유해 주십시오.', `MaleText_loc4`='一个新挑战：幻影征服者！当它们暴怒时，它们的攻击凶狠异常。', `MaleText_loc5`='啊，新的挑戰，幻影征服者!當它們狂怒時，力量非常驚人。', `MaleText_loc7`='Un desafío nuevo: ¡Conquistadores ilusorios! Prepárate para sanarme rápidamente cuando estén enfurecidos.' WHERE `ID`=75865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 쓰러졌습니다! 죄송합니다. 다음엔 더 오래 견디겠습니다.', `MaleText_loc4`='我失败了！抱歉，今后我会更加努力训练的。', `MaleText_loc5`='我倒下了!抱歉，下次我會試著擋住更多傷害。', `MaleText_loc7`='¡Caí! Lo siento, la próxima vez entrenaré más duro.' WHERE `ID`=75866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오토, 내가 이렇게 공격당하면 큰 피해를 못 줘!', `FemaleText_loc4`='欧图，我老被攻击的话就没法全力输出了！', `FemaleText_loc5`='奧托，我一直被打是要怎麼殺敵?', `FemaleText_loc7`='¡Oto, no puedo atacarlos si siguen golpeándome!' WHERE `ID`=75867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물폭탄이 터졌잖아! 다음엔 더 빨리 차단해야 해!', `FemaleText_loc4`='刚才是水爆弹爆炸了？！下次快点驱散它！', `FemaleText_loc5`='是液體炸彈爆炸了!下次要快點驅散它!', `FemaleText_loc7`='¡Ha detonado una bomba acuática! ¡Neutralízala más rápido la próxima vez!' WHERE `ID`=75868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 환영 수병들이 우리에게 위험한 마법을 쓸 거예요. 어서 무효화해요!', `FemaleText_loc4`='这些幻影侍水僧会对我们施放危险的魔法效果，快驱散它们！', `FemaleText_loc5`='這些幻影水解師會對我們施放危險的法術效果。要快速地驅散掉!', `FemaleText_loc7`='Estos Acuálitos ilusorios nos dañarán con magia negra; ¡disípalos rápidamente!' WHERE `ID`=75869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 쓰러졌어요. 긴급 상황에서는 신속한 치유 주문을 사용해야 하죠.', `FemaleText_loc4`='我倒下了。在那种紧急情况下，最好使用快速治疗。', `FemaleText_loc5`='我倒下了。快速的治療比較適合這種緊急狀況。', `FemaleText_loc7`='Caí. Las curaciones rápidas serían lo mejor para emergencias como esa.' WHERE `ID`=75870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요. 더 많은 환영이 공격해올 테니 열심히 치유해 주세요.', `FemaleText_loc4`='你好啊。这次的幻影会更多，我们需要更多的治疗。', `FemaleText_loc5`='又見面了。更多的幻影正在接近，我們需要更多治療。', `FemaleText_loc7`='Hola otra vez. Se acercan más ilusiones y requeriremos de tus artes de sanación.' WHERE `ID`=75871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요. 소멸!', `FemaleText_loc4`='抱歉，隐身！', `FemaleText_loc5`='不好意思，馬上消失!', `FemaleText_loc7`='Lo siento, ¡me voy!' WHERE `ID`=75872;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카반, 저들도 애쓰고 있어. 친절해야지.', `FemaleText_loc4`='他们已经很努力了，卡凡。礼貌点。', `FemaleText_loc5`='他們已經很努力了，卡萬。有禮貌點。', `FemaleText_loc7`='Estoy segura de que hacen lo que pueden, Kavan. No seas mala.' WHERE `ID`=75873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='술리! 움직여요!', `FemaleText_loc4`='苏立，快跑开！', `FemaleText_loc5`='蘇力，快走開!', `FemaleText_loc7`='¡Sooli, MUÉVETE!' WHERE `ID`=75874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첫 번째 적이네요! 환영 톱날갈퀴는 그렇게 강하지 않아요. 어서 처치하죠!', `FemaleText_loc4`='第一个敌人！幻影撕裂者只是普通战士。来干掉他们吧！', `FemaleText_loc5`='我們的第一個敵人!幻影撕裂者只是一般的戰士。咱們上吧!', `FemaleText_loc7`='¡Nuestro primer enemigo! Los Desgarradores ilusorios son luchadores comunes. ¡Vamos contra ellos!' WHERE `ID`=75875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환영 불꽃소환사군요! 모두 발밑을 조심하세요! 용암을 밟지 마세요!', `FemaleText_loc4`='幻影召焰者！各位，注意脚下！别站在岩浆里！', `FemaleText_loc5`='幻影招炎者!小心腳下!所有人!別站在岩漿裡!', `FemaleText_loc7`='¡Clamallamas ilusorios! ¡Oigan todos, cuidado con sus pies! ¡No pisen la lava!' WHERE `ID`=75876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 쓰러졌어요!... 다시 하죠!', `FemaleText_loc4`='我失败了！……我们再试一次吧！', `FemaleText_loc5`='我倒下了!...再試一次!', `FemaleText_loc7`='¡Caí! ¡Volvamos a intentarlo!' WHERE `ID`=75877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 자기 몸도 치료하셔야지요!', `FemaleText_loc4`='哦不！你忘记给自己治疗了吗？', `FemaleText_loc5`='噢不!你忘記治療自己了嗎?', `FemaleText_loc7`='¡Oh, no! ¿Se te olvido sanarte a ti mismo?' WHERE `ID`=75878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번엔 환영들이 봐주지 않을 거예요. 공격도 가차없을 거고요. 가장 강력한 치유 주문을 준비하세요.', `FemaleText_loc4`='这次，幻影是不会后退的。它们会连续攻击。准备使用你最强的治疗手段吧。', `FemaleText_loc5`='這些幻影這次不會留情了。它們的攻擊將永不停止。準備好使用你最強的治療法術。', `FemaleText_loc7`='Las ilusiones no se contendrán esta vez. Sus ataques serán implacables. Prepárate para usar tus sanaciones más fuertes.' WHERE `ID`=75879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 이런, 날쌘돌이야, 도와줘!', `MaleText_loc4`='噢，天呐……飞毛腿，来帮忙！', `MaleText_loc5`='噢，糟了...史畢迪，快幫我!', `MaleText_loc7`='Ay, no... ¡Rapidín, ayúdame!' WHERE `ID`=75880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응?... 이런!', `MaleText_loc4`='哈？……噢！', `MaleText_loc5`='呃?噢，噢!', `MaleText_loc7`='¿Eh? ¡AH!' WHERE `ID`=75881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 환영 채굴꾼이군요. 날쌘돌이와 저는 예전에 이놈들과 싸워본 적이 있습니다. 조심하십시오. 놈들은 가끔씩 땅을 파고 들어간 뒤 적에게 튀어 올라서 확! 하하!', `MaleText_loc4`='啊，幻影隧道工。我和飞毛腿对付过这种敌人。小心，它们会钻洞，然后突然从新目标脚下冒出来狂啃！哈哈！', `MaleText_loc5`='啊，幻影隧掘者。史畢迪跟我碰過這種敵人。小心，它們會鑽地然後突然在新目標下面跳出來「咖茲」!哈哈!', `MaleText_loc7`='Ah, Tuneladores ilusorios. Rapidín y yo ya nos hemos enfrentado a estos enemigos. Ten cuidado: ¡a veces se entierran y luego salen de golpe por debajo de un nuevo objetivo y MUERDEN! ¡Jaja!' WHERE `ID`=75882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 날쌘돌이를... 부탁드립니다.', `MaleText_loc4`='啊啊……请照顾好……飞毛腿。', `MaleText_loc5`='啊...請照顧好...史畢迪。', `MaleText_loc7`='Auuugg… Por favor, cuida... a Rapidín.' WHERE `ID`=75883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영이 끝없이 밀려드네요. 그래도 최대한 오래 버텨내야지요!', `MaleText_loc4`='这些幻影是无穷无尽的，但我们要尽力守住！', `MaleText_loc5`='這些幻影源源不絕，但我們盡量試著撐越久越好!', `MaleText_loc7`='¡Estas ilusiones parecen no tener fin pero aguantaremos todo lo que podamos!' WHERE `ID`=75884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 모두 훌륭합니다! 친구, 다음 시험을 시작하려면 로툰을 만나보십시오.', `MaleText_loc4`='哈哈！干得好，各位！朋友，去找罗敦开启下一轮试炼吧。', `MaleText_loc5`='哈哈，大家都做得漂亮!朋友，準備好下一個試煉時去找羅通。', `MaleText_loc7`='¡Jaja! ¡Excelente trabajo, todos! Busca a Rotun para comenzar la prueba siguiente.' WHERE `ID`=75885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 쓰러질 순 없다!', `MaleText_loc4`='我不会再倒下了！', `MaleText_loc5`='我不會再次倒下的!', `MaleText_loc7`='¡No volveré a caer!' WHERE `ID`=75886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 명예로운 오크다, 나즈그림. 내가 할 일을 용서해다오.', `MaleText_loc4`='你是个高贵的兽人，纳兹戈林。很抱歉我必须这么做。', `MaleText_loc5`='你是一個高貴的獸人，納茲格寧姆。很遺憾我必須這麼做。', `MaleText_loc7`='Eres un Orco honorable, Nazgrim. Lamento tener que hacer esto.' WHERE `ID`=75887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 약속하지. 명예로웠던 네 전투는 영영 기억될 것이다. 호드를 위하여.', `MaleText_loc4`='你带着荣耀而战，加摩尔会让你的精神流传下去。为了部落，我的朋友。', `MaleText_loc5`='你以榮耀作戰。加摩爾會確保你的精神流傳下去。為了部落，我的朋友。', `MaleText_loc7`='Luchaste con honor, Gamon se asegurará de que tu legado continúe. Por la Horda.' WHERE `ID`=75888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게... 끝날 순 없어...', `MaleText_loc4`='不能就这样……结束……', `MaleText_loc5`='不能就這樣...結束...', `MaleText_loc7`='No puede acabar... así…' WHERE `ID`=75889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비바람과 눈보라가 몸을 뒤흔드는 높은 산꼭대기에서, 나무가 말라 죽고 산이 바다로 무너져 내릴 때까지 버틸 수 있겠느냐?', `MaleText_loc4`='你能否独立山巅，任由风霜侵袭，直至沧海变为桑田，高山沉入海底？', `MaleText_loc5`='你是否能站在最高峰，任狂風暴雨吹襲你的身軀仍屹立不搖，直到海枯石爛?', `MaleText_loc7`='¿Podrás pararte en la cima más alta, con los vientos y la escarcha cortándote la piel, hasta que los árboles se marchiten y las montañas caigan al mar?' WHERE `ID`=75890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 확인해 보지.', `MaleText_loc4`='让我们拭目以待吧。', `MaleText_loc5`='我們拭目以待。', `MaleText_loc7`='Ya veremos.' WHERE `ID`=75891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비바람이 너흴 흔들고, 눈보라가 너흴 할퀸다.', `MaleText_loc4`='风刀霜剑，四面受敌。', `MaleText_loc5`='狂風強襲，暴雨如豆。', `MaleText_loc7`='Los vientos estarán fuertes y la escarcha te lastimará.' WHERE `ID`=75892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 산이다. 시간만이 너흴 흔들 수 있지.', `MaleText_loc4`='不动如山，亘古不移。', `MaleText_loc5`='如高山一樣堅定不移。', `MaleText_loc7`='Tú eres la montaña, inamovible ante todo excepto el tiempo.' WHERE `ID`=75893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿋꿋이 자리를 지켜라. 그래야만 목표를 달성할 수 있으니.', `MaleText_loc4`='想要达到目标，你必须寸步不让。', `MaleText_loc5`='保持警戒，否則你將永遠無法成功。', `MaleText_loc7`='Mantente vigilante o nunca alcanzarás tus metas.' WHERE `ID`=75894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='견뎌내야 한다!', `MaleText_loc4`='坚持住！', `MaleText_loc5`='你必須堅持下去!', `MaleText_loc7`='¡Tienes que perseverar!' WHERE `ID`=75895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상상도 할 수 없는 강력한 적들에게 둘러싸여 있는 그런 때에도, 인내가 너희를 굳건히 지탱할 것이다. 다가오는 시간에 이 교훈을 반드시 기억해라.', `MaleText_loc4`='虽然被强大得超乎想象的敌人包围，毅力还是让你坚持了下来。在未来的日子里，请记住这一课。', `MaleText_loc5`='雖然被難以想像的敵人包圍，你的堅毅會讓你堅持下去。在未來要記得這一點。', `MaleText_loc7`='Aunque te rodearán enemigos más grandes de los que imaginas, tu fortaleza te permitirá resistir.  Recuerda esto en los tiempos que vendrán.' WHERE `ID`=75896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번도 겪지 못한 시련을 마주했을 때, 너흰 어떤 희망을 품겠느냐? 너희가 찾는 미래는 무엇이냐?', `MaleText_loc4`='在面对空前的挑战时，你有着怎样的期盼？你想要怎样的未来？', `MaleText_loc5`='當你面對前所未見的挑戰時，你希望如何?你想要見到怎樣的未來?', `MaleText_loc7`='Cuando te enfrentas a los peores desafíos de tu vida, ¿en qué pones tu esperanza? ¿Cuál es el futuro que buscas?' WHERE `ID`=75897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시작하자.', `MaleText_loc4`='让我们开始吧。', `MaleText_loc5`='那我們就開始吧。', `MaleText_loc7`='Entonces comencemos.' WHERE `ID`=75898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서로를 믿고, 서로에게 희망을 주어라!', `MaleText_loc4`='相信彼此，让别人为你带来希望！', `MaleText_loc5`='相信彼此，讓其他人為你傳承希望!', `MaleText_loc7`='¡Crean en sus semejantes y que los otros tengan esperanza en ustedes!' WHERE `ID`=75899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이 없다면 미래는 어둡기만 할 것이다!', `MaleText_loc4`='没有希望，未来就没有光明！', `MaleText_loc5`='沒有希望，未來就沒有光明!', `MaleText_loc7`='Sin esperanza, ¡el futuro no tiene luz!' WHERE `ID`=75900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 스스로 만들어라!', `MaleText_loc4`='去创造你想要的命运吧！', `MaleText_loc5`='創造你要的命運!', `MaleText_loc7`='¡Creen el destino que buscan!' WHERE `ID`=75901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하지 마라!', `MaleText_loc4`='不要放弃自己！', `MaleText_loc5`='不要放棄自己!', `MaleText_loc7`='¡No pierdan la fe en ustedes mismos!' WHERE `ID`=75902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 희망은 밝게 빛나고, 역경을 극복하려고 힘을 합치면 더욱 밝게 빛난다. 가장 어두운 곳에서도, 희망이 너희의 길을 밝혀줄 것이다.', `MaleText_loc4`='你们的希望十分闪亮，你们团结起来后，它更是璀璨夺目。哪怕在最黑暗的地方，它也将照亮你们的道路。', `MaleText_loc5`='你的希望閃耀，尤其在團結後更是燦爛。即使在最黑暗的地方，它也會照亮你的路途。', `MaleText_loc7`='Su esperanza brilla mucho y aún más cuando luchan juntos para triunfar. Siempre iluminará su camino, hasta en los lugares más oscuros.' WHERE `ID`=75903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑하는 영웅들이여, 진정한 지혜는 너희 안에, 너희가 하는 선택 안에 있단다. 압도적인 어둠과 마주할 때, 너희는 올바른 결정을 내릴 수 있느냐?', `MaleText_loc4`='亲爱的英雄，真正的智慧就在你心中，也在你所作出的选择中。当面对压倒性的黑暗时，你能否作出正确的选择呢？', `MaleText_loc5`='真正的智慧就在你們的內心和你們做的選擇，親愛的英雄們。在無可抗拒的黑暗之下，你們會做出正確的選擇嗎?', `MaleText_loc7`='La lección de la verdadera sabiduría está en ustedes y en las elecciones que hacen. Al enfrentarse a la oscuridad abrumadora, ¿tomarán las decisiones correctas?' WHERE `ID`=75904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 시작하자!', `MaleText_loc4`='试炼开始！', `MaleText_loc5`='試煉開始!', `MaleText_loc7`='¡Que comiencen las pruebas!' WHERE `ID`=75905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내면의 목소리에 귀를 기울이고, 진실을 찾아라!', `MaleText_loc4`='倾听你内心的声音，找出真相吧！', `MaleText_loc5`='傾聽你們內心的聲音，找出真相!', `MaleText_loc7`='¡Escuchen a su voz interior y busquen la verdad!' WHERE `ID`=75906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시련 때문에 판단력이 흐려져선 안 된다!', `MaleText_loc4`='审时度势，别让危机干扰你的判断！', `MaleText_loc5`='別讓你們的判斷被困境蒙蔽!', `MaleText_loc7`='¡No dejen que su juicio se nuble en los momentos críticos!' WHERE `ID`=75907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 행동이 어떤 결과를 낳을지 생각해라!', `MaleText_loc4`='考虑好行动的顺序！', `MaleText_loc5`='時刻考慮你們行動的後果!', `MaleText_loc7`='¡Siempre consideren las consecuencias de sus actos!' WHERE `ID`=75908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실수를 되새겨 봐라!', `MaleText_loc4`='从错误中汲取教训！', `MaleText_loc5`='從錯誤中學習!', `MaleText_loc7`='¡Aprendan de sus errores!' WHERE `ID`=75909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시험에서 너희의 지혜가 빛을 발했다. 그 지혜가 어두운 곳에서 항상 너희의 등불이 되길.', `MaleText_loc4`='你的智慧帮你赢得了这次试炼。愿它能始终带你走出困境。', `MaleText_loc5`='你們的智慧幫你們度過了考驗。希望智慧能在黑暗中照亮你們的道路。', `MaleText_loc7`='Su sabiduría los ha hecho pasar esta prueba. Que siempre ilumine su camino hasta salir de los lugares más oscuros.' WHERE `ID`=75910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘. 그것은 단순히 육체적 강함을 넘어서는 무엇이지. 진정한 시련을 마주했을 때, 그냥 힘과 진정한 힘의 차이를 말할 수 있겠느냐?', `MaleText_loc4`='力量。它不仅仅是指单纯的肉体强度。在面对真正的考验时，你是否能够分清力量与能力？', `MaleText_loc5`='力量。它不只是單純的肉體強度。當你經歷真正的考驗時，是否能釐清力量與強度的分別?', `MaleText_loc7`='Fuerza. Es mucho más simple que la proeza física. En una verdadera prueba, ¿podrás encontrar la diferencia entre la fuerza y el poder?' WHERE `ID`=75911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 시험을 시작하자!', `MaleText_loc4`='哈哈！试炼开始！', `MaleText_loc5`='哈哈!試煉開始吧!', `MaleText_loc7`='¡Ja, ja!  ¡Que comience la prueba!' WHERE `ID`=75912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신의 힘을 믿어라!', `MaleText_loc4`='相信你的力量！', `MaleText_loc5`='相信自己的力量!', `MaleText_loc7`='¡Cree en tu fuerza!' WHERE `ID`=75913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에겐 운명을 바꿀 힘이 있다!', `MaleText_loc4`='你拥有改变命运的能力！', `MaleText_loc5`='你有改變命運的力量!', `MaleText_loc7`='¡Tienes el poder de cambiar tu destino!' WHERE `ID`=75914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 주는 힘을 진정한 힘으로 착각하지 마라!', `MaleText_loc4`='不要把黑暗之力错当成真正的力量！', `MaleText_loc5`='不要把黑暗的強度當成真正的力量!', `MaleText_loc7`='¡No confundas el poder que ofrece la oscuridad con la fuerza verdadera!' WHERE `ID`=75915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 배는 강해져서 돌아와라!', `MaleText_loc4`='加倍奉还！', `MaleText_loc5`='加倍奉還!', `MaleText_loc7`='¡Regresa con el doble de poder!' WHERE `ID`=75916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 강하다. 너희 생각보다 훨씬. 앞에 놓인 어둠 속으로 들어갈 때 이것을 기억하고, 방패로 삼아라.', `MaleText_loc4`='你很强大，比你自己以为的还要强大。带着这个信念勇敢迎接黑暗吧，它将会庇佑着你。', `MaleText_loc5`='你很強，比你認知的還要強大。帶著這個信念迎接前方的黑暗，讓它保護你。', `MaleText_loc7`='Eres fuerte, más fuerte de lo que crees. Llévate este consejo contigo cuando entres en la oscuridad y deja que te cuide.' WHERE `ID`=75917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이제야 좀 재미있군. 록타르 오가르!', `MaleText_loc4`='啊，总算能活动了。 Lok''tar Ogar！', `MaleText_loc5`='終於，能活動筋骨了。(獸人語)不勝即亡!', `MaleText_loc7`='Ah, al fin un poco de acción. ¡Lok''tar Ogar!' WHERE `ID`=75918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... 멋진... 일격이었다...', `MaleText_loc4`='啊……哈……打得好……', `MaleText_loc5`='呃...哈...打得...好...', `MaleText_loc7`='Ja, ja... buen golpe...' WHERE `ID`=75919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허튼 수작 마라, 볼진! 남은 공성 무기가 없으니, 이 전투를 이길 순 없어!', `MaleText_loc4`='别傻了，沃金！你们没有攻城武器了！你是赢不了的！', `MaleText_loc5`='別傻了，沃金!你沒有攻城武器了!你不可能贏的!', `MaleText_loc7`='¡No seas tonto, Vol''jin!  ¡No te quedan armas de asedio!  ¡No puedes ganar esta batalla!' WHERE `ID`=75920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전쟁 병기를 파괴했을진 몰라도, 아직 성문은 멀쩡하다. 오그리마를 포기해!', `MaleText_loc4`='就算你们打败了它，可城门依然耸立。你们休想攻占奥格瑞玛。', `MaleText_loc5`='你們也許擊敗了我的戰爭機器，但是城門仍屹立不搖。今天，你們拿不下奧格瑪。', `MaleText_loc7`='Habrás detenido a mi máquina de guerra pero la puerta sigue en pie. Hoy no tomarás Orgrimmar.' WHERE `ID`=75921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 코르크론이여! 성문으로! 어서!', `MaleText_loc4`='什么？库卡隆，到城门那边去！快！', `MaleText_loc5`='什麼?柯爾克隆，去城門那裡!快!', `MaleText_loc7`='¿Qué? ¡Kor''kron, a las puertas! ¡Ya!' WHERE `ID`=75922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 얼라이언스도 날 쓰러뜨리진 못했다. 너희라고 가능할 것 같나?', `MaleText_loc4`='我从未被联盟打倒过。你觉得自己够强吗？', `MaleText_loc5`='我從沒被任何一個聯盟擊倒過。你覺得自己有這個本事嗎?', `MaleText_loc7`='Jamás he caído a manos de la alianza. ¿Acaso pretenden estar preparados?' WHERE `ID`=75923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 나즈그림, 대족장님의 오른팔이자 호드의 장군. 흐... 내 오늘 죽을 운명이라면, 명예롭게 싸우다 죽으리라. 호드를 위하여!', `MaleText_loc4`='我是纳兹戈林，酋长之拳，部落统帅。就算我今天难逃一死，也要光荣地战死沙场。为了部落！', `MaleText_loc5`='我是納茲格寧姆，大酋長之拳，部落的將軍。如果我今日會死，我會在戰鬥中榮耀地死去。為了部落!', `MaleText_loc7`='Soy Nazgrim, el puño del Jefe de Guerra y el general de la Armada de la Horda. Si tengo que morir hoy, moriré con honor en batalla. ¡Por la Horda!' WHERE `ID`=75924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 훈련이 한참 부족하군.', `MaleText_loc4`='你训练得太糟糕了。', `MaleText_loc5`='你該多練一練的。', `MaleText_loc7`='Debieron haber entrenado más.' WHERE `ID`=75925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예롭게... 죽는구나... 록타르 오가르...', `MaleText_loc4`='我……虽死犹荣……Lok''tar Ogar……', `MaleText_loc5`='我...雖死猶榮...Lok''tar Ogar...', `MaleText_loc7`='Muero... con honor... Lok''tar ogar...' WHERE `ID`=75926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 가몬... 마침내 깨달았구나... 네 손에... 죽게 돼... 영광이다...', `MaleText_loc4`='啊……加摩尔……你终于变强了……能死在……你的手上……是我的荣幸……', `MaleText_loc5`='啊，加摩爾...你終於懂了...我很榮幸...死在...你的手裡...', `MaleText_loc7`='Ah, Gamon... por fin has aprendido... Estoy orgulloso... de morir... a tu mano...' WHERE `ID`=75927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 참 많이 늘었구나... 명예로운 전투였다.', `MaleText_loc4`='啊……你学会了很多……学得很好……光荣的战斗。', `MaleText_loc5`='啊，你學了很多...學得很好...光榮的一戰。', `MaleText_loc7`='Ah... has aprendido mucho... y bien... Una batalla honorable.' WHERE `ID`=75928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 순간까지, 난 대족장 곁을 지켰다. 그게 내 임무였으니까. 날 쓰러뜨린 게 너라 기쁘구나. 너의 힘이... 호드를... 새 시대로 이끌길 빌겠다.', `MaleText_loc4`='我最终站在了酋长一边，因为这是我的使命，很高兴打倒我的人是你。愿你的力量……带领部落……走向繁荣昌盛。', `MaleText_loc5`='最終，我站在大酋長身邊，因為這是我的職責，很高興是你擊敗我。希望你的力量...能帶領部落...進入新的繁榮時代。', `MaleText_loc7`='Al final, apoyé al jefe de guerra porque era mi deber y estoy feliz de que hayas sido tú quien me derrotó. Que tu fuerza... lidere a la horda... hacia una nueva era de prosperidad.' WHERE `ID`=75929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여...', `MaleText_loc4`='为了部落……', `MaleText_loc5`='為了部落...', `MaleText_loc7`='Por la Horda…' WHERE `ID`=75930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 때가 왔군. 수년간, 우린 함께 싸우며 성장해왔다. 그리고 마침내, 전장에서 이렇게 맞붙게 되었구나. 내가 봐줄 거라 생각 마라, 너 역시 날 봐줘선 안 돼. 지금부터 벌어질 우리 싸움은 그 누구도 아닌, 바로 호드를 위한 거니까.', `MaleText_loc4`='这一天终于来了。多年来我们一起成长，一起学习，如今却在战场上兵戎相见。别幻想我会放过你，我也不会求饶。此时此刻，我们所做的一切，都是为了部落。', `MaleText_loc5`='看來要結束了。我們曾一起學習成長，但現在卻要在戰場上兵戎相見。別以為我會放水，我也不期望你們會手下留情。我們所做的一切，都是為了部落。', `MaleText_loc7`='Así que llegamos a esto. Juntos, aprendimos y crecimos durante años y ahora nos encontramos cara a cara en el campo de batalla. No creas que te la haré más fácil, ni yo espero piedad alguna. Lo que haremos ahora, lo haremos por la horda, por ambos.' WHERE `ID`=75931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 너와 싸우게 되어 영광이다. 록타르 오가르. 명예를 위해, 그리고 호드를 위하여!', `MaleText_loc4`='能够与你一战是我的荣幸。Lok''tar Ogar，为了荣耀，为了部落！', `MaleText_loc5`='很榮幸最終在戰鬥中與你們對戰。Lok''tar Ogar，為了榮耀，為了部落!', `MaleText_loc7`='Es un honor enfrentarme a ustedes en combate, al fin.  Lok''tar Ogar, por el Honor, ¡y por la Horda!' WHERE `ID`=75932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전 옥룡은 내게 영혼을 깨끗이 하고 대지와 하나가 되라고 가르쳤네. 그랬더니 내가 품었던 의심이 말끔히 사라졌지.', `MaleText_loc4`='很久以前，睿智的青龙教会我净化自己的灵魂并与大地融为一体，我的疑虑就此被打消了。', `MaleText_loc5`='許多年前，玉蛟教導我淨化靈魂並與大地合一，我的懷疑就被擊敗了。', `MaleText_loc7`='Hace mucho tiempo, el Dragón de Jade me enseñó a purificar mi espíritu y a volverme uno con la tierra; y así conquisté mis dudas.' WHERE `ID`=75933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 여정이 시작되었을 때, 나는 힘을 함부로 휘둘렀다네. 백호가 내게 절제를 가르쳤고, 그러자 증오와 분노, 폭력성이 말끔히 사라졌지.', `MaleText_loc4`='当旅程开始时，我只会鲁莽地运用自己的力量。白虎教我学会控制，从而征服了我的仇恨、愤怒和暴虐。', `MaleText_loc5`='當我的旅程開始時，我只會依靠蠻力。白虎教了我控制，使我的仇恨、憤怒及暴力都被擊敗了。', `MaleText_loc7`='Cuando comenzó mi viaje, fui imprudente con mi fuerza. El Tigre Blanco me enseñó a controlarme y conquisté mi odio, mi ira, y mi violencia.' WHERE `ID`=75934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주학은 내게서 희망을 보고, 내게 내면을 들여다보라고 가르쳤네. 얼굴엔 절망이 가득했음에도 나는 희망을 찾았고, 그러자 절망이 사라졌지.', `MaleText_loc4`='朱鹤看到了我内心的希望，并且教我学会自省。透过绝望的表象，我发现了希望，并由此征服了绝望。', `MaleText_loc5`='紅鶴看到了我內心的希望並要我捫心自問。我在自己絕望的表象下找到了希望，絕望也因此被擊敗了。', `MaleText_loc7`='La Grulla Roja vio esperanza en mí y me enseñó a mirar en mi interior. A pesar de mi estado de desesperación, encontré esta esperanza y conquisté mi desesperación.' WHERE `ID`=75935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 크나큰 공포를 마주했을 때 흑우가 내게 인내를 가르쳤네. 그로써 두려움과 어둠을 이겨 냈고, 그러자 공포가 사라졌지.', `MaleText_loc4`='在巨大的恐惧面前，玄牛教我懂得坚毅，让我在恐怖与黑暗的时代不屈不挠，征服恐惧。', `MaleText_loc5`='在極端的恐懼下，玄牛教了我堅忍。這讓我熬過了恐怖與黑暗，恐懼因此被擊敗了。', `MaleText_loc7`='Frente a un miedo terrible, el Buey Negro me enseñó sobre la fortaleza. Perseveró frente al terror y a la oscuridad y conquistó el miedo.' WHERE `ID`=75936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 지혜의 시험을 치르고 옥룡의 도를 배웠네. 내가 그랬듯이 자네도 가르침을 얻었기를 바라네.', `MaleText_loc4`='你通过了智慧的试炼，并领悟了青龙之道。愿你能像我一样，有所收获。', `MaleText_loc5`='你通過了智慧的試煉，學會了玉蛟之道。希望你像我一樣吸取到教訓。', `MaleText_loc7`='Has recorrido la prueba de la sabiduría y aprendido sobre la senda del Dragón de Jade. Espero que hayas aprendido de esta lección, como lo hice yo.' WHERE `ID`=75937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 힘의 시험을 치르고 백호의 도를 배웠네. 늘 이 가르침을 기억하기를.', `MaleText_loc4`='你通过了力量的试炼，并领悟了白虎之道。愿你永远记住这一课。', `MaleText_loc5`='你通過了力量的試煉，學會了白虎之道。希望你能一直記得這個教訓。', `MaleText_loc7`='Has recorrido la prueba de la fuerza y aprendido sobre la senda del Tigre Blanco. Espero que siempre recuerdes esta lección.' WHERE `ID`=75938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 희망의 시험을 치르고 주학의 도를 배웠네. 이 가르침이 자네의 발걸음을 이끌기를.', `MaleText_loc4`='你通过了希望的试炼，并领悟了朱鹤之道。愿它永远指引你的脚步。', `MaleText_loc5`='你通過了希望的試煉，學會了紅鶴之道。希望它能在未來指引你的步伐。', `MaleText_loc7`='Has recorrido la prueba de la esperanza y aprendido sobre la senda de la Grulla Roja. Que siempre guíe tus pasos.' WHERE `ID`=75939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 인내의 시험을 치르고 흑우의 도를 배웠네. 이 가르침이 자네의 길을 축복하기를.', `MaleText_loc4`='你通过了坚毅的试炼，并领悟了玄牛之道。愿它永远护佑你的道路。', `MaleText_loc5`='你通過了堅忍的試煉，學會了玄牛之道。希望它祝福你的路途。', `MaleText_loc7`='Has recorrido la prueba de la fortaleza y aprendido sobre la senda del Buey Negro. Que bendiga tu camino.' WHERE `ID`=75940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무너진 동굴에서 빠져나가기 위해 할 수 있는 건 다 했다. 이제는 돌맹이 하나 움직일 힘도 없다. 아, 흑우시여, 제게 강인한 힘을 내려 주시옵소서. 사원의 전설적인 무기를 빌려 왔어야 하는 건데...', `MaleText_loc4`='我用尽了一切办法想要移走塌方的石头！可玄牛在上，我连一块石头都搬不动。或许我得去寺院里借一把传奇武器来才行……', `MaleText_loc5`='我已經試過各種辦法剷除這塊塌陷了!玄牛，賜我堅毅之力吧。現在我連一塊石頭都搬不動，或許...我能去天尊之廷借把厲害的武器的話...', `MaleText_loc7`='¡Lo he intentado todo para despejar este derrumbe! Que el Buey Negro me dé fuerza, porque no puedo mover ni una sola roca. A lo mejor si pido prestada una de las armas legendarias del templo...' WHERE `ID`=75941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 부탁이니 골짜기의 중심에 있는 만개화 광산 근처에서 보세. 그곳에서 자네에게 꼭 보여주고 싶은 게 있다네.', `MaleText_loc4`='我的朋友，请到锦绣谷中心的繁盛矿洞附近来找我。我想给你看点东西。', `MaleText_loc5`='我的朋友，請你到山谷中間的繁花礦坑跟我碰面。我在那裡有些東西想讓你看看。', `MaleText_loc7`='Hazme un favor: reúnete conmigo cerca de la Mina de la Gran Flor, en el centro del valle. Quiero enseñarte algo.' WHERE `ID`=75942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코리코! 나쁘진 않은데...', `MaleText_loc4`='里克里克可是很有两下子的……', `MaleText_loc5`='瑞可有個很棒的競技場...', `MaleText_loc7`='Me gusta kómo suena "Riko Riko"...' WHERE `ID`=75943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 뭘 그렇게 놀라나? 나는 검은용이다. 오로지 나 자신에게만 충성하지.', `MaleText_loc4`='噢，别那么惊讶！我可是黑龙。我只忠于我自己。', `MaleText_loc5`='噢，不要看起來那麼驚訝!我是黑龍。我只對自己忠誠。', `MaleText_loc7`='¡Ay, ¿por qué esa cara de sorpresa?! Soy un dragón negro. Mis lealtades son cosa mía.' WHERE `ID`=75944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코 불꽃놀이 좋아한다!', `MaleText_loc4`='里克喜欢烟火！', `MaleText_loc5`='瑞可什麼煙火都喜歡!', `MaleText_loc7`='¡A Riko le gustan los fuegos artificiales!' WHERE `ID`=75945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코 좋은 생각 있다. 우끼하면서 계속 춤추는 거다!', `MaleText_loc4`='里克有个主意。乱斗俱乐部！', `MaleText_loc5`='瑞可有個主意。拿上棍子!', `MaleText_loc7`='Riko tiene una idea: ¡el klub del kraku!' WHERE `ID`=75947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽이든 오른쪽이든 흐르는 쪽으로 가. 흐름에 맞서 싸울 필요는 없으니까.', `MaleText_loc4`='当河流转向时，我们应该顺应潮流，而非逆势而上。', `MaleText_loc5`='當河流改道的時候，隨波逐流就對了，不要反抗。', `MaleText_loc7`='Si el río gira a izquierda o derecha, fluye con él, no te resistas.' WHERE `ID`=75948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친한 친구를 잊지 마. 영원히 함께 할 동반자니까.', `MaleText_loc4`='永远不要忘记你最伟大的朋友，他们会与你并肩作战，直到最后一刻。', `MaleText_loc5`='別忘記你最好的朋友，他們會陪你堅持到最後。', `MaleText_loc7`='Nunca te olvides de tu mejor amigo, permanecerá a tu lado hasta el final.' WHERE `ID`=75949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제가 가까이에 있어. 의심, 증오, 분노, 절망, 그리고 공포를 물리친 그 사람 말이야.', `MaleText_loc4`='皇帝就快成功了，他击败了猜忌、仇恨、暴怒和恐惧。', `MaleText_loc5`='皇帝非常近，對抗懷疑、仇恨、憤怒、絕望及恐懼。', `MaleText_loc7`='El Emperador está cerca. Luchó contra la duda, el odio, la ira, la desesperación y el miedo.' WHERE `ID`=75950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 그 바보 천치 린! 고결하시기도 해라!', `MaleText_loc4`='可那个白痴，白痴“国王”乌瑞恩！', `MaleText_loc5`='但那個白痴，白痴烏瑞恩!「大君主」個鬼!', `MaleText_loc7`='¡Pero ese idiota, ese IDIOTA de Wrynn! ¡"Su Majestad", sí, claro!  ' WHERE `ID`=75951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 대족장을 뽑게 놔둔 거지? 얼라이언스의 깃발 아래 온 세상을 결집시킬 기회였는데. 그자의 야망을 믿은 내가 바보지!', `MaleText_loc4`='他怎能容忍新的“酋长”的出现！他本可以一统全世界。我真傻，居然会指望他的野心！', `MaleText_loc5`='他為什麼允許新的大酋長就任?他本來可以讓全世界都歸於聯盟旗下。我怎麼會蠢到相信他的野心!', `MaleText_loc7`='¿Por qué permitió que hubiera otro Jefe de Guerra? Podría haber unido al mundo bajo el Estandarte de la Alianza. ¡Qué tonto fui en confiar en su ambición!' WHERE `ID`=75952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 나 스스로 왕좌를 차지할 걸 그랬어. 오닉시아 이모처럼. 그래야 뭘 제대로 하지.', `MaleText_loc4`='我就该像奥妮克希亚一样，把王者之位抢过来。亲手搞定一切。', `MaleText_loc5`='早知道就自己拿下王位。像奧妮克希亞阿姨一樣。不擇手段。', `MaleText_loc7`='Tendría que haberme apoderado de la sala del trono por mi cuenta. Como la tía Onyxia, y hacer las cosas como se debe.' WHERE `ID`=75953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1을;를; 탑에서 끌어낼 수 없습니다!', `MaleText_loc4`='%s拒绝撤离塔楼！', `MaleText_loc5`='%s是不會從他的哨塔上被打下來的!', `MaleText_loc7`='¡%s no sale de su torre!', `FemaleText_loc1`='%s|1을;를; 탑에서 끌어낼 수 없습니다!', `FemaleText_loc4`='%s拒绝撤离塔楼！', `FemaleText_loc5`='%s是不會從他的哨塔上被打下來的!', `FemaleText_loc7`='¡%s no sale de su torre!' WHERE `ID`=75954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명심하게, $n.

위대한 천신회는 얼라이언스와 호드가 이곳에서 다투는 일을 결코 용납하지 않을 걸세.', `MaleText_loc4`='请小心些，$n。

至尊天神严禁联盟和部落在此地私斗。', `MaleText_loc5`='請保重，$n。

聖獸天尊是不會容忍聯盟和部落之間的仇恨的。', `MaleText_loc7`='Ten cuidado, $n.

Los Augustos Celestiales no tolerarán agresiones entre la Alianza y la Horda.' WHERE `ID`=75955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와줘요! 이것들 좀 떼내주세요!', `FemaleText_loc4`='救命！把它们赶开！', `FemaleText_loc5`='救命!把它們拉走啊!', `FemaleText_loc7`='¡Ayuda! ¡Quítame estas cosas de encima!' WHERE `ID`=75956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 서서 뭐하는 거예요?! 불길에서 나오세요!', `FemaleText_loc4`='你往哪儿站呢？！离火焰远点儿！', `FemaleText_loc5`='你站在那裡不痛嗎?快離開那裡啊!', `FemaleText_loc7`='¡¿Qué haces ahí parado?! ¡Sal del fuego!' WHERE `ID`=75957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환영 톱날갈퀴가 공격해오고 있어요. 멍청한 놈들이니 별로 어렵지 않을 거예요.', `FemaleText_loc4`='幻影撕裂者来了。它们算不上挑战，只是些没脑子的蛮兵。', `FemaleText_loc5`='幻影撕裂者來了。他們應該沒什麼威脅，都是無腦的小兵。', `FemaleText_loc7`='Vienen unos Desgarradores ilusorios. No serán un gran desafío; solo son brutos descerebrados.' WHERE `ID`=75958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어 태세를 갖추세요. 저건 환영 정복자예요! 환영 정복자가 격노하면 엄청난 힘이 생겨서 아무도 못 막아요!', `FemaleText_loc4`='准备防御。那是幻影征服者！它们暴怒时，会造成极高的伤害，无人能挡！', `FemaleText_loc5`='準備防禦。那是幻影征服者!當它們狂怒時，它們會造成可怕的傷害，沒有人能阻止它們!', `FemaleText_loc7`='Preparen sus defensas. ¡Eso es un Conquistador ilusorio! Cuando se enfurecen, ganan una fuerza increíble y ¡nada puede detenerlos!' WHERE `ID`=75959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새로운 적인 환영 불꽃소환사네요. 화염구를 던지고 용암을 내뿜죠. 그 용암을 이용하세요. 다른 환영도 태워버리니까요!', `FemaleText_loc4`='有新的敌人来了，幻影召焰者。它们会施放火球术并喷吐岩浆。好好利用这些岩浆，它们能烧死其他幻影！', `FemaleText_loc5`='新的敵人，幻影招炎者。它們會施放火球術並噴出岩漿。我們可以好好利用它們噴出的岩漿來燒其他的幻影!', `FemaleText_loc7`='Un enemigo nuevo, los Clamallamas ilusorios. Lanzan bolas de fuego y escupen lava. Usa la lava a tu favor; ¡quemará a las otras ilusiones!' WHERE `ID`=75960;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하세요. 환영 바람 경비대는 날개로 당신을 밀쳐낼 수 있어요. 그러면 놈들은 당신 대신 저를 공격할 거예요!', `FemaleText_loc4`='小心，幻影风卫士会用翅膀击退你，然后再转过头来攻击我！', `FemaleText_loc5`='小心，幻影風衛能使用翅膀擊退你。在擊退你之後，他們就會來攻擊我了!', `FemaleText_loc7`='Cuidado, Los Guardias del Viento ilusorios pueden usar sus alas para repelerte. Cuando lo hagan, ¡lo más probable es que pasen a atacarme a mí!' WHERE `ID`=75961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환영 복병이네요! 어서 놈들의 주의를 끄세요. 놈들이 바나나로 저를 공격하지 못하도록 멀리 떨어뜨려 주세요!', `FemaleText_loc4`='幻影伏击者！快吸引它们的主意，让它们离我远点，别让那些危险的香蕉击中我！', `FemaleText_loc5`='幻影伏擊者!快取得它們的注意力，讓它們離我遠一點，別讓它們用恐怖的香蕉攻擊我!', `FemaleText_loc7`='¡Emboscadores ilusorios! Llama su atención rápidamente y aléjalos de mí, ¡así no me podrán golpear con sus bananas devastadoras!' WHERE `ID`=75962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환영 채집꾼이 공격하네요! 그 귀여운 얼굴에 속지 마세요. 놈들은 힘을 합쳐서 끔찍한 공격을 할 수 있어요.', `FemaleText_loc4`='幻影抢劫者进攻了！别让它们可爱的样子骗了，它们能合力造成极高的伤害。', `FemaleText_loc5`='幻影強奪者在攻擊了!別被它們可愛的樣子騙了，他們可以合力造成恐怖的傷害!', `FemaleText_loc7`='¡Los Batidores ilusorios están atacando! No dejes que sus rostros bonitos te engañen, pueden trabajar juntos para infligir una devastación terrible.' WHERE `ID`=75963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으, 이렇게 심각한 피해는 치유할 수 없어요! 안 좋은 방어구 찬 거 아니에요?!', `FemaleText_loc4`='啊，我治疗不了那么高的伤害！你忘记换坦克装了吗？', `FemaleText_loc5`='啊，我沒辦法治療那麼重的傷害!你忘記換上你最好的護甲了嗎?', `FemaleText_loc7`='Arggg, ¡no puedo sanar con tanto daño! ¡¿Te olvidaste de utilizar tu mejor armadura?!' WHERE `ID`=75964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 쓰러졌어요! 아, 다음엔 치유 약초를 더 가져와야겠어요.', `FemaleText_loc4`='我失败了！或许下次我应该穿上治疗装备？', `FemaleText_loc5`='我不行了。也許下次我該插一些耐力寶石?', `FemaleText_loc7`='¡Caí! Tal vez tendría que traer algunas hierbas curativas para la próxima vez, ¿no?' WHERE `ID`=75965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요. 저는 시카리예요. 비취 번개와 기, 치유의 안개의 대가죠. 이번 시험에서는 제가 당신을 치유하고 적을 처치하는 동안 환영의 공격에서 저를 지켜주셔야 해요.', `FemaleText_loc4`='你好。我是司佳丽，碎玉闪电、真气与治疗之雾的大师。在试炼中，你得保护我，挡住涌来的幻影。而我会治疗你并对付我们敌人。', `FemaleText_loc5`='你好，我是希卡莉，翠玉閃電、氣功及治療迷霧的大師。在這場試煉中，你必須保護我不受幻影攻擊，讓我治療你並擊敗敵人。', `FemaleText_loc7`='Saludos. Soy Sikari, maestra del relámpago de jade, chi y las nieblas curativas. Para esta prueba, tienes que protegerme de las ilusiones que atacan mientras te sano y acabo con nuestros enemigos.' WHERE `ID`=75966;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 만났네요. 다음 시험은 더욱 힘들 거예요. 저를 지킬 준비를 해주세요!', `FemaleText_loc4`='你好啊。我们的下一场试炼更具挑战性。准备保护我！', `FemaleText_loc5`='又見面了。我們的下一場試煉將會更有挑戰性。準備保護我!', `FemaleText_loc7`='Hola de nuevo. La próxima prueba será más difícil. ¡Prepárate para defenderme!' WHERE `ID`=75967;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에도 저를 잘 지켜 주세요. 로툰, 이번엔 어려운 걸로 부탁해!', `FemaleText_loc4`='这次，你还是要保护我。嘿，罗敦，来场真正的挑战吧！', `FemaleText_loc5`='你必須再次保護我。嘿，羅通，這次認真一點好嗎?', `FemaleText_loc7`='Una vez más, tienes que defenderme. Rotun, ¡mándanos algo difícil esta vez!' WHERE `ID`=75968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가는 최후를 맞기 마련이지만, 그래도 최대한 많은 적을 해치우자고요. 준비하세요!', `FemaleText_loc4`='虽然失败无法避免，但是我们还是要尽力杀敌。做好准备！', `FemaleText_loc5`='雖然我們難以取勝，至少盡力試著多擊敗幾個敵人。準備好!', `FemaleText_loc7`='Si bien nuestro final es inevitable, tratemos de llevarnos con nosotros a cuantos podamos. ¡Prepárate!' WHERE `ID`=75969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의심의 샤를 처치했으니, 두루마리를 읽을 준비가 된 것 같습니다.', `MaleText_loc4`='击败疑之煞后，你终于可以阅读这些卷轴了。', `MaleText_loc5`='疑惑之煞已被擊敗，你可以讀卷軸的內容了。', `MaleText_loc7`='Tras haber derrotado al Sha de la duda, estás $glisto:lista; para leer el pergamino.' WHERE `ID`=75970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잃어버린 지식을 위해서 할 수 있는 일은 이미 다 했습니다.', `MaleText_loc4`='你已经为获取这一失传的技艺做出了一切努力。', `MaleText_loc5`='你已經為這被遺忘的知識盡了你最大的努力。', `MaleText_loc7`='Ya has hecho lo posible por recuperar este conocimiento perdido.' WHERE `ID`=75971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게.

거대한 야수들 말고도 해변 반대쪽에는 적 진영의 야영지가 있더군.', `MaleText_loc4`='出门在外，请多加小心。

除了那些巨兽，这片海滩的另一头还有敌人的营地。', `MaleText_loc5`='小心那裡。

除了巨大的野獸之外，在海灘的另一端還有一處敵營。', `MaleText_loc7`='Ten cuidado ahí fuera.

Además de las bestias gigantes, hay un campamento enemigo en el otro extremo de esta playa.' WHERE `ID`=75972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위협적으로 노려봅니다.', `MaleText_loc4`='%s恶毒地瞥了你一眼。', `MaleText_loc5`='%s面露威脅地瞇起眼睛。', `MaleText_loc7`='%s lanza una mirada amenazadora.' WHERE `ID`=75973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!!', `MaleText_loc7`='¡¡Basta!!' WHERE `ID`=75977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말! 말! 말!', `MaleText_loc4`='说，说，说！', `MaleText_loc5`='一直說，一直說!', `MaleText_loc7`='¡Hablar, hablar y hablar!' WHERE `ID`=75978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늘 말하기만 하고, 듣지는 않지! 자넨 판다리아의 교훈을 무시하고 있어!', `MaleText_loc4`='你只知道说，却从不倾听！你忽略了潘达利亚的教训！', `MaleText_loc5`='你總是一直說。從來都不傾聽!你無視潘達利亞的教誨!', `MaleText_loc7`='Siempre hablas. ¡Nunca escuchas! ¡Ignoras las lecciones de Pandaria!' WHERE `ID`=75979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠나? 세상 모든 것엔 균형이 있네. 바로 우리 털가죽에서도 그 지혜를 찾아볼 수가 있지. 흑과 백. 암흑과 빛.', `MaleText_loc4`='万物自有平衡之道。这智慧铭刻在我们的皮毛上：黑与白。黑暗与光明。', `MaleText_loc5`='你要知道，一切都需要平衡。我們的毛皮上嵌著智慧:黑與白。黑暗與光明。', `MaleText_loc7`='Lo ves, en todas las cosas hay equilibrio. La sabiduría está grabada en nuestro pelaje: negro y blanco. Oscuridad y luz.' WHERE `ID`=75980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 황제께서 우리 땅을 세상에서 숨겼을 때, 그분은 우리의 오랜 적인 사마귀의 땅도 함께 숨겼지. 왜 그랬을까?', `MaleText_loc4`='当末代皇帝将我们的土地与外部世界隔离时，他也留下了我们的宿敌，螳螂妖。他为什么这么做？', `MaleText_loc5`='當末代皇帝把我們的大陸從世界上隱去，他同時也保留了我們古老的敵人，螳螂人。他為什麼這麼做呢?', `MaleText_loc7`='Cuando el último emperador ocultó nuestra tierra del resto del mundo también preservó la tierra natal de nuestro enemigo ancestral, los mántides. ¿Por qué lo hizo?' WHERE `ID`=75981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 호드도 마찬가질세. 서로의 존재에도 불구하고 강한 게 아니야. 서로의 존재 덕분에, 강한 거지.', `MaleText_loc4`='联盟和部落之间的战争也是一样。如果没有对方存在的话，他们也绝不会如此强盛。', `MaleText_loc5`='你們的聯盟與部落也是這樣。他們的強大不是各自形成的，他們的強大是因為彼此的存在。', `MaleText_loc7`='Así ocurre con su Alianza y su Horda. Uno no es fuerte a pesar del otro, sino fuerte GRACIAS al otro.' WHERE `ID`=75982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 지금 가장 큰 강점을 약점으로 착각하고 있는 걸세. 모르겠나?', `MaleText_loc4`='你把自己最大的优势当成了劣势。你明白吗？', `MaleText_loc5`='你把你們最大的優點當成弱點了。你能了解嗎?', `MaleText_loc7`='Confundes tu fortaleza más importante por debilidad. ¿Te das cuenta?' WHERE `ID`=75983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하아... 내 여관을 엉망으로 만들고, 팁도 안 주고... 참! 나쁜 녀석.', `MaleText_loc4`='……他毁了我的酒馆，还不给小费。真没风度。', `MaleText_loc5`='...他砸了我的客棧。還沒留小費。他很糟糕。', `MaleText_loc7`='Destruyó mi posada. No dejó propina. ¡Qué malo es!' WHERE `ID`=75984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 뭐라고?', `MaleText_loc4`='呃？', `MaleText_loc5`='呃...嗄?', `MaleText_loc7`='Oh, ¿eh?' WHERE `ID`=75985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 너... 네까짓 게 대체 뭐라고!', `MaleText_loc4`='……你……你不过是个倒酒的！', `MaleText_loc5`='...你 ...你只是個端盤子的!', `MaleText_loc7`='Tú... tú no eres más que... ¡un CANTINERO!' WHERE `ID`=75986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 똑똑히 들어라. 난 멈추지 않는다. 다가올 전쟁을 위해 이 세상을 준비시킬 거야.', `MaleText_loc4`='我发誓：我要不惜一切代价让这个世界做好战争的准备。', `MaleText_loc5`='我跟你保證:我不會讓任何事情阻止我替這個世界做好未來戰鬥的準備。', `MaleText_loc7`='Te prometo esto: nada me impedirá preparar a este mundo para la batalla que se avecina.' WHERE `ID`=75987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 다른 가능성을 절대로 남겨두지 않겠어.', `MaleText_loc4`='下一次，我绝不会再失手。', `MaleText_loc5`='下次，我不會留下變數。', `MaleText_loc7`='La próxima vez no dejaré nada al azar.' WHERE `ID`=75988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로!', `MaleText_loc4`='绝不！', `MaleText_loc5`='絕不會!', `MaleText_loc7`='¡Nada!' WHERE `ID`=75989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 온전히 지키려고 그리하신 걸세. 만 년 동안 사마귀와 우린 공존하며 둘 다 강해졌지.', `MaleText_loc4`='因为这才是一片完整的土地。一万年来，与螳螂妖的战争令双方都变得强大。', `MaleText_loc5`='他是為了保持大陸的完整。與螳螂人共處一萬年使得我們雙方都變得強大。', `MaleText_loc7`='Lo hizo para no dividir la tierra. Vivir con los mántides por diez mil años nos hizo FUERTES a ambos.' WHERE `ID`=75990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"피가 강을 이루어도, 산은 움직이지 않는다." - 니우짜오', `MaleText_loc4`='“哪怕血流漂杵，山岳岿然不动。”——砮皂', `MaleText_loc5`='「縱然血流成河，青山仍舊不改。」怒兆說。', `MaleText_loc7`='"Aunque la sangre inunde la tierra, la montaña permanecerá inamovible". - Niuzao', `FemaleText_loc1`='"피가 강을 이루어도, 산은 움직이지 않는다." - 니우짜오', `FemaleText_loc4`='“哪怕血流漂杵，山岳岿然不动。”——砮皂', `FemaleText_loc5`='「縱然血流成河，青山仍舊不改。」怒兆說。', `FemaleText_loc7`='"Aunque la sangre inunde la tierra, la montaña permanecerá inamovible". - Niuzao' WHERE `ID`=75992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"진실은 혼란스러운 시기에 가장 빛을 발하는 법이다." - 위론', `MaleText_loc4`='“真理之光总在混沌的时代闪耀。”——玉珑', `MaleText_loc5`='「在混沌難明的時刻，真理之光更加閃耀。」玉龍說。', `MaleText_loc7`='"Es en las épocas oscuras cuando la verdad brilla con más fuerza". - Yu''lon', `FemaleText_loc1`='"진실은 혼란스러운 시기에 가장 빛을 발하는 법이다." - 위론', `FemaleText_loc4`='“真理之光总在混沌的时代闪耀。”——玉珑', `FemaleText_loc5`='「在混沌難明的時刻，真理之光更加閃耀。」玉龍說。', `FemaleText_loc7`='"Es en las épocas oscuras cuando la verdad brilla con más fuerza". - Yu''lon' WHERE `ID`=75993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"희망의 불길은 모이면 모일수록 더욱 찬란히 빛난다." - 츠지', `MaleText_loc4`='“精诚团结，才能燃起希望之火。”——赤精', `MaleText_loc5`='「群焰聚集之時，希望之火將應運而生。」赤吉說。', `MaleText_loc7`='"El fuego de la esperanza se aviva cuando las llamas permanecen unidas". - Chi-Ji', `FemaleText_loc1`='"희망의 불길은 모이면 모일수록 더욱 찬란히 빛난다." - 츠지', `FemaleText_loc4`='“精诚团结，才能燃起希望之火。”——赤精', `FemaleText_loc5`='「群焰聚集之時，希望之火將應運而生。」赤吉說。', `FemaleText_loc7`='"El fuego de la esperanza se aviva cuando las llamas permanecen unidas". - Chi-Ji' WHERE `ID`=75994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"힘과 강력함은 해와 달만큼이나 다른 존재이다." - 쉬엔', `MaleText_loc4`='“力量与气力的差别，就如日月般一目了然。”——雪怒', `MaleText_loc5`='「匹夫之勇和王者之力，有雲泥之別。」雪怒說。', `MaleText_loc7`='"La fuerza y el poder son tan distintos como el sol y la luna". - Xuen', `FemaleText_loc1`='"힘과 강력함은 해와 달만큼이나 다른 존재이다." - 쉬엔', `FemaleText_loc4`='“力量与气力的差别，就如日月般一目了然。”——雪怒', `FemaleText_loc5`='「匹夫之勇和王者之力，有雲泥之別。」雪怒說。', `FemaleText_loc7`='"La fuerza y el poder son tan distintos como el sol y la luna". - Xuen' WHERE `ID`=75995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르도스가 제단을 더럽혔습니다!', `MaleText_loc4`='祭坛被斡耳朵斯腐蚀了！', `MaleText_loc5`='祭壇被歐朵斯摧毀了!', `MaleText_loc7`='¡Ordos ha corrompido el santuario!', `FemaleText_loc1`='오르도스가 제단을 더럽혔습니다!', `FemaleText_loc4`='祭坛被斡耳朵斯腐蚀了！', `FemaleText_loc5`='祭壇被歐朵斯摧毀了!', `FemaleText_loc7`='¡Ordos ha corrompido el santuario!' WHERE `ID`=75996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='줄을 서서 기다리는 손님을 클릭하세요. 손님을 잘 대접했다면 손님이 손을 흔들 거예요.', `FemaleText_loc4`='点击一名排队的客人。如果点击成功，他们就会向你招手。', `FemaleText_loc5`='點擊一個在排隊的客人。若你成功與他們互動，應該會看到他們對你揮手。', `FemaleText_loc7`='Haz clic en un cliente que esté en la cola. Deberían hacerte señas cuando has interactuado con ellos con éxito.' WHERE `ID`=75997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[줄 서서 기다리기]|h|r', `MaleText_loc4`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[排队等候]|h|r', `MaleText_loc5`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[排隊]|h|r', `MaleText_loc7`='|TInterfaceIconsability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[En la cola]|h|r', `FemaleText_loc1`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[줄 서서 기다리기]|h|r', `FemaleText_loc4`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[排队等候]|h|r', `FemaleText_loc5`='|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[排隊]|h|r', `FemaleText_loc7`='|TInterfaceIconsability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[En la cola]|h|r' WHERE `ID`=75998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님을 선택한 후에 빈 자리를 클릭하면 손님이 자리에 앉을 거예요.', `FemaleText_loc4`='选中一名客人后，点击一个空位，客人就会过去入座了。', `FemaleText_loc5`='當顧客被選擇後，點擊一個空的位子，顧客就會去那裡坐下。', `FemaleText_loc7`='Cuando hayas seleccionado a un cliente, haz clic en un asiento disponible y el cliente se sentará en él.' WHERE `ID`=75999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[음식 기다리는 중]|h|r', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[等待食物]|h|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[等候食物]|h|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[Esperando la comida]|h|r', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[음식 기다리는 중]|h|r', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[等待食物]|h|r', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[等候食物]|h|r', `FemaleText_loc7`='|TInterfaceIconsinv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[Esperando la comida]|h|r' WHERE `ID`=76000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 타락으로부터 물을 지켜야 한다!', `MaleText_loc4`='我们必须保卫池塘不受污染！', `MaleText_loc5`='我們必須保護這些水池不受腐化污染!', `MaleText_loc7`='¡Debemos impedir que contaminen los charcos!' WHERE `ID`=76002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일이 아직 끝나지 않았다! 놈들을 저지해라!', `MaleText_loc4`='我们的工作尚未结束！快阻止他们！', `MaleText_loc5`='我們的工作還沒完成!阻止他們!', `MaleText_loc7`='¡Nuestra obra no ha terminado! ¡Deténganlos!' WHERE `ID`=76003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 보호해라!', `MaleText_loc4`='保卫池塘！', `MaleText_loc5`='保護那些水池!', `MaleText_loc7`='¡Defiendan los charcos!' WHERE `ID`=76004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님에게 낼 국수를 만드세요. 이 손님은 학자라서 소박한 기본 국수를 좋아해요. 지금 한번 만들어보세요.', `FemaleText_loc4`='为你的客人煮汤面吧。这是一位学者，他们都喜欢简单清爽的汤面。试着做一碗吧。', `FemaleText_loc5`='為你的顧客煮碗湯麵。這是一位學者，他們喜歡簡單的普通湯麵。現在就試著煮一碗看看吧。', `FemaleText_loc7`='Prepara una sopa de fideos para tu cliente. Es un erudito, así que le gustará la simplicidad de una sopa de fideos sencilla. Prueba a cocinar una.' WHERE `ID`=76005;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='국수를 만든 다음에는 클릭해서 집어 드세요. 국수를 너무 오래 방치하면 상하니까, 손님에게 필요한 양만 만드세요.', `FemaleText_loc4`='汤面做好了，现在，点击拿起它吧。如果放置太久，汤面就会坏掉。所以，你一定要按照客人的需求来煮面。', `FemaleText_loc5`='現在湯麵煮好了，點擊它就能把它端起來。如果放太久，湯麵的味道會餿掉，所以只煮夠顧客吃的份量就好。', `FemaleText_loc7`='Una vez preparada la sopa, haz clic en ella para recogerla. La sopa se estropea si se queda demasiado tiempo fuera, así que cocina solo lo que necesiten tus clientes.' WHERE `ID`=76006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 자리에 앉은 손님을 클릭해서 국수를 배달하세요.', `FemaleText_loc4`='现在，点击入座的客人，把汤面给他们送过去吧。', `FemaleText_loc5`='現在點擊坐著的顧客把湯麵送去給他。', `FemaleText_loc7`='Ahora haz clic en el cliente sentado para entregarle su sopa de fideos.' WHERE `ID`=76007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요! 이제 손님이 국수를 흡족하게 먹을 거예요. 다 먹고 나면 기분 좋게 가게를 나가겠지요.', `FemaleText_loc4`='好极了！现在你的客人就会开心地品尝你为他们煮的面了。吃完之后，他们也会高高兴兴地离开。', `FemaleText_loc5`='很好!現在你的顧客會開心地吃你煮的湯麵。等他們吃飽，他們會開心地離開。', `FemaleText_loc7`='¡Excelente! Ahora tu cliente se comerá alegremente la sopa de fideos que le has preparado. Cuando termine, se marchará satisfecho.' WHERE `ID`=76008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지를 떠나는가?

위대한 천신회는 우리들에게 더는 섬 안쪽으로 영역을 넓히지 말라고 부탁했다네. 그래서 우리는 이 상륙지만 지키고 있지.

조심하게. 적 진영도 이곳에 흥미를 보이기 시작했다네. 놈들은 해변 반대쪽에 야영지를 세우고 그곳을 견고하게 지키고 있지.', `MaleText_loc4`='你要离开营地吗？

至尊天神已经要求我们岛上的部队停止推近了，所以我们就留在这里守卫登陆点。

你要出去的话一定要小心。敌人也对这里表现出了兴趣。他们的营地就在海滩的另一头，且守卫森严。', `MaleText_loc5`='你要離開營地嗎?

聖獸天尊已經要求過我們不要把武裝勢力擴張到島上，所以我們會待在這裡保護這個登陸點。

你在那裡要小心，敵人對這裡可是虎視眈眈。他們駐紮在海灘的另一端，還派了重兵把守。', `MaleText_loc7`='¿Vas a salir del campamento?

Los Augustos Celestiales nos han pedido que no despleguemos tropas en el interior de la isla, así que nos quedaremos aquí para asegurar el desembarco.

Ten cuidado ahí fuera. El enemigo también se interesa por este lugar. Han montado un campamento en el otro extremo de la playa, y está bien vigilado.' WHERE `ID`=76009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염을 위해 내 목숨을 바치리라!', `MaleText_loc4`='我的生命属于烈火！', `MaleText_loc5`='我為火焰而活!', `MaleText_loc7`='¡Mi vida por la llama!' WHERE `ID`=76010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르도스 님께서 날 이끄신다!', `MaleText_loc4`='斡耳朵斯指引我的道路！', `MaleText_loc5`='歐朵斯指引我的道路!', `MaleText_loc7`='¡Que Ordos me guíe!' WHERE `ID`=76011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염이야말로 진실이다!', `MaleText_loc4`='烈火即真理！', `MaleText_loc5`='火焰就是真理!', `MaleText_loc7`='¡Las llamas son la verdad!' WHERE `ID`=76012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염으로 점쳐진 나의 운명을 따르겠다!', `MaleText_loc4`='我的命运将由烈火来书写！', `MaleText_loc5`='我的命運與火焰同在!', `MaleText_loc7`='¡Mi destino está escrito en las brasas!' WHERE `ID`=76013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 고통 속에서 소멸할 것이다!', `MaleText_loc4`='你将在痛苦中死去！', `MaleText_loc5`='你會在極度痛苦中死去!', `MaleText_loc7`='¡Morirás de dolor!' WHERE `ID`=76014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르도스 님을 위해!', `MaleText_loc4`='为了斡耳朵斯！', `MaleText_loc5`='為了歐朵斯!', `MaleText_loc7`='¡Por Ordos!' WHERE `ID`=76015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 화염의 신을 따른다!', `MaleText_loc4`='誓死效忠火焰之神！', `MaleText_loc5`='我侍奉火焰之神!', `MaleText_loc7`='¡Sirvo a los dioses del fuego!' WHERE `ID`=76016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 불타는 화염을 위하여!', `MaleText_loc4`='为了永恒不灭的烈火！', `MaleText_loc5`='為了永恆不滅的火焰!', `MaleText_loc7`='¡Por la llama eterna!' WHERE `ID`=76017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛으로 심판받을지어다!', `MaleText_loc4`='接受光明的审判吧！', `MaleText_loc5`='站在光明中接受審判!', `MaleText_loc7`='¡Colóquense bajo la luz y sean juzgados!' WHERE `ID`=76022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루크... 너 누군지 알아...', `MaleText_loc4`='你……鲁克认识你……', `MaleText_loc5`='你...茹克認識你...', `MaleText_loc7`='Tú... Rook sabe quién eres...' WHERE `ID`=76023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루크... 잘 모른다... 머리가... 컴컴해...', `MaleText_loc4`='鲁克……不知道……头……好晕……', `MaleText_loc5`='茹克...不知道...頭...好暈...', `MaleText_loc7`='Rook... no sabe... Cabeza... Confundida...' WHERE `ID`=76024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 절망만 보여요. 저희에게 잘 어울리는 벌이죠.', `FemaleText_loc4`='我们满心绝望。这是失败者应得的惩罚。', `FemaleText_loc5`='我們只剩下絕望了。這是失敗的最好懲罰。', `FemaleText_loc7`='Ahora solo conocemos la desesperación. Un castigo justo para nuestro fracaso.' WHERE `ID`=76025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 도와줘...', `MaleText_loc4`='请……帮帮我们……', `MaleText_loc5`='請...幫我...', `MaleText_loc7`='Por favor... Ayuda...' WHERE `ID`=76026;
