UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 애완동물을 치료하고 되살렸구나! 천신의 시합에서 $n의 진행 상황이 초기화되었다. $n|1은;는; 처음부터 다시 다시 도전할 수 있다.', `MaleText_loc4`='看来$n已经决定要治疗并复活他的宠物了！$g他:她;在比武大会中的进度已被重置，需要重新进行挑战。', `MaleText_loc5`='看來$n決定要替寵物治療及復活!$g他:她;在聯賽中的進度已經重置，並能夠重新進行每一個挑戰。', `MaleText_loc7`='¡Parece que $n ha decidido sanar y revivir a sus mascotas! Se ha reiniciado su progreso en el torneo. Ahora tendrá que superar todos los desafíos desde el principio.' WHERE `ID`=76036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='손님을 너무 많이 놓쳤군요. 다시 해 보시겠어요?', `FemaleText_loc4`='离开的顾客太多了。你要再试一次吗？', `FemaleText_loc5`='你讓太多顧客跑掉了。也許你想再重新試試看?', `FemaleText_loc7`='Has dejado que se vayan demasiados clientes. Siempre puedes intentarlo de nuevo.' WHERE `ID`=76049;
