UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈라크라스가 맞았습니다!', `MaleText_loc4`='迦拉卡斯被击中了！打得好！', `MaleText_loc5`='葛拉卡斯被擊中了!幹得好!', `MaleText_loc7`='¡Has golpeado a Galakras! ¡Buen tiro!', `FemaleText_loc1`='갈라크라스가 맞았습니다!', `FemaleText_loc4`='迦拉卡斯被击中了！打得好！', `FemaleText_loc5`='葛拉卡斯被擊中了!幹得好!', `FemaleText_loc7`='¡Has golpeado a Galakras! ¡Buen tiro!' WHERE `ID`=76070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국수 가게에서 장사를 할 준비가 됐습니다!', `MaleText_loc4`='我做好去面档上工的准备了！', `MaleText_loc5`='我準備好在拉麵攤值下一個班了!', `MaleText_loc7`='¡Estoy listo para el siguiente turno en el carrito de fideos!', `FemaleText_loc1`='국수 가게에서 장사를 할 준비가 됐습니다!', `FemaleText_loc4`='我做好去面档上工的准备了！', `FemaleText_loc5`='我準備好在拉麵攤值下一個班了!', `FemaleText_loc7`='¡Estoy lista para el siguiente turno en el carrito de fideos!' WHERE `ID`=76071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 데즈코와 그의 선택을 지지합니다. 우리는 모구, 사우록, 샤, 그리고 호드의 대족장과 맞서 싸울 것이며, 필요하다면 이 골짜기 또한 지킬 것입니다.', `FemaleText_loc4`='我们支持德兹科和他的决定。我们要奋起反抗魔古族、蜥蜴人、煞魔甚至是部落酋长。如有必要，我们愿意保护这座山谷直至最后一人。', `FemaleText_loc5`='我們支持戴斯可和他的選擇。我們會與魔古、薩烏洛克、煞，甚至部落的大酋長戰鬥。必要的話，我們會為了這座山谷而戰到最後一兵一卒。', `FemaleText_loc7`='Apoyamos las decisiones que ha tomado Dezco. Lucharemos contra los mogu, los saurok, los sha, y hasta el Jefe de Guerra de la Horda. Protegeremos este valle con nuestras vidas, si es necesario.' WHERE `ID`=76072;
