UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬은 뭐죠?', `MaleText_loc4`='这是什么地方？', `MaleText_loc5`='這是什麼地方啊?', `MaleText_loc7`='¿Qué es este lugar?' WHERE `ID`=76077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 시간이 흘렀는데, 태양이 안 움직여요...', `MaleText_loc4`='都几个小时了，太阳却一直没动过……', `MaleText_loc5`='我在這裡幾個小時了，太陽完全沒有移動...', `MaleText_loc7`='Hace horas que estoy aquí y el sol no se ha movido...' WHERE `ID`=76078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수 있죠?', `MaleText_loc4`='这是什么造成的？', `MaleText_loc5`='誰能創造這樣的狀態?', `MaleText_loc7`='¿Qué podría crear una tal cosa?' WHERE `ID`=76079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험한가요?', `MaleText_loc4`='这里危险吗？', `MaleText_loc5`='會很危險嗎?', `MaleText_loc7`='¿Es peligroso?' WHERE `ID`=76080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴게요.', `MaleText_loc4`='我会的。', `MaleText_loc5`='我會的。', `MaleText_loc7`='Sí.' WHERE `ID`=76081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌의 수수께끼죠, 어린 왕자님! 안개 속의 신비입니다.', `MaleText_loc4`='这是熊猫人的秘密，我的小王子！迷雾中的秘密。', `MaleText_loc5`='熊貓人的謎團，年輕的王子!在迷霧中的謎團。', `MaleText_loc7`='¡Un enigma Pandaren, mi joven príncipe! Un misterio en la niebla.' WHERE `ID`=76082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 시간이 영원히 얼어붙었죠. 원인과 결과 따위 여기선 무의미합니다.', `MaleText_loc4`='没错。时间在此凝固。万物难逃因果，因果本是虚无。', `MaleText_loc5`='沒錯。時間永恆地停住了。因果關係 - 在這裡毫無意義。', `MaleText_loc7`='Exacto. El tiempo está detenido perpetuamente. Causa y efecto no son más que insignificantes.' WHERE `ID`=76083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 알고 싶습니다! 안개와 관련된 걸까요? 만 년 전 세계의 분리를 초래한 그 힘과 관련이 있을까요? 조사해 봐야 합니다!', `MaleText_loc4`='我会找到这个答案！究竟是因为迷雾？还是一万年前的大分裂所释放出的能量？我们必须好好调查！', `MaleText_loc5`='我也想知道!也許跟迷霧有關?或者是一萬年前導致大爆炸的那股力量?哦，我們必須查清楚!', `MaleText_loc7`='¡Es lo que me gustaría saber! ¿Tal vez esté relacionado con la Niebla? ¿O el poder que fue desatado en el Cataclismo hace diez mil años? Oh, ¡tenemos que investigar!' WHERE `ID`=76084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이죠. 이 장소는 시간과 우주에 대한 우리의 관념을 완전히 뒤집는 곳입니다.', `MaleText_loc4`='是的。此地推翻了我们对时间的认识，以及宇宙形成的理论。', `MaleText_loc5`='當然。這個地方顛覆了我們對時間的認知，以及它對宇宙的影響。', `MaleText_loc7`='Claro. Este lugar anula nuestra noción misma del tiempo y cómo este le da forma al universo.' WHERE `ID`=76085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에 발을 들이면 판다리아 전체에서 가장 위험한 생명체들을 만나게 됩니다. 정 원한다면 탐험해 보십시오. 하지만 조심하세요.', `MaleText_loc4`='这里有着全潘达利亚最危险的生物。如果你坚持，安度因王子，你可以去探索一番。但请务必小心。', `MaleText_loc5`='困在這座島上會遭遇到整個潘達利亞最危險的生物。想探索就去吧，安杜因王子。但是要小心。', `MaleText_loc7`='Varadas en esta isla encontrarás a las criaturas más peligrosas de toda Pandaria. Explórala si es lo que debes hacer, Anduin. Pero ten cuidado.' WHERE `ID`=76086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님. 영원의 섬의 비밀을 알아내기 위해 오셨습니까?', `MaleText_loc4`='你好，$c。你发现永恒岛的秘密了吗？', `MaleText_loc5`='你好，$c。你是來探究永恆之島的秘密的嗎?', `MaleText_loc7`='Hola, $c. ¿Has venido a descubrir los secretos de la Isla Intemporal?' WHERE `ID`=76087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 곳이 있다니 믿기세요? 배우고 탐험할 게 너무나도 많아요! 이곳에서 찾은 것들로 책을 써야겠어요.$b$b하지만 너무나도 양이 많네요. 사람들이 다 읽을 수 있을까요? 차드릭은 아예 노래로 만들어버리자고 했지만... 그건 좀 그렇죠?', `FemaleText_loc4`='你能相信吗？世上居然有这种地方的存在！这里有太多需要学习和发现的东西了！在这里的发现绝对能让我著作等身。$b$b但它们的信息量太大了，我不知道有谁能读完它们。查德里克觉得我们该把它们写成歌谣，但这太蠢了……对吧？', `FemaleText_loc5`='你能相信這種地方竟然真的存在嗎?有太多東西可以學習及探索!我能根據我所探索的一切寫出一本又一本的書。$b$b但是訊息太多了，我不知道有誰能把它全部讀完。查德里克認為我們可以寫成歌，但那有點傻...對吧?', `FemaleText_loc7`='¿Te lo puedes creer? Hay tanto por aprender y descubrir... Voy a llenar libro tras libro con mis hallazgos en esta isla.$b$bPero es mucha información... No creo que nadie sea capaz de leérsela entera. Chadrik dice que podríamos componer una canción, pero es una idea absurda... ¿o no?' WHERE `ID`=76088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 여정은 여기서 끝이다, 겁쟁이들아! 내가 살아 있는 한, 이 문은 절대 열리지 않는다!', `MaleText_loc4`='你们的路到此为止了，懦夫！只要我还活着，你们休想打开这些门！', `MaleText_loc5`='你的旅途到此結束，懦夫!只要我有一口氣在，你就別想跨越雷池一步!', `MaleText_loc7`='¡Su recorrido acaba aquí, cobardes! Estas puertas no se abrirán mientras yo siga con vida.' WHERE `ID`=76089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "태양노래 농장에 몇 달 동안 못 가봤어요. 잡초와 토깽으로 뒤덮인 모습을 상상할 뿐이죠."', `MaleText_loc4`='[%s]忏悔：我已经好几个月没去过日歌农场了。我都能想象出那里杂草丛生，兔妖遍地的样子了。', `MaleText_loc5`='[%s]坦承:我好幾個月沒去日歌農莊了，我可以想像那裡滿地都是雜草和兔妖。', `MaleText_loc7`='[%s] confiesa: Hace meses que no voy al Rancho Cantosol. Me imagino hierbajos y mures por todas partes.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "태양노래 농장에 몇 달 동안 못 가봤어요. 잡초와 토깽으로 뒤덮인 모습을 상상할 뿐이죠."', `FemaleText_loc4`='[%s]忏悔：我已经好几个月没去过日歌农场了。我都能想象出那里杂草丛生，兔妖遍地的样子了。', `FemaleText_loc5`='[%s]坦承:我好幾個月沒去日歌農莊了，我可以想像那裡滿地都是雜草和兔妖。', `FemaleText_loc7`='[%s] confiesa: Hace meses que no voy al Rancho Cantosol. Me imagino hierbajos y mures por todas partes.' WHERE `ID`=76092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "한 번은 레이 스 대신 레이 션을 처치할 뻔 한 것 같아요."', `MaleText_loc4`='[%s]忏悔：我曾经试图杀死雷施，而非雷神。', `MaleText_loc5`='[%s]坦承: 我想，有一次我想殺的是蕾希，而不是雷神。', `MaleText_loc7`='[%s] confiesa: Creo que una vez intenté matar a Lei Shi en lugar de a Lei Shen.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "한 번은 레이 스 대신 레이 션을 처치할 뻔 한 것 같아요."', `FemaleText_loc4`='[%s]忏悔：我曾经试图杀死雷施，而非雷神。', `FemaleText_loc5`='[%s]坦承: 我想，有一次我想殺的是蕾希，而不是雷神。', `FemaleText_loc7`='[%s] confiesa: Creo que una vez intenté matar a Lei Shi en lugar de a Lei Shen.' WHERE `ID`=76093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "한동안 전 깃털 때문에 메디브가 드루이드인 줄 알았어요."', `MaleText_loc4`='[%s]忏悔：我曾经以为麦迪文是德鲁伊，因为他身上插满了羽毛。', `MaleText_loc5`='[%s]坦承:我一直以為麥迪文是德魯伊，因為他那些羽毛。', `MaleText_loc7`='[%s] confiesa: Antes creía que Medivh era un druida, por las plumas.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "한동안 전 깃털 때문에 메디브가 드루이드인 줄 알았어요."', `FemaleText_loc4`='[%s]忏悔：我曾经以为麦迪文是德鲁伊，因为他身上插满了羽毛。', `FemaleText_loc5`='[%s]坦承:我一直以為麥迪文是德魯伊，因為他那些羽毛。', `FemaleText_loc7`='[%s] confiesa: Antes creía que Medivh era un druida, por las plumas.' WHERE `ID`=76094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 아직도 은빛십자군 스컬지석을 갖고 다녀요. 언제 또 유용해질 지 모르니까요."', `MaleText_loc4`='[%s]忏悔：我到现在还留着银色北伐军的天灾石。天知道它们什么时候又能派上用场。', `MaleText_loc5`='[%s]坦承:我還隨身帶著銀白十字軍的天譴石，你說不準那天它們還能派上用場。', `MaleText_loc7`='[%s] confiesa: Todavía guardo las piedras de la Plaga de la Cruzada Argenta. ¿Quién sabe? A lo mejor un día nos vuelven a hacer falta.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 아직도 은빛십자군 스컬지석을 갖고 다녀요. 언제 또 유용해질 지 모르니까요."', `FemaleText_loc4`='[%s]忏悔：我到现在还留着银色北伐军的天灾石。天知道它们什么时候又能派上用场。', `FemaleText_loc5`='[%s]坦承:我還隨身帶著銀白十字軍的天譴石，你說不準那天它們還能派上用場。', `FemaleText_loc7`='[%s] confiesa: Todavía guardo las piedras de la Plaga de la Cruzada Argenta. ¿Quién sabe? A lo mejor un día nos vuelven a hacer falta.' WHERE `ID`=76095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 제 지상 탈것들한테 미안해 죽겠어요. 이제 거의 탈 일이 없으니까요."', `MaleText_loc4`='[%s]忏悔：我为我的地面坐骑感到难过。我几乎不怎么用它们了。', `MaleText_loc5`='[%s]坦承:我為我的陸行坐騎感到難過，我都沒在騎了。', `MaleText_loc7`='[%s] confiesa: Me dan pena las monturas terrestres. Ya casi no las uso.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 제 지상 탈것들한테 미안해 죽겠어요. 이제 거의 탈 일이 없으니까요."', `FemaleText_loc4`='[%s]忏悔：我为我的地面坐骑感到难过。我几乎不怎么用它们了。', `FemaleText_loc5`='[%s]坦承:我為我的陸行坐騎感到難過，我都沒在騎了。', `FemaleText_loc7`='[%s] confiesa: Me dan pena las monturas terrestres. Ya casi no las uso.' WHERE `ID`=76096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저 돼지 같은 냥꾼의 템을 닌자해주겠어요."', `MaleText_loc4`='[%s]忏悔：我要抢光那个猎人的装备。', `MaleText_loc5`='[%s]坦承:我真的很想偷那個獵人的賞金。', `MaleText_loc7`='[%s] confiesa: Pienso darle necesidad al equipo de ese cazador.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저 돼지 같은 냥꾼의 템을 닌자해주겠어요."', `FemaleText_loc4`='[%s]忏悔：我要抢光那个猎人的装备。', `FemaleText_loc5`='[%s]坦承:我真的很想偷那個獵人的賞金。', `FemaleText_loc7`='[%s] confiesa: Pienso darle necesidad al equipo de ese cazador.' WHERE `ID`=76097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "여자 드레나이가 노움을 왜 좋아하는 지 정말 궁금해요."', `MaleText_loc4`='[%s]忏悔：我很疑惑，为什么女性德莱尼长得像侏儒。', `MaleText_loc5`='[%s]坦承:我很困惑，為什麼女德萊尼那麼像地精。', `MaleText_loc7`='[%s] confiesa: No entiendo por qué a las draenei les gustan los gnomos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 여자 드레나이가 노움을 왜 좋아하는 지 정말 아리송해요."', `FemaleText_loc4`='[%s]忏悔：我很疑惑，为什么女性德莱尼长得像侏儒。', `FemaleText_loc5`='[%s]坦承:我很困惑，為什麼女德萊尼那麼像地精。', `FemaleText_loc7`='[%s] confiesa: No entiendo por qué a las draenei les gustan los gnomos.' WHERE `ID`=76098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<래시온은 홀로 앉아, 게임에 사용되는 말을 손가락 사이에서 빙글빙글 돌리고 있습니다. 눈은 놀이판에 못 박혀 있지만, 당신은 왠지 그의 마음이 다른 곳에 가 있다는 인상을 받습니다.>', `MaleText_loc4`='<拉希奥独坐一隅，转动着手上的棋子。他专注地凝视着棋盘，但你觉得他的心思已经飞到其他地方去了。>', `MaleText_loc5`='<怒西昂獨坐著，手裡把玩著一個小東西。他目不轉睛地盯著面前的遊戲板，但你卻能感覺到他的心思不在這裡。>', `MaleText_loc7`='<Wrathion está solo, girando una pieza del juego con los dedos. Observa fijamente el tablero, pero te da la impresión de que su mente está en otra parte.>' WHERE `ID`=76114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼 옛날, 쟁쟁한 모험가들과 황제들은 이곳에서 위대한 천신들이 낸 시험을 치렀다네.

우리 선조들이 오랜 시간 전에 그랬던 것처럼, 우리 또한 자네들이 시험에 임하는 모습을 지켜볼 걸세.

하지만 기억하게. 천신의 경비병들은 이 성역에서 양 진영이 싸우는 것을 엄격히 금하고 있네.', `MaleText_loc4`='在很久很久以前，志向高远的英雄和帝王们会来这里面对至尊天神的考验。

如今，我们也像我们的祖先一样，守卫着这些被时光侵蚀的道路。

天神卫士绝不容许在这片圣地上发生阵营冲突。', `MaleText_loc5`='在許多年以前，熱血的英雄及皇帝來到這裡面對聖獸天尊的考驗。

如同我們祖先會遵守那些歷史悠久規矩一樣，我們也將如此。

聖獸守衛將不會容許這個神聖地方出現陣營之間的衝突。', `MaleText_loc7`='En épocas pasadas, los aspirantes a héroes y los emperadores venían a esta isla para someterse a las pruebas de los Augustos Celestiales.

Nuestros antepasados vigilaban el transcurso de estos rituales ancestrales, y nosotros haremos lo mismo.

La Guardia celestial no tolerará rencillas entre facciones en este lugar sagrado.' WHERE `ID`=76115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 화나신 모습은 처음 본 것 같군.$b$b진정하실 때까진 찾아 나서지 않는 게 좋을 것 같네.', `MaleText_loc4`='我从没见老板这么焦躁过。$b$b你最好等王子殿下冷静下来之后再去找他。', `MaleText_loc5`='我想我從沒看過陛下這麼沮喪的樣子。$b$b在王子冷靜一點之前，你最好不要去找他。', `MaleText_loc7`='Nunca había visto al jefe tan alterado.$b$bSerá mejor que no lo molestes hasta que se tranquilice un poco.' WHERE `ID`=76116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양에서 눈을 떼기가 힘들군. 도통 움직이질 않으니 자꾸 눈이 간단 말이야.$b$b도대체 이 섬은 뭐지?', `MaleText_loc4`='我已经尽力不去看太阳了。它是不会移动的。$b$b这到底是什么地方？', `MaleText_loc5`='我只能這樣做才不會一直盯著太陽看。它從未移動過。$b$b這是什麼地方啊?', `MaleText_loc7`='No puedo dejar de mirar al sol. No se mueve.$b$b¿Qué clase de sitio es este?' WHERE `ID`=76117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 낚시가 하고 싶군!', `MaleText_loc4`='好想钓鱼啊！', `MaleText_loc5`='我很想去釣魚!', `MaleText_loc7`='¡Tengo ganas de pescar!' WHERE `ID`=76118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 바꿀 준비가 됐나, $n?', `MaleText_loc4`='你做好改变世界的准备了吗，$n？', `MaleText_loc5`='準備好要改變世界了嗎，$n?', `MaleText_loc7`='¿Estás $glisto:lista; para cambiar el mundo, $n?' WHERE `ID`=76153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해야 할 일은 알고 있겠지, 용사여.', `MaleText_loc4`='你知道该怎么做，勇士。', `MaleText_loc5`='你知道該怎麼做，勇士。', `MaleText_loc7`='Ya sabes lo que hay que hacer.' WHERE `ID`=76154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 끝내면 장막의 계단에서 만나자... 모든 일이 끝난 후에도 네가 살아 있다면 말이지.', `MaleText_loc4`='等事情了结之后，就来雾纱栈道找我——如果你那时还活着的话。', `MaleText_loc5`='等你完成後，在朦朧天梯與我碰面-假設你還活著的話。', `MaleText_loc7`='Búscame en la Escalera Velada cuando esté terminada la tarea... si es que sigues con vida.' WHERE `ID`=76155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아!', `MaleText_loc4`='啊啊啊！！', `MaleText_loc5`='呃啊啊啊啊啊!', `MaleText_loc7`='¡Rrrrraaaaaaghhhh!' WHERE `ID`=76156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없는... 나의 고통...', `MaleText_loc4`='我的痛苦……永无止尽……', `MaleText_loc5`='我的痛苦...無窮無盡...', `MaleText_loc7`='Mi dolor... es interminable...' WHERE `ID`=76157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼지지 않는 불길...', `MaleText_loc4`='永不……熄灭的烈焰……', `MaleText_loc5`='火焰...永不息止...', `MaleText_loc7`='Las llamas... nunca cesan...' WHERE `ID`=76158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 영원히 불탄다...', `MaleText_loc4`='日夜……煎熬……', `MaleText_loc5`='我永恆...燃燒...', `MaleText_loc7`='Ardo... para siempre...' WHERE `ID`=76159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 화로에서 내 자리를 대신해라.', `MaleText_loc4`='你将代替我永远在这洪炉中煎熬。', `MaleText_loc5`='你將代替我永恆地燃燒!', `MaleText_loc7`='Ocuparán mi lugar en el brasero eterno.' WHERE `ID`=76160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹아내려라.', `MaleText_loc4`='你的血肉将会融化。', `MaleText_loc5`='你的肉體會融化。', `MaleText_loc7`='Su carne se derretirá.' WHERE `ID`=76161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없는 고통을 느껴라.', `MaleText_loc4`='你的痛苦永无止尽。', `MaleText_loc5`='你的痛苦無窮無盡。', `MaleText_loc7`='Su dolor será infinito.' WHERE `ID`=76162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 고통의 일부일 뿐이다.', `MaleText_loc4`='这点痛苦比不上我的万分之一。', `MaleText_loc5`='你感到的痛苦不到我的萬分之一。', `MaleText_loc7`='Sentirán apenas una fracción de mi agonía.' WHERE `ID`=76163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라!', `MaleText_loc4`='燃烧吧！', `MaleText_loc5`='燒吧。', `MaleText_loc7`='¡Ardan!' WHERE `ID`=76164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라.', `MaleText_loc4`='灰飞烟灭吧。', `MaleText_loc5`='灰飛煙滅。', `MaleText_loc7`='Conviértanse en humo.' WHERE `ID`=76165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 불은 절대로 꺼지지 않는다.', `MaleText_loc4`='永恒的烈焰不会熄灭。', `MaleText_loc5`='永恆之火將永不熄滅。', `MaleText_loc7`='El fuego eterno nunca se extinguirá.' WHERE `ID`=76166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손은 떨지 말고...', `MaleText_loc4`='手不要抖……', `MaleText_loc5`='手要穩...', `MaleText_loc7`='Que no me tiemble el pulso...' WHERE `ID`=76167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹색 줄무늬의 파란 선? 노란 줄무늬의 까만 선? 기억이 나지 않아.', `MaleText_loc4`='到底是绿条纹的蓝线还是黄条纹的黑线？我总是记不住。', `MaleText_loc5`='綠條紋的藍線，還是黃條紋的黑線?我根本就記不得了。', `MaleText_loc7`='¿Era el cable azul con rayas verdes, o el cable negro con rayas amarillas? Siempre me confundo.' WHERE `ID`=76168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러요!', `FemaleText_loc4`='快呀！', `FemaleText_loc5`='趕快!', `FemaleText_loc7`='¡Rápido!' WHERE `ID`=76169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨간 선 말고 파란 선!', `FemaleText_loc4`='不是红色的线，是蓝色的！', `FemaleText_loc5`='不是紅線，是藍線!', `FemaleText_loc7`='El cable rojo no, ¡el azul!' WHERE `ID`=76170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기다려요!', `FemaleText_loc4`='等等我！', `FemaleText_loc5`='等等我!', `FemaleText_loc7`='¡Voy!' WHERE `ID`=76171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 다시 살아났다!', `MaleText_loc4`='我又复活啦！', `MaleText_loc5`='我又活過來了!', `MaleText_loc7`='¡Vuelvo a la vida!' WHERE `ID`=76173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하하!', `MaleText_loc4`='哈哈哈哈哈！', `MaleText_loc5`='哈哈哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja!' WHERE `ID`=76174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽바다는 영원히 나의 것이다!', `MaleText_loc4`='南海是我永远的狩猎场！', `MaleText_loc5`='南海永生永世都將任我魚肉!', `MaleText_loc7`='¡Los Mares del Sur son míos! ¡Los saquearé eternamente!' WHERE `ID`=76175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 바주비어스호여. 심해에서 떠올라라!', `MaleText_loc4`='来啊，瓦祖维斯号，从深海归来吧！', `MaleText_loc5`='來吧，維蘇威號，從深海之中升起吧!', `MaleText_loc7`='¡Adelante, Vazuvius! ¡Álzate desde las profundidades!' WHERE `ID`=76176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_gouge:20|t%s|1이;가; |cFFFF0000|Hspell:143330|h[후려치기]|h|r를 시도합니다. 눈을 피하십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_gouge:20|t%s试图对你使用|cFFFF0000|Hspell:143330|h[凿击]|h|r，快转身！', `MaleText_loc5`='|TInterface\\Icons\\ability_gouge:20|t%s想對你施展|cFFFF0000|Hspell:143330|h[鑿擊]|h|r，快走!', `MaleText_loc7`='|TInterfaceIconsability_gouge:20|t%s intenta utilizar |cFFFF0000|Hspell:143330|h[Gubia]|h|r contra ti. ¡Date la vuelta!' WHERE `ID`=76177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휴! 재미있었다!', `FemaleText_loc4`='噢！真是段有趣的旅程！', `FemaleText_loc5`='啊，真是有趣的旅途啊!', `FemaleText_loc7`='¡Qué viaje tan divertido!' WHERE `ID`=76178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅들아, 고맙구나. 도시 밑 어딘가에 사악한 무언가가 있어.', `FemaleText_loc4`='英雄们，向你们致敬。这些地下大厅里有着某种非常邪恶的东西。', `FemaleText_loc5`='英雄們，我向你們致敬。這座城底下有某種相當糟糕的東西。', `FemaleText_loc7`='Saludos, héroes. Aquí en estas cámaras debajo de la ciudad hay algo maléfico.' WHERE `ID`=76179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저거 위험해 보이는군. 병사들이여! 우리의 뜨거운 맛을 보여줘라.', `FemaleText_loc4`='呼，它看起来很危险，冲上去，小伙子们，让他们看看我们的本事。', `FemaleText_loc5`='欸，那看起來很危險，進去吧，小伙子們!讓他們看看我們的本事。', `FemaleText_loc7`='Ay, parece peligroso, métanse ahí, chicos, y demuéstrenles de qué estamos hechos.' WHERE `ID`=76180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참 고약한 기계였군. 여기선 몸조심 하는 게 좋을 거야.', `FemaleText_loc4`='真是个暴躁的家伙。你们最好小心点，英雄们。', `FemaleText_loc5`='真是個惡劣的機械。你們在這裡最好步步為營，英雄們。', `FemaleText_loc7`='Es una máquina mortífera. Cuidado al bajar, héroes.' WHERE `ID`=76181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하... 자자, 아니 이건 또 뭐야?', `MaleText_loc4`='嘿，看看我们找到什么了？', `MaleText_loc5`='嘿，看我們找到啥啦?', `MaleText_loc7`='Ey. ¿Qué tenemos aquí?' WHERE `ID`=76182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 감히 이 그리즐 님의 돈을 떼먹으려 했다, 이거지?', `MaleText_loc4`='加尔鲁什还以为他能赖掉格里兹尔的帐，嗯？', `MaleText_loc5`='卡爾洛斯真以為他能賴掉老格里斯的帳嗎，嗯?!', `MaleText_loc7`='Así que Garrosh cree que puede engañar al viejo Grizzle y no pagarle, ¿eh?' WHERE `ID`=76183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 덮쳐! 저 흉물은 우리 진짜 고블린 기계에 비하면 별거 아냐!', `MaleText_loc4`='干掉它，在正版地精工程学面前，那玩意儿不堪一击！', `MaleText_loc5`='幹掉它，那玩意兒在真正的哥布林工程學前不值一提!', `MaleText_loc7`='Ataquen, muchachos, ¡esa cosa no es nada comparada con la ingeniería goblin!' WHERE `ID`=76184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별거였구만. 음, 난 다른 녀석들을 확인하러 가야겠어.', `MaleText_loc4`='看来还有点本事。我最好……呃……去看看其他人。', `MaleText_loc5`='看來還有點本事。我，呃，去看看其他人怎麼樣了。', `MaleText_loc7`='O tal vez sí. Será mejor que... emm... vaya a ver cómo están los demás.' WHERE `ID`=76185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 섬은 놀라우면서도 무섭군요.', `FemaleText_loc4`='这座岛真是既迷人又可怕。', `FemaleText_loc5`='這座島有多令人著迷，就有多令人恐懼。', `FemaleText_loc7`='Esta isla es fascinante y aterradora a partes iguales.' WHERE `ID`=76186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골록.', `MaleText_loc4`='鳄鱼人。', `MaleText_loc5`='戈洛克。', `MaleText_loc7`='Górlocs.', `FemaleText_loc1`='골록.', `FemaleText_loc4`='鳄鱼人。', `FemaleText_loc5`='戈洛克。', `FemaleText_loc7`='Górlocs.' WHERE `ID`=76187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<쿠마가 당신을 응시합니다.>', `MaleText_loc4`='<库玛瞪着你。>', `MaleText_loc5`='<庫瑪盯著你看。>', `MaleText_loc7`='<Ku''ma te observa.>' WHERE `ID`=76188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 대답해보세요, 영웅이여. 언데드인 멀록을 뭐라고 부르죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！告诉我，英雄，亡灵鱼人被称作什么？', `FemaleText_loc5`='我們來測驗一下歷史知識吧!告訴我，英雄，不死魚人叫什麼？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Dime, ¿cómo se llama a los múrlocs no-muertos?' WHERE `ID`=76189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀구울.', `MaleText_loc4`='行尸鱼人。', `MaleText_loc5`='屍化魚人。', `MaleText_loc7`='Mur''crófagos.', `FemaleText_loc1`='멀구울.', `FemaleText_loc4`='行尸鱼人。', `FemaleText_loc5`='屍化魚人。', `FemaleText_loc7`='Mur''crófagos.' WHERE `ID`=76190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울바르.', `MaleText_loc4`='狼獾人。', `MaleText_loc5`='獾狼怪。', `MaleText_loc7`='Wolvar.', `FemaleText_loc1`='울바르.', `FemaleText_loc4`='狼獾人。', `FemaleText_loc5`='獾狼怪。', `FemaleText_loc7`='Wolvar.' WHERE `ID`=76191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리치.', `MaleText_loc4`='巫妖鱼人。', `MaleText_loc5`='巫妖魚人。', `MaleText_loc7`='Mur''zombis.', `FemaleText_loc1`='멀리치.', `FemaleText_loc4`='巫妖鱼人。', `FemaleText_loc5`='巫妖魚人。', `FemaleText_loc7`='Mur''zombis.' WHERE `ID`=76192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='틀렸어요!', `FemaleText_loc4`='答错了！', `FemaleText_loc5`='不對!', `FemaleText_loc7`='¡Respuesta incorrecta!' WHERE `ID`=76193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞았어요!', `FemaleText_loc4`='答对了！', `FemaleText_loc5`='正確!', `FemaleText_loc7`='¡Has acertado!' WHERE `ID`=76194;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 하얀 늑대를 즐겨 타던 오크 부족의 이름이 뭐였죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！白狼曾是哪个兽人氏族最喜爱的坐骑？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!白狼曾經是哪個獸人氏族鍾愛的坐騎？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué clan orco utiliza lobos blancos como montura?' WHERE `ID`=76195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 드루이드에게 내려지는 가장 높은 호칭이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！德鲁伊的最高称号是什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!德魯伊被授予的最高階級是什麼？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cuál es el rango más alto que puede alcanzar un druida?' WHERE `ID`=76196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 지금 노움을 다스리고 있는 지도자가 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！侏儒如今的领袖是谁？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!現任的地精領袖是誰？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Quién es el líder actual de los gnomos?' WHERE `ID`=76197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 말퓨리온 스톰레이지의 도움으로 설립된 아제로스 최대의 드루이드 집단이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！由玛法里奥·怒风协助建立的，艾泽拉斯最主要的德鲁伊组织叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!由瑪法里恩·怒風協助創立的，最早的艾澤拉斯德魯伊組織是哪一個？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cuál es la organización druídica más importante de Azeroth, fundada por Malfurion Tempestira, entre otros?' WHERE `ID`=76198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 3차 대전쟁이 일어나고 몇 년이 지난 후 어둠의 문이 다시 열렸을 때, 갈색 피부의 오크들이 아제로스에 모습을 보였죠. 이 오크들이 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在第三次大战过去数年之后，黑暗之门重新开启时，艾泽拉斯首次出现了棕色皮肤的兽人。这些兽人被称为什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!棕色皮膚的獸人首度出現在艾澤拉斯，是第三次大戰的數年後，黑暗之門再度被開啟的時候。這些獸人叫什麼？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Los orcos de piel marrón aparecieron en Azeroth unos años después de la Tercera Guerra, cuando se reactivó el Portal Oscuro. ¿Cómo se llaman esos orcos?' WHERE `ID`=76199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아서스가 언데드로 되살려 스컬지의 종복이 되기 전, 신드라고사는 어느 용군단의 일원이었죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在被阿尔萨斯复活为亡灵，并加入天灾军团之前，辛达苟萨曾属于哪个巨龙军团？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在被阿薩斯復活以聽命於天譴軍團之前，辛德拉苟莎曾屬於哪個龍族軍團？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿A qué Vuelo pertenecía Sindragosa antes de que Arthas la resucitara de entre los muertos para servir a la Plaga?' WHERE `ID`=76200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아웃랜드의 귀중한 물을 독차지하기 위해 나가가 장가르 습지대에 만든 구조물이 뭐죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！赞加沼泽有一个地方，那里为纳迦所控制，他们还试图在那里抽取一种珍贵而稀有的资源：外域之水。这个地方叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!有一棟建築物，在贊格沼澤，被納迦所控制，想要抽取一種珍貴的資源:外域的水源。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué estructura de la Marisma de Zangar tomaron los naga para drenar el agua de Terrallende, su recurso más valioso y limitado?' WHERE `ID`=76201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 어둠의 문으로 아제로스와 연결되어 있던 세계의 원래 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！通过黑暗之门与艾泽拉斯相连的世界，它的本名叫什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!和艾澤拉斯以黑暗之門相連的世界原名是什麼？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llamaba originalmente el mundo que está conectado con Azeroth a través del Portal Oscuro?' WHERE `ID`=76202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 언데드를 강타하면 흔적도 넘기지 않고 파멸시킨다는 강력한 검의 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！下列哪一把剑能够将亡灵烧成灰烬？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!是哪一把強大的劍能以無比強大的力量擊殺不死生物，讓它們只留下灰燼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué poderosa espada era capaz de fulminar a los no-muertos con fuerza suficiente como para reducirlos a cenizas?' WHERE `ID`=76203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아제로스를 지키기 위해 특별한 힘을 부여받은 용군단의 수는 몇인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！为了保护艾泽拉斯世界，有几个巨龙军团被赋予了特殊的能力？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!有幾個龍族軍團因為保護艾澤拉斯的使命而被賜予特殊的力量？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cuántos vuelos de dragones recibieron poderes especiales para proteger Azeroth?' WHERE `ID`=76204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! "배신자"로 널리 알려진 나이트 엘프의 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！被称为“背叛者”的暗夜精灵是谁？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!哪個夜精靈是眾所周知的『背叛者』？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué elfo de la noche es conocido como "el Traidor"?' WHERE `ID`=76205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 대부분의 숲트롤은 2차 대전쟁 이후에 호드와 적대적인 관계가 되었죠. 그중 한 종족은 지금까지 호드와 우호적인 관계를 유지하고 있어요. 이 숲트롤들은 어느 부족이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在第二次大战之后，大部分森林巨魔都开始仇视部落。如今，哪一个森林巨魔部族依然对部落友善？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!多數的森林食人妖在第二次獸人戰爭後便對部落產生敵意。是哪一個部族時至今日還與部落保持友好關係?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Casi todos los trols del bosque se volvieron hostiles hacia la Horda tras la Segunda Guerra. ¿Qué tribu de trols del bosque mantiene lazos de amistad con la Horda hoy en día?' WHERE `ID`=76206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 태양샘 고원에서 푸른용 칼렉고스를 조종하여 모험가들을 곤경에 빠뜨린 악마가 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！是哪个恶魔强迫蓝龙卡雷苟斯在太阳之井高地去攻击一群冒险者的呢？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!是哪個惡魔迫使藍龍卡雷苟斯在太陽之井攻擊冒險者?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué demonio obligó al dragón Azul Kalecgos a luchar contra un grupo de aventureros en la Meseta de la Fuente del Sol?' WHERE `ID`=76207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 실바나스 윈드러너의 자매 중 한명은 키린 토와 전투적인 하이 엘프의 무리를 이끌고 있습니다. 이 집단의 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！希尔瓦娜斯·风行者有一位姐妹领导着一个高等精灵的武装阵营以及肯瑞托。这个组织叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!希瓦娜斯·風行者的姊妹之一是祈倫托及高等精靈軍事組織的領袖。這個組織叫什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Una de las hermanas de Sylvanas Brisaveloz dirige una facción militante de elfos nobles asociada con el Kirin Tor. ¿Cuál es el nombre del grupo?' WHERE `ID`=76208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 그롬 헬스크림이 전투에서 휘두른 유명한 도끼의 이름이 뭐죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！格罗姆·地狱咆哮在战斗中使用的著名战斧叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!葛羅·地獄吼在戰鬥中所使用的知名斧頭叫什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué famosa hacha blandía Grom Grito Infernal en combate?' WHERE `ID`=76209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 고대의 전쟁 이후 용의 위상들이 나이트 엘프에게 무엇을 선물했죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在上古之战后，守护巨龙们给了暗夜精灵什么东西？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!守護巨龍在先祖之戰過後給了夜精靈什麼東西?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué dieron los dragones Aspectos a los elfos de la noche tras la Guerra de los Ancestros?' WHERE `ID`=76210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 3차 대전쟁 때 아서스 왕자가 무엇 때문에 스트라솔름의 주민들을 학살했나요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在第三次大战期间，是什么证据促使阿尔萨斯王子屠杀了斯坦索姆的居民？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在第三次大戰中，阿薩斯王子得到了什麼證據，促使他屠殺斯坦索姆的人民?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué prueba convenció al príncipe Arthas para masacrar a los habitantes de Stratholme durante la Tercera Guerra?' WHERE `ID`=76211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아서스의 죽음의 기사들은 공중에 떠있는 요새에서 훈련을 받았죠. 그리고 리치 왕으로부터 독립을 한 후에 이곳을 탈환했습니다. 이 요새는 어디인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！阿尔萨斯用来训练死亡骑士，后来又由于大部分死亡骑士背叛巫妖王而被占领的浮空堡垒叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!阿薩斯的死亡騎士是在一個飄浮的堡壘訓練而成，該堡壘在他們對巫妖王的叛亂中被武力攻下。這個堡壘的名稱是什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Los caballeros de la Muerte de Arthas se entrenaban en una ciudadela flotante que fue tomada por la fuerza cuando un grupo de caballeros se rebeló contra el Rey Exánime. ¿Cómo se llama la fortaleza?' WHERE `ID`=76212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 영주 쿠르드란 와일드해머는 근래에 자신이 아끼는 그리폰을 화재로 잃었습니다. 이 그리폰의 이름이 무엇인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！大领主库德兰·蛮锤最近痛失爱将，他英勇的狮鹫在一次大火中不幸丧生。这头狮鹫叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!庫德蘭·蠻錘族長最近承受了悲劇性的損失，他英勇的獅鷲獸被火燒死了。這頭獅鷲獸的名字叫什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! El señor feudal Kurdran Martillo Salvaje sufrió una pérdida terrible hace poco, cuando su valiente grifo murió en un incendio. ¿Cómo se llamaba el grifo?' WHERE `ID`=76213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 대격변이 일어날 당시 이 여왕은 포세이큰이 공격해왔을 때 자신의 백성들을 대피시겠죠. 이 사람은 누군가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！有一位王后，在大灾变和被遗忘者袭击她的国度时，她井井有条地安排了人民的疏散工作。这位王后叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!這位女王在大災變發生，及被遺忘者攻擊她的王國後疏散了她的子民。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué reina supervisó la evacuación de su pueblo cuando se desató el Cataclismo y los Renegados invadieron su reino?' WHERE `ID`=76214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 으르렁니가 늑대인간이 되기 전에 그에게는 가족이 있었죠. 으르렁니의 아내의 이름이 무엇이었죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在撕心狼变成狼人之前，他也曾有过家室。他的妻子叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在利普斯納爾變成狼人之前，他原本也有自己的家庭。他的妻子叫什麼名字?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Rasgagruñido tenía familia antes de convertirse en huargen. ¿Cómo se llamaba su mujer?' WHERE `ID`=76215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아제로스에서 생겨난 첫 번째 죽음의 기사가 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！艾泽拉斯出现的第一个死亡骑士是谁？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!誰是艾澤拉斯第一位被創造的死亡騎士?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Quién fue el primer caballero de la Muerte de Azeroth?' WHERE `ID`=76216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 한때 건장한 성기사였던 이 드레나이는 불타는 군단과 싸우던 도중 건강이 악화되어 뒤틀린 드레나이가 되었습니다. 후에 그는 강력한 주술사가 되었지요. 이 드레나이는 누군가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！有一位德莱尼人，他曾是一个健康的圣骑士，但在与燃烧军团作战时，他身染恶疾，变成了破碎者。后来，他成了一个强大的萨满。这个德莱尼人是谁？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!原本是一位健康的聖騎士，這位德萊尼在與燃燒軍團作戰時生了病，並成為破碎者之一。他後來成為一位強大的薩滿。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Un draenei que antaño fue un robusto paladín cayó enfermo tras luchar contra la Legión Ardiente y se convirtió en un Perdido. Ahora es un poderoso chamán. ¿Cómo se llama?' WHERE `ID`=76217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 흑요석 성소에서 황혼의 비룡의 알들을 지키던 어린 황혼의 비룡 셋이 누구였죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在黑曜石圣殿守护暮光龙蛋的三头暮光幼龙分别叫什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!是哪三隻年輕的暮光飛龍在黑曜聖所守護著暮光飛龍的蛋?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llamaban los tres jóvenes dracos Crepusculares que protegían huevos de dragón Crepuscular en el Sagrario Obsidiana?' WHERE `ID`=76218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 티리온 폴드링이 타고 다니는 회색 말의 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！提里奥·弗丁的灰色公马叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!提里奧·弗丁的灰馬叫什麼名字?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llama el corcel gris de Tirion Vadín?' WHERE `ID`=76219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 고블린들이 만든 이 호드 함선은 원래 스랄과 아그라를 혼돈의 소용돌이로 보내기 위해 만든 것이었어요. 하지만 얼라이언스의 기습 공격으로 파괴되었죠. 이 함선의 이름은 무엇인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！由地精制造，原计划搭载萨尔和阿格娜前往大漩涡，却被联盟意外摧毁的部落舰船叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!這艘部落的船是由哥布林所製造。原本是要帶索爾及阿格拉前往大漩渦，但在聯盟的突襲之下被摧毀了。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Los goblins fabricaron un barco que debía llevar a Thrall y a Aggra a La Vorágine, pero la Alianza lo destruyó en un ataque sorpresa. ¿Cómo se llamaba el barco?' WHERE `ID`=76220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 고위 판테온의 일원으로 티탄의 역사를 기록하는 임무를 맡은 이 자는 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！隶属于万神殿精锐的泰坦知识守护者叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!哪一位萬神殿的成員是該組織的博識者?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llamaba el titán tradicionalista que era un miembro de élite del Panteón?' WHERE `ID`=76221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 한때 강력한 원시비룡이었지만 로켄에게 사로잡혀 칼날비늘이 되어버린 이 용의 이름은 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！被洛肯捕获并变成锋鳞的强大始祖龙叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!被洛肯捕捉並轉化為銳鱗的強大元龍叫什麼名字?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué poderoso protodraco fue capturado por Loken y transformado en Tajoescama?' WHERE `ID`=76222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 드레나이는 나루의 언어로 농담을 하는 걸 좋아하죠. 엑소다르가 그중 한 예인데요, 엑소다르가 무엇을 의미하죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！根据德莱尼人的玩笑，“埃索达”在纳鲁语中是什么意思？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!德萊尼喜歡開玩笑說，用那魯的語言來講，艾克索達有這個意思。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Según un chiste popular entre los draenei, ¿qué significa Exodar en el idioma de los naaru?' WHERE `ID`=76223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! "부디 그 피 묻은 왕관이 영원히 돌아오지 않고 잊혀지기를" 이 글귀가 새겨진 무덤은 누구의 것이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！下列哪一位的墓志铭上刻有“愿血染的王冠永远被遗失和忘却”这句话？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!是誰的墓地上有刻著這麼一段話:「願血染的王冠永遠被遺失和忘卻」?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿A quién pertenece la lápida que reza "Que la corona manchada de sangre permanezca en el olvido"?' WHERE `ID`=76224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 처음으로 창조된 사티로스는 누구인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！这个世界上的第一个萨特是谁？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!誰是第一個被創造出來的薩特?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Quién fue el primer sátiro?' WHERE `ID`=76225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 국왕 바리안 린의 첫 번째 아내는 누구였죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！瓦里安·乌瑞恩国王的第一任妻子的正确名字是什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!瓦里安·烏瑞恩國王的第一任妻子，正確的名字是哪個?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llamaba la mujer del rey Varian Wrynn?' WHERE `ID`=76226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 에테리얼의 고향은 어디인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！虚灵的家乡叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!以太族的家鄉在哪裡?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se llama el mundo natal de los etéreos?' WHERE `ID`=76227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 호드가 생기기 이전, 오크들 사이에서 급속도로 퍼져나간 전염병이 있었어요. 오크들은 이 병을 뭐라고 불렀죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在最初的部落建立之前，有一种高传染性的病毒在兽人间快速传播。兽人们称这种病为什么？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在原本的部落成立前，一種傳染性極高的疾病在獸人中快速流傳。獸人們稱呼它為什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Antes de que se formara la primera Horda, una enfermedad altamente contagiosa se propagó entre los orcos. ¿Cómo la llamaban?' WHERE `ID`=76228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 붉은십자군 소속이었던 이 수호자는 공포의 군주 벨테리스를 처치하는 도중에 전사했어요. 이 자가 누군가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！一位血色十字军保卫者在刺杀恐惧魔王贝塞利斯时遇害，她叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!這位血色十字軍在刺殺驚懼領主貝塞利斯時犧牲了。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué defensor de la Cruzada Escarlata murió tras matar al señor del terror Beltheris?' WHERE `ID`=76229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 아이언포지의 도서관에는 비정상적으로 거대한 산양의 두개골이 있죠. 이 전설적인 산양의 이름은 무엇인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！铁炉堡图书馆中展出了一具巨型山羊的骨架复制品。这头传奇山羊叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!鐵爐堡的圖書館有著一個巨大公羊的骷髏仿製品。這隻傳說中的公羊叫什麼?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! La biblioteca de Forjaz alberga una réplica del esqueleto de un carnero inusualmente grande. ¿Cómo se llamaba este carnero legendario?' WHERE `ID`=76230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 얼음왕관 전투에서 호드는 이 관문에서 스컬지와 싸우는 얼라이언스에게 기습 공격을 감행했습니다. 이 관문의 이름이 무엇이죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在突袭冰冠堡垒时，部落军队无耻地偷袭正与天灾军团激战的联盟士兵，并试图占领的那座城门叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在攻擊寒冰皇冠的戰役中，部落的軍隊罔顧榮耀攻擊了聯盟正在與天譴軍團作戰並嘗試攻下這座門的聯盟士兵。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Durante el asalto a Corona de Hielo, un grupo de la Horda atacó deshonrosamente a los soldados de la Alianza mientras luchaban contra la Plaga. ¿Cómo se llamaba la puerta que intentaban capturar?' WHERE `ID`=76231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! "감사합니다."를 용들의 언어인 용언으로 뭐라고 할까요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！下列哪句话是龙语中“谢谢你”的意思？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在龍的語言中，哪一句是「謝謝你」?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Cómo se dice "Gracias" en dracónico, el idioma de los dragones?' WHERE `ID`=76232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 학자인 시절에 스탈반 미스트맨틀은 제자였던 틸로아라는 젊은 여자에게 집착에 가까운 애정을 느꼈습니다. 여기서 틸로아는 누구의 누나였죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在担任家庭教师期间，斯塔文·密斯特曼托爱上了自己的学生，一个名叫蒂罗亚的年轻姑娘。请问她的弟弟叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!斯塔文·密斯特曼托在身為導師時，瘋狂愛上了他的一個學生，一個年輕的女人名叫蒂羅亞。她的弟弟叫什麼名字?', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Cuando trabajaba como tutor, Stalvan Mantoniebla se obsesionó con una de sus pupilas, una joven llamada Tilloa. ¿Cómo se llamaba el hermano menor de Tilloa?' WHERE `ID`=76233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 얼마 전에 이 나약한 잔달라 트롤은 공포뿔을 조련하기 위한 여행을 떠났습니다. 괴수의 섬에 도착한 그는 안타깝게도 도중에 죽었죠. 그의 이름은 무엇인가요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！不久之前，一个脆弱的赞达拉巨魔想要驯服一头恐角龙。虽然他登上了巨兽岛，却在任务过程中遇害。请问这个巨魔叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!不久以前，有個脆弱的贊達拉食人妖想要馴服一隻恐角龍。雖然他遠赴巨獸島，卻在旅途中喪生。他的名字是？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! No hace mucho, un débil trol Zandalari intentó domar un cuernoatroz. Aunque viajó a la Isla de los Gigantes, murió antes de cumplir su misión. ¿Cómo se llamaba?' WHERE `ID`=76234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 호드의 사절 중 하나였던 이 자는 실버문이 너무 밝고 깨끗하다고 불평했었죠. 이 자는 누구죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！嫌弃银月城过于明亮和干净的部落大使叫什么名字？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!覺得銀月城有點太過明亮乾淨的部落使者是哪位？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué emisario de la Horda opinó que la Ciudad de Lunargenta era demasiado limpia y luminosa?' WHERE `ID`=76235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 서큐버스들은 고통을 주는 것을 즐기고 그들의 끔찍한 고문 수법은 악몽과도 같다고 합니다. 서큐버스는 어떤 종에 속하죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！魅魔热衷于制造痛苦，她们在燃烧军团中专门负责进行可怕的拷问工作。请问魅魔属于哪个品种的恶魔？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!魅魔以製造苦痛為樂，並聽命於軍團，施行惡夢般的審訊。魅魔屬於哪個種族？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! Los súcubos disfrutan provocando angustia y sirven a la Legión llevando a cabo interrogatorios dignos de las peores pesadillas. ¿A qué especie pertenece el súcubo?' WHERE `ID`=76236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 이 로아의 이름은 "어두운 밤의 절친한 벗"을 뜻합니다. 이 로아는 누구일까요?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！头衔中包含“夜晚之友”的是哪位神灵？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!這個羅亞的其中一個名字是「夜晚之友」。', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué loa se conoce también como "amigo de la noche"?' WHERE `ID`=76237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 역사를 얼마나 잘 아는지 시험해볼게요! 타우렌어로 "라르코르위"는 무엇을 뜻하죠?', `FemaleText_loc4`='那就让我们来测试一下你的历史知识吧！在牛头人的语言中，lar''korwi是什么意思？', `FemaleText_loc5`='那就讓我們來測試你的歷史知識吧!在牛頭人語中，拉克維代表什麼意思？', `FemaleText_loc7`='¡Pongamos a prueba tus conocimientos de historia! ¿Qué significa "lar''kowi" en taurahe, el idioma de los tauren?' WHERE `ID`=76238;
