UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자님, 안녕하세요!$b$b오늘 밤 유랑객의 축제에 오실 건가요? 일몰 직후에 판다렌들이 바로 여기 거북 해안으로 모여들 거예요! 꽤 장관일 거라구요!$b$b축제가 시작될 무렵에 저한테 물어보시면 얼마나 기다려야 되는지 알려 드릴게요.', `MaleText_loc4`='你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b在活动快开始前跟我对话，我会告诉你还需要等待多久。', `MaleText_loc5`='哈囉，旅行者!$b$b你今晚要來參加遊子節活動嗎?日落後不久，熊貓人會在海龜海灘這邊聚集，非常值得一看!$b$b活動快開始的時候來找我談話，我會讓你知道你還需要等多久。', `MaleText_loc7`='¡Hola, $gviajero:viajera;!$b$b¿Vas a ir al Festival del Errante esta noche? Los pandaren se reunirán aquí, en la Playa de la Tortuga, al caer el sol. Es digno de ver.$b$bHabla conmigo cuando quede poco para el evento y te contaré cuánto tienes que esperar.' WHERE `ID`=76527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자님, 안녕하세요!$b$b오늘 밤 유랑객의 축제에 오실 건가요? 일몰 직후에 판다렌들이 바로 여기 거북 해안으로 모여들 거예요! 꽤 장관일 거라구요!$b$b축제는 세 시간 안에 시작될 거예요. 세 시간이 지나기 전에 정시에 와서 다시 확인해보세요!', `MaleText_loc4`='你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到三小时。请在整点时回来确认！', `MaleText_loc5`='哈囉，旅行者!$b$b你今晚要來參加遊子節活動嗎?日落後不久，熊貓人會在海龜海灘這邊聚集，非常值得一看!$b$b節慶活動將在三小時內開始，整點的時候再來找我!', `MaleText_loc7`='¡Hola, $gviajero:viajera;!$b$b¿Vas a ir al Festival del Errante esta noche? Los pandaren se reunirán aquí, en la Playa de la Tortuga, al caer el sol. Es digno de ver.$b$bEl festival empieza en menos de tres horas. ¡Vuelve dentro de un rato!' WHERE `ID`=76528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자님, 안녕하세요!$b$b오늘 밤 유랑객의 축제에 오실 건가요? 일몰 직후에 판다렌들이 바로 여기 거북 해안으로 모여들 거예요! 꽤 장관일 거라구요!$b$b축제는 두 시간 안에 시작될 거예요. 두 시간이 지나기 전에 정시에 와서 다시 확인해보세요!', `MaleText_loc4`='你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到两小时。请在整点时回来确认！', `MaleText_loc5`='哈囉，旅行者!$b$b你今晚要來參加遊子節活動嗎?日落後不久，熊貓人會在海龜海灘這邊聚集，非常值得一看!$b$b節慶活動將在兩小時內開始，整點的時候再來找我!', `MaleText_loc7`='¡Hola, $gviajero:viajera;!$b$b¿Vas a ir al Festival del Errante esta noche? Los pandaren se reunirán aquí, en la Playa de la Tortuga, al caer el sol. Es digno de ver.$b$bEl festival empieza en menos de dos horas. ¡Vuelve dentro de un rato!' WHERE `ID`=76529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자님, 안녕하세요!$b$b오늘 밤 유랑객의 축제에 오실 건가요? 일몰 직후에 판다렌들이 바로 여기 거북 해안으로 모여들 거예요! 꽤 장관일 거라구요!$b$b축제는 한 시간 안에 시작될 거예요. 정시에 와서 다시 확인해보세요!', `MaleText_loc4`='你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到一小时。请在整点时回来确认！', `MaleText_loc5`='哈囉，旅行者!$b$b你今晚要來參加遊子節活動嗎?日落後不久，熊貓人會在海龜海灘這邊聚集，非常值得一看!$b$b節慶活動將在一小時內開始，整點的時候再來找我!', `MaleText_loc7`='¡Hola, $gviajero:viajera;!$b$b¿Vas a ir al Festival del Errante esta noche? Los pandaren se reunirán aquí, en la Playa de la Tortuga, al caer el sol. Es digno de ver.$b$bEl festival empieza en menos de una hora. ¡Vuelve dentro de un rato!' WHERE `ID`=76530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제가 시작됐어요! 친구들을 초대하세요!$b$b축제의 시작과 끝에 펼쳐지는 불꽃놀이를 놓치지 마세요! 축제에서 제일 중요한 부분이니까요.', `MaleText_loc4`='庆典已经开始了！快去邀请你的朋友们吧！$b$b千万别错过庆典头尾的烟火表演。那是最精彩的部分。', `MaleText_loc5`='遊子節已經開始了!邀請你的朋友一起來吧!$b$b千萬不要錯過開幕和閉幕時的煙火，那是節慶活動的高潮所在。', `MaleText_loc7`='¡El festival ha comenzado! ¡Invita a tus amigos!$b$bNo os perdáis los fuegos artificiales al principio y al final del festival. Son la mejor parte.' WHERE `ID`=76531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하가 명하신 대로 전선을 강화하라! 우리의 영웅들이 가로쉬에게 도달할 수 있게 시간을 벌어야 한다!', `MaleText_loc4`='听国王的命令，守住阵线！帮我们的英雄争取追击加尔鲁什的时间！', `MaleText_loc5`='你們聽到國王的話了，向前線推進!給我們的英雄足夠的時間前往卡爾洛斯那裡!', `MaleText_loc7`='¡Ya oyeron al Rey! ¡Refuercen la delantera! ¡Denles tiempo a los héroes para ir adonde Garrosh!' WHERE `ID`=76532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골 열쇠 필요', `MaleText_loc4`='需要万能钥匙', `MaleText_loc5`='需要骷髏鑰匙', `MaleText_loc7`='Requiere la llave esqueleto', `FemaleText_loc1`='해골 열쇠 필요', `FemaleText_loc4`='需要万能钥匙', `FemaleText_loc5`='需要骷髏鑰匙', `FemaleText_loc7`='Requiere la llave esqueleto' WHERE `ID`=76533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 친구! 나는 차석 역사가 주파라고 하네. 아직 공식적으로 차석인 건 아니지만 언젠가는 꼭 발표가 날 걸세.', `MaleText_loc4`='嘿，伙计！我是助理历史学家帕吉。他们还没有正式授予我这个的头衔，但我相信那是迟早的事。', `MaleText_loc5`='嘿，老兄!我是副官歷史學家裘帕。他們還沒把稱號給我，不過我相信這只是暫時的。', `MaleText_loc7`='¡Hola, colega! Soy el hi''toriador adjunto Ju''pa. Todavía no me lo han pueh''to en el título, pero es temporal.' WHERE `ID`=76537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가! 나는 역사가 로어라네! 다들 내가 너무 자주 웃는다고 하지만, 딱히 그런 것도 아니라네!', `MaleText_loc4`='你好！我是历史学家勒洛尔！大家都说我笑得太多了，可我觉得这完全不可能！', `MaleText_loc5`='歡迎!我是歷史學家洛爾!大家都說我太愛笑，但我覺得他們講得太誇張了!', `MaleText_loc7`='¡Hola! ¡Soy el historiador Llore! Todos me dicen que sonrío demasiado, ¡pero creo que eso es imposible!' WHERE `ID`=76538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 심판의 시간이 왔다. 이 괴물은 전쟁에서 스러져 간 얼라이언스의 목숨 하나하나에 대가를 치를 것이다.', `MaleText_loc4`='复仇的时刻终于到来了。这个怪物将为我们所牺牲的每一位联盟战友而受到惩罚。', `MaleText_loc5`='終於，伸張正義的時刻到了。這個怪物將會為在這場戰爭中喪生的每一位聯盟成員付出代價。', `MaleText_loc7`='Por fin ha llegado la hora de la justicia. Ese monstruo responderá por todas y cada una de las vidas de la Alianza que hemos perdido en esta guerra.' WHERE `ID`=76539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 죄값을 치를 겁니다.', `MaleText_loc4`='加尔鲁什将为他的罪行付出代价。', `MaleText_loc5`='卡爾洛斯會為他的罪行付出代價。', `MaleText_loc7`='Garrosh pagará por sus crímenes.', `FemaleText_loc1`='가로쉬는 죄값을 치를 겁니다.', `FemaleText_loc4`='加尔鲁什将为他的罪行付出代价。', `FemaleText_loc5`='卡爾洛斯會為他的罪行付出代價。', `FemaleText_loc7`='Garrosh pagará por sus crímenes.' WHERE `ID`=76540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두를 이 어두운 곳으로 이끈 나의 오래전 실수를 끝낼 수 있게 도와줘서 고맙네. 나 혼자 힘으론 불가능했을 거라네. 이제 내가 영광을 되찾고 가로쉬의 공포스러웠던 통치를 여기서 영원히 끝낼 수 있게 도와주게.', `MaleText_loc4`='谢谢你来帮助我纠正过去所犯下的错误，是它将我们的人民推入了黑暗的深渊。我一个人是无法成功的。现在，我就要赢回自己的荣誉，并彻底终结加尔鲁什的恐怖统治。', `MaleText_loc5`='謝謝你幫我終結我許久之前犯的錯誤，讓我的人民陷入黑暗的錯誤。我無法獨自做到這一點。讓我重獲我的榮耀，徹底地終結卡爾洛斯的恐怖統治吧。', `MaleText_loc7`='Gracias por ayudarme a poner fin al grave error que cometí hace tiempo, un error que condujo a mi pueblo a la oscuridad. No puedo hacerlo solo. Dejen que recupere mi honor y acabe con el reino de terror de Garrosh de una vez por todas.' WHERE `ID`=76541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주십시오. 호드를 위해.', `MaleText_loc4`='为了部落，结束这一切吧。', `MaleText_loc5`='為了部落，結束這一切。', `MaleText_loc7`='Acaba con esto. Por la Horda.', `FemaleText_loc1`='끝내주세요. 호드를 위해.', `FemaleText_loc4`='为了部落，结束这一切吧。', `FemaleText_loc5`='為了部落，結束這一切。', `FemaleText_loc7`='Acaba con esto. Por la Horda.' WHERE `ID`=76542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전선은 우리가 지키겠습니다. 당신은 가로쉬의 광기를 끝장내는 데만 집중해 주십시오!', `MaleText_loc4`='我们会守住战线的，$n。你只需要考虑如何阻止加尔鲁什的疯狂罪行。', `MaleText_loc5`='我們會守住陣線，$n。你只要專心終結卡爾洛斯的瘋狂就好。', `MaleText_loc7`='Nosotros mantendremos el frente, $n. Tú preocúpate de acabar con la locura de Garrosh.' WHERE `ID`=76543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 잠금 장치가 열려 땅에 떨어집니다. 둘 남았습니다.', `MaleText_loc4`='三重锁的囚笼上的第一道锁“喀啦”一声掉在了地上，还剩两道锁。', `MaleText_loc5`='三重鎖牢籠的第一個鎖在微弱的聲響中掉落到地上。還有兩個。', `MaleText_loc7`='El primer candado de la jaula con tres cerrojos se abre y cae al suelo. Quedan dos.', `FemaleText_loc1`='첫 번째 잠금 장치가 열려 땅에 떨어집니다. 둘 남았습니다.', `FemaleText_loc4`='三重锁的囚笼上的第一道锁“喀啦”一声掉在了地上，还剩两道锁。', `FemaleText_loc5`='三重鎖牢籠的第一個鎖在微弱的聲響中掉落到地上。還有兩個。', `FemaleText_loc7`='El primer candado de la jaula con tres cerrojos se abre y cae al suelo. Quedan dos.' WHERE `ID`=76544;
