UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 번째 잠금 장치가 열려 땅에 떨어집니다. 우리가 열립니다!', `MaleText_loc4`='三重锁的囚笼上的第三道锁“喀啦”一声掉在了地上。囚笼打开了！', `MaleText_loc5`='三重鎖牢籠的第三個鎖在微弱的聲響中掉落到地上。牢籠打開了!', `MaleText_loc7`='El tercer candado de la jaula con tres cerrojos se abre y cae al suelo. ¡La jaula se abre!', `FemaleText_loc1`='세 번째 잠금 장치가 열려 땅에 떨어집니다. 우리가 열립니다!', `FemaleText_loc4`='三重锁的囚笼上的第三道锁“喀啦”一声掉在了地上。囚笼打开了！', `FemaleText_loc5`='三重鎖牢籠的第三個鎖在微弱的聲響中掉落到地上。牢籠打開了!', `FemaleText_loc7`='El tercer candado de la jaula con tres cerrojos se abre y cae al suelo. ¡La jaula se abre!' WHERE `ID`=76546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 반바지가 좋아요! 이 날씨에 딱이잖아요!', `MaleText_loc4`='我喜欢穿短裤！它最适合这里的天气！', `MaleText_loc5`='我喜歡短褲!這種天氣穿正好!', `MaleText_loc7`='¡Me gustan los pantalones cortos! Vienen bien para el calor.', `FemaleText_loc1`='난 반바지가 좋아요! 이 날씨에 딱이잖아요!', `FemaleText_loc4`='我喜欢穿短裤！它最适合这里的天气！', `FemaleText_loc5`='我喜歡短褲!這種天氣穿正好!', `FemaleText_loc7`='¡Me gustan los pantalones cortos! Vienen bien para el calor.' WHERE `ID`=76547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물이 하나밖에 없는데, 괜찮겠죠?', `MaleText_loc4`='我只有一只宠物！但愿这能行！', `MaleText_loc5`='我只有一隻寵物!希望這樣沒問題!', `MaleText_loc7`='¡Solo tengo una mascota! No pasa nada, ¿verdad?' WHERE `ID`=76548;
