UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소포나 편지 보내고 싶어?$B$B믿고 맡겨봐!', `MaleText_loc4`='你是来拿包裹的吗？还是来寄信的？$B$B我可以提供超速快递服务哦！', `MaleText_loc5`='你有包裹要領?你有信要寄?$B$B服務快速，使命必達!', `MaleText_loc7`='¿Tienes algún paquete por recoger? ¿Quieres mandar una carta?$b$b¡Ofrezco un servicio muy rápido!' WHERE `ID`=76553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우편 서비스를 이용합니다.', `MaleText_loc4`='使用邮件服务。', `MaleText_loc5`='使用郵件服務吧。', `MaleText_loc7`='Utilizar el servicio de correo.', `FemaleText_loc1`='우편 서비스를 이용합니다.', `FemaleText_loc4`='使用邮件服务。', `FemaleText_loc5`='使用郵件服務吧。', `FemaleText_loc7`='Utilizar el servicio de correo.' WHERE `ID`=76554;
