UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='히익! 뭐, 뭐죠?! 아...$B$B차, 찾으시는 거라도 있나요?$B$B내가 왜 언니 말을 곧이곧대로 듣고 이런 곳에 왔을까... 저 동물들이 얼마나 거대한지 보셨어요?!', `FemaleText_loc4`='呃！什、什么？！噢……$B$B你、你需要、要什么吗？$B$B我、我怎么就让姐姐给骗过来了呢……你看到那些动物有多、多大吗？！', `FemaleText_loc5`='呃!什...什麼?!噢...$B$B你...你需要什麼嗎?$B$B我...我怎麼會讓我姊姊說服來這裡...你有看到那些動物多大隻嗎?', `FemaleText_loc7`='¡Aaah! ¿Q-qué? Ah...$b$b¿N-necesitas algo?$b$b¿P-por qué dejé que mi hermana me convenciera para venir aquí? ¿Has visto lo e-enormes que son esos animales?' WHERE `ID`=76558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<지저분한 늙은 판다렌이 평화롭게 코를 골고 있습니다. 여러 종류의 빈 병이 그의 옆에 나뒹굴고 있습니다.>', `MaleText_loc4`='<这个脏兮兮的老熊猫人安详地打着呼噜，身边丢满了各种瓶子。>', `MaleText_loc5`='<髒髒的老熊貓人平靜地打呼著。各式各樣的酒瓶散落在他身邊。', `MaleText_loc7`='<El anciano pandaren ronca tranquilamente. Hay varias botellas esparcidas a su alrededor.>' WHERE `ID`=76559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물품을 살펴봅니다.', `MaleText_loc4`='检查他的货物。', `MaleText_loc5`='檢查他的貨物。', `MaleText_loc7`='Examina su mercancía.', `FemaleText_loc1`='물품을 살펴봅니다.', `FemaleText_loc4`='检查他的货物。', `FemaleText_loc5`='檢查他的貨物。', `FemaleText_loc7`='Examina su mercancía.' WHERE `ID`=76560;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 안녕하세요!$B$B들어오세요! 좀 쉬다 가시죠.$B$B먹을 게 필요하세요? 아니면 마실 거라도?', `FemaleText_loc4`='噢，你好！$B$B请进，快请进！请休息一会儿吧。$B$B你想吃点什么吗？或者来杯喝的？', `FemaleText_loc5`='噢，哈囉!$B$B請進，請進!休息一下。$B$B你們想要吃什麼嗎?還是要喝的?', `FemaleText_loc7`='¡Ah, hola!$b$b¡Pasa, pasa! Descansa un rato.$b$b¿Quieres comer algo? ¿Tienes sed?' WHERE `ID`=76561;
