UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 있게 친구. 시간이 다 돼서 난 이만 가봐야겠네.', `MaleText_loc4`='再见了我的朋友，时间不早，我得走了。', `MaleText_loc5`='再見了朋友們，時間快不夠了。我必須離開了。', `MaleText_loc7`='Adiós, amigos. Se acaba el tiempo, y debo partir.' WHERE `ID`=76570;
