UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 내 동료들 못봤나?', `MaleText_loc4`='你见过我的同伴吗？', `MaleText_loc5`='你有看到我的夥伴嗎?', `MaleText_loc7`='¿Has visto a mis colegas?' WHERE `ID`=76581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 도전에 응하겠다, 외부인이여. 오르도가 불타는 신의 이름으로 이곳을 차지하겠다!', `MaleText_loc4`='外来者，我们接受你的挑战。斡耳朵，以火神的名义，夺下这个地方！', `MaleText_loc5`='你的挑戰已經得到應允了，外來者。歐朵，以火神之名，宣示這裡的主權吧!', `MaleText_loc7`='Hemos escuchado tu desafío, hereje. Ordon, ¡tomen esta zona en nombre del dios ardiente!' WHERE `ID`=76582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역사가의 일에는 끝이 없습니다. 늘 기억해야 하는 중요한 일이 일어나고 있기 때문이지요.$B$B이미 당신들의 역사에 대해 많이 썼지만, 아직도 배울 게 너무 많습니다! 당신의 공적도 길이길이 기억되겠지요.', `FemaleText_loc4`='你瞧，历史学家的工作是永远也干不完的。那些需要我们铭记的重要事件总是层出不穷。$B$B我已经记下了你的大部分事迹，但有待了解的东西还是太多了！你的事迹肯定会流芳百世的。', `FemaleText_loc5`='歷史學家的工作永遠沒有結束的時候。隨時都會有值得我們銘記的重要事情發生。$B$B我已經寫下許多你的事蹟，但值得探尋的還有很多!能確定的是，你的功績將會流芳百世。', `FemaleText_loc7`='El trabajo de una historiadora no termina nunca, ¿sabes? Siempre está sucediendo algo importante que debemos recordar.$b$bYa he escrito mucho sobre tu legado, ¡pero todavía quedan muchas cosas por descubrir! Estoy segura de que tus hazañas se recordarán durante siglos.' WHERE `ID`=76583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 헛것이 다 보이는 모양이군! 저건... 해골? 해골들이 배를 몰고 있다고?', `MaleText_loc4`='我不是眼花了吧？！船上那些……是骷髅吗？', `MaleText_loc5`='我的眼睛好像出了點問題!那些...在開船的水手是骷髏嗎?', `MaleText_loc7`='Creo que veo visiones... ¿Hay esqueletos tripulando ese barco?' WHERE `ID`=76584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때의 폭풍 때문에 항로에서 벗어났다. 이곳이 쿨 티라스와 로데론 사이에 있다는 것 말고는 아무것도 모른다. 모두들 긴장하라!', `MaleText_loc4`='那场风暴将我们吹离了航道。我们可能位于库尔提拉斯和洛丹伦之间的任何地方，所以都给我提高警惕！', `MaleText_loc5`='風暴把我們吹離了航道。我們可能是在庫爾提拉斯或羅德隆之間的任何一個區域，所以打起精神來!', `MaleText_loc7`='La tormenta nos cambió de rumbo. Podríamos estar en cualquier sitio entre Kul Tiras y Lordaeron. ¡Manteneos alerta!' WHERE `ID`=76585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게나 자욱한 안개는 처음 보는군. 돛을 내리고 안개가 지나가는 걸 기다려야겠다. 조가비호를 산호초에 박고 싶을 만한 날은 아니니까 말이야.', `MaleText_loc4`='我从没见过这么浓的雾。我们得把帆降下来，等雾散开。我可不想让藤壶号撞上暗礁啥的。', `MaleText_loc5`='我從未見過這麼濃的霧。我們得把風帆扯下，等濃霧散去。我可不希望藤壺號擱淺在淺礁上。', `MaleText_loc7`='Nunca había visto una niebla así de espesa. Tendremos que arriar las velas y esperar a que se despeje. Hoy no me apetece encallar el Percebe en una roca...' WHERE `ID`=76586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 뭐지? 배인가? 어이! 우린 이곳에서 9일 동안 표류하고 있다! 도움이 필요하다!', `MaleText_loc4`='远处那是什么？船帆！嘿！我们都搁浅九天啦！救命！', `MaleText_loc5`='看到遠方那個東西沒有?船帆?喂!我們已經困在這裡九天了!救救我們!', `MaleText_loc7`='¿Qué es eso que se ve a lo lejos? ¿Velas? ¡Ah del barco! ¡Llevamos nueve días a la deriva! ¡Socorro!' WHERE `ID`=76587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원 집합! 조가비호가 공격받고 있다!', `MaleText_loc4`='全体上甲板！藤壶号遭到攻击啦！', `MaleText_loc5`='所有人準備!藤壺號正在遭受攻擊!', `MaleText_loc7`='¡Todo el mundo a cubierta! ¡Atacan al Percebe!' WHERE `ID`=76588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간은 아름다우면서 잔인할 수 있죠.', `FemaleText_loc4`='时间既是美丽的，也是残酷的。', `FemaleText_loc5`='時間可以同時是美麗，並殘酷的。', `FemaleText_loc7`='El tiempo puede ser hermoso y cruel al mismo tiempo.' WHERE `ID`=76609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 방법이 없네, 친구. 지금 가로쉬를 막지 못하면 우린 평생 도망자 신세가 될 거야.', `MaleText_loc4`='没办法了，伙计。我们必须马上阻止加尔鲁什，否则大家只能白白送死。', `MaleText_loc5`='沒有其他辦法了，老兄。我們必須在此時此刻阻止卡爾洛斯，否則就得一輩子逃命了。', `MaleText_loc7`='No hay de otra, amigo. Tenemos que detener a Garrosh aquí y ahora o nos pasaremos la vida huyendo.' WHERE `ID`=76610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항구를 점령한 건가! 하하! 학살의 장에 온 걸 환영하네.', `MaleText_loc4`='他们一定攻占了码头！哈哈！欢迎来到修罗场。', `MaleText_loc5`='他們一定攻下碼頭了!哈哈!歡迎來到煉獄。', `MaleText_loc7`='¡Deben de haber tomado los muelles!  ¡Jaja!  Bienvenidos a los campos de la masacre.' WHERE `ID`=76611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 그대로 영웅들이로군.', `MaleText_loc4`='不用怀疑，他们是英雄。', `MaleText_loc5`='他們是英雄，這點無庸置疑。', `MaleText_loc7`='Son héroes, de eso no hay duda.' WHERE `ID`=76612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물을 쓰러뜨렸다!', `MaleText_loc4`='那头野兽完蛋了！', `MaleText_loc5`='那野獸死了!', `MaleText_loc7`='¡La bestia ha muerto!' WHERE `ID`=76613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데...', `MaleText_loc4`='泰兰德……', `MaleText_loc5`='泰蘭妲...', `MaleText_loc7`='Tyrande...' WHERE `ID`=76614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 기지를 통째로 숨겨 뒀었군. 힘의 탐욕에 이끌려 어디까지 간 거지?', `MaleText_loc4`='加尔鲁什藏了一个秘密基地。他到底有什么打算？', `MaleText_loc5`='卡爾洛斯一直藏著一整個秘密基地。他對力量的渴望到了什麼地步啊?', `MaleText_loc7`='Garrosh esconde una base entera. ¿Hasta dónde lo llevó su sed de poder?  ' WHERE `ID`=76615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바인, 자네는 부하들과 이곳을 막아주게. 이 영웅들은 빨리 가서 숨어 있는 대족장을 처단해야 하니.', `MaleText_loc4`='贝恩，你和你的战士们守住这里。这些英雄们要继续前进，找到加尔鲁什的踪迹。', `MaleText_loc5`='貝恩，你和你的戰士守住這個路口。這些英雄們要繼續前進，把大酋長揪出來。', `MaleText_loc7`='Baine, tú y tus guerreros, protejan esta intersección. Estos valientes deberán avanzar y hacer que el Jefe de Guerra salga de su escondite.' WHERE `ID`=76616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위에서 사람들이 죽어가고 있네. 온 도시가 혼란에 빠졌어. 내, 참사를 막고 자네에게 돌아오지.', `MaleText_loc4`='人民正在哀嚎。城里一片混乱。我要去阻止这场屠杀。我会回来找你的。', `MaleText_loc5`='上面有平民性命垂危。整座城市混亂不堪。我要阻止這場殺戮。我會回來找你的。', `MaleText_loc7`='Ahí arriba hay gente muriendo. La ciudad está en caos. Terminaré con eso... Detendré la matanza. Volveré por ustedes.' WHERE `ID`=76617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 말게. 우린 스랄을 찾고 대족장을 처치할 거야. 자네 아버지의 복수를 하는 거지.', `MaleText_loc4`='没事的，贝恩。我们会找到萨尔，打倒酋长，为你父亲报仇的。', `MaleText_loc5`='我會沒事的，貝恩。我們會找到索爾，殺死大酋長，替你的父親報仇。', `MaleText_loc7`='Todo va a estar bien, Baine. Vamos a encontrar a Thrall, a matar al Jefe de Guerra, a vengar a tu padre. ' WHERE `ID`=76618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하. 검은창 부족은 결코 쓰러지지 않아.', `MaleText_loc4`='哈。暗矛永不灭亡。', `MaleText_loc5`='哈。暗矛的命很硬的。', `MaleText_loc7`='Ja. Los Lanza Negra nunca mueren.' WHERE `ID`=76619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아누도라!', `FemaleText_loc4`='Anu''dora！', `FemaleText_loc5`='(達納蘇斯語)為了真理!', `FemaleText_loc7`='¡Anu''dora!  ' WHERE `ID`=76620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칼림도어를 위하여! 공격!', `FemaleText_loc4`='姐妹们，进攻！为了卡利姆多！', `FemaleText_loc5`='攻擊他們，姊妹們!為了卡林多!', `FemaleText_loc7`='¡Atáquenlos, mis hermanas! ¡Por Kalimdor!' WHERE `ID`=76621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='널 구하러 온 게 아니다, 트롤. 칼림도어를 위해서지. 우리가 코르크론의 주의를 끌테니 병력을 성문 안으로 들여보내!', `FemaleText_loc4`='我们可不是来救你的，巨魔。我们是为卡利姆多而来。我们来引开敌人，让你的部队趁势杀进去。', `FemaleText_loc5`='別以為我們是來救你，食人妖。我們是為了卡林多。趁我們引開敵人，快攻進城門裡!', `FemaleText_loc7`='No creas que vinimos a salvarte a ti, trol. Vinimos por Kalimdor. ¡Mete a tus fuerzas por las puertas mientras distraemos al enemigo!' WHERE `ID`=76622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 쪽 피해가 너무 심합니다!', `MaleText_loc4`='我们的伤亡太大了！', `MaleText_loc5`='我們的傷亡大大了!', `MaleText_loc7`='¡Nuestras bajas son demasiadas!' WHERE `ID`=76623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 아마 새 지원군이 우릴 도와줄 겁니다.', `MaleText_loc4`='或许新来的援军能帮上忙。', `MaleText_loc5`='也許我們新的援軍能幫助我們。', `MaleText_loc7`='Tal vez nuestros nuevos refuerzos nos ayudarán.' WHERE `ID`=76624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 희망의 불씨가 살아 있었군요.', `MaleText_loc4`='或许我们还有希望。', `MaleText_loc5`='也許終究還有希望。', `MaleText_loc7`='Tal vez queden esperanzas, después de todo.' WHERE `ID`=76625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신의 축복이 이들과 함께하길.', `MaleText_loc4`='愿大地母亲祝福他们。', `MaleText_loc5`='願大地之母祝福他們。', `MaleText_loc7`='Que la bendición de la Madre Tierra se pose sobre ellos.' WHERE `ID`=76626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 알 수 있을 겁니다. 놈은 이 통로 안에 갇힌 쥐와 다름 없습니다.', `MaleText_loc4`='我们很快就知道了。他就像老鼠一样躲在某条地道里。', `MaleText_loc5`='我們很快就會知道。他已經像被逼到死角的老鼠一樣。', `MaleText_loc7`='Pronto lo sabremos. Está acorralado como una rata en uno de esos corredores. ' WHERE `ID`=76627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어떻게 할까요?', `MaleText_loc4`='接下来我们该怎么办？', `MaleText_loc5`='我們接下來要怎麼做?', `MaleText_loc7`='¿Qué debemos hacer ahora?' WHERE `ID`=76628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은?', `MaleText_loc4`='那么你呢？', `MaleText_loc5`='那你呢?', `MaleText_loc7`='¿Qué hay de ti?' WHERE `ID`=76629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠...알겠습니다.', `MaleText_loc4`='……好吧。', `MaleText_loc5`='...好吧。', `MaleText_loc7`='Muy bien.' WHERE `ID`=76630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신이 당신을 지켜주길.', `MaleText_loc4`='愿大地母亲护佑着你，沃金。', `MaleText_loc5`='願大地之母護祐你，沃金。', `MaleText_loc7`='Que la Madre Tierra te proteja, Vol''jin.' WHERE `ID`=76631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벌써 가려고요? 손님들은 어쩌고요?', `FemaleText_loc4`='这么快就要走了吗？客人怎么办？', `FemaleText_loc5`='這麼快就要走了?那顧客怎麼辦?', `FemaleText_loc7`='¿Ya te vas? ¿Y qué pasa con los clientes?' WHERE `ID`=76632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 우린 이거보다 더한 폭풍도 잠재웠습니다, $n 님! 서두르십시오. 가로쉬를 기다리게 하고 싶진 않으실 테니까요!', `MaleText_loc4`='哈！我们还见识过比这更可怕的风暴呢，$n。那么，快行动吧，可别让加尔鲁什久等了！', `MaleText_loc5`='哈!我們經歷過比這更糟的風暴，$n。快動身吧，你不會想要讓卡爾洛斯等下去吧!', `MaleText_loc7`='¡Ja! Hemos capeado temporales peores, $n. Ahora, date prisa. ¡No querrás hacer esperar a Garrosh!' WHERE `ID`=76633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬의 광기를 중단시켜야 하네, $n. 우리의 미래가 거기 달렸어. 어마어마하게 중대한 임무인 만큼, 다른 이에게 맡기고 싶지 않네.', `MaleText_loc4`='必须阻止加尔鲁什的疯狂行为，$n，我们的未来全系于此。由于这个任务极其重要，所以我不能把它托付给别人。', `MaleText_loc5`='有人得去阻止卡爾洛斯的瘋狂的行徑，$n。我們的未來就靠這一場戰鬥了。雖然這項任務十分沈重，我無法把它交到別人的手上。', `MaleText_loc7`='Hay que poner fin a la locura de Garrosh, $n. Nuestro futuro depende de ello. Es una misión crucial, y no se la confiaría a nadie más.' WHERE `ID`=76634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t노루셴이 격리 구역의 |cFFFF0000|Hspell:145779|h[안전 장치]|h|r를 작동시킵니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t诺鲁什启动了检疫空间中的|cFFFF0000|Hspell:145779|h[安全措施]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t諾努衫啟動了隔離區的|cFFFF0000|Hspell:145779|h[安全措施]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_titankeeper_quarantine.blp:20|t¡Norushen activa las |cFFFF0000|Hspell:145779|h[Medidas de seguridad]|h|r de la zona de cuarentena!', `FemaleText_loc1`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t노루셴이 격리 구역의 |cFFFF0000|Hspell:145779|h[안전 장치]|h|r를 작동시킵니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t诺鲁什启动了检疫空间中的|cFFFF0000|Hspell:145779|h[安全措施]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t諾努衫啟動了隔離區的|cFFFF0000|Hspell:145779|h[安全措施]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_titankeeper_quarantine.blp:20|t¡Norushen activa las |cFFFF0000|Hspell:145779|h[Medidas de seguridad]|h|r de la zona de cuarentena!' WHERE `ID`=76635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장담하는데, 제가 숨을 쉬고 있는 한, 이 코르크론 짐승들은 여길 지나갈 수 없을 거예요. 미친 들개 마냥 날뛰는 가로쉬를 잠재워주겠다고 약속만 해주세요.', `FemaleText_loc4`='我发誓，只要我还有一口气在，这些库卡隆畜生就休想通过这里。你只要保证把加尔鲁什那条疯狗干掉就够了。', `FemaleText_loc5`='我發誓，柯爾克隆的那群動物只要我還有一口氣在，就無法通過這裡。只要你答應我，把卡爾洛斯打得抱頭鼠竄。', `FemaleText_loc7`='Te juro que mientras yo viva ninguno de esos animales Kor''kron pasará de aquí. Tú prométeme que abatirás a Garrosh como el perro rabioso que es.' WHERE `ID`=76640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 제가 해드릴 수 있는 최선의 의료 지원은 애초에 부상을 방지할 수 있는 수단을 제공해 드리는 겁니다.', `FemaleText_loc4`='目前，我能提供的最好的医疗手段就是给你一些能够避免伤害的东西了。', `FemaleText_loc5`='現在，我所能提供的最好醫療就是給你避免受傷的工具。', `FemaleText_loc7`='Ahora mismo los mejores cuidados médicos que puedo ofrecerte consisten en darte las herramientas que necesitas para que no te hieran.' WHERE `ID`=76641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 확실히 평소 업무인 정보 수집 작업보다 훨씬 재미있네요. 자, 어서 가로쉬를 처치해주세요. 이게 SI:7에서 제 마지막 임무가 되길 바라진 않으니까요.', `FemaleText_loc4`='这肯定会比我平时的情报收集工作刺激得多。现在，快去对付加尔鲁什吧，我可不希望这变成我在军情七处的最后一次任务。', `FemaleText_loc5`='這一定比我平常的情報蒐集行動還要令人興奮。現在快去搞定卡爾洛斯，我可不想這成為我在軍情七處的最後一個任務。', `FemaleText_loc7`='Debo admitir que esto es más emocionante que las operaciones de reconocimiento habituales. Ahora date prisa y acaba con Garrosh. No quiero que esta sea mi última misión con el IV:7.' WHERE `ID`=76642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 장비가 아무리 멋져도 난 관심 없네. 어차피 발을 관리하지 않으면 자네도 끝장날 테니까. 그리니 탈것들은 좀 쉬게 놔두고 내 차원문을 사용해서 입구로 바로 이동하게.', `MaleText_loc4`='我不管你的装备有多好，$n，如果不注意脚下，那你就死定了。让那些小崽子们休息一下，用我的传送门立即返回入口处吧。', `MaleText_loc5`='我不管你的裝備有多炫，$n。如果你不小心保護腳，你就完蛋了。所以讓那些小傢伙們輕鬆點，用我的傳送門回去入口那裡。', `MaleText_loc7`='Da igual lo maravilloso que sea tu equipo si al final no te puedes tener en pie, $n. Da un descanso a tus pies y utiliza mi portal para volver inmediatamente a la entrada.' WHERE `ID`=76645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겼다!', `MaleText_loc4`='我赢了！', `MaleText_loc5`='我贏了!', `MaleText_loc7`='¡Gané!' WHERE `ID`=76648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 임무는 너무 중요해서 장비 수리는 나 말고 다른 이에게 맡기면 안돼요.', `MaleText_loc4`='这个任务太重要了，所以我不放心把你的修理工作交给别人。', `MaleText_loc5`='這個任務太重要了，不能把修理的東西放在除了我以外的人手上。', `MaleText_loc7`='Esta misión es demasiado importante como para dejar que te repare el equipo otra persona.' WHERE `ID`=76651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 당신을 영원의 섬으로 데려다주려고 했는데, 이미 한 번 가보셨군요. 제가 시간의 길에서 또 길을 잃었었나보네요.', `FemaleText_loc4`='啊！我是来引导你前往永恒岛的，但我看到你已经抵达了。我恐怕又把时间流搞混了。', `FemaleText_loc5`='啊!我被派來指引你前往永恆之島，但看來你已經去過了。恐怕我又在時間之道裡搞混了。', `FemaleText_loc7`='¡Ah! Me mandaron para llevarte a la Isla Intemporal, pero veo que ya has hecho el viaje. Creo que me he vuelto a enredar con las líneas temporales...' WHERE `ID`=76652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 청동 시계를 꺼내서 흔들더니 바늘을 쳐다봅니다. 부끄러워하는 표정입니다.', `FemaleText_loc4`='%s拿出一个铜质计时器，眯着眼看了看刻度盘。她看起来有些尴尬。', `FemaleText_loc5`='%s拿出了一個青銅的計時器，搖了搖，然後瞇眼看著刻度。她看起來有點難為情。', `FemaleText_loc7`='%s saca un reloj de bolsillo de bronce, lo agita y observa las agujas con atención. Parece un poco avergonzada.' WHERE `ID`=76653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 삶은 실과 같아요. 그리고 이 세상의 이야기는 우리 모두가 함께 짜는 양탄자라 할 수 있죠. 판다렌 전승지기들은 그 누구보다도 이 사실을 잘 알고 있어요. 그들의 도서관을 보세요! 이야기가 어찌나 많은지...', `FemaleText_loc4`='每个生命都是一条线，而把我们交织起来，就构成了这个世界的故事。熊猫人游学者对此的理解无人能及。看看这个图书馆吧！这么多故事……', `FemaleText_loc5`='每一個生命都是條線，而我們一起編織的毯子就是我們這個世界的故事。熊貓人的博學行者比任何人都更清楚這一點。看看這個圖書館就知道了!好多的故事...', `FemaleText_loc7`='Cada vida es un hilo, y el tapiz que tejemos entre todos es la historia de nuestro mundo. Los eremitas pandaren lo saben mejor que nadie. ¡Mira esta biblioteca! Cuántas historias...' WHERE `ID`=76659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나 화창하고 맛있는 음식이 가득한 우의 가게에 온 걸 환영해요!', `FemaleText_loc4`='欢迎光临王记，这里的太阳永不下山，这里的美食永远热气腾腾！', `FemaleText_loc5`='歡迎來到老吳的店，這裡有四季普照的陽光，還有熱騰騰的食物!', `FemaleText_loc7`='Con los Woo, ¡el sol siempre brilla y la comida siempre está caliente!' WHERE `ID`=76662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇이 맛있습니까?', `MaleText_loc4`='什么味道这么香？', `MaleText_loc5`='什麼東西聞起來很好吃?', `MaleText_loc7`='¿Qué es eso que huele tan bien?', `FemaleText_loc1`='무엇이 맛있나요?', `FemaleText_loc4`='什么味道这么香？', `FemaleText_loc5`='什麼東西聞起來很好吃?', `FemaleText_loc7`='¿Qué es eso que huele tan bien?' WHERE `ID`=76663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젊고 늙은 친구들 모두와 함께 어울리는 건 역시 좋구나.', `FemaleText_loc4`='能和新朋旧友欢聚一堂真是太好了。', `FemaleText_loc5`='很高興能坐在老朋友跟新朋友之間。', `FemaleText_loc7`='Qué bien se está con nuevos y viejos amigos.' WHERE `ID`=76664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경치를 즐기는 것도 잊지 마려무나!', `FemaleText_loc4`='别忘了花点时间去欣赏风景！', `FemaleText_loc5`='別忘了，花點時間去看看風景!', `FemaleText_loc7`='¡Acuérdate de descansar un rato para admirar el paisaje!' WHERE `ID`=76665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 가장 좋은 자리 같구나. 안 그렇니?', `FemaleText_loc4`='我的位子是整个庭院里最好的，你不觉得吗？', `FemaleText_loc5`='我這裡是整間屋子最棒的位置，你不覺得嗎?', `FemaleText_loc7`='¿A que tengo el mejor asiento?' WHERE `ID`=76666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 다들 친절하다... 치 치 이런 거 좋다.', `MaleText_loc4`='这里的人都很好……吱吱喜欢这里。', `MaleText_loc5`='這裡的人都很好...奇奇喜歡。', `MaleText_loc7`='Akí todo el mundo es muy bueno... A Chee Chee le gusta.' WHERE `ID`=76667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 소랑 싸우러 가?', `MaleText_loc4`='你要去跟大牛战斗吗？', `MaleText_loc5`='你要跟大牛打嗎?', `MaleText_loc7`='¿Makaku va a luchar kon buey gigante?' WHERE `ID`=76668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 치 치가 만난 $c 중에 가장 강하다!', `MaleText_loc4`='你是吱吱见过的，最强大的$c！', `MaleText_loc5`='你是奇奇所見過最強壯的$c!', `MaleText_loc7`='¡Makaku es $gel:la; $c más fuerte ke Chee Chee ha visto jamás!' WHERE `ID`=76669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제법인데.', `MaleText_loc4`='真不错。', `MaleText_loc5`='相當不錯。', `MaleText_loc7`='Impresionante.' WHERE `ID`=76670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 수로군.', `MaleText_loc4`='打得好。', `MaleText_loc5`='打得好。', `MaleText_loc7`='Buena jugada.' WHERE `ID`=76673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 덫에 꼼짝없이 걸려들었군.', `MaleText_loc4`='这下你可上我的当了。', `MaleText_loc5`='你一腳踏入了我的陷阱。', `MaleText_loc7`='Has caído en mi trampa.' WHERE `ID`=76674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠.', `MaleText_loc4`='唔。', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm.' WHERE `ID`=76675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 판 더 하자고, 카트.', `MaleText_loc4`='再来一盘吧，凯特。', `MaleText_loc5`='再來一場，凱特。', `MaleText_loc7`='Otra vez, Kat.' WHERE `ID`=76676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 볼진의 저항군인가. 해냈군.', `MaleText_loc4`='啊，是沃金的起义军。你们来了。', `MaleText_loc5`='啊，沃金的義軍。你們到了。', `MaleText_loc7`='Ah, más de los revolucionarios de Vol''jin. Han llegado.' WHERE `ID`=76677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄은 찾았나? 내가 크게 다치는 바람에 스랄 혼자 갔다네.', `MaleText_loc4`='你找到萨尔了吗？我受了重伤，他坚持要独自前进。', `MaleText_loc5`='有找到索爾嗎?我受了重傷，他堅持要獨自前進。', `MaleText_loc7`='¿Encontraron a Thrall? Estoy muy lastimado, él insistió en seguir solo.' WHERE `ID`=76678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해보게. 위에서의 전투는 어찌 되었나? 나즈그림은? 어서!', `MaleText_loc4`='告诉我，上面的战斗怎么样了？纳兹戈林呢？告诉我！', `MaleText_loc5`='告訴我，上面的戰況如何?納茲格寧姆怎麼樣了?跟我說!', `MaleText_loc7`='Dime, ¿cómo va la batalla en la superficie? ¿Qué hay de Nazgrim? ¡Cuéntame!' WHERE `ID`=76679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나즈그림. 위대한 지도자이자 강인한 전사. 그는 대족장에 대한 맹세를 목숨보다 소중히 여겼네.', `MaleText_loc4`='啊，纳兹戈林。他是个好领袖，好战士。他珍视自己的誓言胜过生命。', `MaleText_loc5`='啊，納茲格寧姆。很棒的領袖及優秀的戰士。他把對大酋長的誓言看得比生命還重。', `MaleText_loc7`='Ah, Nazgrim. Un gran líder y un buen guerrero. Valoraba su juramento al Jefe de Guerra más que su propia vida.' WHERE `ID`=76680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해주려 했네... 헬스크림이 우릴 배신했다고. 호드를 지켜야 하는 대족장의 사명을 저버렸다고. 하지만 나즈그림은... 너무 충직했어... 긍지가 높았지.', `MaleText_loc4`='我试图告诉他……地狱咆哮背叛了我们大家，抛弃了对人民的责任。但纳兹戈林……太忠诚……太骄傲了。', `MaleText_loc5`='我試著告訴他...告訴他地獄吼背叛了我們，把自己身為大酋長對人民的責任拋棄了。但是納茲格寧姆...太忠心...太驕傲。', `MaleText_loc7`='Intenté decírselo... Que Grito Infernal nos traicionó, que ignoró su responsabilidad como Jefe de Guerra. Pero Nazgrim... era demasiado leal... demasiado orgulloso.' WHERE `ID`=76681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 헬스크림. 놈의 야망이 호드를 찢어놨어.', `MaleText_loc4`='该死的地狱咆哮。他的野心令部落四分五裂。', `MaleText_loc5`='該死的地獄吼。他的野心把部落撕裂了。', `MaleText_loc7`='Maldito Grito Infernal.  Su ambición hizo pedazos a nuestra Horda.' WHERE `ID`=76682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가게. 스랄을 찾고, 가로쉬를 끝내. 난 괜찮아.', `MaleText_loc4`='去找萨尔吧。结束这一切。我会活下来的。', `MaleText_loc5`='去吧，去找索爾。結束這一切，我會沒事的。', `MaleText_loc7`='Vayan, encuentren a Thrall.  Terminen con esto.  Yo viviré.' WHERE `ID`=76683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가서 가로쉬를 끝장내게, $n. 그리고 기억하게. 대지모신의 두 눈이 자네를 지켜보고 있네.', `MaleText_loc4`='快去吧，$n，去干掉加尔鲁什。记住，大地母亲在关注着你。', `MaleText_loc5`='快去吧，$n。了結卡爾洛斯。記得，大地之母正照看著你。', `MaleText_loc7`='Date prisa, $n. Acaba con Garrosh. Pero no lo olvides: la Madre Tierra te observa.' WHERE `ID`=76690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안쉬의 힘에 맹세컨대, 이 코르크론 버러지들은 여길 지날 수 없을 거요.', `MaleText_loc4`='我以安瑟的威能起誓，这些库卡隆杂种休想通过这里。', `MaleText_loc5`='我以安希之力起誓，這些柯爾克隆的幼龍將無法通過。', `MaleText_loc7`='Juro por el poder de An''she que esos malditos Kor''kron no pasarán.' WHERE `ID`=76691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신, 지고 있네요!', `FemaleText_loc4`='你死定了！', `FemaleText_loc5`='你輸定了!', `FemaleText_loc7`='¡Voy por ti!' WHERE `ID`=76692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코가 코르크론을 응가에 우끼해버릴 테니까 $n|1은;는; 리코의 부탁을 들어주겠어? 키린한테 가로쉬를 무찌른 게 리코라고 말해줘.', `MaleText_loc4`='里克会把这些库卡隆都干掉的。作为回报，$n能帮里克一个忙吗？你只要告诉琪麟，加尔鲁什是里克干掉的就行了。', `MaleText_loc5`='瑞可會把柯爾克隆打到褲子裡都是便便。也讓$n幫瑞可一個忙吧?告訴卡玲，是瑞可打扁卡爾洛斯的。', `MaleText_loc7`='Riko hará kraku a los Kor''kron en los mikos. $n hace favor a Riko a kambio. Tú dice a Kiryn ke Riko es el ke jeringa a Garrosh.' WHERE `ID`=76695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가... 졌다고?', `FemaleText_loc4`='我……输了？', `FemaleText_loc5`='我...輸了?', `FemaleText_loc7`='¿He perdido?' WHERE `ID`=76698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 좀 할 만하네!', `FemaleText_loc4`='这正是我想要的！', `FemaleText_loc5`='這才對嘛!', `FemaleText_loc7`='¡Así me gusta!' WHERE `ID`=76699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선조에게 맹세코 이 코르크론은 여길 지나지 못할 거예요. 가세요, $n 님. 가로쉬를 쓰러뜨리는 영광은 당신 몫입니다!', `FemaleText_loc4`='我以先祖的名义发誓，这些库卡隆休想通过此地。快去吧，$n，打倒加尔鲁什的荣誉就归你了！', `FemaleText_loc5`='我以先祖之名起誓，這些柯爾克隆無法通過。去吧，$n，親手打倒卡爾洛斯的榮耀將屬於你!', `FemaleText_loc7`='Juro por mis ancestros que los Kor''kron no pasarán. Ahora ve, $n. ¡El honor de derrotar a Garrosh es tuyo!' WHERE `ID`=76700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디 보자...', `FemaleText_loc4`='让我想想……', `FemaleText_loc5`='我們看看...', `FemaleText_loc7`='A ver...' WHERE `ID`=76701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 괜찮았어요!', `FemaleText_loc4`='打得好！', `FemaleText_loc5`='這招不錯!', `FemaleText_loc7`='¡Bien jugado!' WHERE `ID`=76702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해 보자고요!', `FemaleText_loc4`='来吧！', `FemaleText_loc5`='咱們來吧!', `FemaleText_loc7`='¡Vamos allá!' WHERE `ID`=76703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 비장의 무기가 있죠!', `FemaleText_loc4`='我还留了好几手呢！', `FemaleText_loc5`='我還有些招還沒出呢!', `FemaleText_loc7`='¡Tengo un as en la manga!' WHERE `ID`=76704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마나가 부족해! 망했다!', `FemaleText_loc4`='我的法力值不够了！噢，不！', `FemaleText_loc5`='我的法力不夠!天啊!', `FemaleText_loc7`='Me he quedado sin maná... ¡Oh, no!' WHERE `ID`=76705;
