UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 알겠다고요. 당신과 모험을 함께하지요. 딱 한 판만 더 하고요.', `MaleText_loc4`='好好，我这就跟你走。但让我再玩一盘。', `MaleText_loc5`='好啦，我會加入你的冒險。讓我再玩一場就好。', `MaleText_loc7`='Sí, sí, iré de aventuras contigo, pero antes déjame jugar otra partida.' WHERE `ID`=76725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 기분은 몇 년 만에 처음입니다!', `MaleText_loc4`='这是我近几年玩过的最好的游戏！', `MaleText_loc5`='我好幾年沒感覺到這麼棒了!', `MaleText_loc7`='¡Hacía años que no me sentía tan bien!' WHERE `ID`=76726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 카드 보이십니까? 저 드워프가 이걸 보면 깜짝 놀라서 의자에서 굴러떨어질걸요!', `MaleText_loc4`='看到这张牌了吗？它肯定能把那个矮人从椅子上打翻。', `MaleText_loc5`='看到這張牌了嗎?這張一定會把那個矮人打到連椅子都坐不穩!', `MaleText_loc7`='¿Ves esta carta? ¡Le va a dar una paliza al enano!' WHERE `ID`=76727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석이 어떻게 이 게임을 이렇게 잘하는 것 같나?이', `MaleText_loc4`='你说他怎么就打得那么好呢？', `MaleText_loc5`='你覺得他為什麼這麼會玩這個遊戲?', `MaleText_loc7`='¿Cómo es posible que se le dé tan bien?' WHERE `ID`=76728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 카드 보이나? 요건 몰랐을걸!', `MaleText_loc4`='看见这张牌了吗？他这次休想打败我！', `MaleText_loc5`='看到這張牌了嗎?他肯定會大吃一驚!', `MaleText_loc7`='¿Ves esta carta? ¡Esta no se la espera!' WHERE `ID`=76729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세코 내가 이길걸세!', `MaleText_loc4`='我会打败他的，我发誓！', `MaleText_loc5`='我一定能打敗他，我發誓!', `MaleText_loc7`='¡Te juro que puedo con él!' WHERE `ID`=76730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘닿는 데까지 도울게요, $n 님. 대신 가로쉬에게 가는 동안 맛있는 코르크론 시체를 많이 만들겠다고 약속해주세요.', `FemaleText_loc4`='我会尽力帮忙的，$n。你只要在追杀加尔鲁什的路上，顺手多留下几具美味的库卡隆尸体就行了。', `FemaleText_loc5`='我會盡可能提供協助，$n。只要你保證在去找卡爾洛斯的路上多製造一些好吃的柯爾克隆屍體。', `FemaleText_loc7`='Te ayudaré en lo que pueda, $n, pero prométeme que dejarás un rastro de deliciosos cadáveres Kor''kron de camino a Garrosh.' WHERE `ID`=76732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한텐 두뇌가 있고 너한텐 근육이 있지. 우리가 힘을 합치면 아름다운 대학살이 일어날 거야.', `MaleText_loc4`='我有脑子，你有力气。只要齐心协力，我们就能打个漂亮仗。', `MaleText_loc5`='我有腦袋，你有肌肉。我們只要合作，就能盡情的屠殺。', `MaleText_loc7`='Yo soy el cerebro, tú los músculos. Juntos desencadenaremos una masacre.' WHERE `ID`=76733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항구 방어선이 무너졌다! 코르크론, 후퇴해서 더 높은 지형으로 이동한다!', `MaleText_loc4`='港口防线崩溃了！库卡隆，后撤，到高地上去！', `MaleText_loc5`='碼頭的防禦被突破了!柯爾克隆，撤退到高處!', `MaleText_loc7`='¡Las defensas del puerto han caído! Kor''kron, ¡retírense a terreno elevado!' WHERE `ID`=76734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플레이어들이 남쪽 탑 대공포를 점령하였습니다!', `MaleText_loc4`='玩家控制了南部塔楼的防空炮台！', `MaleText_loc5`='玩家控制了南邊的防空砲塔!', `MaleText_loc7`='¡Los jugadores se han apoderado de la torreta antiaérea del sur!', `FemaleText_loc1`='플레이어들이 남쪽 탑 대공포를 점령하였습니다!', `FemaleText_loc4`='玩家控制了南部塔楼的防空炮台！', `FemaleText_loc5`='玩家控制了南邊的防空砲塔!', `FemaleText_loc7`='¡Los jugadores se han apoderado de la torreta antiaérea del sur!' WHERE `ID`=76735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r. 저는 감시자 메가나를 지키기로 맹세한 파수꾼입니다. 그녀는 제가... 아니, 우리들이 보기에 엄청난 재능을 가지고 있습니다. 그래서 무슨 일이 있더라도 그녀를 지켜야만 합니다.', `MaleText_loc4`='欢迎，$r。我是观察者麦佳娜的忠实守卫。她有着特殊的天赋，令我……呃，我们的领袖……十分欣赏，所以必须受到严密的保护。', `MaleText_loc5`='你好啊，$r。我將誓死護衛看守者梅佳娜。她有些特殊的能力是我...呃，我們的領袖...非常佩服的。我們必須謹慎地貼身保護她。', `MaleText_loc7`='Saludos, $r. Soy el protector jurado de la vigía Megana. Tiene dones especiales que admiro... eh, que nuestros líderes admiran... Y que hay que proteger cuidadosamente.' WHERE `ID`=76736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상인들은 용의 둥지 국수처럼 특이한 음식을 먹을 수 있다면 웃돈이라도 낼 거예요.', `FemaleText_loc4`='商人会愿意多花一些钱来品尝浇头比较多的面，如龙须汤面。', `FemaleText_loc5`='商人們會多花點錢在比較不一樣的東西上，像是龍巢湯麵。', `FemaleText_loc7`='Los mercaderes pagan un poco más por platos más variados, como la sopa de fideos Nido del Dragón.' WHERE `ID`=76737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='농사꾼들은 푸짐하고 맛있는 판다렌 보물 국수를 먹고 밭일의 피로를 푸는 걸 좋아하죠.', `FemaleText_loc4`='农夫在经过一天的辛勤耕作后，就需要分量十足的熊猫人八宝汤面来帮他们恢复精神。', `FemaleText_loc5`='農夫在一天的辛勤耕種後，會需要吃碗熊貓人國寶級湯麵來恢復精神。', `FemaleText_loc7`='Los granjeros necesitan algo nutritivo, como la sopa de fideos Tesoro Pandaren, para reponerse después de un duro día de trabajo en el campo.' WHERE `ID`=76738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 나 좀 도와줄래? 난 지금 내 몸을 찾고 있어. 이 동굴 어딘가에 있는데, 영혼의 세계에서만 찾을 수 있지. 날 도와줄 수 있으면 내게 말해줘.

하지만 조심해. 영원의 영혼들은 우릴 영혼의 세계 밖으로 쫓아낼 수 있어. 그리고 그러면 아무리 나라도 한동안 영혼의 세계로 널 들여보낼 수 없을 거야.', `MaleText_loc4`='好吧。我需要一些帮助……我在找我的身体。它就在这个山洞里的某处，但你只有在进入灵魂世界后才能看到它。如果你愿意帮忙，就告诉我一声。

但你要小心。永恒之灵能把我们赶出灵魂世界，如果那样的话，凭我的力量恐怕无法让我们马上再次进入灵魂世界。', `MaleText_loc5`='好吧，我需要幫忙...我在找我的身體。它就在這個洞穴裡面，但你只有在靈魂世界裡才能看到它。如果你願意幫我找出來，請跟我說。

但是要小心，永恆之魂能把我們踢出靈魂世界，如果我們被踢出去了，我的力量不足以立刻把我們帶回去。', `MaleText_loc7`='Verás, necesito ayuda... No encuentro mi cuerpo. Está en algún lado de esta cueva, pero solo se ve desde el mundo de los espíritus. Si quieres ayudarme, avísame.

Pero ten clara una cosa: los espíritus intemporales pueden echarnos del mundo de los espíritus, y si lo consiguen, no podremos volver a entrar hasta pasado un rato.' WHERE `ID`=76739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 세계에 들어갈 준비가 됐습니다.', `MaleText_loc4`='我做好进入灵魂世界的准备了。', `MaleText_loc5`='我準備好進入靈魂世界了。', `MaleText_loc7`='Estoy listo para entrar en el mundo de los espíritus.', `FemaleText_loc1`='영혼의 세계에 들어갈 준비가 됐어요.', `FemaleText_loc4`='我做好进入灵魂世界的准备了。', `FemaleText_loc5`='我準備好進入靈魂世界了。', `FemaleText_loc7`='Estoy lista para entrar en el mundo de los espíritus.' WHERE `ID`=76740;
