UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴수가! 바주비어스호는 너 따위에게 무너지지 않는다!', `MaleText_loc4`='这不可能！瓦祖维斯号怎么可能败在你这种人手上！', `MaleText_loc5`='這不可能!維蘇威號永遠不會敗給你們這些傢伙!', `MaleText_loc7`='¡No es posible! ¡Vazuvius nunca caería ante alguien como tú!' WHERE `ID`=76778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하요새가 뚫렸다! 분쇄기를 타고 침입자들을 찢어버려라!', `MaleText_loc4`='地下堡垒被攻破了！快去开动切割者，把这些入侵者撕成碎片！', `MaleText_loc5`='地下要塞被攻破了!快去伐木機那裡，把這些入侵者撕成碎片!', `MaleText_loc7`='¡Han entrado en el Búnker! ¡Monten en las trituradoras y hagan pedazos a los intrusos!' WHERE `ID`=76779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 세대 동안 나는 안개로 백성들을 보호했다네. 하지만 그 안개 너머에서 온 용사들을 볼 때마다 나는 내가 얼마나 잘못된 결정을 했는지 알게 되었지. 자네도 나처럼 판다리아가 주는 교훈을 명심하기 바라네.', `MaleText_loc4`='几代以来，我一直用迷雾保护着我的人民，但看着眼前的一个个勇士，我越来越意识到自己的错误。愿你和我一样，从潘达利亚的历史中得到教训。', `MaleText_loc5`='許多世代以來，我用迷霧保護了我的人民，但每當我見到眼前的每一位勇士，我都會更加理解到自己的錯誤。希望你能像我一樣學到潘達利亞的教誨。', `MaleText_loc7`='Protegí a mi pueblo con la niebla durante generaciones, pero con cada campeón que veo ante mí me doy cuenta de que estaba equivocado. Espero que aprendas las lecciones de Pandaria igual que yo. ' WHERE `ID`=76790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들과 이런 귀중한 시간을 보낼 수 있어 기쁘군. 다 자네 덕일세. 정말 고맙네.', `MaleText_loc4`='我很高兴能和我的儿子分享这一时刻。再次感谢你为我们所做的一切。', `MaleText_loc5`='我好高興能與我的兒子分享這一刻。再次感謝你為我們所做的一切。', `MaleText_loc7`='Me alegro muchísimo de compartir este momento con mi hijo. Gracias por todo lo que habéis hecho por nosotros.' WHERE `ID`=76791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들과 이런 귀중한 시간을 보낼 수 있어 기쁘군.', `MaleText_loc4`='我很高兴能和我的儿子分享这一时刻。', `MaleText_loc5`='我好高興能與我的兒子分享這一刻。', `MaleText_loc7`='Me alegro muchísimo de compartir este momento con mi hijo.' WHERE `ID`=76792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 하늘 호롱불 팔아요! 촛불에 불을 붙이면 바람이 없어도 하늘에 뜬다고요!', `MaleText_loc4`='卖魔法天灯啦！只要点亮蜡烛，它就能飞上天空，甚至不需要有风！', `MaleText_loc5`='快來買魔法的飛天燈籠!點燃蠟燭，它就會飄起來，而且不需要有風!', `MaleText_loc7`='¡Farolillos voladores mágicos a la venta! ¡Si enciendes la vela, flotan aunque no haga viento!' WHERE `ID`=76793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심장부 문 잠금 장치가 풀리자 강철 가는 소리가 통로에 울려 퍼집니다.', `MaleText_loc4`='随着枢纽大门的打开，削磨金属的刺耳噪音在大厅里回荡开来。', `MaleText_loc5`='在奧核之門上的鎖打開時，金屬交擊的聲響在大廳中迴盪。', `MaleText_loc7`='El chirrido de metal resuena por toda la sala cuando se abre la cerradura de la puerta del Nexo.' WHERE `ID`=76794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈들아, 내 휘하에는 무수한 코르크론이 있다! 지금 투항하면 고통스럽지 않게 빨리 죽여주지.', `MaleText_loc4`='你们这些蠢货，我手里有着无穷无尽的库卡隆物资！立即投降，我还能给你们一个痛快。', `MaleText_loc5`='我有無限的柯爾克隆軍隊可以指揮，你們這些笨蛋!現在投降，我還能給你們一個痛快。', `MaleText_loc7`='¡Estúpidos! Los Kor''kron que lidero son infinitos. Ríndanse ahora mismo y les daré una muerte rápida.' WHERE `ID`=76795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 스랄을 찾아서 헬스크림의 통치를 끝내야 하네.', `MaleText_loc4`='你必须找到萨尔，并推翻加鲁什的统治。', `MaleText_loc5`='你必須找到索爾，並終結地獄吼的統治。', `MaleText_loc7`='Deben encontrar a Thrall y poner fin al reino de Grito Infernal.' WHERE `ID`=76796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신들의 가호가 없어 당신은 오르도스의 사원에서 강제로 쫓겨납니다!', `MaleText_loc4`='没有至尊天神的庇护，你被驱逐出了斡耳朵圣殿！', `MaleText_loc5`='沒有了天尊的保護，你從歐朵斯的神殿中被強制傳送出去!', `MaleText_loc7`='Sin la protección de los celestiales, ¡te expulsan del templo de Ordos!', `FemaleText_loc1`='천신들의 가호가 없어 당신은 오르도스의 사원에서 강제로 쫓겨납니다!', `FemaleText_loc4`='没有至尊天神的庇护，你被驱逐出了斡耳朵圣殿！', `FemaleText_loc5`='沒有了天尊的保護，你從歐朵斯的神殿中被強制傳送出去!', `FemaleText_loc7`='Sin la protección de los celestiales, ¡te expulsan del templo de Ordos!' WHERE `ID`=76798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='같은 행동을 연속으로 여러 번 하면 작은 보너스를 받을 수 있어요. 손님을 여러 명 연속으로 앉히거나 음식을 여러 번 연속으로 배달하면 추가 점수를 받을 수 있어요!', `FemaleText_loc4`='连续执行相同的动作可以让你获得一些小奖励。尽量连续引导客人入座或者连续上菜来赢得额外的分数吧！', `FemaleText_loc5`='連續許多次完成同樣的動作將會使你獲得一些小小的額外獎勵。嘗試替許多顧客找到位子，或快速而連續地替他們上菜，就能獲得額外的點數!', `FemaleText_loc7`='Realizar una misma acción varias veces te ortorgará una pequeña bonificación. Prueba a sentar a muchos clientes o entregarles sus pedidos rápidamente para ganar puntos extra.' WHERE `ID`=76857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 거미 지뢰를 터트렸습니다!', `MaleText_loc4`='$n附近的蛛形地雷爆炸了！', `MaleText_loc5`='爬行者地雷在$n身上爆炸了!', `MaleText_loc7`='¡Una mina reptadora ha detonado bajo $n!' WHERE `ID`=76896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 역겨운 물결을 시전 중입니다!', `MaleText_loc4`='污秽水流的目标指向了你！', `MaleText_loc5`='你被施放了腐流!', `MaleText_loc7`='¡Te están lanzando Corriente hedionda!' WHERE `ID`=76897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군을 보내라! 돌진!', `MaleText_loc4`='让后备队上来！冲锋！', `MaleText_loc5`='派出後備兵!衝啊!', `MaleText_loc7`='¡Traigan a los refuerzos! ¡A la carga!', `FemaleText_loc1`='지원군을 보내라! 돌진!', `FemaleText_loc4`='让后备队上来！冲锋！', `FemaleText_loc5`='派出後備兵!衝啊!', `FemaleText_loc7`='¡Traigan a los refuerzos! ¡A la carga!' WHERE `ID`=76899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁군주 잴라가 |cFFFF0404|h코르크론 파괴전차|h|r에게 탑을 공격하라고 명령합니다!', `MaleText_loc4`='督军扎伊拉命令|cFFFF0404|h库卡隆投石车|h|r攻击塔楼！', `MaleText_loc5`='督軍札伊拉命令了一台|cFFFF0404|h柯爾克隆石毀車|h|r前去進攻砲台!', `MaleText_loc7`='¡La señora de la guerra Zaela ordena a un |cFFFF0404|hdemoledor Kor''kron|h|r que asalte la torre!', `FemaleText_loc1`='전쟁군주 잴라가 |cFFFF0404|h코르크론 파괴전차|h|r에게 탑을 공격하라고 명령합니다!', `FemaleText_loc4`='督军扎伊拉命令|cFFFF0404|h库卡隆投石车|h|r攻击塔楼！', `FemaleText_loc5`='督軍札伊拉命令了一台|cFFFF0404|h柯爾克隆石毀車|h|r前去進攻砲台!', `FemaleText_loc7`='¡La señora de la guerra Zaela ordena a un |cFFFF0404|hdemoledor Kor''kron|h|r que asalte la torre!' WHERE `ID`=76900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양조장이는 계속 삼촌의 맥주를 마셔요. 덕분에 더 강해졌다면 좋을 텐데!', `FemaleText_loc4`='小酒灵一直在喝叔叔的酒。但愿这能让它在战斗中凶猛一点！', `FemaleText_loc5`='小酒一直在喝叔叔釀的酒。希望這能讓他的戰鬥力變強!', `FemaleText_loc7`='Cerves no deja de beberse la cerveza del tío. ¡Espero que le dé fuerzas en el combate!' WHERE `ID`=76922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 멍청한 귀뚜라미 때문에 밤에 잠을 잘 수가 없어요. 삼촌한테는 비밀인데, 당신이 저 녀석을 밟아 줬음 좋겠어요!', `FemaleText_loc4`='那个白痴蟋蟀害得我整晚都睡不着觉。别告诉我叔叔，你帮我去踩死它吧！', `FemaleText_loc5`='那隻愚蠢的蟋蟀叫得我晚上無法入睡。我希望你把牠踩扁，但是不能跟叔叔說喔!', `FemaleText_loc7`='Ese grillo tonto no me deja dormir. No se lo digas al tío, ¡pero quiero que lo aplastes!' WHERE `ID`=76923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='톤사는 가끔 절 등에 태워 준답니다... 근데 애가 냄새가 좀 나긴 해요.', `FemaleText_loc4`='有时唐莎会让我骑到他背上……可他太臭了。', `FemaleText_loc5`='有時候童沙會背著我...但是他有點臭臭的。', `FemaleText_loc7`='A veces Tonsa me deja subirme a su lomo... Pero huele un poco mal.' WHERE `ID`=76924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도대체 왜 제 말을 안 듣는 건지 모르겠다니까요! 국수를 더 맛있게 만드는 방법을 알려 주려는 것뿐인데!', `FemaleText_loc4`='我也不知道他为什么就不肯听我的！我只想告诉他怎么才能把面条做得更好吃。', `FemaleText_loc5`='我不知道他為什麼不聽我的!我只是想跟他解釋怎樣才能讓他的麵更好吃。', `FemaleText_loc7`='¡No sé por qué no me escucha! Solo quiero explicarle cómo hacer que sus fideos sepan aún mejor...' WHERE `ID`=76925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노래요?', `MaleText_loc4`='歌谣？', `MaleText_loc5`='一首歌?', `MaleText_loc7`='¿Una canción?', `FemaleText_loc1`='노래요?', `FemaleText_loc4`='歌谣？', `FemaleText_loc5`='一首歌?', `FemaleText_loc7`='¿Una canción?' WHERE `ID`=76926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네! 우리가 배운 역사와 교훈을 모두 담은 노래 말이예요. 좋은 생각이지 않나요?$b$b하지만... 아직 완성된 건 아니예요. 차드릭이 요즘 멍한 채로 자주 있어서요. 혹시 제 휘장에 뭔가 묻었나요?', `FemaleText_loc4`='是的！一首关于传说，以及我们从中所得到的知识的歌谣。听起来很激动人心吧？$b$b不过……我们还在研究。查德里克最近似乎一直在分心。我的战袍上有什么脏东西吗？', `FemaleText_loc5`='是的，這首歌和傳說有關，還有我們能從中學到的教誨。聽起來很刺激，對吧?$b$b但是...我們還沒寫完。查德里克最近似乎很容易分心。我的外袍上有沾到什麼東西嗎?', `FemaleText_loc7`='¡Sí! Una canción sobre la historia y todo lo que podemos aprender de ella. ¿No te parece emocionante?$b$bPero... todavía estamos trabajando en ello. Últimamente Chadrik se distrae con mucha facilidad. ¿Tengo algo en el tabardo?' WHERE `ID`=76927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 배치하라! 방어선을 구축해!', `MaleText_loc4`='部署设备！建立防御带！', `MaleText_loc5`='準備儀器!建立陣地!', `MaleText_loc7`='¡Activen el equipamiento!  ¡Establezcan un perímetro!' WHERE `ID`=76929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 반갑네! 방금 지상을 거의 확보하고 왔는데, 진짜 싸움은 이 밑에서 벌어지고 있었군!', `MaleText_loc4`='噢，你们好，朋友们！我们已经差不多肃清了地面，看来真正的战斗还在下面！', `MaleText_loc5`='噢，哈囉朋友!我們已經差不多鞏固地面了，看來真正的戰鬥會在地底!', `MaleText_loc7`='Ah, ¡hola, amigos!  ¡Estamos a punto de asegurar la superficie, parece que la verdadera batalla será aquí abajo!' WHERE `ID`=76930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정마. 우리가 지켜줄 테니! 영웅들이여! 전진!', `MaleText_loc4`='别担心，我们会支援你们的！前进吧，英雄们！', `MaleText_loc5`='不用擔心，我們會掩護你們!前進吧，勇敢的英雄們!', `MaleText_loc7`='¡No se preocupen, nosotros los cubrimos!  ¡Avancen, héroes valientes!' WHERE `ID`=76931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전문 지식이 다른 곳에 필요해서, 난 이만! 가로쉬를 만나거든 노움 기술에 투자하지 않은 게 가장 큰 실수였다고 전해줘!', `MaleText_loc4`='英雄们，我得去其他地方支援了！如果你们见到加尔鲁什，记得告诉他，他应该投资侏儒科技才对！', `MaleText_loc5`='還有其他地方需要我的本領，英雄們!等你們看到卡爾洛斯，告訴他當初他早該投資在地精的科技上!', `MaleText_loc7`='¡Se requiere mi habilidad en otra parte, héroes! ¡Cuando vean a Garrosh, díganle que esto le pasa por no invertir en ingeniería gnómica!' WHERE `ID`=76932;
