UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사해서 다행이오. 계속할 준비 됐소?', `MaleText_loc4`='很高兴你们成功了。我们可以前进了吗？', `MaleText_loc5`='很高興你能來到這裡。準備好要繼續了嗎?', `MaleText_loc7`='Me alegro de que estén bien. ¿Seguimos adelante?', `FemaleText_loc1`='무사해서 다행이에요. 계속할 준비 되셨나요?', `FemaleText_loc4`='很高兴你们成功了。我们可以前进了吗？', `FemaleText_loc5`='很高興你能來到這裡。準備好要繼續了嗎?', `FemaleText_loc7`='Me alegro de que estén bien. ¿Seguimos adelante?' WHERE `ID`=76949;
