UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t 샤나가 당신에게 레이저를 발사합니다!', `MaleText_loc4`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t莎娜正在向你发射激光！', `MaleText_loc5`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t珊娜正在對你發射雷射!', `MaleText_loc7`='|TInterfaceIconsAbility_Siege_Engineer_Superheated.blp:20|t ¡Shanna te está disparando con su láser!' WHERE `ID`=76961;
