UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피에르는 정말 멋지지 않아요? 제 친구인 자르드가 만들어줬어요!', `FemaleText_loc4`='皮埃尔很厉害吧？是我的朋友贾德帮我做的！', `FemaleText_loc5`='皮耶很棒吧!我的朋友賈德替我做的!', `FemaleText_loc7`='¿A que Pierre es increíble? ¡Mi amigo Jard me lo construyó!' WHERE `ID`=76968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피에르를 훈련시키고 싶지만, 다치지 않을까 걱정돼요.', `FemaleText_loc4`='我想要训练他，可我又不想让他受伤害。', `FemaleText_loc5`='我想要訓練他，但是我不想他受傷。', `FemaleText_loc7`='Quiero entrenarlo, pero me da pena que le hagan daño...' WHERE `ID`=76969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피에르는 정말 착해요. 제게 요리도 해준답니다. 안타깝게도, 사람이 먹을만한 음식이 아니라 피에르가 안 볼때 몰래 버리곤 하죠.', `FemaleText_loc4`='他真的很好，还想帮我煮东西吃。可惜那些东西根本没法入口，我只能趁他不注意的时候都扔了。', `FemaleText_loc5`='他真的很好，還試著替我煮東西。可惜的是，煮的東西實在難以下嚥，我得趁他不注意的時候丟掉。', `FemaleText_loc7`='Es muy simpático y trata de prepararme comida. Por desgracia, no le sale nada comestible, así que tengo que tirarla cuando no mira...' WHERE `ID`=76970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금이 기회예요!', `FemaleText_loc4`='机会来了！', `FemaleText_loc5`='我的機會來了!', `FemaleText_loc7`='¡Esta es mi oportunidad!' WHERE `ID`=76988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 이런 건 한 번도 본 적이 없어요! 시합이 끝나면 엄청나게 많은 애완동물을 히료해줘야 할 것 같네요.', `FemaleText_loc4`='我从没见过类似的东西！等比武大会结束之后，恐怕有很多宠物需要我的治疗了。', `FemaleText_loc5`='我從沒見過像這樣的東西!我想等這個聯賽結束時，我得治療很多的寵物了。', `FemaleText_loc7`='¡Nunca había visto nada igual! Creo que tendré que sanar a muchas mascotas cuando acabe el torneo...' WHERE `ID`=77002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 죄송하지만 그럴 수 없어요! 시합 중에 애완동물을 치료하는 건 규칙에 어긋나거든요.', `FemaleText_loc4`='噢，不，我很抱歉，可我不能这么做！在比武大会期间治疗宠物是违反规则的。', `FemaleText_loc5`='噢，不，我很抱歉，但是不行!這違反了聯賽中不得治療寵物的規定。', `FemaleText_loc7`='Lo siento mucho, pero no puedo. Está prohibido sanar mascotas durante el torneo.' WHERE `ID`=77003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 가끔 내 실력이 놀랍소. 저기 추락하는 용을 보시오!', `MaleText_loc4`='有时候我觉得自己还不错。那条龙掉下来了！', `MaleText_loc5`='有時候我對自己都感到讚嘆。龍掉下來了!', `MaleText_loc7`='A veces me asombro a mí mismo. ¡Dragón derribado!' WHERE `ID`=77004;
