UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 정말 잘 처리해줬소. 이제 더 큰 문제를 해결할 준비가 되었소?', `MaleText_loc4`='那些火炮都哑火了。干得好，英雄。你做好解决这一切的准备了吗？', `MaleText_loc5`='做得不錯，你把砲台解決了，英雄。準備好要徹底解決一切了嗎?', `MaleText_loc7`='Buen trabajo con los cañones. ¿Acabamos con esto de una vez por todas?', `FemaleText_loc1`='대포를 정말 잘 처리해주셨어요. 이제 더 큰 문제를 해결할 준비가 되었나요?', `FemaleText_loc4`='那些火炮都哑火了。干得好，英雄。你做好解决这一切的准备了吗？', `FemaleText_loc5`='做得不錯，你把砲台解決了，英雄。準備好要徹底解決一切了嗎?', `FemaleText_loc7`='Buen trabajo con los cañones. ¿Acabamos con esto de una vez por todas?' WHERE `ID`=77014;
