UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배가 고프세요? 목이 마르세요? 심신이 지쳤나요? 우아한 스완이 다 해결해드릴게요!', `FemaleText_loc4`='饿了？渴了？还是累了？让优雅的斯万来照顾你吧！', `FemaleText_loc5`='餓了?渴了?累了?來讓優雅的史旺照顧你!', `FemaleText_loc7`='¿Tienes hambre? ¿Sed? ¿Cansancio? ¡Deja que Cisne Grácil te cuide!' WHERE `ID`=77025;
