UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아 최고의 국수만을 취급한다네!', `MaleText_loc4`='这里有全潘达利亚最美味的面条。', `MaleText_loc5`='你在這裡會嚐到整個潘達利亞最好吃的麵。', `MaleText_loc7`='Aquí vendemos los mejores fideos de todo Pandaria.' WHERE `ID`=77037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가게를 후원해준다면 정말 고맙겠네, 모험가여.', `MaleText_loc4`='感谢你的光顾，冒险者。', `MaleText_loc5`='你的大駕光臨，真是榮幸啊，冒險者。', `MaleText_loc7`='Sería un honor para mí contarte entre mis clientes.' WHERE `ID`=77038;
