UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 보시오! 무기를 두고 갔군.', `MaleText_loc4`='看这里！他丢下了自己的武器。', `MaleText_loc5`='看啊!他把武器留在這了。', `MaleText_loc7`='¡Miren! Dejó su arma.' WHERE `ID`=77040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈은 완전히 이성을 상실했소.', `MaleText_loc4`='看来他已经彻底疯了。', `MaleText_loc5`='這代表他的心智完全失常了。', `MaleText_loc7`='Esto significa que está totalmente trastornado.' WHERE `ID`=77041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 마찬가지요. 실바나스와 나도 볼진을 돕기 위해 병력을 보냈소.', `MaleText_loc4`='我们也一样。希尔瓦娜斯和我都派出舰队去支援沃金了。', `MaleText_loc5`='我們也是。希瓦娜斯和我都派了艦隊支援沃金的行動。', `MaleText_loc7`='De la misma forma, Sylvanas y yo hemos enviado barcos para apoyar la revolución de Vol''jin.' WHERE `ID`=77042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 그대는 호탕하군, 프라우드무어 여군주.', `MaleText_loc4`='我还是很高兴见到您的，普罗德摩尔女士。', `MaleText_loc5`='這一向是我的榮幸，普勞德摩爾女士。', `MaleText_loc7`='Siempre es un gusto verla, Lady Valiente.' WHERE `ID`=77043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여, 따라오시오. 우리의 "대족장님"과 결판을 낼 시간이오.', `MaleText_loc4`='勇士们，跟我来。该去找我们的……“酋长”算总账了。', `MaleText_loc5`='勇士們，跟我來。是時候解決跟我們...「大酋長」之間的恩怨了。', `MaleText_loc7`='Vengan conmigo. Es hora de ajustar cuentas con nuestro... "Jefe de Guerra".' WHERE `ID`=77044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림의 오만함이 결국 마지막 샤를 풀어줬군요. 놀랍진 않네요.', `FemaleText_loc4`='看来地狱咆哮的傲慢放出了最后一头煞魔。我早料到了。', `FemaleText_loc5`='看來地獄吼的傲慢放出了最後一個煞。我一點都不驚訝。', `FemaleText_loc7`='Así que la arrogancia de Grito Infernal desató al último sha. No me extraña.' WHERE `ID`=77045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피의 울음소리군요.', `FemaleText_loc4`='血吼。', `FemaleText_loc5`='血吼之斧。', `FemaleText_loc7`='Aullavísceras.' WHERE `ID`=77046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새삼스럽지도 않네요, 섭정이여. 바리안 폐하의 함대가 지금 오그리마로 향하고 있어요.', `FemaleText_loc4`='这并不稀奇，摄政王。如今，乌瑞恩国王的舰队正驶向奥格瑞玛。', `FemaleText_loc5`='這不是新聞，攝政王。烏瑞恩國王的艦隊在此刻正駛向奧格瑪。', `FemaleText_loc7`='No es ninguna novedad, señor regente. La flota del Rey Wrynn está convergiendo en Orgrimmar en este momento.' WHERE `ID`=77047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경고하겠어요, 로르테마르. 얼라이언스는 오그리마를 공격하여 반드시 헬스크림을 무너뜨릴 겁니다. 우리 앞을 가로막지 않는 게 좋을 거예요.', `FemaleText_loc4`='我警告你，洛瑟玛。联盟已经包围了那座城市，我们要消灭地狱咆哮。你的人最好别妨碍我们。', `FemaleText_loc5`='我警告你，洛索瑪。聯盟將攻擊奧格瑪，而我們必會擊敗地獄吼。你們的人最好別擋住我們的路。', `FemaleText_loc7`='Te lo advierto, Lor''themar. La Alianza está asediando la ciudad y destruiremos a Grito Infernal. Será mejor que tu gente se quite de nuestro camino.' WHERE `ID`=77048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문을 통과하세요, 영웅들이여. 오그리마 공성전이 시작됩니다!', `FemaleText_loc4`='英雄们，穿过传送门！围攻奥格瑞玛的战役开始了！', `FemaleText_loc5`='來吧，英雄們!穿過傳送門!開始奧格瑪的圍城之戰!', `FemaleText_loc7`='¡Vengan, héroes, atraviesen el portal! ¡Que comience el asedio de Orgrimmar!' WHERE `ID`=77049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 투영이 폭발합니다!', `MaleText_loc4`='%s的投影爆炸了！', `MaleText_loc5`='%s的投影爆炸了!', `MaleText_loc7`='¡La proyección de %s explota!', `FemaleText_loc1`='%s의 투영이 폭발합니다!', `FemaleText_loc4`='%s的投影爆炸了！', `FemaleText_loc5`='%s的投影爆炸了!', `FemaleText_loc7`='¡La proyección de %s explota!' WHERE `ID`=77050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족장들의 식사처럼 성대하게! 야운골 국수!', `MaleText_loc4`='野牛人鲜辣面！酋长才能享用的美食！', `MaleText_loc5`='像酋長一樣的盛宴!揚古風味湯麵!', `MaleText_loc7`='¡Fideos yaungol! ¡UN BANQUETE DIGNO DE UN GRAN JEFE!' WHERE `ID`=77051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밋밋하고 맛도 없는 국수를 왜 드십니까? 야운골 방식을 시도해보세요!', `MaleText_loc4`='那种清汤寡水的面有什么好吃的？来尝尝野牛人鲜辣面吧！', `MaleText_loc5`='為什麼要忍受下等、無味的麵呢?試試揚古的風味吧!', `MaleText_loc7`='¿Por qué conformarte con fideos sosos y pasados? ¡Prueba el estilo yaungol!' WHERE `ID`=77052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매콤하고 화끈하게! 야운골 국수를 드셔보십시오!', `MaleText_loc4`='新鲜热辣，分量十足！快来尝尝野牛人鲜辣面吧！', `MaleText_loc5`='麻辣爽利!試試揚古風味湯麵!', `MaleText_loc7`='¡Picantes y nutritivos! ¡Fideos yaungol!' WHERE `ID`=77053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대담한 맛! 대담한 열기! 그 어떤 국수도 따라할 수 없습니다!', `MaleText_loc4`='又鲜又辣！无与伦比的美味！', `MaleText_loc5`='風味獨特，熱騰騰的湯麵!其他的麵條無法比擬!', `MaleText_loc7`='¡Llenos de sabor, llenos de picor! ¡No se parece a ningún otro fideo!' WHERE `ID`=77054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이국적이고, 좋은 향기가 가득하다네! 자네의 몸과 영혼을 치유할 약주일세!', `MaleText_loc4`='芬芳馥郁、强身提神的异域美酒！', `MaleText_loc5`='獨特，誘人，讓你身心都無比舒暢的酒!', `MaleText_loc7`='Exótico y aromático: ¡este brebaje es bueno para el cuerpo y para el espíritu!' WHERE `ID`=77055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐린빛 호박석 맥주라네! 와서 마셔보게!', `MaleText_loc4`='荧光琥珀酒！快来尝尝吧！', `MaleText_loc5`='閃光琥珀酒!來嚐嚐看!', `MaleText_loc7`='¡Brebaje de ámbar fulgurante! ¡Ven a probarlo!' WHERE `ID`=77056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 척추에서 공수해온 강렬한 호박석 맥주!', `MaleText_loc4`='来自蟠龙脊之外的琥珀美酒！', `MaleText_loc5`='來自蟠龍脊彼端的精釀琥珀酒!', `MaleText_loc7`='¡Cerveza de ámbar deliciosa de más allá del Espinazo del Dragón!' WHERE `ID`=77057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘도 없는 독특한 맥주를 마셔보게나! 활기와 만족감을 한 번에 느낄 수 있는... 호박석 맥주라네!', `MaleText_loc4`='快来尝尝真正的独家美酒吧！绝对提神、过瘾的……琥珀酒！', `MaleText_loc5`='試試真正獨特的酒!提振精神，讓人無比滿足的...琥珀酒!', `MaleText_loc7`='¡Atrévete con un brebaje realmente único! ¡Vigorizante y satisfactoria... cerveza de ámbar!' WHERE `ID`=77058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 수액 맛이 끝내주는군요.', `MaleText_loc4`='关键就在于里面的树脂。', `MaleText_loc5`='樹汁的最佳狀態。', `MaleText_loc7`='La savia es lo mejor que hay.' WHERE `ID`=77059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='김 나는 염소 국수! 냄새도 좋답니다!', `MaleText_loc4`='热气羊肉面！最好吃的面！', `MaleText_loc5`='第一名的熱氣羊湯麵!', `MaleText_loc7`='Fideos de cabra al vapor: ¡son LOS NÚMERO UNO!' WHERE `ID`=77060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국수로 배를 채우러 오세요! 아주 맛있어요!', `MaleText_loc4`='快来吃碗面垫垫肚子吧！好吃的面！', `MaleText_loc5`='來用湯麵填飽肚子吧，是的!非常好吃的湯麵!', `MaleText_loc7`='¡Vengan a comer fideos hasta más no poder! ¡Son estupendos!' WHERE `ID`=77061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='김 나는 염소 국수! 최고예요!', `MaleText_loc4`='热气羊肉面！最美味的面！', `MaleText_loc5`='熱氣羊湯麵!最棒的!', `MaleText_loc7`='¡FIDEOS DE CABRA AL VAPOR! ¡Son los mejores!' WHERE `ID`=77062;
