UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가. 나는 샤오하오라 하네. 천신들의 지혜를 탐구하기 위해 왔는가?', `MaleText_loc4`='你好，我是少昊。你是来聆听至尊天神教诲的吗？', `MaleText_loc5`='你好，我是紹昊。你來傾聽天尊們的智慧之言嗎?', `MaleText_loc7`='Saludos. Soy Shaohao. ¿Has venido para escuchar los sabios consejos de los celestiales?' WHERE `ID`=77065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최고를 원한다면, 이곳으로 오세요!', `FemaleText_loc4`='最美味的食物，别光看不尝啦！', `FemaleText_loc5`='要吃最好吃的食物，就在這裡!', `FemaleText_loc7`='¡No busques más! ¡La mejor comida está aquí!' WHERE `ID`=77068;
