UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 어떤 요리도 완벽하게 익힌 제 솜씨를 보세요!', `FemaleText_loc4`='没有我不会做的菜！快来尝尝吧！', `FemaleText_loc5`='世界上沒有我不會做的菜!來吃吃看!', `FemaleText_loc7`='¡No existe plato que yo no haya dominado! ¡Ven a comer!' WHERE `ID`=77071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맛 좋은 음식은 물론, 섬의 특산물을 이용한 진귀한 먹거리도 있어요!', `FemaleText_loc4`='美味的食物，刚出锅的海岛佳肴！', `FemaleText_loc5`='好吃的菜，還有新鮮出爐的海島美食!', `FemaleText_loc7`='Platos sabrosos, delicias propias de la isla, ¡todo recién hecho!' WHERE `ID`=77073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 하늘 호롱불 팔아요!', `MaleText_loc4`='卖魔法天灯啦！', `MaleText_loc5`='快來買魔法的飛天燈籠!', `MaleText_loc7`='¡Farolillos voladores mágicos a la venta!' WHERE `ID`=77074;
