UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용용주 한 번 드셔보시렵니까? 용의 기운이 솟아난다고요!', `MaleText_loc4`='快来喝一杯巨龙P.I.E.吧！它能让你身体强健，龙精虎猛！', `MaleText_loc5`='敢喝龍之獨飲嗎?這會讓你的胸口長毛，還讓你的胸毛上也長毛!', `MaleText_loc7`='¡Atrévete a beber P.E.D.O. de dragón! ¡Hará que te crezca pelo en el pelo del pecho!' WHERE `ID`=77080;
