UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 어이! 어서 오세요, 맛 좋은 국수가 준비됐어요!', `MaleText_loc4`='嘿嘿！快来尝尝好吃的面条吧！', `MaleText_loc5`='嘿，嘿!來這裡，吃碗好吃的湯麵!', `MaleText_loc7`='¡Oye, tú! Ven, ¡tengo unos fideos para chuparse los dedos!' WHERE `ID`=77085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강물 방식 국수입니다. 가장 싱싱한 생선들로 요리했습니다.', `MaleText_loc4`='河鲜面，只用最新鲜河鱼烹制。', `MaleText_loc5`='靜河風味湯麵，只用最鮮的魚!', `MaleText_loc7`='¡Fideos a la torrentera! Se elaboran solo con el pescado más fresco.' WHERE `ID`=77088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조화로운 강 국수를 드셔보십시오. 결코 실망하지 않으실 겁니다.', `MaleText_loc4`='请来尝尝我的杂烩河鲜面吧，绝对不会让你失望。', `MaleText_loc5`='來嚐嚐我的靜河冷湯麵。你絕不會失望。', `MaleText_loc7`='Prueba mis fideos del río armonioso, por favor. No te decepcionarán.' WHERE `ID`=77089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 낚은 싱싱한 생선입니다! ...아마 싱싱할 겁니다. 이 섬이 원체 별나긴 하지만요.', `MaleText_loc4`='刚出水还不到一小时的新鲜河鱼！……好像是吧？都怪这该死的岛。', `MaleText_loc5`='鮮魚，一個小時內的鮮魚!...應該是一個小時吧?該死的島。', `MaleText_loc7`='¡Pescado fresco! ¡Atrapado hace menos de una hora! Bueno, eso creo... En esta isla nunca se sabe...' WHERE `ID`=77090;
