UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조계의 황제, 스톰스타우트입니다!', `MaleText_loc4`='风暴烈酒：酒中帝王！', `MaleText_loc5`='風暴烈酒:釀造之皇!', `MaleText_loc7`='Cerveza de Trueno: ¡el brebaje ejemplar!' WHERE `ID`=77094;
