UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주의 모든 것을 통달한 스톰스타우트 가문입니다!', `MaleText_loc4`='风暴烈酒：美酒中的美酒！', `MaleText_loc5`='風暴烈酒:這才是美酒!', `MaleText_loc7`='Cerveza de Trueno: los mejores brebajes.' WHERE `ID`=77096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간만 내세요. 맥주는 제가 준비하겠습니다! 스톰스타우트 맥주!', `MaleText_loc4`='如果你有空，就来尝尝我们的美酒吧。风暴烈酒！', `MaleText_loc5`='只要你有時間，我們就有酒。風暴烈酒!', `MaleText_loc7`='Si tú tienes tiempo, nosotros tenemos brebajes. ¡Cerveza de Trueno!' WHERE `ID`=77097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트가 무슨 뜻이냐고요? 판다렌어로 "맥주"라는 뜻이지요.', `MaleText_loc4`='风暴烈酒，熊猫人的“啤酒”。', `MaleText_loc5`='風暴烈酒。熊貓人的「啤酒」。', `MaleText_loc7`='Cerveza de Trueno. Es como se dice "cerveza" en pandaren.' WHERE `ID`=77098;
