UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 술도 녹옥 맥주의 대담한 맛을 능가할 수 없다네!', `MaleText_loc4`='绿石佳酿，一口难忘！', `MaleText_loc5`='沒有酒能跟綠石酒的風味比擬!', `MaleText_loc7`='¡No hay nada como el sabor del brebaje de Verdemar!' WHERE `ID`=77102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 자네! 이리 와서 녹옥 맥주 맛 좀 보게나!', `MaleText_loc4`='你！过来尝尝我的绿石佳酿吧！', `MaleText_loc5`='喂!來試試綠石酒吧!', `MaleText_loc7`='¡Eh, tú! ¡Ven a probar el brebaje de Verdemar!' WHERE `ID`=77103;
