UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 악몽에서 나가시겠습니까?', `MaleText_loc4`='想要离开这个噩梦了吗？', `MaleText_loc5`='你想要離開這場夢靨嗎?', `MaleText_loc7`='¿Te gustaría abandonar esta pesadilla?' WHERE `ID`=77128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌려보내 주십시오.', `MaleText_loc4`='请送我回去。', `MaleText_loc5`='帶我回去。', `MaleText_loc7`='Llévame de vuelta.', `FemaleText_loc1`='돌려보내 주세요.', `FemaleText_loc4`='请送我回去。', `FemaleText_loc5`='帶我回去。', `FemaleText_loc7`='Llévame de vuelta.' WHERE `ID`=77129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌은 이기면 맥주를 한 통 가져와서 마시고, 지면 두 통 가져와서 마셔요. 그러니까 결국 삼촌은 항상 이기는 거라고 할 수 있죠!', `FemaleText_loc4`='叔叔要是赢了，就会喝一桶酒；要是输了，那就要喝两桶。所以我猜他还是赢了！', `FemaleText_loc5`='叔叔帶了酒，如果贏了喝一桶，如果輸了喝兩桶。所以不管怎樣，他最終還是算是贏的!', `FemaleText_loc7`='El tío compró un barril para beber si ganaba y dos si perdía. Así que supongo que al final ganó.' WHERE `ID`=77138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<니우짜오가 긍정의 의미로 고개를 끄덕입니다.>', `MaleText_loc4`='<砮皂赞许地向你点点头。>', `MaleText_loc5`='<怒兆對你讚賞地點頭。>', `MaleText_loc7`='<Niuzao te mira y asiente, complacido.>' WHERE `ID`=77142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 자네가 이룬 일은 앞으로 수천 년간 판다리아를 변화시킬 걸세.$b$b고맙네, 영웅이여. 나는 전승지기로서 대대로 자네의 이야기를 널리 전하겠네.', `MaleText_loc4`='你今天的壮举将决定潘达利亚在未来几千年中的面貌。$b$b谢谢你，英雄。游学者将会世代传颂你的故事。', `MaleText_loc5`='你今天做到的一切會在未來數千年當中深遠地影響潘達利亞大陸。$b$b謝謝你，英雄。博學行者們將會一代一代地傳頌你的故事。', `MaleText_loc7`='Lo que has logrado hoy cambiará la faz de Pandaria en los milenios futuros.$B$BGracias. Los eremitas contarán tu historia de generación en generación.' WHERE `ID`=77143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 웅덩이를 만들어 내던 타락이 마지막 물의 수호병과 함께 사라지자 조용한 울림도 멈춥니다.', `MaleText_loc4`='随着最后一位液态防御者的死亡，柔和的嗡鸣声停止了，腐化物也不再生成新的软泥怪。', `MaleText_loc5`='在最後的元水防衛者死亡時，輕聲的嗡鳴停了，一直在產生軟泥的腐化也隨之散去。', `MaleText_loc7`='Un suave murmullo cesa cuando la corrupción que creaba nuevos charcos se desvanece tras la muerte del último defensor acuoso.' WHERE `ID`=77144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철파수병! 내게 오라!', `MaleText_loc4`='铁甲哨兵！支援我！', `MaleText_loc5`='鐵哨兵!來我這裡!', `MaleText_loc7`='¡Centinelas férreos! ¡Conmigo!' WHERE `ID`=77152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜서시오, 형제들이여. 우린 헬스크림과 이야기를 해야 하오.', `MaleText_loc4`='请让开，兄弟们。我们必须和地狱咆哮谈谈。', `MaleText_loc5`='別擋路，兄弟們。我們必須跟地獄吼交談。', `MaleText_loc7`='Apártense, hermanos. Tenemos que hablar con Grito Infernal.' WHERE `ID`=77153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에는 아무도 못 들어갑니다. 당신도 마찬가지입니다, 주술사.', `MaleText_loc4`='谁都不准进入城市。包括你，萨满。', `MaleText_loc5`='沒有人能進入這座城市，即使是你也不行，薩滿。', `MaleText_loc7`='Nadie puede entrar en la ciudad. Ni siquiera tú, chamán.', `FemaleText_loc1`='도시에는 아무도 못 들어갑니다. 당신도 마찬가지입니다, 주술사.', `FemaleText_loc4`='谁都不准进入城市。包括你，萨满。', `FemaleText_loc5`='沒有人能進入這座城市，即使是你也不行，薩滿。', `FemaleText_loc7`='Nadie puede entrar en la ciudad. Ni siquiera tú, chamán.' WHERE `ID`=77154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님? 바로크 님? 여기엔 무슨 일이십니까?', `MaleText_loc4`='萨尔？萨鲁法尔？你们来干什么？', `MaleText_loc5`='索爾?瓦洛克?你們來這裡做什麼?', `MaleText_loc7`='¿Thrall? ¿Varok? ¿Qué los trae aquí?' WHERE `ID`=77155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘과 명예를. 우리는 가로쉬와 이야기하러 왔네. 아직 평화를 지킬 수 있을지도 모르네.', `MaleText_loc4`='力量和荣誉，将军。我们是来找加尔鲁什谈判的。这样或许还有一线和平的希望。', `MaleText_loc5`='力量與榮耀，將軍。我們來與卡爾洛斯談判。也許還有和平解決的希望。', `MaleText_loc7`='Fuerza y honor, General. Venimos a hablar con Garrosh. Puede que aún haya esperanza para la paz.' WHERE `ID`=77156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만...', `MaleText_loc4`='可是……', `MaleText_loc5`='不過...', `MaleText_loc7`='Pero...', `FemaleText_loc1`='하지만...', `FemaleText_loc4`='可是……', `FemaleText_loc5`='不過...', `FemaleText_loc7`='Pero...' WHERE `ID`=77157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론! 전선에 너희 힘이 필요하다!', `MaleText_loc4`='库卡隆！都上前线去！', `MaleText_loc5`='柯爾克隆!前線需要你們!', `MaleText_loc7`='¡Kor''kron, se les necesita en el frente!' WHERE `ID`=77158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장!', `MaleText_loc4`='快！', `MaleText_loc5`='馬上!', `MaleText_loc7`='¡AHORA!' WHERE `ID`=77159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아시다시피 저는 두 분의 안전을 보장할 수 없습니다... 가로쉬 님의 반응도요.', `MaleText_loc4`='你们知道的，我无法保证你们的安全……以及加尔鲁什的反应。', `MaleText_loc5`='你知道我無法保證你們的安全...或卡爾洛斯會有什麼回應。', `MaleText_loc7`='Sabes que no puedo garantizar tu seguridad... ni la reacción de Garrosh.' WHERE `ID`=77160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르, 형제들이여.', `MaleText_loc4`='Lok''tar Ogar，兄弟们。', `MaleText_loc5`='Lok''tar Ogar，兄弟們。', `MaleText_loc7`='Lok''tar Ogar, hermanos.' WHERE `ID`=77161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야호!!!', `MaleText_loc4`='耶！！！', `MaleText_loc5`='啊哈!', `MaleText_loc7`='¡Yiiijaaaa!' WHERE `ID`=77177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 아세요? 저는 이거 처음 조종해봐요! 우와앗!', `MaleText_loc4`='我在想什么呢？我没练习过这种装备！啊哈！！', `MaleText_loc5`='我在想什麼?我還沒受過這種裝備的訓練!啊啊啊啊!!!', `MaleText_loc7`='¿Pero en qué estoy pensando? ¡No he estudiado este tipo de equipo! ¡Aaaaaah!' WHERE `ID`=77178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거워! 너무 뜨거워!', `MaleText_loc4`='好热！好热！好热！', `MaleText_loc5`='熱，熱，熱!!', `MaleText_loc7`='¡QUEMA! ¡QUEMA! ¡QUEMA!' WHERE `ID`=77179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고. 탑승자가 연소하고 있습니다. 안전 절차를 수행해주십시오.', `MaleText_loc4`='警告。你正在燃烧。请执行安全程序。', `MaleText_loc5`='警告。你正在燃燒。請執行安全程序。', `MaleText_loc7`='Alerta. Te estás quemando. Ejecuta procedimientos de seguridad.' WHERE `ID`=77180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 모두들! 한바탕 놀아볼 시간이야!', `MaleText_loc4`='好吧，伙计们，让我们疯狂一把吧。', `MaleText_loc5`='好吧小子們，咱們瘋狂一下吧。', `MaleText_loc7`='Muy bien, chicos, ¡vamos con todo!' WHERE `ID`=77181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸자 가동!', `MaleText_loc4`='歼灭者已激活！', `MaleText_loc5`='殲滅者已啟動!', `MaleText_loc7`='¡Aniquilador activado!' WHERE `ID`=77182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대걸레가 필요하겠는데요! 정말 큰 걸로요!', `MaleText_loc4`='我们这儿需要一个拖把！', `MaleText_loc5`='我們這裡會需要一支拖把!', `MaleText_loc7`='¡Vamos a necesitar un trapeador!' WHERE `ID`=77183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 정말 삐까번쩍하군요!', `MaleText_loc4`='哇！这玩意儿真是让人难以置信，太耀眼了！', `MaleText_loc5`='哇賽!這玩意兒可真是亮晶晶!', `MaleText_loc7`='¡Vaya! ¡Eso es una cosita brillante increíble!' WHERE `ID`=77184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론이 어떤 장난감을 만들고 있었는지 볼까요!', `MaleText_loc4`='让我们看看库卡隆造了些什么玩意儿吧。', `MaleText_loc5`='咱們來看看柯爾克隆都在製造什麼玩具。', `MaleText_loc7`='Veamos qué clase de juguetes han estado construyendo los Kor''kron.' WHERE `ID`=77185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청소 좀 해볼까! 파멸자를 작동시켜!', `MaleText_loc4`='横扫时刻！激活歼灭者！', `MaleText_loc5`='該清理清理了!啟動殲滅者!', `MaleText_loc7`='¡Hora de hacer limpieza! ¡Activen el aniquilador!' WHERE `ID`=77186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍멍!', `MaleText_loc4`='哇！', `MaleText_loc5`='呼呼!', `MaleText_loc7`='¡Vaya!' WHERE `ID`=77187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망토에서 비취빛 안개가 피어오르고 천신의 축복이 느껴집니다.', `MaleText_loc4`='当你的斗篷在翠绿色的雾气中翻滚时，你感受到了至尊天神的祝福。', `MaleText_loc5`='你的披風翻騰著翠玉之霧，使你感到了天尊的祝福之力。', `MaleText_loc7`='Sientes la bendición de los Celestiales mientras tu capa ondea con niebla de jade.', `FemaleText_loc1`='망토에서 비취빛 안개가 피어오르고 천신의 축복이 느껴집니다.', `FemaleText_loc4`='当你的斗篷在翠绿色的雾气中翻滚时，你感受到了至尊天神的祝福。', `FemaleText_loc5`='你的披風翻騰著翠玉之霧，使你感到了天尊的祝福之力。', `FemaleText_loc7`='Sientes la bendición de los Celestiales mientras tu capa ondea con niebla de jade.' WHERE `ID`=77210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신한테는 할 말이 없습니다.', `MaleText_loc4`='我跟你没什么好说的，$r。', `MaleText_loc5`='我跟你沒什麼好說的，$r。', `MaleText_loc7`='No tengo nada que decirte, $r.', `FemaleText_loc1`='당신한테는 할 말이 없어요.', `FemaleText_loc4`='我跟你没什么好说的，$r。', `FemaleText_loc5`='我跟你沒什麼好說的，$r。', `FemaleText_loc7`='No tengo nada que decirte, $r.' WHERE `ID`=77347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 $r에겐 할 말이 없다. 너희 동족은 책임져야 할 일이 많지. 하지만 어쩌면 이게 새로운 시작일 수도 있겠군.', `MaleText_loc4`='我跟你没什么好说的，$r。你们的人要为许多事情负责。但这或许能成为一个新的开始。', `MaleText_loc5`='我跟你沒什麼好說的，$r。你們還有很多問題需要回答。但也許這是一個新的開始。', `MaleText_loc7`='No tengo nada que decirte, $r. Tu pueblo tiene mucho por lo que responder. Pero puede que esto sea un nuevo comienzo.' WHERE `ID`=77348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 고맙다. 그대와 그대의 동료들이 얼라이언스 창 끝의 촉이 되었다. 그대가 판다리아를 탐사하고, 골짜기를 확보하고, 궁극적으로 가로쉬의 요새를 함락시켰기에 오늘 우리가 승리할 수 있었다.$b$b우리가 여기서 거둔 승리로 칼림도어에서의 전쟁은 중단되겠지만, 평화의 시기에도 이곳과 우리의 고향, 다른 곳에서도 아직 해야 할 일이 많다.', `MaleText_loc4`='谢谢你，英雄。你和你的同伴们都是联盟的尖刀：你探索潘达利亚、保卫锦绣谷，以及突袭加尔鲁什老巢的一系列行动为我们带来了这次胜利。$b$b我们在这里的胜利将使卡利姆多的纷争落下帷幕，但即使在和平时期，我们在这里、在家乡、在全世界，都还有许多事情要做。', `MaleText_loc5`='英雄，謝謝你。你和你的同伴們是聯盟的鋒利的刀刃:探索潘達利亞、保障恆春谷的安全，最後成功攻破卡爾洛斯的要塞，多虧了這些努力才成就最後的勝利。$b$b這場勝利也結束了卡林多的爭戰，但即使在回歸和平之後，還是有許多未完成的事情，無論在這裡、在家鄉，還是其他地方。', `MaleText_loc7`='Gracias, adalid. Tus compañeros y tú habéis sido el filo de la espada de la Alianza. Vuestro trabajo explorando Pandaria, tomando el valle y, finalmente, asaltando el bastión de Garrosh, ha hecho posible esta victoria.$b$bNuestro triunfo en esta tierra acabará con la lucha en Kalimdor, pero incluso en tiempos de paz hay muchas cosas que hacer: aquí, de vuelta en nuestro hogar y en el resto del mundo.' WHERE `ID`=77349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 얼라이언스가 해야 할 일은 뭡니까?', `MaleText_loc4`='联盟接下来该怎么办？', `MaleText_loc5`='聯盟下一個目標是什麼?', `MaleText_loc7`='¿Qué hará ahora la Alianza?', `FemaleText_loc1`='앞으로 얼라이언스가 해야 할 일은 뭔가요?', `FemaleText_loc4`='联盟接下来该怎么办？', `FemaleText_loc5`='聯盟下一個目標是什麼?', `FemaleText_loc7`='¿Qué hará ahora la Alianza?' WHERE `ID`=77350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 계속 싸우지 않는 겁니까?', `MaleText_loc4`='为什么不继续打下去？', `MaleText_loc5`='為什麼不繼續奮戰?', `MaleText_loc7`='¿Por qué no seguir luchando?', `FemaleText_loc1`='왜 계속 싸우지 않는 거죠?', `FemaleText_loc4`='为什么不继续打下去？', `FemaleText_loc5`='為什麼不繼續奮戰?', `FemaleText_loc7`='¿Por qué no seguir luchando?' WHERE `ID`=77351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우린 그 어느 때보다 단결되었다. 우리는 칼림도어에 안전을 되찾고, 억압을 종식시켰으며, 대해를 사이에 둔 양 대륙에서 너무나 많은 피를 쏟아낸 이 전쟁에 종지부를 찍었다.$b$b나는 이제, 평화를 다지기 위해 테라모어 근처에 주둔지를 세우려 한다. 우리는 길니아스의 땅에서 역병을 정화시킬 방법을 조사하여 그들이 다시 일어설 수 있게 도와야 한다. 또한 우리는 실바나스를 견제해야 한다.$b$b이제부터 얼라이언스는 주도적으로 움직인다. 절대로, 헬스크림과 같은 족속이 다시 나타나서는 안 된다.', `MaleText_loc4`='我们如今正空前的团结。我们为卡利姆多的人民带来了安全，终止了封锁，并结束了这场令大洋两岸无数人民流血牺牲的战争。$b$b现在，我们该致力于恢复和平。我打算在塞拉摩附近建立一座军营。我们需要研究如何净化吉尔尼恩的瘟疫，以便他们重建家园。我们必须遏制希尔瓦娜斯。$b$b从今往后，联盟将采取先发制人的策略，绝不会再让第二个地狱咆哮出现。', `MaleText_loc5`='我們從未如此團結強大。我們讓卡林多的人民回歸安定的生活，撤除了封鎖線，結束了多年來血濺東西邊海岸的全面爭戰。$b$b當務之急是維持眼下的和平。我想要在塞拉摩派駐軍隊。我們需要調查吉爾尼斯瘟疫淨化的狀況是否可進行重建。我們還得好好管好希瓦娜斯。$b$b從現在開始，聯盟將會積極應對。絕對不能再讓一個像地獄吼的傢伙出現。', `MaleText_loc7`='Estamos más unidos que nunca. Hemos logrado para nuestro pueblo seguridad en Kalimdor, el fin del bloqueo y el final a la guerra abierta que ha derramado tanta sangre en ambos lados del Mare Magnum.$b$bAhora, para trabajar en la paz, me gustaría ubicar un cuartel cerca de Theramore. Necesitamos investigar cómo eliminar la plaga de las tierras de Gilneas para que puedan reconstruirse. Debemos contener a Sylvanas.$b$bDe aquí en adelante, la Alianza será proactiva. No permitiremos que haya nadie semejante a Grito Infernal.' WHERE `ID`=77352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에 더 큰 고통을 가하고 싶은 심정은 이해한다. 하지만 그럼 언제 멈추겠는가? 썬더 블러프, 아즈샤라, 메아리 섬를 침공해서 더 많은 얼라이언스의 죽음을 감수해야 하겠는가? 침공에 성공했다 한들, 정복한 이들은 어떻게 다스릴 것인가?$b$b판다렌은 항상 우리에게 왜 싸우냐고 물었다. 오늘 우리는 정의를 되찾았고, 호드의 반란을 지지하여 그들에게 속죄할 기회를 주었다. 더 이상의 피는 오직 복수만을 위함이고, 그 피는 또다시 복수를 불러올 것이다.', `MaleText_loc4`='我理解你希望进一步打击部落的想法。但冤冤相报何时了？如果我们入侵雷霆崖、艾萨拉和回音群岛，联盟又会增加多少伤亡？我们又该如何管理那些被征服的人民？$b$b熊猫人总是问我们为何而战。今天，我们赢得了正义，并通过支援起义军给了部落一个赎罪改过的机会。更多的血腥杀戮就变成了单纯的复仇——而这只会引来更多的复仇。', `MaleText_loc5`='我知道你想要讓部落受到更多的苦難折磨。但冤冤相報何時了?如果我們舉兵入侵雷霆崖、艾薩拉與回音群島又要犧牲多少人命?我們又怎麼去統治那些被俘虜的人?$b$b熊貓人總是質問我們爭戰的意義何在。今天，我們以正義之名勝利了，支持叛軍給他們一個贖罪的機會。但繼續流血就就成了復仇的行為 - 而這樣只會導致別人對我們更多的復仇。', `MaleText_loc7`='Entiendo tu deseo de infligir más sufrimiento a la Horda. Pero, ¿cuál es el límite? ¿Cuántos miembros más de la Alianza perderían la vida si invadiésemos la Cima del Trueno, Azshara y las Islas del Eco? Y, ¿cómo gobernaríamos a los pueblos conquistados?$b$bLos pandaren siempre preguntan por qué luchamos. Hoy, hemos ganado justicia y hemos dado a la Horda una oportunidad de redención apoyando su rebelión. Continuar el río de sangre sería solo venganza... y obtendríamos venganza a cambio.' WHERE `ID`=77353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안 폐하는 호드가 새로운 대족장을 뽑게 놔둔 걸 반드시 후회하게 될 거예요.$b$b우리는 계속 싸웠어야 해요. 몇 년 지나지 않아서, 이 새로운 대족장이 또 어떤 트롤다운 생각에 휩싸일지 누가 알겠어요?', `FemaleText_loc4`='乌瑞恩国王迟早会为自己允许部落出现另一个酋长而后悔的。$b$b我们应该继续打下去。谁敢保证几年之后这位新酋长的巨魔脑袋里不会冒出什么馊主意？', `FemaleText_loc5`='烏瑞恩國王將會後悔讓部落選出另外一個大酋長。$b$b我們應該繼續戰下去。誰說新上任大酋長的食人妖腦袋裡不會在幾年後打什麼歪主意?', `FemaleText_loc7`='El Rey Wrynn lamentará el día en que permitió a la Horda nombrar a otro Jefe de Guerra.$b$bDeberíamos haber seguido luchando. ¿Quién nos asegura que este nuevo Jefe de Guerra no desarrollará ninguna idea en su cabeza de trol dentro de unos años?' WHERE `ID`=77354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 아버지가 옳은 결정을 내리셨다고 생각해요. 우리가 오그리마를 차지하려고 했으면 전쟁이 영원히 끝나지 않았을 거예요. 그리고 나머지 호드는 어떻게 했을까요? 포로 수용소로 보내버리면 끝이었을까요? 이미 가본 길이죠. 끝이 좋지 않은 길이란 걸 우리 모두 알고 있고요!$b$b우리는 전쟁광을 퇴위시키고 우리가 함께 일할 수 있는 지도자를 세웠어요. 우리의 평화로운 미래를 위한 유일한 기회이자 선택이죠.', `MaleText_loc4`='我觉得我父亲做得对。如果我们试图占领奥格瑞玛，那战争将永无止境。而且剩下的部落人民怎么办？难道要依靠收容所吗？我们过去就这么干过——那根本行不通！$b$b我们废黜了一个战争贩子，并让一位可以沟通的领袖取代了他。这是达成和解的唯一机会。', `MaleText_loc5`='我覺得我的父親做了正確的決定。如果我們想要佔領奧格瑪，那麼這場戰役將永不止息。那剩下的部落將何以適從?我們要把所有人拘留起來?這方法以前就已經試過了 - 一點都不管用!$b$b我們罷免了一個好勇鬥狠的傢伙，用一個能跟我們合作的領袖來代替他。這是唯一能保障和平的方法。', `MaleText_loc7`='Creo que mi padre ha hecho lo correcto. Si hubiese intentado ocupar Orgrimmar, la lucha nunca habría acabado. Además, ¿qué sucedería con el resto de la Horda? ¿Recurriríamos a los campos de reclusión? ¡Ya hemos probado ese sistema y no funciona!$b$bHemos derrocado a un belicista y lo hemos reemplazado por un líder con el que podemos trabajar. Es nuestra única opción de lograr la paz en el futuro.' WHERE `ID`=77355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 승리했네! 여기서 떠나기 전에, 우린 이 기상천외한 고블린 기술을 최대한 많이 습득해 갈 셈이네.', `MaleText_loc4`='胜利属于联盟！在我们撤出这里之前，我的人要尽可能多搞一些疯狂的地精科技。', `MaleText_loc5`='聯盟得勝!清場之前，我的人手只要能拿得上的，都會把這些哥布林的瘋狂科技研究全部帶走。', `MaleText_loc7`='¡Victoria para la Alianza! Antes de marcharnos, mi gente tomará toda la tecnología goblin demente que pueda.' WHERE `ID`=77356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두가 힘을 합치게 하는 데에는 공공의 적 만한 게 없지. 드워프 부족은 여태 이렇게 단결된 적이 없었소. 평화가 지속된다면 우리의 세 왕국은 그 어느 때보다 강해질 거요.', `FemaleText_loc4`='一个共同的敌人，是让人民保持团结的最好方法。矮人部族从未如此团结过。如果和平能持续下去，我们三大王国将会空前的强大……', `FemaleText_loc5`='共同的敵人是凝聚人心最好的辦法。矮人部族從未如此團結過。如果和平能夠繼續維持下去，那麼我們的三個王國將會是史無前例的強大...', `FemaleText_loc7`='No hay nada como un enemigo común para unir a los pueblos. Los clanes enanos nunca han estado tan unidos. Si la paz perdura, nuestros tres reinos serán más fuertes que nunca...' WHERE `ID`=77357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안이 오늘 여기서 결정을 내리기 전에, 평화의 대가에 대해 함께 얘기를 나눴어요. 만약 호드가 잿빛 골짜기에서 영원히 떠난다면, 전 호드가 아즈샤라의 목재를 사용하게 해 줄 용의가 있어요. 저 고블린 놈들의 자원 갉아먹는 속도를 생각하면, 그걸로 얼마나 버틸 수 있을지 내심 궁금하기도 하네요.$b$b저는 이 평화를 지지하지만, 바리안 국왕만큼 확신이 서진 않아요. 만약 호드가 조약을 깨고 또다시 우리에게 맞서면... 우린 기꺼이 그들을 상대할 준비가 되어 있을 거예요.', `FemaleText_loc4`='在瓦里安今天做出决定之前，他和我就和平的代价讨论了很久。只要部落同意永久放弃灰谷，我就允许他们使用艾萨拉的木材。考虑到地精吞噬资源的做派，我们倒要看看艾萨拉能支撑多久。$b$b我支持和解，可我没有国王陛下那么自信。如果部落胆敢撕毁条约，再来招惹我们……我们也会做好准备的。', `FemaleText_loc5`='在下了今天的決定之前，瓦里安與我討論了很多關於和平所需要付出的代價。只要他們願意永遠放棄梣谷，我還是願意讓部落使用艾薩拉的木材。看過哥布林是怎麼暴殄天物以後，就知道那些資源還能維持多久。$b$b我支持和平，但我可沒大君王那麼樂觀。如果部落膽敢違反條約，再次對我們動手...我的人民會讓他們付出代價的。', `FemaleText_loc7`='Varian y yo hablamos largo y tendido del precio de la paz antes de su decisión de hoy. Permitiré a la Horda que utilicen la madera de Azshara si abandonan Vallefresno. Teniendo en cuenta cuántos recursos consumen los goblin, veremos cuánto tiempo los mantiene.$b$bApoyo esta paz, pero no comparto la confianza de su majestad. Si la Horda rompe el tratado y vuelve a hacernos frente... mi pueblo estará preparado.' WHERE `ID`=77358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 위대한 승리일세. 이제 역병에 엉망이 된 우리 고향, 길니아스로 관심을 돌릴 때야... 린 폐하께서 내 왕국의 재건을 돕겠노라 맹세하셨지만, 어디서부터 시작해야 할지 잘 모르겠군.', `MaleText_loc4`='毫无疑问，这是一次大捷。现在，我们得将注意力放到我们在吉尔尼恩的家园——那个被瘟疫毁于一旦的地方。乌瑞恩已经保证会帮忙重建我的王国，但该从何处着手依然是个难题。', `MaleText_loc5`='這確實是一場漂亮的勝仗。現在該把目標轉移到我們飽受疾病之苦 - 吉爾尼斯的家鄉了。烏瑞恩承諾要提供協助重建我的王國，但真的很難決定要從哪裡開始下手。', `MaleText_loc7`='Una gran victoria, sin duda. Ahora nos centraremos en nuestra Gilneas natal, asolada por la enfermedad. Wrynn ha prometido ayudar a reconstruir mi reino, pero no es fácil saber por dónde empezar.' WHERE `ID`=77359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화만큼 싸울 가치가 있는 건 없네.', `MaleText_loc4`='和平是唯一值得为之而战的东西。', `MaleText_loc5`='和平就是值得爭取的唯一理由。', `MaleText_loc7`='La paz es lo único por lo que merece la pena luchar.' WHERE `ID`=77360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당당히 어깨를 펴게, $c|1이여;여;. 오늘 자네는 호드의 정신을 지켜냈네.', `MaleText_loc4`='抬头挺胸，$c。今天，你挽救了部落的灵魂。', `MaleText_loc5`='挺直腰桿，$c。你今天拯救了部落的靈魂。', `MaleText_loc7`='Mantén la cabeza alta, $c. Hoy hemos salvado el alma de la Horda.' WHERE `ID`=77361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 가로쉬가 준비됐다고 생각했네. 대족장이라는 막중한 책임이 그의 시야를 넓혀 주리라 믿었지. 하지만 그는 우리 앞에 놓인 수많은 문제를 해결하는 방법들 중 단 하나밖에 보지 못했네. 호드에 대한 가로쉬의 이상은 우리를 벼랑 끝으로 몰고 갔지.$b$b이제 새로운 방향으로 나아갈 때야. 볼진이 우리를 이끌어 줄 걸세. 그는 여러모로 이 자리를 원치 않았지... 하지만 바로 그 때문에, 볼진은 더 나은 지도자가 될 걸세.', `MaleText_loc4`='我以为加尔鲁什已经做好了准备。我以为酋长的重任能让他把目光放长远。可当我们的人民面临重重困难时，他却只看到了一种解决办法——他对部落的虚妄规划将我们都逼到了悬崖。$b$b是时候了，我们要寻找新的方向。沃金会带领我们前进。他其实并不想挑起这个重担……但我想这反而能让他成为一个更好的领袖。', `MaleText_loc5`='我以為卡爾洛斯已經準備好了。我以為背負大酋長的責任能夠給他更有遠見。但是當我們的人民在面臨這麼多的問題當中，他只能看到一個解決辦法 -  他的急功近利讓部落瀕臨到毀滅的邊緣。$b$b是時候讓部落往另一個方向發展了。沃金將會帶領我們。雖然許多跡象都顯示出他並不想要負擔這麼多的責任...但我認為他會成為一個優秀的領袖。', `MaleText_loc7`='Creía que Garrosh estaba listo. Creía que el cargo de Jefe de Guerra le daría perspectiva. Para los muchos problemas que afronta nuestro pueblo, solo vio una solución: su visión de la Horda nos ha llevado al borde de un precipicio.$b$bNecesitamos una nueva dirección y Vol''jin será quien nos guíe. En muchos sentidos no deseaba esta responsabilidad... pero creo que eso hará que sea un líder mejor.' WHERE `ID`=77362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정치란 참으로 피곤한 일이오. 나는 볼진이 우리가 가야 할 곳으로 우리를 이끌어 주리라 믿어 의심치 않소.$b$b<실바나스를 흘끗 쳐다보는 로르테마르>$b$b그가 이 호드를 하나로 묶을 수 있다는 전제 하에.', `MaleText_loc4`='我发现政治真是个累死人的玩意儿。我相信沃金会带领我们走上正确的道路。$b$b<洛瑟玛瞥了一眼希尔瓦娜斯。>$b$b假如他能让部落团结一致的话。', `MaleText_loc5`='玩弄政治只會讓人精疲力盡。我確信沃金將會帶領我們前往下一個目標。$b$b<洛索瑪看著希瓦娜斯。>$b$b前提是他還能統一這個部落。', `MaleText_loc7`='La política me resulta agotadora. Confío en que Vol''jin nos guiará por el camino necesario.$b$b<Lor''themar dirige la mirada a Sylvanas.>$b$bSiempre y cuando logre mantener esta Horda unida.' WHERE `ID`=77363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 함께일세, $c|1이여;여;.', `MaleText_loc4`='我们需要和衷共济，$c。', `MaleText_loc5`='我們會同舟共濟，$c。', `MaleText_loc7`='Todos estamos juntos en esto, $c.' WHERE `ID`=77364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"대족장 볼진"이라. 말도 안 되는 것처럼 들리지 않나, $c? 나로 말할 것 같으면, 물론 트롤 따위에게 명령을 받지는 않을 것이다.$b$b하지만 이 귀여운 연합을 하나로 묶은 건 볼진이었고, 덕분에 이 날이 왔지. 게다가 그를 죽이는 게 거의 불가능하단 것도 보여줬고... 그 점에는 감탄하고 있다.$b$b
볼진이 진정 어떤 인물인지 시험할 때로군...', `FemaleText_loc4`='“沃金酋长”。你觉得听起来滑稽吗，$c？最起码，我是不会听从一个巨魔的命令的。$b$b可是，是他集结起了这支小小的联军，并赢得了今天的胜利。而且他还证明了自己是杀不死的——这是我最佩服的一点。$b$b
时间会证明他有多少真本事的……', `FemaleText_loc5`='『沃金大酋長』。對你而言聽起來很怪嗎，$c?至少對我來說，是絕對不可能聽從一個食人妖所下達的命令。$b$b儘管如此，他還是設法統合了所有人而且贏得的最後的勝利。而且他證明了自己堅不可摧的實力，這點我很欣賞。$b$b
測試一下他到底是什麼來頭的時候到了...', `FemaleText_loc7`='"Jefe de Guerra Vol''jin." ¿A ti también te suena absurdo, $c? Yo no pienso acatar las órdenes de un trol.$b$bPero formó esta coalición y salvó la situación. Además, ha demostrado ser imposible de matar. Lo admiro por eso.$b$b
Es hora de ver de qué está hecho...' WHERE `ID`=77365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진은 정말 보통이 아니야. 목에 칼침을 맞고도 빚을 받으러 돌아오다니. 아주 마음에 든다고!$b$b우리 고블린한테는 안전과 이익이 필요하지. 하지만 헬스크림이 대족장이었을 땐 양쪽 다 국물도 없었다고.', `MaleText_loc4`='沃金是个坚强的人。哪怕被割断了脖子，他还能挺着回来为自己讨还公道。我喜欢这家伙！$b$b我的人民需要安全和利润。在加尔鲁什手下，我们啥都得不到。', `MaleText_loc5`='沃金真是個老瘋子。即使脖子上被插了一刀，他還能回來討債。我喜歡這傢伙!$b$b我的人民需要安全的環境和經濟上的利潤。在地獄吼的統治下，我們什麼也拿不到。', `MaleText_loc7`='Vol''jin es un tipo duro. Incluso después de una puñalada en la nuca vuelve a reclamar lo que le deben. ¡Me gusta!$b$bMi pueblo necesita seguridad y beneficios. Bajo el mando de Grito Infernal, no teníamos ninguna de las dos cosas.' WHERE `ID`=77366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_bomb_05:20|t |cFFFF0000|Hspell:145996|h[폭파 준비 완료]|h|r! |cFFFF0000|Hspell:146364|h[폭탄 투척]|h|r으로 폭탄을 던지십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_bomb_05:20|t你身后被|cFFFF0000|Hspell:145996|h[设置炸弹]|h|r了！快使用|cFFFF0000|Hspell:146364|h[投掷炸弹]|h|r扔掉它们！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_bomb_05:20|t你獲得|cFFFF0000|Hspell:145996|h[引爆]|h|r!使用|cFFFF0000|Hspell:146364|h[投擲炸彈]|h|r來投擲炸彈!', `MaleText_loc7`='|TInterfaceIconsinv_misc_bomb_05:20|tTienes |cFFFF0000|Hspell:145996|h[Listo para explotar]|h|r! Utiliza |cFFFF0000|Hspell:146364|h[Lanzar bomba]|h|r para lanzarlas!' WHERE `ID`=77369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 최후로군.$b$b<경계하는 눈길로 당신을 바라보는 볼진>$b$b$r|1이여;여;, 앞으로는 어쩔 셈인가?', `MaleText_loc4`='地狱咆哮已经完蛋了。$b$b<沃金警惕地看着你。>$b$b接下来呢，$r？', `MaleText_loc5`='這就是地獄吼最終的下場。$b$b<沃金小心翼翼地看著你。>$b$b下一步是什麼，$r?', `MaleText_loc7`='Eh''te es el final de Grito Infernal.$b$b<Vol''jin te mira con cautela.>$b$b¿Y ahora qué, $r?' WHERE `ID`=77371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\achievement_arena_2v2_5:20|t$n|1이;가; 전투를 시작하려고 합니다. 전투 시작에 필요한 추가 인원: $8589w', `MaleText_loc4`='|TInterface\\Icons\\achievement_arena_2v2_5:20|t$n已同意开始战斗。另外还需要$8589w名玩家才可开始。', `MaleText_loc5`='|TInterface\\Icons\\achievement_arena_2v2_5:20|t$n同意進行戰鬥。另外還需要$8589w名玩家才可開始。', `MaleText_loc7`='|TInterfaceIconsachievement_arena_2v2_5:20|t$n ha aceptado el encuentro. Jugadores adicionales necesarios para comenzar: $8589w.' WHERE `ID`=77865;

